# The site owner + admins (bot-application-owner ids) that gate the owner-only
# sandbox switch and admin powers. Kept OUT of the public repo: loaded from
# owner_subs.txt (one sub per line; '#' comments and blank lines ignored),
# gitignored like the other secrets. A missing file yields an empty set, so a
# fresh clone still boots - with no owner until the file is provided.
def _load_owner_subs():
    _p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "owner_subs.txt")
    _subs = set()
    try:
        with open(_p, encoding="utf-8") as _f:
            for _line in _f:
                _line = _line.strip()
                if _line and not _line.startswith("#"):
                    _subs.add(_line)
    except OSError:
        pass
    return _subs


OWNER_SUBS = _load_owner_subs()


def _load_preview_key():
    """The preview key, or None. No file, no route: the feature is off."""
    _p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "preview_key.txt")
    try:
        with open(_p, encoding="utf-8") as _f:
            _k = _f.read().strip()
        return _k if len(_k) >= 24 else None
    except OSError:
        return None


PREVIEW_KEY = _load_preview_key()
# Keys the owner hands to testers. The key itself is never stored - only a
# hash - so a leak of the database is not a leak of the keys, and a key is
# shown once, at the moment it is made.
PREVIEW_KEY_PREFIX = "sbgem"
# What a key does when it is used. A sandbox key puts whoever redeems it on a
# throwaway account of their own - right for poking at the shop, wrong for an
# event, where a tester has to play as themselves and be paid as themselves.
PREVIEW_KINDS = ("sandbox", "access")
# What an access key hands over so a tester can actually see the thing: more
# gems than the catalogue costs, in one clearly-labelled ledger row, granted
# once per key per person. It is test money - DELETE FROM gem_ledger WHERE
# reason = 'preview-credit' takes every penny of it back at release.
PREVIEW_CREDIT = 1000000
PREVIEW_KEY_DAYS = (1, 7, 14, 30, 90)
PREVIEW_KEY_DEFAULT_DAYS = 14
PREVIEW_KEY_LABEL_MAX = 40
_PREVIEW_OK_CACHE = {}


def _preview_key_hash(plain):
    return hashlib.sha256(("starblast-preview|" + str(plain or "")).encode("utf-8")).hexdigest()


def preview_key_make(c, label, days, by, kind="sandbox"):
    """Mint a key, store only its hash, and hand the plain one back to be
    shown once. Returns (id, plain)."""
    kind = kind if kind in PREVIEW_KINDS else "sandbox"
    plain = "%s-%s" % (PREVIEW_KEY_PREFIX, secrets.token_urlsafe(24))
    label = " ".join(str(label or "").split())[:PREVIEW_KEY_LABEL_MAX] or "Tester"
    try:
        days = int(days)
    except (TypeError, ValueError):
        days = PREVIEW_KEY_DEFAULT_DAYS
    days = days if days in PREVIEW_KEY_DAYS else PREVIEW_KEY_DEFAULT_DAYS
    c.execute("INSERT INTO preview_keys (label, key_hash, created_at, created_by, expires_at, "
              "kind) VALUES (?, ?, ?, ?, datetime('now', ?), ?)",
              (label, _preview_key_hash(plain), _stamp(), str(by or "")[:80],
               "+%d days" % days, kind))
    return c.lastrowid, plain


def preview_key_match(c, plain):
    """(id, kind) of the live key this plain text is, or (None, None).
    Constant-time against each candidate; revoked and expired are not live."""
    if not plain:
        return None, None
    want = _preview_key_hash(plain)
    try:
        rows = c.execute("SELECT id, key_hash, COALESCE(kind, 'sandbox') FROM preview_keys "
                         "WHERE revoked_at IS NULL AND expires_at > ?", (_stamp(),)).fetchall()
    except sqlite3.Error:
        return None, None
    for kid, kh, kind in rows:
        if hmac.compare_digest(str(kh), want):
            return kid, kind
    return None, None


def preview_any_live():
    """Is there any way in at all - the master key or a live tester key? The
    door is hidden when there is not, so it cannot be found by guessing."""
    if PREVIEW_KEY:
        return True
    try:
        conn = db(timeout=3)
        r = conn.execute("SELECT 1 FROM preview_keys WHERE revoked_at IS NULL "
                         "AND expires_at > ? LIMIT 1", (_stamp(),)).fetchone()
        conn.close()
        return bool(r)
    except sqlite3.Error:
        return False


def preview_key_live(kid):
    """Is this key still good? Checked on every request that shows the
    preview, through a short cache, so revoking one takes effect at once
    rather than whenever the tester happens to sign in again."""
    if not kid:
        return False
    now = time.time()
    hit = _PREVIEW_OK_CACHE.get(kid)
    if hit and now - hit[0] < 30:
        return hit[1]
    ok = False
    try:
        conn = db(timeout=3)
        r = conn.execute("SELECT 1 FROM preview_keys WHERE id = ? AND revoked_at IS NULL "
                         "AND expires_at > ?", (kid, _stamp())).fetchone()
        conn.close()
        ok = bool(r)
    except sqlite3.Error:
        ok = False
    _PREVIEW_OK_CACHE[kid] = (now, ok)
    return ok


def preview_session_ok():
    """Whether THIS session may see the unreleased surfaces: the key it came
    in on is still live (or it came in on the master key in the file)."""
    if not session.get("preview"):
        return False
    kid = session.get("preview_key")
    if not kid:
        return True
    return preview_key_live(kid)


def preview_key_rows(c):
    """Every key the owner has made, newest first, for the page."""
    out = []
    try:
        rows = c.execute("SELECT id, label, created_at, expires_at, revoked_at, "
                         "COALESCE(uses, 0), COALESCE(last_used_at, ''), "
                         "COALESCE(kind, 'sandbox') FROM preview_keys "
                         "ORDER BY id DESC").fetchall()
    except sqlite3.Error:
        return out
    now = _stamp()
    for kid, label, made, exp, revoked, uses, last, kind in rows:
        state = "revoked" if revoked else ("expired" if (exp or "") <= now else "live")
        out.append({"id": kid, "label": label, "made": (made or "")[:10],
                    "expires": (exp or "")[:10], "state": state, "uses": uses,
                    "last": (last or "")[:16], "kind": kind})
    return out

# ----------------------------------------------------------- CLAN KEYS
# What it costs to start a clan once the economy is public. A tag is a claim
# on a name the whole site can see, and a price makes starting one a decision
# rather than something to collect. Nobody is locked out by it: the older way
# in - ask, and the site owner says yes - still works and still costs nothing.
# ~12 weeks of ordinary play, or three of a good one. The older way in -
# ask, and the owner says yes - is still free, so this is the price of not
# waiting, not the price of a clan.
CLAN_START_COST = 7500
# A key from the owner IS that yes, handed over directly: it skips the wait
# and the price, for exactly one clan.
CLAN_KEY_PREFIX = "sbclan"
CLAN_KEY_DAYS = (7, 30, 90, 365)
CLAN_KEY_DEFAULT_DAYS = 90
CLAN_KEY_USES_MAX = 20
CLAN_KEY_LABEL_MAX = 40


def _clan_key_hash(plain):
    return hashlib.sha256(("starblast-clan|" + str(plain or "")).encode("utf-8")).hexdigest()


def clan_key_make(c, label, days, uses, by):
    """Mint a clan key, store only its hash, hand the plain one back to be
    shown once. Returns (id, plain)."""
    plain = "%s-%s" % (CLAN_KEY_PREFIX, secrets.token_urlsafe(24))
    label = " ".join(str(label or "").split())[:CLAN_KEY_LABEL_MAX] or "A clan"
    try:
        days = int(days)
    except (TypeError, ValueError):
        days = CLAN_KEY_DEFAULT_DAYS
    days = days if days in CLAN_KEY_DAYS else CLAN_KEY_DEFAULT_DAYS
    try:
        uses = max(1, min(CLAN_KEY_USES_MAX, int(uses)))
    except (TypeError, ValueError):
        uses = 1
    c.execute("INSERT INTO clan_keys (label, key_hash, created_at, created_by, expires_at, "
              "max_uses) VALUES (?, ?, ?, ?, datetime('now', ?), ?)",
              (label, _clan_key_hash(plain), _stamp(), str(by or "")[:80],
               "+%d days" % days, uses))
    return c.lastrowid, plain


def clan_key_match(c, plain):
    """The id of the live clan key this plain text is, or None. Used up,
    revoked and expired keys are not live."""
    if not plain:
        return None
    want = _clan_key_hash(plain)
    try:
        rows = c.execute("SELECT id, key_hash FROM clan_keys WHERE revoked_at IS NULL "
                         "AND expires_at > ? AND COALESCE(uses, 0) < COALESCE(max_uses, 1)",
                         (_stamp(),)).fetchall()
    except sqlite3.Error:
        return None
    for kid, kh in rows:
        if hmac.compare_digest(str(kh), want):
            return kid
    return None


def clan_key_burn(c, kid, sub_id, tag):
    """Count the use, and remember what it was spent on - the owner's page
    shows which clan came out of which key."""
    c.execute("UPDATE clan_keys SET uses = COALESCE(uses, 0) + 1, last_used_at = ?, "
              "used_by = COALESCE(NULLIF(used_by, ''), ?), "
              "used_tag = TRIM(COALESCE(used_tag || ', ', '') || ?) WHERE id = ?",
              (_stamp(), str(sub_id or "")[:80], tag, kid))


def clan_key_rows(c):
    """Every clan key the owner has made, newest first, for the page."""
    out = []
    try:
        rows = c.execute("SELECT id, label, created_at, expires_at, revoked_at, "
                         "COALESCE(uses, 0), COALESCE(max_uses, 1), COALESCE(used_tag, ''), "
                         "COALESCE(last_used_at, '') FROM clan_keys ORDER BY id DESC").fetchall()
    except sqlite3.Error:
        return out
    now = _stamp()
    for kid, label, made, exp, revoked, uses, cap, tags, last in rows:
        if revoked:
            state = "revoked"
        elif uses >= cap:
            state = "used up"
        elif (exp or "") <= now:
            state = "expired"
        else:
            state = "live"
        out.append({"id": kid, "label": label, "made": (made or "")[:10],
                    "expires": (exp or "")[:10], "state": state, "uses": uses,
                    "cap": cap, "tags": tags, "last": (last or "")[:16]})
    return out


def account_norm_for(c, sub_id):
    """The norm_name this account plays under - the name the gem ledger is
    kept against. Same deterministic pick as account_name_for."""
    if not sub_id:
        return None
    c.execute("SELECT norm_name FROM players WHERE google_sub = ? "
              "ORDER BY (COALESCE(wins, 0) + COALESCE(losses, 0)) DESC, name LIMIT 1",
              (sub_id,))
    row = c.fetchone()
    return row[0] if row else None


