# ---- The ship shop ---------------------------------------------------
# What a ship costs, by tier (the hundreds digit of its code). Dearer as the
# hull gets bigger; a top-tier hull costs more than the top tier pays.
# A week of ordinary play is ~620 gems, a good week ~1,740. So: tier 1 is a
# night, tier 4 a fortnight, tier 7 a month or two of real play.
SHIP_TIER_PRICE = {1: 150, 2: 400, 3: 800, 4: 1500, 5: 2500, 6: 4000, 7: 6000}
# Which ship each tier hands you on arrival, matching ranks.py. The Odyssey
# belongs to Mythos: finish a day at number one and it is yours, free.
SHIP_RANK_UNLOCK = {101: 1, 201: 2, 301: 3, 406: 4, 501: 5, 601: 6, 603: 7,
                    702: 8, 701: 9}
# The tier you must have reached to BUY a hull, where that is not simply the
# hull's own tier. A tier ship is not on sale at all - reach the tier and it
# is handed to you - and the Odyssey may be bought by the top climbable tier
# (Archon) although only Mythos is given it.
SHIP_BUY_LEVEL = {701: ranks.TOP_CLIMBABLE}
# Priced by hand rather than by tier.
SHIP_SPECIAL_PRICE = {703: 8000, 704: 10000, 701: 25000}
MYTHIC_SHIP = 701                       # the Odyssey
MYTHIC_COLOR = "#ff2e4d"                # crimson, whatever your tier - and apart from Warden orange
MYTHIC_GLOW = "rgba(255,46,77,.6)"


def ship_catalog():
    """Every ship you could wear, cheapest first within a tier. Each carries
    the colour of the tier it stands for - the Shadow X-3 its own,
    the Odyssey the mythic red - which is how the shop draws it; on the
    board a ship always wears its owner's rank colour."""
    by_level = {r["level"]: r["color"] for r in ranks.RANKS}
    by_ship = {r["ship"]: r["color"] for r in ranks.RANKS}
    # A tier's colour is that of the lowest rank whose own ship sits in it
    # (tier 6 holds both the Advanced-Fighter and the Marauder; the tier is
    # gold, the Marauder itself is orange).
    tier_level = {}
    for r in ranks.RANKS:
        t = r["ship"] // 100
        tier_level[t] = min(tier_level.get(t, 99), r["level"])
    out = []
    for code in sorted(ship_shapes.ship_codes()):
        tier = code // 100
        tier_color = by_level.get(tier_level.get(tier, 0), "#8b949e")
        unlock = SHIP_RANK_UNLOCK.get(code)
        out.append({
            "code": code, "name": ship_shapes.ship_name(code), "tier": tier,
            "price": SHIP_SPECIAL_PRICE.get(code, SHIP_TIER_PRICE.get(tier, 0)),
            "unlock_level": unlock,
            # A tier's hulls are for the people who have reached that tier.
            # Where a hull is a tier's own reward, the gate IS the reward, so
            # it never appears for sale: you earn it or you do not have it.
            "buy_level": SHIP_BUY_LEVEL.get(code, unlock or tier),
            # true when reaching the tier IS how you get it, so the shop and
            # the buy route say "earn it" rather than "come back richer".
            "earn_only_gate": bool(unlock) and code not in SHIP_BUY_LEVEL,
            "mythic": code == MYTHIC_SHIP,
            "premium": code in (703, 704),
            "tier_color": tier_color,
            "color": MYTHIC_COLOR if code == MYTHIC_SHIP else by_ship.get(code, tier_color),
        })
    return out


def owned_ships(c, nn):
    """The set of ship codes this player may wear, and why each is theirs."""
    own = {}
    lvl = gem_peak_level(c, nn)
    for code, need in SHIP_RANK_UNLOCK.items():
        if lvl >= need:
            own[code] = "rank"
    try:
        for (ref,) in c.execute("SELECT ref FROM gem_ledger WHERE owner_kind = 'player' "
                                "AND owner = ? AND reason = 'purchase' "
                                "AND ref LIKE 'ship-%'", (nn,)).fetchall():
            try:
                own.setdefault(int(ref[5:]), "bought")
            except ValueError:
                pass
    except sqlite3.Error:
        pass
    return own


def ship_buyable(c, nn, item, lvl=None):
    """Whether this player has earned the right to buy this hull, and the
    tier they would need. A hull a tier hands out is never for sale."""
    need = int(item.get("buy_level") or 0)
    if not need:
        return True, None
    lvl = gem_peak_level(c, nn) if lvl is None else lvl
    return lvl >= need, ranks.RANK_BY_LEVEL.get(need)


def gem_charge(c, nn, amount, reason, ref):
    """Spend, once, and only what is there. Returns 'ok', 'duplicate' or
    'short'. The ledger row goes first so the unique index settles a double
    purchase; the debit is conditional so a balance can never go below zero
    even if two requests race; and a debit that is refused takes its ledger
    row back out again in the same transaction."""
    amount = int(amount)
    if amount <= 0:
        return "ok"
    c.execute("INSERT OR IGNORE INTO gem_ledger (owner_kind, owner, amount, reason, ref, at) "
              "VALUES ('player', ?, ?, ?, ?, ?)", (nn, -amount, reason, ref, _stamp()))
    if not c.rowcount:
        return "duplicate"
    c.execute("UPDATE players SET gems = COALESCE(gems, 0) - ? "
              "WHERE norm_name = ? AND COALESCE(gems, 0) >= ?", (amount, nn, amount))
    if not c.rowcount:
        c.execute("DELETE FROM gem_ledger WHERE owner_kind = 'player' AND owner = ? "
                  "AND reason = ? AND ref = ?", (nn, reason, ref))
        return "short"
    return "ok"


# The most a single joining bonus or ask may be.
GEM_BONUS_MAX = 1000000


def gem_clan_charge(c, tag, amount, reason, ref):
    """Spend from a treasury, once, and only what is there - the clan-side
    twin of gem_charge. Returns 'ok', 'duplicate' or 'short'."""
    amount = int(amount)
    if amount <= 0:
        return "ok"
    c.execute("INSERT OR IGNORE INTO gem_ledger (owner_kind, owner, amount, reason, ref, at) "
              "VALUES ('clan', ?, ?, ?, ?, ?)", (tag, -amount, reason, ref, _stamp()))
    if not c.rowcount:
        return "duplicate"
    c.execute("UPDATE clans SET gems = COALESCE(gems, 0) - ? "
              "WHERE tag = ? AND COALESCE(gems, 0) >= ?", (amount, tag, amount))
    if not c.rowcount:
        c.execute("DELETE FROM gem_ledger WHERE owner_kind = 'clan' AND owner = ? "
                  "AND reason = ? AND ref = ?", (tag, reason, ref))
        return "short"
    return "ok"


def gem_pay_join_bonus(c, invite_id, clan, name):
    """Move an invite's bonus, or an application's ask, from the treasury to
    the player as part of the join. Returns (status, amount): 'ok' - paid,
    or nothing was owed - or 'short', meaning the treasury cannot cover it
    and the join must not go through. Keyed on the invite id on both sides,
    so a join processed twice pays once and never twice."""
    try:
        r = c.execute("SELECT COALESCE(gems, 0) FROM clan_invites WHERE id = ?",
                      (invite_id,)).fetchone()
    except sqlite3.Error:
        return "ok", 0
    amount = int(r[0]) if r and r[0] else 0
    if amount <= 0:
        return "ok", 0
    ref = "invite-%d" % int(invite_id)
    got = gem_clan_charge(c, clan, amount, "salary", ref)
    if got == "short":
        return "short", amount
    gem_grant(c, "player", normalize_name(name), amount, "salary", ref)
    return "ok", amount


def _gem_amount(data, key="gems"):
    """A non-negative whole number of gems out of a request, or 0."""
    try:
        return max(0, min(GEM_BONUS_MAX, int(data.get(key) or 0)))
    except (TypeError, ValueError):
        return 0


_SHIP_CACHE = {"ts": 0.0, "map": {}}


def display_ship_map():
    """norm_name -> equipped ship code, for everyone who has one. Tiny -
    only players who chose a ship are in it - and cached briefly because the
    board asks once per page."""
    now = time.time()
    if now - _SHIP_CACHE["ts"] < 60:
        return _SHIP_CACHE["map"]
    m = {}
    try:
        conn = db(timeout=3)
        for nn, code in conn.execute("SELECT norm_name, display_ship FROM players "
                                     "WHERE display_ship IS NOT NULL").fetchall():
            if nn and code:
                m[nn] = int(code)
        conn.close()
    except sqlite3.Error:
        pass
    _SHIP_CACHE["ts"], _SHIP_CACHE["map"] = now, m
    return m


def worn_emblem(nn, shipmap, allowed):
    """(ship code, colour override, is_mythic) for a player - or (None, None,
    False) meaning draw the division's own. `allowed` is whether the viewer
    may see any of this; while unreleased that is only the owner."""
    if not allowed or not nn:
        return None, None, False
    code = shipmap.get(nn)
    if not code:
        return None, None, False
    if code == MYTHIC_SHIP:
        return code, MYTHIC_COLOR, True
    return code, None, False


