_ACH_EXTRA = _ach_extra()


def gem_achievement_catalog():
    """Every achievement there is, grouped and in the order a page shows them."""
    out = []
    for r in sorted(ranks.RANKS, key=lambda x: x["level"]):
        out.append({
            "key": "div-%s" % r["key"], "group": "Tiers", "name": r["name"],
            "desc": ("Finish a day at number one on the board. Yours for ever "
                     "after, with the Odyssey."
                     if r.get("mythic") else
                     "Reach the %s tier \u2014 %s of the board."
                     % (r["name"], (r.get("band") or "").replace("Top ", "the top "))),
            "gems": GEM_DIVISION_AWARD.get(r["level"], 100), "rank": r, "icon": "rank",
        })
    for key, name, desc, _need, amount in GEM_WIN_MILESTONES:
        out.append({"key": key, "group": "Milestones", "name": name,
                    "desc": desc, "gems": amount, "rank": None, "icon": "gem"})
    for key, group, name, desc, gems, icon, _need in _ACH_EXTRA:
        out.append({"key": key, "group": group, "name": name, "desc": desc,
                    "gems": gems, "rank": None, "icon": icon})
    for a in out:
        a["unlocks"] = list(ACH_UNLOCKS.get(a["key"], ()))
    order = {g: i for i, g in enumerate(ACH_GROUPS)}
    out.sort(key=lambda a: order.get(a["group"], 99))
    return out


def _ach_need(key, f):
    """(have, need) for one achievement against a player's facts."""
    if key.startswith("div-"):
        r = ranks.RANK_BY_KEY.get(key[4:])
        return (f["peak"], r["level"]) if r else (0, 1)
    for k, _n, _d, need, _a in GEM_WIN_MILESTONES:
        if k == key:
            return (f["wins"], need)
    for row in _ACH_EXTRA:
        if row[0] == key:
            return row[6](f)
    return (0, 1)


def _ach_facts(c, nn):
    """Everything the rules look at, read once."""
    f = {"peak": gem_peak_level(c, nn), "wins": 0, "games": 0, "surv": 0, "ships": set(),
         "bought": 0, "cos": set(), "bought_cos": 0, "worn": 0, "spent": 0, "earned": 0,
         "best": 0, "total": 0, "deaths": 0, "days": 0, "regions": 0, "friends": 0,
         "clan": False, "officer": False, "hours": 0}
    try:
        r = c.execute("SELECT COALESCE(wins, 0), COALESCE(losses, 0), clan, google_sub, cosmetics, name "
                      "FROM players WHERE norm_name = ?", (nn,)).fetchone()
        if r:
            f["wins"] = int(r[0] or 0)
            f["games"] = int(r[0] or 0) + int(r[1] or 0)
            f["clan"] = bool(r[2])
            f["worn"] = len(_worn_cosmetics(r[4]))
            if r[3]:
                a = c.execute("SELECT 1 FROM clan_admins WHERE google_sub = ? "
                              "AND COALESCE(role, 'leader') IN ('leader', 'coleader') LIMIT 1",
                              (r[3],)).fetchone()
                f["officer"] = bool(a)
            if r[5]:
                f["regions"] = sum(1 for x in region_split(c, r[5]) if x.get("played"))
        sv = c.execute("SELECT COALESCE(wins, 0) FROM survival_players WHERE norm_name = ?",
                       (nn,)).fetchone()
        f["surv"] = int(sv[0]) if sv else 0
        own = owned_ships(c, nn)
        f["ships"] = set(own)
        f["bought"] = sum(1 for v in own.values() if v == "bought")
        f["cos"] = owned_cosmetics(c, nn)
        f["bought_cos"] = sum(1 for i in f["cos"] if not COSMETIC_BY_ID[i]["via"])
        sp = c.execute("SELECT COALESCE(-SUM(CASE WHEN amount < 0 AND reason = 'purchase' THEN amount ELSE 0 END), 0), "
                       "COALESCE(SUM(CASE WHEN amount > 0 THEN amount ELSE 0 END), 0), "
                       "SUM(CASE WHEN reason = 'daily-win' THEN 1 ELSE 0 END) "
                       "FROM gem_ledger WHERE owner_kind = 'player' AND owner = ?", (nn,)).fetchone()
        f["spent"], f["earned"], f["days"] = int(sp[0] or 0), int(sp[1] or 0), int(sp[2] or 0)
        # Score and deaths come from the rated matches themselves, back past
        # any wipe: what you did happened, whatever the record shows.
        sc = c.execute("SELECT COALESCE(MAX(score), 0), COALESCE(SUM(score), 0), COALESCE(SUM(deaths), 0) "
                       "FROM match_players WHERE norm_name = ?", (nn,)).fetchone()
        f["best"], f["total"], f["deaths"] = int(sc[0] or 0), int(sc[1] or 0), int(sc[2] or 0)
        f["friends"] = len(friends_of(c, nn))
        # Whole hours only - an achievement that ticks over mid-match reads
        # as a bug, and nobody counts their playtime in seconds.
        f["hours"] = played_seconds(c, nn) // 3600
    except sqlite3.Error:
        pass
    return f


def ach_status(c, nn):
    """The catalogue with this player's standing on each: have/need,
    unlocked (done), claimed (paid - a ledger row), ready (done, unpaid)."""
    f = _ach_facts(c, nn)
    claimed = {}
    try:
        for ref, at in c.execute("SELECT ref, at FROM gem_ledger WHERE owner_kind = 'player' "
                                 "AND owner = ? AND reason = 'achievement'", (nn,)).fetchall():
            claimed[ref] = at
    except sqlite3.Error:
        pass
    out = []
    for a in gem_achievement_catalog():
        have, need = _ach_need(a["key"], f)
        need = max(1, int(need))
        have = max(0, min(int(have), need))
        d = dict(a, have=have, need=need, unlocked=have >= need,
                 claimed=a["key"] in claimed, at=(claimed.get(a["key"]) or "")[:10])
        d["ready"] = d["unlocked"] and not d["claimed"]
        d["unlock_items"] = [COSMETIC_BY_ID[i] for i in a.get("unlocks", ()) if i in COSMETIC_BY_ID]
        out.append(d)
    return out


def played_seconds(c, nn, days=None):
    """Seconds this player has been in rated matches - all of them, or the
    last `days`. Results from before the watcher reported a duration carry
    NULL and are simply not counted."""
    sql = ("SELECT COALESCE(SUM(mp.played_s), 0) FROM match_players mp "
           "JOIN matches m ON m.id = mp.match_row "
           "WHERE mp.norm_name = ? AND mp.played_s IS NOT NULL "
           "AND COALESCE(m.voided, 0) = 0")
    args = [nn]
    if days:
        sql += " AND m.played_at > datetime('now', ?)"
        args.append('-%d days' % int(days))
    try:
        r = c.execute(sql, args).fetchone()
    except sqlite3.Error:
        return 0
    return int(r[0] or 0)


def pretty_hours(secs):
    """'12h 30m', or '45m' under an hour, or '-' for nothing yet."""
    secs = int(secs or 0)
    if secs <= 0:
        return "-"
    h, m = secs // 3600, (secs % 3600) // 60
    if h:
        return "%dh %dm" % (h, m) if m else "%dh" % h
    return "%dm" % m if m else "under a minute"


def ach_earned(c, nn):
    """The achievements this player has claimed, newest first. Read off the
    ledger alone - no facts recomputed - because a profile only needs to
    know what was earned, not how close anything else is."""
    got = {}
    try:
        for ref, at in c.execute("SELECT ref, at FROM gem_ledger WHERE owner_kind = 'player' "
                                 "AND owner = ? AND reason = 'achievement'", (nn,)).fetchall():
            got[ref] = at or ""
    except sqlite3.Error:
        return []
    if not got:
        return []
    out = [dict(a, at=got[a["key"]][:10]) for a in gem_achievement_catalog()
           if a["key"] in got]
    out.sort(key=lambda a: a["at"], reverse=True)
    return out


SANDBOX_SUB = "test:sandbox"
# The sandbox can be given a rating so the signed-in site renders at a chosen
# standard (see /dev/actas). That makes it look exactly like a player to any
# query that counts them, so every such query carries this and leaves it out:
# the board, the search index, a clan's roster and a clan's averages. Written
# once, here, so the list of places is greppable rather than remembered.
# Every test account, the owner's and each tester's (test:sandbox:<key>),
# is kept off the board, out of clan averages and out of every listing.
NOT_SANDBOX = "COALESCE(google_sub, '') NOT LIKE '%s%%'" % SANDBOX_SUB

# One name per Google account. A network was never a person - everyone
# behind one home, school or mobile connection shared a single address, so
# the old per-network cap both let one player take several names from
# different networks and stopped several real players sharing one.
MAX_NAMES_PER_ACCOUNT = 1

# Protection can only be flipped once a day. Without a cooldown it is a
# switch you could throw the moment a match looked like going badly: leave
# it off while winning, turn it on to void the losses. The rating only means
# something if the choice is made in advance and lived with.
PROTECTION_COOLDOWN_HOURS = 24
DECLINE_COOLDOWN_DAYS = 7     # after a no, the one who was turned down waits

# A claim is unproven by definition, so an unlimited supply of them is just
# a way to bury the real ones - and every new claim raises an alert.
MAX_PENDING_CLAIMS = 3

# How many times an account name may be changed after it is first set. The
# name is an identity other players recognise on the board, so it is not a
# thing to churn - but one correction for a typo or a rethink is fair.
MAX_ACCOUNT_NAME_CHANGES = 1

# Bug reports allowed from one address per day. High enough that somebody
# working through several real problems is never blocked, low enough that
# the page cannot be used to flood the review queue.
MAX_REPORTS_PER_DAY = 10

# What a report can be about. The kind is only a label to sort by - every
# one of them lands in the same list.
REPORT_KINDS = [
    ("bug", "Something is broken"),
    ("result", "A match result is wrong"),
    ("name", "Someone is using my name"),
    ("idea", "Suggestion"),
    ("other", "Something else"),
]

# Wins needed, AFTER the claim is filed, before a name is handed over.
# This is a cost, not a proof: a Starblast name is not a credential, so
# nothing observed in game can tell the real owner from somebody wearing
# their name. What it does is make taking someone's name require actually
# playing as them and winning, while the claim sits publicly on that
# player's page for the real owner to see and report.
CLAIM_WINS_REQUIRED = 1

# A match the tracker gave up on may still have been running when it walked
# away, so scoring it is a judgement call. Late games fill up with bots as
# real players drift off, and a game thinned out to a handful of genuine
# players is effectively over - calling that one by score is safe. One that
# still has a real crowd in it is very much alive, and guessing a winner
# there would hand out ratings for a match nobody had finished.
ABANDON_MAX_REAL_PLAYERS = 10

STARTING_ELO = 1000
ELO_K = 200    # max elo swing for a single match, approached as the result gets more lopsided
ELO_SCALE = 2000  # rating-gap scale: bigger = ratings must differ more before the odds shift sharply

# A rating means less when it is built on two games than on two hundred,
# so new players move faster to find their level and settled players are
# not whipped around by them (7.0.0). Measured 23 Aug 2026: 77% of the
# board had fewer than 5 games while every player moved at the same K.
PROVISIONAL_GAMES = 5
ESTABLISHED_GAMES = 20
PROVISIONAL_K_MULT = 1.4
ESTABLISHED_K_MULT = 0.8

# How strongly a roster's rating is pulled toward the starting rating
# when few of its players are known. Only 58% of the players in a live
# match are on the leaderboard; counting every stranger as exactly 1000
# made a team's strength depend on how many strangers happened to be
# aboard rather than on how good the known players were.
TEAM_PRIOR_WEIGHT = 3.0

# --- Survival placement Elo (v1, review-only, 9.2.0) ---------------------
# A passive observer sees only who is left and in what ORDER they fall - no
# score, kills or deaths - so survival is a battle-royale PLACEMENT rating:
# each round is decomposed into pairwise finish results, field-size-normalised
# so a big lobby doesn't over-swing, from zero at 1000 and near zero-sum per
# round. Kept apart from the team board - different skill, different number.
SURV_START = 1000
SURV_SCALE = 2000            # same rating-gap scale as the team board
SURV_K = 64                 # max per-round swing; an even-field win is ~+K/2
SURV_PROVISIONAL_ROUNDS = 5
SURV_PROVISIONAL_K_MULT = 1.4
SURV_MIN_FIELD = 4          # ignore rounds where fewer than this reached elimination

# The least a late arrival's result can be worth. Turning up for the last
# minute should count for very little - but never for nothing, or a real
# player who genuinely fought at the end walks away with no record of it.
LATE_JOIN_FLOOR = 0.15

# Minimum score to COLLECT A WIN - idling on the winning team earns
# nothing. Losers have NO floor at all (owner's rule): they usually finish
# small precisely because they lost, holding them to a bar let whole
# losing teams dodge their losses (feeds full of matches with zero
# losers), and any floor is gameable - a loser can suicide their score
# under it on purpose. The assembled losing team takes the loss, full
# stop; spectator bodies are already stripped upstream. A player with NO
# recorded score is still rated - missing evidence never drops anyone.
MIN_RATED_SCORE = 1000        # to collect a win (legacy: on FINAL score)
# Owner's rule (5 Sep 2026): eligibility is judged on the PEAK score a player
# ever reached, not their final one. A defender killed repeatedly to a low
# final score still fought (they peaked high); a late-joining idler never
# climbed. When the payload carries peak_scores, a winner needs this peak to
# collect - which fixes wins lost to end-game score collapse and still filters
# drive-by joiners. Falls back to MIN_RATED_SCORE on the final score for any
# payload without peak_scores.
MIN_RATED_PEAK = 2000

# Anchored to this file's own directory rather than a bare relative path,
# since different hosts (PythonAnywhere vs the droplet) run this with
# different working directories.
# How long a request will wait for the write lock before giving up. The
# tracker writes every few seconds, so a user's write regularly has to
# queue behind one; five seconds - sqlite3's default - was short enough
# that saving a name failed outright during a busy push.
DB_TIMEOUT_SECONDS = 30

# What the tracker's own lobby push will wait. It re-sends the complete
# state every sweep, so a push that cannot get the lock has lost nothing
# by giving up - whereas holding on past the tracker's 10-second client
# timeout means the reply is thrown away AND a web worker was blocked for
# the whole time. Must stay comfortably under that client timeout.
PUSH_TIMEOUT_SECONDS = 4


def db(timeout=None):
    """A connection that waits its turn instead of failing.

    Pass a shorter timeout for anything that runs on a schedule and will
    be retried anyway. Blocking such a request only ties up a web worker
    while its caller has already given up on it.
    """
    if timeout is None:
        timeout = DB_TIMEOUT_SECONDS
    conn = sqlite3.connect(DB_PATH, timeout=timeout)
    # timeout= covers the driver's own retry loop; busy_timeout covers
    # locks hit inside a statement SQLite is already executing. Both are
    # needed, and they are cheap.
    conn.execute("PRAGMA busy_timeout = %d" % int(timeout * 1000))
    return conn


BASE_DIR = os.path.dirname(os.path.abspath(__file__))
DB_PATH = os.path.join(BASE_DIR, 'players.db')

# Only the tracker bot should be able to report match results - this
# endpoint is reachable by anyone on the internet, so require a shared
# secret to prevent random visitors from POSTing fake match results.
#
# Keys live in api_keys.txt beside this file, one per line - never in the
# source, which is public. Several keys are valid at once, so a key can
# be rotated with no window in which real match reports are dropped.
def _load_api_keys():
    try:
        with open(os.path.join(BASE_DIR, 'api_keys.txt')) as _f:
            return {ln.strip() for ln in _f if ln.strip()}
    except OSError:
        return set()


def api_key_ok(key):
    return bool(key) and key in _load_api_keys()


# --- Live match state (owner-only win-probability view) --------------------
# The website cannot reach the tracker (PythonAnywhere blocks outbound calls),
# so a small feed process on the droplet tails the tracker's per-read log and
# POSTs each watched lobby's live team scores/counts to /api/live/state. Kept
# in its OWN sqlite file so these frequent writes never contend with players.db.
LIVE_DB_PATH = os.path.join(BASE_DIR, 'live.db')
# Replay trajectories live in their OWN file too (9.3.0): they are large
# (~70KB/match) and only the replay page ever reads them, so keeping them out
# of players.db stops the big blob writes from locking the hot board queries
# and keeps players.db small and fast. Same reasoning as live.db above.
REPLAY_DB_PATH = os.path.join(BASE_DIR, 'replays.db')
LIVE_STALE_SECONDS = 70    # a lobby not updated within this is treated as gone
LIVE_TRAJ_CAP = 600        # reads kept per lobby: the WHOLE match (~100 min at
                           # ~10s/read), so a finished match can be snapshotted
                           # as a replay. The /live view still slices the tail.
LIVE_TEAMS = ("team_1", "team_2", "team_3")

# Trained win-probability model: a conditional logit over the alive teams,
# trained on ~143k ten-second reads across 1011 matches (see winprob notes).
# Features per team: score_share, count_share, score_margin, count_margin,
# top_score, top_count, then each share/margin x game-progress.
_WP_W = [1.1295076628447995, 0.46926494423388093, 1.5665834227690387,
         0.5415906485501419, 0.08886121945581577, 0.20478138329227297,
         -0.23838655751300555, -0.7290679303463938, 0.23254840970750054,
         0.22969712735760298]
_WP_TSCALE = 1400.0


def _station_state(v):
    """(level, gems, modules_dead, mean_module_hp) from either station form.

    Full tracker form: [level, gems, alive, total, weak, dead, [hp x12]];
    slim replay form:  [level, gems, [hp x12]]. Any element may be None
    during a telemetry blank - a None stays None and the feature built
    from it stays neutral."""
    if not isinstance(v, (list, tuple)) or len(v) < 3:
        return (None, None, None, None)
    lvl = v[0] if isinstance(v[0], (int, float)) else None
    gems = v[1] if isinstance(v[1], (int, float)) else None
    hp12 = v[-1] if isinstance(v[-1], (list, tuple)) else None
    dead = None
    if len(v) >= 6 and isinstance(v[5], (int, float)):
        dead = v[5]
    elif hp12:
        dead = sum(1 for h in hp12 if h == 0)
    mhp = (float(sum(hp12)) / len(hp12)) if hp12 else None
    return (lvl, gems, dead, mhp)


def _station_usable(d):
    """True if this stations dict carries at least one real reading -
    during a feed blank the tuples are present but all None, which must
    not count as evidence."""
    if not isinstance(d, dict):
        return False
    return any(x is not None for v in d.values()
               for x in _station_state(v))


def win_probability(counts, scores, elapsed_seconds=None, weights=None,
                    skills=None, depth=None, window=None, stations=None):
    """Each team's probability of winning, from current counts + scores (and
    how long the match has run). A team with 0 players is out (probability 0).
    Returns {team_key: prob} summing to 1 over the teams that can still win.

    `weights` lets the daily-retrained model override the built-in defaults,
    and its LENGTH selects the feature set (each size is a prefix of the next,
    so old models keep working):
      10  score/count only
      13  + roster skill: `skills` maps team -> top-2 leaderboard Elo
      19  + time-shape over `window` (recent [(t, scores)] reads: lead share,
          drawdown from peak, 60s trend) and roster `depth` per team
          ((winrate, games, clan-stack)). Every extra feature is neutral when
          its data is missing, so the model degrades gracefully.
      23  + station margins from `stations` (team -> station tuple, full or
          slim form): level, gem bank, modules destroyed, mean module HP -
          the on-map evidence a scoreboard cannot see."""
    import math
    W = _WP_W
    if weights and len(weights) in (10, 13, 19, 23):
        W = weights
    keys = list(LIVE_TEAMS)
    score = {k: max(0.0, float(scores.get(k, 0) or 0)) for k in keys}
    count = {k: max(0, int(counts.get(k, 0) or 0)) for k in keys}
    alive = [k for k in keys if count[k] > 0]
    if not alive:
        tot = sum(score.values()) or 1.0
        return {k: score[k] / tot for k in keys}
    if len(alive) == 1:
        return {k: (1.0 if k == alive[0] else 0.0) for k in keys}
    if elapsed_seconds is None:
        prog = min(1.0, max(score.values()) / 74000.0)
    else:
        prog = min(1.0, max(0.0, float(elapsed_seconds)) / _WP_TSCALE)
    ssum = sum(score[k] for k in alive) + 1.0
    nsum = sum(count[k] for k in alive) + 1.0
    smax = max(score[k] for k in alive)
    nmax = max(count[k] for k in alive)
    util = {}
    for k in alive:
        s, n = score[k], count[k]
        os_ = max((score[j] for j in alive if j != k), default=0.0)
        on_ = max((count[j] for j in alive if j != k), default=0)
        ss = s / ssum
        cs = n / nsum
        sm = (s - os_) / ssum
        cm = (n - on_) / nsum
        tsc = 1.0 if s == smax else 0.0
        tcc = 1.0 if n == nmax else 0.0
        x = [ss, cs, sm, cm, tsc, tcc, ss * prog, sm * prog, cs * prog, cm * prog]
        if len(W) >= 13:
            sk = {j: float((skills or {}).get(j) or 1000.0) for j in alive}
            sk_sum = sum(sk.values()) or 1.0
            rival = max((sk[j] for j in alive if j != k), default=1000.0)
            sk_margin = (sk[k] - rival) / 1000.0
            x += [sk_margin, sk_margin * (1.0 - prog),
                  sk[k] / sk_sum - 1.0 / len(alive)]
        if len(W) >= 19:
            led = 0.0
            peak = s
            s_old = None
            if window:
                tops = 0
                tcur = window[-1][0]
                for (tw, sw) in window:
                    vals = {j: sw.get(j, 0) for j in keys}
                    if vals.get(k, 0) == max(vals.values()) and vals.get(k, 0) > 0:
                        tops += 1
                    if sw.get(k, 0) > peak:
                        peak = sw.get(k, 0)
                    if s_old is None and tcur - tw <= 60.5:
                        s_old = sw.get(k, 0)
                led = tops / len(window)
            dd = (peak - s) / (peak + 1000.0)
            tr = 0.0
            if s_old is not None:
                tr = max(-1.0, min(1.0, (s - s_old) / ssum))
            dp = depth or {}
            wr_k, g_k, st_k = dp.get(k) or (0.5, 0, 0)
            r_wr = max(((dp.get(j) or (0.5, 0, 0))[0] for j in alive if j != k),
                       default=0.5)
            r_g = max(((dp.get(j) or (0.5, 0, 0))[1] for j in alive if j != k),
                      default=0)
            r_st = max(((dp.get(j) or (0.5, 0, 0))[2] for j in alive if j != k),
                       default=0)
            x += [led, dd, tr, wr_k - r_wr,
                  (math.log1p(g_k) - math.log1p(r_g)) / 8.0,
                  (st_k - r_st) / 4.0]
        if len(W) == 23:
            stn = stations or {}
            own = _station_state(stn.get(k))
            riv = [_station_state(stn.get(j)) for j in alive if j != k]
            lvm = gm = dm = hpm = 0.0
            _rl = [r[0] for r in riv if r[0] is not None]
            if own[0] is not None and _rl:
                lvm = (own[0] - max(_rl)) / 4.0
            _rg2 = [r[1] for r in riv if r[1] is not None]
            if own[1] is not None and _rg2:
                gm = (own[1] - max(_rg2)) / 6400.0
            _rd = [r[2] for r in riv if r[2] is not None]
            if own[2] is not None and _rd:
                dm = (min(_rd) - own[2]) / 12.0
            _rh = [r[3] for r in riv if r[3] is not None]
            if own[3] is not None and _rh:
                hpm = (own[3] - max(_rh)) / 255.0
            x += [lvm, gm, dm, hpm]
        util[k] = sum(W[i] * x[i] for i in range(len(W)))
    m = max(util.values())
    ex = {k: math.exp(util[k] - m) for k in alive}
    z = sum(ex.values())
    out = {k: 0.0 for k in keys}
    for k in alive:
        out[k] = ex[k] / z
    return out


_TSR_MIGRATED = False


def _ensure_replay_indexes(conn, schema=''):
    """The two indexes the Replays listing walks: replays by lobby and end
    time (is this match replayable?) and the no-result rows by end time.
    Both covering, so the listing never touches the trajectory blobs. Safe
    to call on every connection; a no-op once they exist."""
    for name, cols in (("idx_tsreplay_sys_at", "(sys_id, at)"),
                       ("idx_tsreplay_nr", "(no_result, at)")):
        try:
            conn.execute("CREATE INDEX IF NOT EXISTS %s%s ON trueskill_replay %s"
                         % (schema, name, cols))
        except sqlite3.Error:
            pass


def replay_db():
    """Connection to the replay-trajectory database (trueskill_replay), kept
    separate from players.db so its large blob writes never lock the board."""
    conn = sqlite3.connect(REPLAY_DB_PATH, timeout=5)
    conn.execute("PRAGMA busy_timeout = 5000")
    conn.execute("CREATE TABLE IF NOT EXISTS trueskill_replay ("
                 "match_key TEXT PRIMARY KEY, sys_id INTEGER, at TEXT, "
                 "region TEXT, first_ts REAL, data BLOB)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_tsreplay_sys "
                 "ON trueskill_replay(sys_id, first_ts)")
    # A replay that was recorded but never scored carries what the listing
    # needs to show it beside the scored ones: the lobby name, how many played,
    # how long, and why it has no result. Migrated once per process.
    global _TSR_MIGRATED
    if not _TSR_MIGRATED:
        for _col in ("name TEXT", "players INTEGER", "dur_s REAL",
                     "no_result INTEGER DEFAULT 0", "reason TEXT"):
            try:
                conn.execute("ALTER TABLE trueskill_replay ADD COLUMN " + _col)
            except sqlite3.OperationalError:
                pass
        _TSR_MIGRATED = True
    _ensure_replay_indexes(conn)
    return conn


def live_db():
    conn = sqlite3.connect(LIVE_DB_PATH, timeout=5)
    conn.execute("PRAGMA busy_timeout = 5000")
    conn.execute("CREATE TABLE IF NOT EXISTS live ("
                 "sys_id INTEGER PRIMARY KEY, updated REAL, elapsed REAL, "
                 "region TEXT, name TEXT, payload TEXT)")
    # The PREVIOUS match's trajectory for each lobby, one deep. When a new
    # match starts in the same sys the live row resets - but the ended
    # match's result usually arrives AFTER that reset, and discarding the
    # old trajectory cost the replay (Albiratos #8039: a single fresh-clock
    # frame 71 seconds before scoring wiped a 30-minute recording).
    conn.execute("CREATE TABLE IF NOT EXISTS live_prev ("
                 "sys_id INTEGER PRIMARY KEY, saved REAL, payload TEXT)")
    conn.execute("CREATE TABLE IF NOT EXISTS model ("
                 "id INTEGER PRIMARY KEY, weights TEXT, meta TEXT, updated REAL)")
    # The SHADOW win-probability model (from t=0, trained on the raw_observer
    # full-match feed) - a DIFFERENT model from `model` above, which is the
    # old 20-minute browser-tracker one. Kept in its own row so the two never
    # collide. Posted daily by winprob/shadow_wp_train.py. 7.9.0.
    conn.execute("CREATE TABLE IF NOT EXISTS shadow_model ("
                 "id INTEGER PRIMARY KEY, weights TEXT, meta TEXT, updated REAL)")
    # The from-the-opening raw_observer feed - one row per lobby, latest
    # snapshot only. Separate from `live` (the browser tracker) so the two
    # never collide; this is the parallel early-entry viewer (7.5.0).
    conn.execute("CREATE TABLE IF NOT EXISTS rawlive ("
                 "sys_id INTEGER PRIMARY KEY, updated REAL, payload TEXT)")
    # A short rolling history of raw_observer snapshots (a few minutes), so the
    # PUBLIC /rawlive can be served ~2 minutes behind. Signed-in owner still
    # reads the latest `rawlive` row; the public reads the closest hist row
    # older than the delay. Pruned on every ingest. 7.9.2.
    conn.execute("CREATE TABLE IF NOT EXISTS rawlive_hist ("
                 "sys_id INTEGER, updated REAL, payload TEXT)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_rawlive_hist "
                 "ON rawlive_hist(sys_id, updated)")
    # Asteroid field per map seed, baked once by asteroid_baker.py (the
    # field is deterministic + static per seed). Positions already in the
    # radar's +/-128 space. 7.6.0.
    conn.execute("CREATE TABLE IF NOT EXISTS asteroids ("
                 "seed INTEGER PRIMARY KEY, data TEXT, baked REAL)")
    return conn


def load_live_model():
    """Current win-probability weights + metadata, set by the daily retrain.
    Falls back to the built-in weights until the first retrain has run."""
    try:
        conn = live_db()
        r = conn.execute("SELECT weights, meta FROM model WHERE id=1").fetchone()
        conn.close()
        if r and r[0]:
            w = json.loads(r[0])
            meta = json.loads(r[1]) if r[1] else {}
            if isinstance(w, list) and len(w) in (10, 13, 19, 23):
                return w, meta
    except Exception:
        pass
    return None, None


# --- SHADOW win probability (from t=0) --------------------------------------
# Trained on the raw_observer full-match feed by winprob/shadow_wp_train.py.
# COMPLETELY SEPARATE from the live model above (which scores the 20-minute
# browser tracker). The feature builder below MUST stay byte-for-byte in step
# with feats_for_read() in shadow_wp_train.py - if you change one, change both,
# or the site will score live lobbies with features the model never saw.
SHADOW_WP_FEATURES = ["ss", "sm", "cs", "cm", "lvlm", "deadm", "hpm", "tierm",
                      "avgtierm", "conc", "skillm", "smXp", "cmXp", "hmXp",
                      "lmXp", "tmXp", "skillEarly", "prog", "bias"]
# Baked from the first real train (467 matches, acc 0.596) so /rawlive shows
# probabilities immediately, before the daily retrain has posted once. The DB
# row (set by the trainer) overrides this whenever present.
SHADOW_WP_BUILTIN = [0.155, 1.615, -0.099, -0.313, 0.406, 0.908, 0.915, 0.227,
                     0.881, -0.756, 0.723, -0.492, 1.042, 0.958, 0.38, -0.347,
                     -0.788, 0.0, 0.0]


_SHADOW_WP_CACHE = {"w": None, "meta": None, "at": 0.0}


def load_shadow_wp_model():
    """Current shadow win-prob weights + meta. Falls back to the built-in
    weights until the daily retrain has posted at least once. Cached for 60s
    so /rawlive doesn't do a DB read on every 1.5s poll (the model only
    changes once a day)."""
    now = time.time()
    if _SHADOW_WP_CACHE["w"] is not None and now - _SHADOW_WP_CACHE["at"] < 60:
        return _SHADOW_WP_CACHE["w"], _SHADOW_WP_CACHE["meta"]
    w, meta = SHADOW_WP_BUILTIN, {"builtin": True}
    try:
        conn = live_db()
        r = conn.execute("SELECT weights, meta FROM shadow_model WHERE id=1").fetchone()
        conn.close()
        if r and r[0]:
            _w = json.loads(r[0])
            if isinstance(_w, list) and len(_w) == len(SHADOW_WP_FEATURES):
                w = _w
                meta = json.loads(r[1]) if r[1] else {}
    except Exception:
        pass
    _SHADOW_WP_CACHE.update(w=w, meta=meta, at=now)
    return w, meta


def _shadow_wp_stat(sh, ti):
    """Station (lvl, gems, dead, hp) for team index ti - mirrors trainer.stat."""
    if not (isinstance(sh, list) and ti < len(sh) and isinstance(sh[ti], dict)):
        return (0, 0, 12, 0.0)
    s = sh[ti]
    mods = s.get("mods") or []
    hp = (sum(mods) / (255.0 * len(mods))) if mods else 0.0
    return (s.get("lvl", 0) or 0, s.get("gems", 0) or 0, s.get("dead", 0) or 0, hp)


def _shadow_wp_agg(rd, i, elo_map):
    """Roster aggregates (maxtier, avgtier, top-2 score share, top-2 mean elo)
    for team index i - mirrors trainer.agg."""
    ros = (rd.get("teams") or {}).get("team_%d" % (i + 1)) or []
    scs = sorted([(r[1] or 0) for r in ros if r], reverse=True)
    tot = sum(scs) or 1
    maxt = max([(r[2] or 0) for r in ros] or [0])
    avgt = (sum((r[2] or 0) for r in ros) / len(ros)) if ros else 0
    top2 = (sum(scs[:2]) / tot) if scs else 0
    els = sorted([elo_map.get(normalize_name(r[0]), 1000.0)
                  for r in ros if r and r[0]], reverse=True)
    return maxt, avgt, top2, ((sum(els[:2]) / len(els[:2])) if els else 1000.0)


def _shadow_wp_feats(rd, elo_map, prog):
    """Per-alive-team feature vectors from one raw snapshot. MUST match
    feats_for_read() in shadow_wp_train.py exactly (same order, same math)."""
    sc = rd.get("scores") or {}
    ct = rd.get("counts") or {}
    tot = sum(sc.values())
    if tot < 5000:
        return None
    alive = [i for i in range(3) if (ct.get("team_%d" % (i + 1), 0) or 0) > 0]
    if len(alive) < 2:
        return None
    ts = float(tot)
    tc = float(sum(ct.values())) or 1.0
    AG = {i: _shadow_wp_agg(rd, i, elo_map) for i in alive}
    ST = {i: _shadow_wp_stat(rd.get("sh"), i) for i in alive}
    out = {}
    for i in alive:
        si = sc.get("team_%d" % (i + 1), 0) or 0
        ci = ct.get("team_%d" % (i + 1), 0) or 0
        lv, gm, dd, hp = ST[i]
        maxt, avgt, top2, skill = AG[i]
        R = [j for j in alive if j != i]
        rmax = lambda f: max([f(j) for j in R] or [0])
        ss = si / ts
        cs = ci / tc
        sm = (si - rmax(lambda j: sc.get("team_%d" % (j + 1), 0) or 0)) / (ts + 1)
        cm = (ci - rmax(lambda j: ct.get("team_%d" % (j + 1), 0) or 0)) / (tc + 1)
        lm = (lv - rmax(lambda j: ST[j][0])) / 4.0
        dm = (rmax(lambda j: ST[j][2]) - dd) / 12.0
        hm = hp - rmax(lambda j: ST[j][3])
        tm = (maxt - rmax(lambda j: AG[j][0])) / 7.0
        atm = (avgt - rmax(lambda j: AG[j][1])) / 7.0
        skm = (skill - rmax(lambda j: AG[j][3])) / 400.0
        out[i] = [ss, sm, cs, cm, lm, dm, hm, tm, atm, top2, skm,
                  sm * prog, cm * prog, hm * prog, lm * prog, tm * prog,
                  skm * (1 - prog), prog, 1.0]
    return out


def shadow_win_probability(rd, elo_map, weights, prog):
    """P(win) per alive team index for one raw snapshot, or None when the
    match is too young / one-sided to score (mirrors the trainer's gate)."""
    f = _shadow_wp_feats(rd, elo_map, prog)
    if not f:
        return None
    nf = len(SHADOW_WP_FEATURES)
    xs = {i: sum(weights[k] * f[i][k] for k in range(nf)) for i in f}
    m = max(xs.values())
    ex = {i: math.exp(xs[i] - m) for i in xs}
    z = sum(ex.values()) or 1.0
    return {i: ex[i] / z for i in ex}



# Format-only validation (letters, length) isn't content moderation -
# this is a public site, so also screen the name's content.
#
# Two lists, because a blanket substring match causes real false
# positives on an 8-character namespace: "SPIC" is inside "SPICY",
# "COON" inside "RACCOON", "RAPE" inside "GRAPE", "ANAL" inside
# "ANALOG". So only unambiguous terms are matched anywhere in the name;
# short words with innocent uses are rejected only as the entire name.
