def detect_clan(raw_name, tags=None):
    """Clan tag for a name as the tracker actually read it, or None.

    Must run on the RAW OCR name: the stored name is already normalised,
    and normalising destroys the brackets and spaces that make a tag
    unambiguous ("F4 * YISUS" and "[SR] BOB" both lose their separator).

    Two passes, strongest evidence first. A tag standing alone as its own
    token is near-certain. A fused prefix (F4ISAAC) is likely but not
    safe - SRSLY starts with SR and belongs to nobody - so longer tags win
    ties and the prefix pass is deliberately last.
    """
    if not raw_name:
        return None
    if tags is None:
        tags = all_clan_tags()
    upper = str(raw_name).upper()
    for tag in tags:
        for m in re.finditer(r'(?<![A-Z0-9])' + re.escape(tag)
                             + r'(?![A-Z0-9])', upper):
            # A token only counts as a TAG when it is dressed like one:
            # touching a bracket, emoji or other separator symbol, or
            # leading the name. Flanked by nothing but spaces it is just
            # a word - the clan 'IS' had 37 members because TWILIGHT IS
            # HERE, THIS IS SPARTA!! and the entire HOMI IS... family
            # matched the English verb (24 Aug 2026).
            before = upper[m.start() - 1] if m.start() > 0 else None
            after = upper[m.end()] if m.end() < len(upper) else None
            if (m.start() == 0
                    or (before is not None and not before.isspace())
                    or (after is not None and not after.isspace())):
                return tag
    key = normalize_name(raw_name)
    if key.upper() in COMMON_PERSONAL_NAMES:
        return None
    for tag in tags:
        if key.startswith(tag) and len(key) > len(tag):
            return tag
    return None


# Letters people write with symbols. Starblast names are full of these -
# the tag pasted as ₣ⱠⱤ⇝ is F, L, R with an arrow stuck on the end -
# and treating a currency sign as punctuation threw the letter away, so
# ₣ⱠⱤ⇝ became ⱠⱤ and ₵ØV became ØV. Uppercase keys: the text is
# upper-cased before this is applied.
TAG_FOLD = {
    "₣": "F", "₤": "L", "£": "L", "Ⱡ": "L", "Ł": "L",
    "₵": "C", "¢": "C", "₡": "C",
    "Ø": "O", "Ɵ": "O", "Ő": "O",
    "₦": "N", "Ñ": "N", "Ń": "N",
    "₱": "P", "Ᵽ": "P", "ᵽ": "P",
    "₮": "T", "Ŧ": "T", "Ⱦ": "T",
    "₴": "S", "Ꞩ": "S", "Ş": "S", "Š": "S",
    "₭": "K", "Ꝁ": "K",
    "¥": "Y", "Ɏ": "Y",
    "€": "E", "Ɇ": "E",
    "₹": "R", "Ɽ": "R",
    "Ƀ": "B", "฿": "B",
    "Đ": "D", "Ð": "D",
    "Ħ": "H", "Ɨ": "I", "ᵹ": "G", "Ǥ": "G",
    "Ꞷ": "W", "₩": "W", "Ʉ": "U", "Ʌ": "A",
    "Ⱥ": "A", "Ȼ": "C", "Ɍ": "R", "Ɖ": "D", "Ɗ": "D", "Ƒ": "F",
    "Ɠ": "G", "Ɫ": "L", "Ɱ": "M", "Ɲ": "N", "Ƥ": "P", "Ƭ": "T",
    "Ʋ": "V", "Ƴ": "Y", "Ƶ": "Z", "Ǝ": "E", "Ꝁ": "K", "Ꞣ": "K",
    # Look-alike DIGITS people style tags with. Without these the fold drops
    # the non-Latin glyph and the tag can't be matched: the S2F clan writes
    # its tag "SᄅF" (Hangul ᄅ as a 2), which folded to "SF" and made every
    # member unmatchable to /clan/add, search and the clan page (7 Sep 2026).
    "ᄅ": "2", "Ꙅ": "2", "ƻ": "2",
}


def clean_clan_tag(text):
    """A clan tag as stored: alphanumerics only, uppercased, Unicode kept.

    Real tags on this leaderboard are not ASCII - [G\u039e], \u20b5\u00d8V, \u0141S and
    \u2325\u0191\u1566 are all live clans. Stripping to A-Z0-9 reduced those to a single
    letter or to nothing, which made them fail the length check and be
    impossible to claim at all. isalnum() is Unicode-aware, so a Greek or
    Latin-extended letter counts as a letter, while brackets, arrows and
    currency signs are still dropped.
    """
    raw = ''.join(TAG_FOLD.get(ch, ch) for ch in str(text or '').upper())
    # NFKD takes the accents off everything ordinary, so É and E are one
    # clan - and it can MINT letters: the subscript ₜ only becomes a t
    # here. Uppercase again, or that t stays lowercase in the key.
    raw = unicodedata.normalize('NFKD', raw).upper()
    plain = ''.join(ch for ch in raw if ch.isalnum() and ch.isascii())
    if plain:
        return plain
    # A tag with no Latin letters in it at all - Cyrillic, Chinese - keeps
    # whatever letters it does have rather than becoming nothing.
    return ''.join(ch for ch in raw if ch.isalnum())


# Symbols people write Latin letters with, where the reading is not in
# doubt. Currency signs are not letters to Unicode, so nothing else folds
# them. Only characters seen on the board are listed, and only where one
# letter is obviously meant.
PLAIN_EXTRA = {
    # currency signs, which are not letters to Unicode so nothing else folds
    # them - and people spell whole names with them
    "₳": "A", "₲": "G", "฿": "B", "₥": "M", "₴": "S",
    "₮": "T", "₭": "K", "₱": "P", "₩": "W", "₹": "R",
    "₺": "T", "₼": "M", "₸": "T", "₽": "P", "₿": "B",
    # letters whose Unicode name does not carry the base letter
    "Ʀ": "R", "ʀ": "R", "ʁ": "R", "Ꝛ": "R", "ꝛ": "R",
    "Ɛ": "E", "ɛ": "E", "Ƨ": "S", "ƨ": "S", "Ʃ": "S",
    "ʇ": "T", "ɥ": "H", "ɐ": "A", "ƿ": "W",
}
_PLAIN_CACHE = {}
_PLAIN_PREFIXES = ("LATIN CAPITAL LETTER SMALL CAPITAL ",
                   "LATIN LETTER SMALL CAPITAL ",
                   "LATIN CAPITAL LETTER ", "LATIN SMALL LETTER ",
                   "LATIN LETTER ")


def _plain_char(ch):
    """One character's plain-letter reading, or '' if it has none."""
    hit = _PLAIN_CACHE.get(ch)
    if hit is not None:
        return hit
    # The character as written is asked about FIRST. Python's upper() can
    # turn a small-capital letter into a differently NAMED one - 'r' small
    # capital becomes YR, whose name carries no base letter - so uppercasing
    # before the lookup lost exactly the letters this exists for.
    out = None
    for form in (ch, ch.upper()):
        out = TAG_FOLD.get(form) or PLAIN_EXTRA.get(form)
        if out:
            break
        k = ''.join(x for x in unicodedata.normalize('NFKD', form)
                    if x.isascii() and x.isalnum())
        if k:
            out = k.upper()
            break
        try:
            nm = unicodedata.name(form)
        except ValueError:
            nm = ''
        for pre in _PLAIN_PREFIXES:
            if nm.startswith(pre):
                base = nm[len(pre):].split(" WITH ")[0].strip()
                if len(base) == 1 and base.isascii() and base.isalpha():
                    out = base.upper()
                break
        if out:
            break
    out = out or ''
    _PLAIN_CACHE[ch] = out
    return out


def plain_reading(text):
    """A stylised name as plain capitals: \u20a6\u00d8\u00d8\u0e3f\u20a5\u20b3\u20b4\u20ae\u0246\u2c6b -> NOOBMASTER.

    For FINDING a player and for matching a member inside their own clan -
    never for deciding who somebody is on its own. Two different people can
    write the same plain letters, so every caller has to handle more than
    one answer."""
    out = []
    for ch in str(text or ''):
        r = _plain_char(ch)
        if r:
            out.append(r)
        elif ch.isalnum() and not ch.isascii():
            out.append(ch.upper())          # Cyrillic, Chinese: left as they are
    return ''.join(out)


def canonical_clan_tag(text, tags=None):
    """The existing clan tag this text refers to, or None.

    Lets /clan/f4 and /clan/F4 reach the same page. Anything not on the
    curated list resolves to nothing on purpose: an arbitrary /clan/XYZ
    would otherwise render an empty roster and read as a real clan that
    simply has no members yet.
    """
    key = clean_clan_tag(text)
    if tags is None:
        tags = all_clan_tags()
    for known in tags:
        if known == key:
            return known
    return None


# What each role is allowed to do. Ordered, so "outranks" is a comparison
# rather than a table of special cases.
CLAN_ROLES = ('moderator', 'coleader', 'leader')
CLAN_ROLE_LABELS = {'leader': 'Leader', 'coleader': 'Co-leader',
                    'moderator': 'Moderator', 'player': 'Member'}
# The role titles a clan may rename for itself. 'player' is the base member;
# 'leader' is renameable too but only by the leader (enforced in
# perform_clan_labels), where the other three are the leader's or a co-leader's.
CUSTOMIZABLE_ROLES = ('player', 'moderator', 'coleader', 'leader')
CLAN_ROLE_NAME_MAX = 24

# --- Clan-profile customisation (7.9.7) ------------------------------------
# Curated, dark-theme-readable colours a clan may choose from. Keys are what
# gets stored; the hex is what renders. A short, tasteful set beats a free
# hex picker (which lets clans pick unreadable colours).
CLAN_PALETTE = {
    "gold": "#e8c153", "sky": "#7fc4ff", "green": "#7ce0a0", "purple": "#c39bf0",
    "red": "#ff6f7d", "amber": "#ffb454", "cyan": "#5fd6d6", "pink": "#ff8fc7",
    "teal": "#57c9a8", "slate": "#9fb3c8", "lime": "#b6e36a", "coral": "#ff9e7a",
}
# Each role's DEFAULT colour key (matches the old hard-coded chip colours).
CLAN_ROLE_DEFAULT_COLOR = {"leader": "gold", "coleader": "sky",
                           "moderator": "green", "player": "slate"}
# Page tints for the clan profile: a background wash + a matching accent.
# Keys stored in clans.theme; "" / absent = the site's default (no tint).
CLAN_THEMES = {
    "red": "#ff5670", "green": "#66e6b8", "blue": "#9adcff", "purple": "#b98cff",
    "amber": "#ffc757", "cyan": "#5fd6d6", "rose": "#ff8fb0", "slate": "#8aa0b8",
}
CLAN_BIO_MAX = 1500
# What each role can do, shown when a member clicks a role chip. Keyed by the
# internal role; "player" is the plain member with no admin powers.
CLAN_ROLE_HELP = {
    "leader": "Runs the clan. Can do everything: invite and remove members, "
              "promote or demote anyone, rename roles, set colours and the "
              "clan profile, and transfer or disband the clan.",
    "coleader": "Trusted second. Can invite and remove members, promote or "
                "demote up to moderator, and edit the clan profile — but "
                "cannot touch other co-leaders or the leader, or disband.",
    "moderator": "Helps manage the roster. Can invite members and review or "
                 "accept applications. Cannot promote, remove, or change the "
                 "profile.",
    "player": "A regular member on the roster. No management powers — "
              "just represents the clan and earns rating for it.",
}


def clan_bio_blocked(text):
    """Screen a clan bio the same per-word way player bios are screened."""
    return bio_blocked(text)


def clan_role_colors(c, tag):
    """role -> hex colour for a clan's chips: its custom pick, else default."""
    out = {}
    try:
        for role, ckey in c.execute(
                "SELECT role, color FROM clan_role_labels WHERE clan = ?", (tag,)):
            if ckey and ckey in CLAN_PALETTE:
                out[role] = CLAN_PALETTE[ckey]
    except Exception:
        pass
    for role, dkey in CLAN_ROLE_DEFAULT_COLOR.items():
        out.setdefault(role, CLAN_PALETTE[dkey])
    return out


def clan_role_color_keys(c, tag):
    """role -> stored colour KEY (for the editor), default key if unset."""
    out = dict(CLAN_ROLE_DEFAULT_COLOR)
    try:
        for role, ckey in c.execute(
                "SELECT role, color FROM clan_role_labels WHERE clan = ?", (tag,)):
            if ckey and ckey in CLAN_PALETTE:
                out[role] = ckey
    except Exception:
        pass
    return out


def clan_rank(role):
    """How senior a role is. 0 means no role at all."""
    return CLAN_ROLES.index(role) + 1 if role in CLAN_ROLES else 0


def clan_role(c, sub_id, tag):
    """This account's role in one clan, or None."""
    if not sub_id or not tag:
        return None
    c.execute("SELECT COALESCE(role, 'leader') FROM clan_admins "
              "WHERE google_sub = ? AND clan = ?", (sub_id, tag))
    row = c.fetchone()
    return row[0] if row else None


def player_clan_role(c, name, tag):
    """The role of a member, found by their player name. None for the rank
    and file - most members have no account at all."""
    c.execute("SELECT google_sub FROM players WHERE name = ?", (name,))
    row = c.fetchone()
    if not row or not row[0]:
        return None
    return clan_role(c, row[0], tag)


def may_kick(actor_role, target_role):
    """Whether one role may take another out of the clan.

    Strictly outrank: a moderator cannot kick a moderator and a co-leader
    cannot kick a co-leader. Only that rule stops two equals removing each
    other, and it is why the leader - who outranks everyone - is safe.
    """
    return clan_rank(actor_role) > 0 and clan_rank(actor_role) > clan_rank(target_role)


def may_manage(c, sub_id, tag):
    """Roster work: inviting, accepting applications, setting the region.
    Leaders and co-leaders. A moderator is there to remove people, not to
    reshape the clan."""
    return clan_rank(clan_role(c, sub_id, tag)) >= clan_rank('coleader')


def is_clan_leader(c, sub_id, tag):
    """Deleting the clan, and handing out co-leader. Leader only.

    A co-leader may not appoint another co-leader: they cannot kick one
    either, so they could otherwise create power they are unable to undo.
    """
    return clan_role(c, sub_id, tag) == 'leader'


def clan_display_map(c):
    """{key: what to show}, for every clan that styles its tag."""
    c.execute("SELECT tag, display_tag FROM clans WHERE display_tag IS NOT NULL "
              "AND display_tag != '' AND display_tag != tag")
    return {r[0]: r[1] for r in c.fetchall()}


def clan_display(c, tag):
    """One clan's tag as its leader wrote it."""
    if not tag:
        return tag
    c.execute("SELECT display_tag FROM clans WHERE tag = ?", (tag,))
    row = c.fetchone()
    return (row[0] if row and row[0] else tag)


_TAG_CACHE = {"ts": 0.0, "styles": {}, "worn": {}, "members": {}, "plain": {}}


def tag_cache_reset():
    _TAG_CACHE["ts"] = 0.0


def _tag_cache(c):
    """Three maps, rebuilt every minute and at once when a styling or a
    member's pick changes:

      styles  {clan: [(id, shown), ...]}  the default first
      worn    {account name: shown}       members wearing a pick of their own
      members {clan: {bare key: (sub, account name)}}
              every member of the clan - an account or a row its leader
              added - by their name WITHOUT the tag, in every styling the
              clan has; a bare key two members share is left out, because
              it would be nobody's.
    """
    now = time.time()
    if now - _TAG_CACHE["ts"] < 60:
        return _TAG_CACHE
    styles, worn, members, seen = {}, {}, {}, {}
    plain, plain_seen = {}, {}
    try:
        default = {r[0]: (r[1] or r[0]) for r in
                   c.execute("SELECT tag, display_tag FROM clans").fetchall()}
        for sid, clan, shown in c.execute(
                "SELECT id, clan, shown FROM clan_tag_styles ORDER BY id").fetchall():
            styles.setdefault(clan, []).append((sid, shown))
        for clan, lst in styles.items():
            d = default.get(clan)
            lst.sort(key=lambda x: 0 if x[1] == d else 1)
        for name, shown in c.execute(
                "SELECT p.name, s.shown FROM players p "
                "JOIN clan_tag_styles s ON s.id = p.tag_style AND s.clan = p.clan "
                "WHERE p.tag_style IS NOT NULL").fetchall():
            worn[name] = shown
        for sub, name, game, clan in c.execute(
                "SELECT google_sub, name, game_name, clan FROM players "
                "WHERE clan IS NOT NULL AND clan != '' AND " + NOT_SANDBOX).fetchall():
            shows = [s for _i, s in styles.get(clan, [])] or [default.get(clan) or clan]
            keys = set()
            pkeys = set()
            for raw in (name, game):
                if not raw:
                    continue
                for s in shows:
                    bare = display_name(raw, clan, s)
                    k = normalize_name(bare)
                    if k:
                        keys.add(k)
                    p = plain_reading(bare)
                    if p:
                        pkeys.add(p)
            for k in keys:
                seen.setdefault(clan, {}).setdefault(k, set()).add((sub, name))
            for k in pkeys:
                plain_seen.setdefault(clan, {}).setdefault(k, set()).add((sub, name))
        for clan, m in seen.items():
            members[clan] = {k: next(iter(v)) for k, v in m.items() if len(v) == 1}
        # Same gate: a reading two members share identifies neither.
        for clan, m in plain_seen.items():
            plain[clan] = {k: next(iter(v)) for k, v in m.items() if len(v) == 1}
    except sqlite3.Error:
        return _TAG_CACHE
    _TAG_CACHE.update(ts=now, styles=styles, worn=worn, members=members,
                      plain=plain)
    return _TAG_CACHE


def clan_styles(c, tag):
    """[(id, shown), ...] for one clan, the default first."""
    return list(_tag_cache(c)["styles"].get(tag, []))


def worn_tag_map(c):
    """{account name: the styling that member chose to wear}."""
    return _tag_cache(c)["worn"]


def player_tag(c, name, clan):
    """The tag as this member wears it: their own pick, else the clan's default."""
    if not clan:
        return None
    return worn_tag_map(c).get(name) or clan_display(c, clan)


def account_tag_styles(c, name, clan):
    """The stylings of this member's clan tag with the worn one marked -
    or nothing when there is only one, since there is nothing to choose."""
    if not clan:
        return []
    styles = clan_styles(c, clan)
    if len(styles) < 2:
        return []
    c.execute("SELECT tag_style FROM players WHERE name = ?", (name,))
    row = c.fetchone()
    mine = row[0] if row else None
    if mine is not None and mine not in {i for i, _s in styles}:
        mine = None
    return [{"id": i, "shown": s,
             "on": (i == mine) if mine is not None else (n == 0)}
            for n, (i, s) in enumerate(styles)]


def clan_member_for_tagged_name(c, name):
    """The account a tagged roster name belongs to, or None.

    'S2F BHU', 'SᄅF̶ ↝ BHU' and '𝐒𝟐𝐅BHU' are one person if an account
    called BHU - or SᄅF̶ BHU - is a member of S2F. The tag is taken off the
    way the pages take it off for display, in every styling the clan has,
    and what is left must match exactly one member of THAT clan. Nobody
    outside the clan is ever matched this way: the tag is the evidence.
    Longest tag first, so SRW is tried before SR could eat its first
    letters.
    """
    cache = _tag_cache(c)
    members = cache["members"]
    if not members or not name:
        return None
    for clan in sorted(members, key=len, reverse=True):
        roster = members[clan]
        shows = [s for _i, s in cache["styles"].get(clan, [])] or [clan]
        tried = set()
        for shown in shows:
            rest = display_name(name, clan, shown)
            if rest == name:
                continue
            key = normalize_name(rest)
            if not key or key in tried:
                continue
            tried.add(key)
            hit = roster.get(key)
            if hit:
                return hit[1]
    # Nothing matched as written. A member who restyled their name - flying
    # (Ł7)TEMPEST while the board knows them as Ŧɇmᵽɇsŧ - is still that
    # member, so the plain reading is tried inside their own clan only.
    for clan in sorted(members, key=len, reverse=True):
        roster = cache.get("plain", {}).get(clan) or {}
        if not roster:
            continue
        shows = [s for _i, s in cache["styles"].get(clan, [])] or [clan]
        tried = set()
        for shown in shows:
            rest = display_name(name, clan, shown)
            if rest == name:
                continue
            key = plain_reading(rest)
            if not key or key in tried:
                continue
            tried.add(key)
            hit = roster.get(key)
            if hit:
                return hit[1]
    return None


# Every table that keys a player's record by norm_name. A rename must carry
# all of them or the record splits: the board row moves and the history,
# the trial ratings and the survival rounds stay behind under a name that
# no longer exists. 8.5.6 fixed that for match_players alone, and the
# Discord rename never got even that.
RENAME_KEYED_TABLES = (
    "match_players", "held_results", "trueskill_match_players",
    "survival_round_players", "custom_match_players",
    "game_ladder", "shadow_players", "wiped_match_players",
    "admin_adjustments", "recredits", "restored_matches", "free_agents",
)


def _fold_survival_row(c, old_key, new_key, new_name):
    """survival_players is one row per identity. When both keys have one -
    the player had already played survival under the bare name - the old
    row folds into the new: rounds and wins add, best place is the better,
    last_at the later, and the rating is both moves from the start (each
    row is 1000 plus its own rounds' deltas). The 18 Sep migration hit
    exactly this twice and the plain UPDATE had nothing to say about it."""
    try:
        o = c.execute("SELECT elo, rounds, wins, best_place, last_at FROM survival_players "
                      "WHERE norm_name = ?", (old_key,)).fetchone()
        if not o:
            return
        n = c.execute("SELECT elo, rounds, wins, best_place, last_at FROM survival_players "
                      "WHERE norm_name = ?", (new_key,)).fetchone()
        if not n:
            c.execute("UPDATE survival_players SET norm_name = ?, name = ? WHERE norm_name = ?",
                      (new_key, new_name, old_key))
            return
        places = [x for x in (o[3], n[3]) if x is not None]
        c.execute("UPDATE survival_players SET elo = ?, rounds = ?, wins = ?, best_place = ?, "
                  "last_at = ? WHERE norm_name = ?",
                  (round((o[0] or 1000) + (n[0] or 1000) - 1000, 2),
                   (o[1] or 0) + (n[1] or 0), (o[2] or 0) + (n[2] or 0),
                   min(places) if places else None,
                   max(o[4] or "", n[4] or "") or None, new_key))
        c.execute("DELETE FROM survival_players WHERE norm_name = ?", (old_key,))
    except sqlite3.Error:
        pass


def _fold_trueskill_row(c, old_key, new_key, new_name):
    """trueskill_players is one trial rating per identity. Two cannot be
    added; the one built on more games is the one that stays."""
    try:
        o = c.execute("SELECT games FROM trueskill_players WHERE norm_name = ?",
                      (old_key,)).fetchone()
        if not o:
            return
        n = c.execute("SELECT games FROM trueskill_players WHERE norm_name = ?",
                      (new_key,)).fetchone()
        if n and (n[0] or 0) >= (o[0] or 0):
            c.execute("DELETE FROM trueskill_players WHERE norm_name = ?", (old_key,))
            return
        if n:
            c.execute("DELETE FROM trueskill_players WHERE norm_name = ?", (new_key,))
        c.execute("UPDATE trueskill_players SET norm_name = ?, name = ? WHERE norm_name = ?",
                  (new_key, new_name, old_key))
    except sqlite3.Error:
        pass


def _move_gem_ledger(c, old_key, new_key):
    """The gem ledger is keyed by the player's norm too (gem_grant takes
    it), and it is what the achievements page, the hangar and the
    once-only guard read - the balance on the row is only a cache. Moved
    as a whole; if a grant already exists under the new key (the once-only
    index says so) the old copy is dropped, since it was paid once."""
    try:
        c.execute("UPDATE gem_ledger SET owner = ? WHERE owner_kind = 'player' AND owner = ?",
                  (new_key, old_key))
        return
    except sqlite3.IntegrityError:
        pass
    except sqlite3.Error:
        return
    for (rid,) in c.execute("SELECT id FROM gem_ledger WHERE owner_kind = 'player' "
                            "AND owner = ?", (old_key,)).fetchall():
        try:
            c.execute("UPDATE gem_ledger SET owner = ? WHERE id = ?", (new_key, rid))
        except sqlite3.IntegrityError:
            c.execute("DELETE FROM gem_ledger WHERE id = ?", (rid,))


def rekey_identity(c, old_name, new_name):
    """Rename one players row and carry everything keyed to it. The name
    each match was flown under (match_players.name) is kept as it was."""
    old_key, new_key = normalize_name(old_name), normalize_name(new_name)
    c.execute("UPDATE players SET name = ?, norm_name = ? WHERE name = ?",
              (new_name, new_key, old_name))
    if old_key != new_key:
        for t in RENAME_KEYED_TABLES:
            try:
                c.execute("UPDATE %s SET norm_name = ? WHERE norm_name = ?" % t,
                          (new_key, old_key))
            except sqlite3.Error:
                pass
        _fold_survival_row(c, old_key, new_key, new_name)
        _fold_trueskill_row(c, old_key, new_key, new_name)
        _move_gem_ledger(c, old_key, new_key)
    try:
        c.execute("UPDATE clan_invites SET name = ? WHERE name = ? AND status = 'pending'",
                  (new_name, old_name))
    except sqlite3.Error:
        pass
    _PLAY_CACHE["ts"] = 0.0
    tag_cache_reset()


def bare_member_name(name, tag, shows):
    """The name with the clan tag taken off, for the ROW (display_name is
    for the eye). Also drops the tag's own decoration left behind - the ✦
    of ᴀʀ✦, the ↝ of SᄅF̶ ↝ - and any combining mark, then squeezes the
    spaces. None when nothing comes off or nothing usable is left."""
    raw = ' '.join(str(name or '').split())
    if not raw:
        return None
    rest = raw
    for s in (shows or [tag]):
        r2 = display_name(raw, tag, s)
        if r2 != raw:
            rest = r2
            break
    if rest == raw:
        return None
    deco = {ch for s in (shows or []) for ch in s if not ch.isalnum() and not ch.isspace()}
    while rest and (rest[0] in deco or rest[0].isspace()
                    or unicodedata.category(rest[0]).startswith('M')):
        rest = rest[1:]
    while rest and (rest[-1] in deco or rest[-1].isspace()):
        rest = rest[:-1]
    rest = ' '.join(rest.split())
    if not any(ch.isalnum() for ch in rest) or not is_valid_name_format(rest):
        return None
    return rest


def strip_tag_on_join(c, name, tag):
    """An account name is just the person; the tag comes from the clan and
    shows beside the name (owner's rule, 18 Sep 2026). Called wherever a
    row is put into a clan: renames the row to its tag-free form and
    carries its record. Leaves it alone when nothing comes off, when what
    is left is not a usable name, or when that name is already another
    row's - folding two rows together is what Merge a name is for."""
    if not name or not tag:
        return None
    shows = [s for _i, s in clan_styles(c, tag)] or [clan_display(c, tag) or tag]
    bare = bare_member_name(name, tag, shows)
    if not bare:
        return None
    c.execute("SELECT 1 FROM players WHERE norm_name = ? AND name != ?",
              (normalize_name(bare), name))
    if c.fetchone():
        return None
    rekey_identity(c, name, bare)
    return bare


def tag_carried(c, name):
    """The clan tag an account name is carrying, or None: {tag, shown, bare}.

    Strong evidence only - the tag as the first or last word, in brackets,
    or the clan's own styling on the front. A word in the middle is a word
    (THIS IS HERE is not in IS), and a fused prefix (ISAAC) is never
    enough. It is a question the account page asks, not a wall.
    """
    raw = ' '.join(str(name or '').split())
    if not raw:
        return None
    styles = _tag_cache(c)["styles"]
    if not styles:
        return None
    toks = raw.split()
    cands = {clean_clan_tag(toks[0]), clean_clan_tag(toks[-1])}
    for m in re.finditer(r'[\[\(\{\u3010\u3016\u300c\u300e<\u276e]\s*'
                         r'([^\]\)\}\u3011\u3017\u300d\u300f>\u276f]{1,12})', raw):
        cands.add(clean_clan_tag(m.group(1)))
    for tag in sorted(styles, key=len, reverse=True):
        shows = [s for _i, s in styles[tag]]
        # The clan's own styling on the front counts only when it is real
        # decoration or stops where the name starts: a plain IS glued into
        # ISAAC is the fused-prefix case, and that is never enough here.
        styled = any(raw.startswith(s) and (len(raw) == len(s) or not s[-1].isalnum()
                                            or not raw[len(s)].isalnum())
                     for s in shows)
        if tag not in cands and not styled:
            continue
        bare = bare_member_name(raw, tag, shows)
        if bare and bare != raw:
            return {"tag": tag, "shown": shows[0], "bare": bare}
    return None


def clan_custom_labels(c, tag):
    """Only the role titles a clan has explicitly renamed: {role: label}."""
    if not tag:
        return {}
    try:
        return {r: l for r, l in c.execute(
            "SELECT role, label FROM clan_role_labels WHERE clan = ?", (tag,)) if l}
    except sqlite3.OperationalError:
        return {}


def role_label_for(role, custom):
    """The display title for a role, given a clan's custom overrides. An
    ordinary member (no admin role) shows the clan's 'player' title only when
    it has been customised, so an untranslated default doesn't override the
    template's own localised 'Member'."""
    if role in CLAN_ROLES:
        return custom.get(role) or CLAN_ROLE_LABELS.get(role, "")
    return custom.get('player') or ""


def clan_admin_tags(c, sub_id):
    """Every clan tag this signed-in account is an admin of."""
    if not sub_id:
        return []
    return [r[0] for r in c.execute(
        "SELECT clan FROM clan_admins WHERE google_sub = ? ORDER BY clan",
        (sub_id,)).fetchall()]


def join_admin_names(c, sub_id, tag):
    """Put an admin's own names into the clan they now run.

    An admin missing from their own roster reads as a mistake, and without
    this every one of them would have to add themselves by hand. Names
    already in another clan are left where they are: being handed one clan
    is not a reason to pull someone out of a different one.
    """
    c.execute("SELECT name, clan FROM players WHERE google_sub = ?", (sub_id,))
    joined, elsewhere = [], []
    for name, clan in c.fetchall():
        if clan == tag:
            continue
        if clan:
            elsewhere.append(name)
            continue
        c.execute("UPDATE players SET clan = ?, clan_locked = 0 WHERE name = ?", (tag, name))
        joined.append(strip_tag_on_join(c, name, tag) or name)
    return joined, elsewhere


def join_own_clans(c, sub_id):
    """Put this account's names into any clan it is an admin of.

    Called whenever a name appears on an account, not only when the clan
    is claimed: somebody can be approved and claim their tag before they
    have registered a name at all, and an admin missing from their own
    roster reads as a bug.
    """
    landed = []
    for tag in clan_admin_tags(c, sub_id):
        got, _elsewhere = join_admin_names(c, sub_id, tag)
        landed.extend((tag, nm) for nm in got)
    return landed


def curated_clans(c):
    """Clans that have at least one admin.

    Their rosters are decided by a person, so automatic tag detection must
    not add anyone to them. Detection reads the tag out of whatever name the
    player typed in game, which means anyone can put a clan's tag in their
    name and land on its page - that is the whole problem admins exist to
    fix, and it would keep happening if detection stayed on.
    """
    return {r[0] for r in c.execute("SELECT DISTINCT clan FROM clan_admins").fetchall()}


def is_valid_name_format(name):
    """Shape only, judged on the normalised form so that "BEL RIOSE" and
    "BELRIOSE" are the same 8-letter name. Applied to BOTH manual
    registration and auto-registered winners, because it is what keeps OCR
    garbage (long fragments, stray dialog text) out of the table."""
    key = normalize_name(name)
    if not key or len(key) > 16:
        return False
    if len(key) == 1:
        # A lone narrow character is nearly always a misread roster - the
        # stray "f" that ended up on the board came in that way. A lone wide
        # one is different: a single Chinese, Japanese or Korean character is
        # an ordinary whole name, so those are let through. A single Latin,
        # Cyrillic or Greek letter is not, since it carries no more meaning
        # than a smudge and is far more likely to be one.
        if unicodedata.east_asian_width(key) not in ('W', 'F'):
            return False
    # At least one letter, so a bare number is never a name.
    if not any(ch.isalpha() for ch in key):
        return False
    # Digits used to be banned at the end of a name. That guarded against
    # the dominant OCR failure - the score column bleeding into the name,
    # which always landed as trailing digits (COMMANDER BERU10031,
    # HANGRYHIPPO9117). Nothing is read off the screen any more, so a
    # trailing digit is just what the player typed, and the rule was
    # turning away real names like Tempest1.
    return True


def is_blocked_word(name):
    """Content moderation, applied ONLY to names typed into /register.

    Deliberately NOT applied to auto-registration: those names are ones
    starblast.io already allowed the player to use in-game, and silently
    dropping them would erase real players from a leaderboard meant to
    rank them. Refusing a typed name is harmless by comparison - the
    player simply picks another one."""
    upper_name = name.upper()
    if upper_name in BLOCKED_EXACT:
        return True
    return any(bad in upper_name for bad in BLOCKED_SUBSTRINGS)


# A profile bio is prose, not a name, so it is screened PER WORD against the
# same lists: a substring slur ("fuck") is caught inside any word, while the
# short whole-name-only terms ("ass", "rape", "sex") are caught as standalone
# words but not inside innocent ones ("class", "grape", "Middlesex").
BIO_MAX = 5000


def bio_blocked(text):
    for tok in re.findall(r"[A-Za-z0-9]+", text or ""):
        if is_blocked_word(tok):
            return True
    return False


