@app.route('/api/rawlive/state', methods=['POST'])
def rawlive_ingest():
    """One snapshot from raw_observer for one lobby. Latest wins."""
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401
    d = request.json
    if not isinstance(d, dict) or d.get('sid') is None:
        return jsonify({"error": "bad payload"}), 400
    d = repair_surrogates(d)
    try:
        conn = live_db(); c = conn.cursor()
        # Stamp when THIS match (sys_id + match_seq) was first seen, so the
        # /rawlive win-prob can compute match progress. A single snapshot has
        # no start time; carry the earliest ts forward until match_seq rolls.
        _now_ts = d.get("ts") or time.time()
        _mstart = _now_ts
        prev = c.execute("SELECT payload FROM rawlive WHERE sys_id=?",
                         (int(d['sid']),)).fetchone()
        if prev:
            try:
                pj = json.loads(prev[0])
                if pj.get("match_seq") == d.get("match_seq") and pj.get("_mstart"):
                    _mstart = pj["_mstart"]
                # same connection (same welcome servertime): keep its first-seen ts
                if (pj.get("servertime") is not None and pj.get("servertime") == d.get("servertime")
                        and pj.get("_ct0")):
                    d["_ct0"] = pj["_ct0"]
            except Exception:
                pass
        d["_mstart"] = _mstart
        if d.get("_ct0") is None:
            d["_ct0"] = _now_ts
        _blob = json.dumps(d, ensure_ascii=False)
        _wall = time.time()
        c.execute("INSERT INTO rawlive (sys_id, updated, payload) VALUES (?,?,?) "
                  "ON CONFLICT(sys_id) DO UPDATE SET updated=excluded.updated, "
                  "payload=excluded.payload",
                  (int(d['sid']), _wall, _blob))
        # Keep a rolling history for the delayed public view, and prune beyond
        # what the delay needs (a little slack past the delay window).
        c.execute("INSERT INTO rawlive_hist (sys_id, updated, payload) VALUES (?,?,?)",
                  (int(d['sid']), _wall, _blob))
        c.execute("DELETE FROM rawlive_hist WHERE updated < ?",
                  (_wall - (RAWLIVE_PUBLIC_DELAY + 90),))
        conn.commit(); conn.close()
    except Exception as e:
        return jsonify({"error": str(e)[:120]}), 500
    return jsonify({"ok": True}), 200


def _shadow_elo_lookup(names):
    """norm_name -> shadow elo for a set of names (batched)."""
    elo_map = {}
    if not names:
        return elo_map
    try:
        pconn = db()
        qs = list(names)
        for i in range(0, len(qs), 400):
            chunk = qs[i:i + 400]
            ph = ",".join("?" * len(chunk))
            for nn, el in pconn.execute(
                    "SELECT norm_name, elo FROM shadow_players "
                    "WHERE norm_name IN (%s)" % ph, chunk):
                elo_map[nn] = float(el)
        pconn.close()
    except Exception:
        return {}
    return elo_map


def _wp_player_impacts(d, elo_map, wp_w, prog, base_probs):
    """Owner-only: how much each player is moving their team's win chance.

    Leave-one-out on the ROSTER: drop the player from their team and re-run
    the model (team score/count are held fixed - only the roster-derived
    features change: top-2 skill, tier, score concentration). The drop in
    that team's P(win) is the player's contribution, in points. Naturally ~0
    for anyone outside the top of their team, since only those feed the
    features. Returns {(team_idx, roster_idx): delta_pct}."""
    out = {}
    if not base_probs:
        return out
    teams = d.get("teams") or {}
    for i in range(3):
        if i not in base_probs:
            continue
        tk = "team_%d" % (i + 1)
        ros = teams.get(tk) or []
        if len(ros) < 2:
            continue
        # Only the top players by score can move the skill/tier/concentration
        # features; the rest come out ~0 and show no badge anyway. Scoring
        # just the top few caps the per-poll leave-one-out cost so /rawlive
        # stays fast enough for the radar to stay smooth.
        idxs = sorted((pi for pi, pr in enumerate(ros) if pr and pr[0]),
                      key=lambda pi: -(ros[pi][1] or 0))[:6]
        for pi in idxs:
            d2 = dict(d)
            t2 = dict(teams)
            t2[tk] = ros[:pi] + ros[pi + 1:]
            d2["teams"] = t2
            try:
                pb = shadow_win_probability(d2, elo_map, wp_w, prog)
            except Exception:
                pb = None
            if pb and i in pb:
                out[(i, pi)] = round((base_probs[i] - pb[i]) * 100, 1)
    return out


@app.route('/api/rawlive/matches')
def rawlive_matches():
    """Raw_observer lobbies. The signed-in owner sees the live, named feed
    with per-player win-prob impact; everyone else sees it ~2 minutes behind
    (security delay), anonymous, radar + probabilities only."""
    now = time.time()
    _owner = is_site_owner()
    delayed = not _owner
    # Gather the payloads to render: latest for the owner, ~2-min-old for the
    # public (the closest history snapshot older than the delay).
    render = []
    try:
        conn = live_db()
        active = conn.execute("SELECT sys_id, updated FROM rawlive "
                              "WHERE updated > ? ORDER BY updated DESC",
                              (now - 40,)).fetchall()
        if delayed:
            cutoff = now - RAWLIVE_PUBLIC_DELAY
            for sys_id, _u in active:
                h = conn.execute(
                    "SELECT updated, payload FROM rawlive_hist WHERE sys_id=? "
                    "AND updated <= ? ORDER BY updated DESC LIMIT 1",
                    (sys_id, cutoff)).fetchone()
                if not h:        # lobby younger than the delay -> not shown yet
                    continue
                try:
                    render.append((sys_id, h[0], json.loads(h[1])))
                except Exception:
                    pass
        else:
            for sys_id, upd in active:
                r = conn.execute("SELECT payload FROM rawlive WHERE sys_id=?",
                                 (sys_id,)).fetchone()
                if not r:
                    continue
                try:
                    render.append((sys_id, upd, json.loads(r[0])))
                except Exception:
                    pass
        conn.close()
    except Exception:
        render = []
    names = set()
    for _s, _u, d in render:
        for ros in (d.get("teams") or {}).values():
            for r in ros or []:
                if r and r[0]:
                    names.add(normalize_name(r[0]))
    elo_map = _shadow_elo_lookup(names)
    wp_w, wp_meta = load_shadow_wp_model()
    out = []
    for sys_id, updated, d in render:
        prog = 0.0
        try:
            ms = d.get("_mstart")
            if ms:
                prog = min(1.0, max(0.0, ((d.get("ts") or updated) - ms) / 2400.0))
        except Exception:
            prog = 0.0
        try:
            probs = shadow_win_probability(d, elo_map, wp_w, prog)
        except Exception:
            probs = None
        impacts = (_wp_player_impacts(d, elo_map, wp_w, prog, probs)
                   if _owner else {})
        facs = d.get("factions") or []
        _hues = d.get("hues") or []      # the lobby's team hues (once the observer sends them)
        _sh = d.get("sh") or []
        _lay = d.get("stlay") or []
        # The hull each pilot is flying, and who is actually on the map: the
        # radar carries every live ship, so a pilot missing from it has none.
        _codes = _live_ship_codes(d)
        _live_ids = set(e[1] for e in (d.get("radar") or []) if e and len(e) > 1)
        teams = []
        for k in ("team_1", "team_2", "team_3"):
            roster = d.get("teams", {}).get(k) or []
            idx = int(k[-1]) - 1
            station = None
            if isinstance(_sh, list) and idx < len(_sh) and isinstance(_sh[idx], dict):
                h = _sh[idx]
                n = h.get("n") or 0
                dead = h.get("dead") or 0
                station = [h.get("lvl"), h.get("gems") or 0, n - dead, n,
                           h.get("weak") or 0, dead, h.get("mods")]
            layout = _lay[idx] if idx < len(_lay) else []
            players = []
            if _owner:
                # Drop our own resident watcher ('homi is watching' etc.): it
                # joins a team to observe and would otherwise sit in the roster
                # as a phantom 0-score player.
                players = sorted(
                    [{"name": r[0], "score": r[1], "tier": r[2],
                      "code": (_codes.get(r[4]) if len(r) > 4 else None),
                      # Not on the radar = nothing of theirs is flying. The old
                      # test read row[3] - the ship MODEL - as a death, and
                      # model 0 is the Fly, so every pilot who had just spawned
                      # or never upgraded was struck out.
                      "dead": (len(r) > 4 and r[4] not in _live_ids),
                      "impact": impacts.get((idx, ri))}
                     for ri, r in enumerate(roster)
                     if r and r[0] and not is_observer_name(r[0])],
                    key=lambda q: -q["score"])[:12]
            teams.append({
                "key": k,
                "label": (facs[idx] if idx < len(facs) and facs[idx] else "Team %d" % (idx+1)),
                "hue": (_hues[idx] if idx < len(_hues) and isinstance(_hues[idx], (int, float)) else None),
                "count": d.get("counts", {}).get(k, 0),
                "score": d.get("scores", {}).get(k, 0),
                "station": station,
                "layout": layout,
                "prob": (round(probs[idx] * 100) if probs and idx in probs
                         else None),
                "players": players,
            })
        # Owner-only: full ship id -> name map (uncapped, unlike the top-12
        # roster) so every dot on the radar can be labelled with its pilot.
        _names = {}
        if _owner:
            for k in ("team_1", "team_2", "team_3"):
                for r in (d.get("teams", {}).get(k) or []):
                    if (r and len(r) > 4 and r[0] and r[0] != "?"
                            and not is_observer_name(r[0])):
                        _names[str(r[4])] = r[0]
        out.append({
            "sys_id": sys_id, "name": d.get("name") or ("Lobby %d" % sys_id),
            "region": d.get("region") or "america",
            "match_seq": d.get("match_seq"), "full_watch": bool(d.get("full_watch")),
            "cap": d.get("cap"), "age": round(now - updated, 1),
            "seed": d.get("seed"),
            # Station ring clock: the observer's exact `mt` when present, else the
            # welcome servertime walked forward from the connection's first snapshot.
            "mt": (round(d["mt"], 1) if isinstance(d.get("mt"), (int, float))
                   else (round(d["servertime"] / 1000.0
                               + (float(d.get("ts") or 0) - float(d.get("_ct0") or d.get("ts") or 0)), 1)
                         if isinstance(d.get("servertime"), (int, float)) and d.get("ts") else None)),
            "phases": (d.get("phases") if isinstance(d.get("phases"), list) else None),
            "radar": _live_radar(d),
            "names": _names,
            "prog": round(prog, 3),
            "wp": bool(probs),
            "teams": teams,
        })
    return jsonify({"matches": out, "count": len(out),
                    "show_players": _owner,
                    "delayed": delayed,
                    "delay_sec": (RAWLIVE_PUBLIC_DELAY if delayed else 0),
                    "wp_model": {"acc": wp_meta.get("accuracy"),
                                 "trained_at": wp_meta.get("trained_at"),
                                 "builtin": bool(wp_meta.get("builtin"))}}), 200


@app.route('/api/asteroids/<int:seed>')
def asteroids_get(seed):
    """The baked asteroid field for a map seed, or null if not baked yet.
    The client fetches this once per seed (static per match)."""
    try:
        conn = live_db()
        r = conn.execute("SELECT data FROM asteroids WHERE seed = ?",
                        (seed,)).fetchone()
        conn.close()
    except Exception:
        r = None
    if not r:
        return jsonify({"seed": seed, "asteroids": None}), 200
    try:
        return jsonify({"seed": seed, "asteroids": json.loads(r[0])}), 200
    except Exception:
        return jsonify({"seed": seed, "asteroids": None}), 200


@app.route('/api/asteroids/needed')
def asteroids_needed():
    """Seeds currently in the rawlive feed that have NOT been baked -
    the baker's work queue."""
    now = time.time()
    try:
        conn = live_db()
        seeds = set()
        for (payload,) in conn.execute("SELECT payload FROM rawlive WHERE updated > ?",
                                       (now - 120,)).fetchall():
            try:
                sd = json.loads(payload).get("seed")
                if isinstance(sd, int):
                    seeds.add(sd)
            except Exception:
                pass
        have = {r[0] for r in conn.execute("SELECT seed FROM asteroids").fetchall()}
        conn.close()
    except Exception:
        return jsonify({"needed": []}), 200
    return jsonify({"needed": sorted(seeds - have)}), 200


@app.route('/api/asteroids', methods=['POST'])
def asteroids_ingest():
    """Baker posts {seed, asteroids:[[x,y,size],...]} (radar +/-128 coords)."""
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401
    d = request.json
    if not isinstance(d, dict) or not isinstance(d.get("seed"), int)             or not isinstance(d.get("asteroids"), list):
        return jsonify({"error": "bad payload"}), 400
    # cap the stored size defensively
    ast = d["asteroids"][:2000]
    try:
        conn = live_db(); c = conn.cursor()
        c.execute("INSERT INTO asteroids (seed, data, baked) VALUES (?,?,?) "
                  "ON CONFLICT(seed) DO UPDATE SET data=excluded.data, baked=excluded.baked",
                  (d["seed"], json.dumps(ast), time.time()))
        # Seeds accumulate as lobbies cycle; a month-old field nobody revisits
        # is dead weight on the same quota the live table filled.
        c.execute("DELETE FROM asteroids WHERE baked < ?", (time.time() - 30 * 86400,))
        conn.commit(); conn.close()
    except Exception as e:
        return jsonify({"error": str(e)[:120]}), 500
    return jsonify({"ok": True, "n": len(ast)}), 200


