@app.route('/api/bot/floods/undelivered')
def api_floods_undelivered():
    """Flood alerts the bot has not shown the owner yet."""
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401
    conn = db()
    c = conn.cursor()
    c.execute("SELECT id, kind, sys_id, match_id, lobby_name, region, worst, "
              "detail, created_at FROM flood_alerts WHERE delivered = 0 "
              "ORDER BY id LIMIT 20")
    out = []
    for r in c.fetchall():
        try:
            detail = json.loads(r[7]) if r[7] else {}
        except (TypeError, ValueError):
            detail = {}
        out.append({"id": r[0], "kind": r[1], "sys_id": r[2], "match_id": r[3],
                    "lobby_name": r[4], "region": r[5], "worst": r[6],
                    "detail": detail, "at": r[8]})
    conn.close()
    return jsonify({"floods": out, "count": len(out)}), 200


@app.route('/api/bot/floods/delivered', methods=['POST'])
def api_floods_delivered():
    """Mark flood alerts as shown, so they are not posted twice."""
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401
    ids = (request.json or {}).get('ids') or []
    ids = [int(i) for i in ids if str(i).isdigit()][:50]
    if not ids:
        return jsonify({"ok": True, "marked": 0}), 200
    conn = db()
    conn.execute("UPDATE flood_alerts SET delivered = 1 WHERE id IN (%s)"
                 % ",".join("?" * len(ids)), ids)
    conn.commit()
    conn.close()
    return jsonify({"ok": True, "marked": len(ids)}), 200


@app.route('/api/flood')
def api_flood():
    """Owner-only. With ?q= it returns one match in full - the result, who
    was rated, and the duplicate-ship evidence - so a reported match can be
    judged. Without it, the recent matches that carried flood evidence."""
    if not is_site_owner():
        return jsonify({"error": "Not allowed."}), 403
    q = (request.args.get('q') or '').strip()
    conn = db()
    c = conn.cursor()

    def flood_of(raw):
        try:
            return json.loads(raw) if raw else {}
        except (TypeError, ValueError):
            return {}

    if q:
        row = None
        if q.isdigit():
            c.execute("SELECT id, match_id, sys_id, played_at, region, lobby_name, "
                      "tracked_reads, flood, flood_max FROM matches WHERE sys_id = ? "
                      "ORDER BY played_at DESC LIMIT 1", (int(q),))
            row = c.fetchone()
        if not row:
            c.execute("SELECT id, match_id, sys_id, played_at, region, lobby_name, "
                      "tracked_reads, flood, flood_max FROM matches "
                      "WHERE match_id = ? LIMIT 1", (q,))
            row = c.fetchone()
        if not row:
            conn.close()
            return jsonify({"found": False, "query": q}), 200
        c.execute("SELECT name, won, delta, team, score FROM match_players "
                  "WHERE match_row = ? ORDER BY won DESC, delta DESC", (row[0],))
        players = [{"name": r[0], "won": bool(r[1]), "delta": r[2],
                    "team": r[3], "score": r[4]} for r in c.fetchall()]
        conn.close()
        return jsonify({"found": True, "match": {
            "match_id": row[1], "sys_id": row[2], "at": row[3],
            "region": row[4], "lobby_name": row[5], "tracked_reads": row[6],
            "flood": flood_of(row[7]), "flood_max": row[8] or 0,
            "significant": (row[8] or 0) >= FLOOD_SIGNIFICANT,
            "players": players}}), 200

    c.execute("SELECT match_id, sys_id, played_at, region, lobby_name, "
              "flood, flood_max FROM matches WHERE COALESCE(flood_max,0) >= 2 "
              "ORDER BY played_at DESC LIMIT 60")
    out = [{"match_id": r[0], "sys_id": r[1], "at": r[2], "region": r[3],
            "lobby_name": r[4], "flood": flood_of(r[5]), "flood_max": r[6] or 0,
            "significant": (r[6] or 0) >= FLOOD_SIGNIFICANT} for r in c.fetchall()]
    conn.close()
    return jsonify({"matches": out, "count": len(out),
                    "significant_at": FLOOD_SIGNIFICANT}), 200


@app.route('/api/replay/<int:mid>')
def replay_data(mid):
    """Everything the replay page draws, from the trajectory frozen at
    match end. Public: the result itself already is."""
    conn = db()
    c = conn.cursor()
    # Match metadata first, independent of any frozen score trajectory. MOST
    # matches the live watcher records have a rich radar/win-prob replay
    # (trueskill_replay, which the page's arena draws) but never a match_replays
    # score snapshot - so a missing snapshot is NOT "no replay", it just means
    # the score-over-time charts are unavailable. The match, its rated players
    # and the radar must still open.
    c.execute("SELECT lobby_name, region, played_at, sys_id, "
              "COALESCE(tracked_reads, 0), flood, COALESCE(flood_max, 0) FROM matches WHERE id = ?", (mid,))
    meta = c.fetchone()
    if not meta:
        conn.close()
        return jsonify({"error": "No such match."}), 404
    m_name, m_region, m_played, m_sys, m_treads, m_flood, m_fmax = meta
    # Flood evidence (several ships under one name at once), so the replay can say
    # why a flagged match shows no swarm on the radar: those accounts rarely spawn.
    try:
        _flood = json.loads(m_flood) if m_flood else None
    except (TypeError, ValueError):
        _flood = None
    _flood_keys = {"flood": _flood, "flood_max": int(m_fmax or 0),
                   "flood_significant": int(m_fmax or 0) >= FLOOD_SIGNIFICANT,
                   # Until 10 Sep 2026 ~10:40 UTC the recorder dropped tier-1 Flies
                   # from the radar (model byte 0 read as 'no ship'), so a swarm of
                   # Flies is invisible in replays recorded before then.
                   "radar_flies_missing": str(m_played or "") < "2026-09-10 10:40"}
    _pat = m_played or ''
    try:
        c.execute("SELECT data FROM match_replays WHERE match_row = ?", (mid,))
        _blob = c.fetchone()
    except sqlite3.Error:
        _blob = None
    # Each player's elo AFTER this match, walked backwards from their
    # current rating minus every delta that came later - same
    # reconstruction the progress chart uses.
    c.execute("SELECT mp.name, mp.team, mp.won, mp.delta, COALESCE(mp.half,0), mp.score, "
              "COALESCE((SELECT p.elo FROM players p WHERE p.norm_name = mp.norm_name), 0) "
              "- COALESCE((SELECT SUM(mp2.delta) FROM match_players mp2 "
              "JOIN matches m2 ON m2.id = mp2.match_row "
              "WHERE mp2.norm_name = mp.norm_name AND (m2.played_at > ? "
              "OR (m2.played_at = ? AND m2.id > ?))), 0), "
              "(SELECT 1 FROM players p2 WHERE p2.norm_name = mp.norm_name) "
              "FROM match_players mp WHERE mp.match_row = ? ORDER BY mp.score DESC",
              (_pat, _pat, mid, mid))
    players = [{"name": r[0], "team": r[1], "won": bool(r[2]),
                "delta": r[3], "half": r[4], "score": r[5],
                "elo": (round(r[6], 1) if r[7] else None)} for r in c.fetchall()]
    conn.close()
    if not _blob:
        # No frozen score trajectory - serve the match, its rated players and
        # the meta so the page still renders the header, the result and (from
        # trueskill_replay) the radar replay. Just no score-over-time points.
        return jsonify(dict(_flood_keys, **{
            "name": m_name or ("#%s" % m_sys), "region": m_region or "",
            "played_at": str(m_played or ""), "sys_id": m_sys,
            "top": {}, "skill": {}, "tracked_seconds": int(m_treads or 0) * 10,
            "gaps": [], "stlay": None, "welcome": None,
            "prob_enabled": WIN_PROB_ENABLED,
            "players": players, "points": [], "no_score_chart": True,
        })), 200
    try:
        p = json.loads(zlib.decompress(_blob[0]).decode('utf-8'))
    except Exception:
        return jsonify({"error": "Replay data unreadable."}), 500
    traj = [r for r in (p.get("traj") or []) if isinstance(r, list) and len(r) >= 3]
    # Replays frozen before the ingest guard existed can hold two timebases
    # (the feed clock restarted mid-stream). Points from different clocks
    # cannot share one axis - keep the longest single-clock run.
    runs, _cur = [], []
    for r in traj:
        if _cur and r[0] < _cur[-1][0] - 30:
            runs.append(_cur)
            _cur = []
        _cur.append(r)
    if _cur:
        runs.append(_cur)
    if runs:
        traj = max(runs, key=len)
    # Single-read glitches - a frame whose total is under half of BOTH
    # neighbours' totals is a reconnect's half-loaded answer, not the match
    # (one drew a one-read 100% spike across the win-probability chart).
    # They are removed from the lines and reported as GAPS, so the chart
    # shows a grey "no reliable data" band instead of either a fake spike
    # or a silently smoothed-over stretch.
    def _rtot(r):
        return sum(int(v or 0) for v in (r[2] or {}).values())
    _gaps_raw = []
    if len(traj) >= 3:
        _keep = [traj[0]]
        for _j in range(1, len(traj) - 1):
            _t = _rtot(traj[_j])
            if _t * 2 < _rtot(traj[_j - 1]) and _t * 2 < _rtot(traj[_j + 1]):
                _gaps_raw.append((traj[_j - 1][0], traj[_j + 1][0]))
                continue
            _keep.append(traj[_j])
        _keep.append(traj[-1])
        traj = _keep
    # Missed reads are gaps too: a frozen client leaves 25s+ holes where
    # nothing was seen at all.
    for _j in range(1, len(traj)):
        if traj[_j][0] - traj[_j - 1][0] > 25:
            _gaps_raw.append((traj[_j - 1][0], traj[_j][0]))
    # The NEXT match's opening frozen by mistake (before the snapshot guard
    # existed) is not this game: its final team scores are nowhere near the
    # match's reported ones. That is the only refusal - a short recording
    # of the RIGHT game is served and labelled partial instead.
    _span = (traj[-1][0] - traj[0][0]) if len(traj) >= 2 else 0.0
    _pmax = max([int(p.get("score") or 0) for p in players] or [0])
    # Peak across the whole recording - the final frame of a normal match
    # reads near-zero once everyone has left.
    _tsc = 0
    for _r in traj:
        _fm = max([int(v or 0) for v in (_r[2] or {}).values()] or [0])
        if _fm > _tsc:
            _tsc = _fm
    if _pmax > 0 and _tsc < 0.5 * _pmax:
        return jsonify({"error": "The recording for this match does not cover "
                                 "the game - no replay is available."}), 404
    # Draw from zero: the watch usually begins ~20 minutes into the match,
    # and the chart is of what was watched.
    _t0 = traj[0][0] if traj else 0.0
    pskill = p.get("skill") or {}
    skills = {k: ((pskill.get(k) or {}).get("top2")
                  or (pskill.get(k) or {}).get("elo")) for k in LIVE_TEAMS}
    dpt = {k: ((pskill.get(k) or {}).get("wr", 0.5),
               (pskill.get(k) or {}).get("games", 0),
               (pskill.get(k) or {}).get("stk", 0)) for k in LIVE_TEAMS
           if pskill.get(k)}
    w, _meta = load_live_model()
    # Down-sample to ~200 drawn points; each point's probability still sees
    # the full 60-read window behind it, exactly like the live view.
    idxs = list(range(len(traj)))
    if len(idxs) > 200:
        step = len(idxs) / 200.0
        idxs = [int(i * step) for i in range(200)]
        if idxs[-1] != len(traj) - 1:
            idxs.append(len(traj) - 1)
    points = []
    for i in idxs:
        t, ct, sc = traj[i][0], traj[i][1], traj[i][2]
        fcrow = traj[i][3] if len(traj[i]) > 3 else None
        wnd = [(r[0], r[2]) for r in traj[max(0, i - 59):i + 1]]
        _strow = traj[i][5] if (len(traj[i]) > 5
                                and isinstance(traj[i][5], dict)) else None
        try:
            hp = win_probability(ct, sc, t, weights=w, skills=skills,
                                 depth=dpt, window=wnd, stations=_strow)
        except Exception:
            hp = {}
        # Radar frame [[team, x, y], ...] recorded with this read, if the
        # match is recent enough to carry one - the radar replay plays
        # these back.
        _rd = traj[i][4] if len(traj[i]) > 4 and isinstance(traj[i][4], list) else None
        _st = traj[i][5] if len(traj[i]) > 5 and isinstance(traj[i][5], dict) else None
        points.append({"t": round(max(0.0, t - _t0), 0),
                       "fc": ([int((fcrow or {}).get(k, 0) or 0) for k in LIVE_TEAMS]
                              if fcrow else None),
                       "rd": _rd,
                       "st": ([(_st or {}).get(k) for k in LIVE_TEAMS] if _st else None),
                       "sc": [int((sc or {}).get(k, 0) or 0) for k in LIVE_TEAMS],
                       "ct": [int((ct or {}).get(k, 0) or 0) for k in LIVE_TEAMS],
                       "p": [round(hp.get(k, 0.0), 3) for k in LIVE_TEAMS]})
    # Rebase and merge the gap intervals for the chart's grey bands.
    _gaps = []
    for _s, _e in sorted(_gaps_raw):
        _s, _e = max(0.0, _s - _t0), max(0.0, _e - _t0)
        if _gaps and _s <= _gaps[-1][1]:
            _gaps[-1][1] = max(_gaps[-1][1], _e)
        else:
            _gaps.append([_s, _e])
    return jsonify(dict(_flood_keys, **{
        "name": p.get("name") or m_name or "", "region": m_region or "",
        "played_at": str(m_played or ""), "sys_id": m_sys,
        "top": p.get("top") or {}, "skill": pskill,
        # So the page can say "covers the last X of a ~Y-minute match"
        # when the recording is partial.
        "tracked_seconds": int(m_treads or 0) * 10,
        "gaps": [[round(a), round(b)] for a, b in _gaps],
        "stlay": p.get("stlay") or None,
        "welcome": p.get("welcome") or None,
        "prob_enabled": WIN_PROB_ENABLED,
        "players": players, "points": points,
    })), 200


@app.route('/replay/<int:mid>')
def replay_page(mid):
    """The journal replay: how a finished match unfolded, read by read."""
    return render_template('replay.html', mid=mid, rkey=None, version=APP_VERSION,
                           page='replay')


@app.route('/replay/r/<path:key>')
def replay_page_unscored(key):
    """A match that was recorded in full but never scored - the scorer could
    not call a winner (no station data, say). The same player, no result."""
    return render_template('replay.html', mid=None, rkey=key, version=APP_VERSION,
                           page='replay')


@app.route('/api/replay/r/<path:key>')
def replay_data_unscored(key):
    """Header + rosters for a no-result replay, from its own frames: every name
    that appeared, by team, with its best score. No result, no ratings, no
    deltas - there were none."""
    rc = replay_db()
    row = rc.execute("SELECT sys_id, at, region, first_ts, data, name, players, dur_s, reason "
                     "FROM trueskill_replay WHERE match_key = ? AND no_result = 1",
                     (key,)).fetchone()
    rc.close()
    if not row:
        return jsonify({"error": "No such replay."}), 404
    try:
        obj = json.loads(zlib.decompress(row[4]).decode('utf-8'))
    except Exception:
        return jsonify({"error": "Replay data unreadable."}), 500
    frames = obj.get("f") if isinstance(obj, dict) else obj
    best = {}
    for fr in (frames or []):
        try:
            for nm, sc, ti in fr[1]:
                if not nm or nm == "?":
                    continue
                k = (str(nm), int(ti))
                if sc is not None and (k not in best or sc > best[k]):
                    best[k] = sc
        except (TypeError, ValueError, IndexError):
            continue
    players = [{"name": nm, "team": "team_%d" % (ti + 1), "won": False,
                "delta": None, "half": 0, "score": sc, "elo": None}
               for (nm, ti), sc in sorted(best.items(), key=lambda kv: -(kv[1] or 0))]
    return jsonify({
        "name": row[5] or ("#%s" % row[0]), "region": row[2] or "",
        "played_at": str(row[1] or ""), "sys_id": row[0],
        "top": {}, "skill": {}, "tracked_seconds": int(row[7] or 0),
        "gaps": [], "stlay": None, "welcome": None,
        "prob_enabled": WIN_PROB_ENABLED,
        "players": players, "points": [], "no_score_chart": True,
        "no_result": True, "reason": row[8] or "",
        "flood": None, "flood_max": 0, "flood_significant": False,
        "radar_flies_missing": False,
    }), 200


_REPLAY_COUNT_CACHE = {}     # (mode, date, sysq) -> (total, ts)
_REPLAY_COUNT_TTL = 300      # the archive count moves only as matches end


def _survival_replays_page(pg, date, sysq, who=''):
    """The Survival side of the /replays archive: recorded survival rounds,
    newest first, each linking to its elimination-timeline replay. Same shape
    of page (search by date + lobby number, ten a page) as the team archive."""
    where, args = [], []
    if date:
        where.append("ended_at LIKE ?")
        args.append(date + '%')
    if sysq:
        where.append("key LIKE ?")           # key = "<sid>|<ended_at>"
        args.append(sysq + '|%')
    if who:
        where.append("winner LIKE ?")        # the rounds they won
        args.append('%' + who + '%')
    clause = (" WHERE " + " AND ".join(where)) if where else ""
    conn = db()
    c = conn.cursor()
    _ckey = ('survival', date, sysq, who)
    _now = time.time()
    _chit = _REPLAY_COUNT_CACHE.get(_ckey)
    if _chit and _now - _chit[1] < _REPLAY_COUNT_TTL:
        total = _chit[0]
    else:
        try:
            total = c.execute("SELECT COUNT(*) FROM survival_results" + clause,
                              args).fetchone()[0]
        except sqlite3.Error:
            total = 0
        if len(_REPLAY_COUNT_CACHE) > 5000:
            _REPLAY_COUNT_CACHE.clear()
        _REPLAY_COUNT_CACHE[_ckey] = (total, _now)
    pages = max(1, (total + 9) // 10)
    pg = min(pg, pages)
    rows = []
    if total:
        labels = dict(REGIONS)
        for key, ended_at, region, lobby, winner, field, data_json in c.execute(
                "SELECT key, ended_at, region, lobby, winner, elim_field_size, data "
                "FROM survival_results" + clause +
                " ORDER BY ended_at DESC LIMIT 10 OFFSET ?", args + [(pg - 1) * 10]):
            try:
                d = json.loads(data_json)
            except (TypeError, ValueError):
                d = {}
            w, ru = _survival_true_winner(d)
            rows.append({
                "key": key, "winner": w or winner or '',
                "field": field or 0,
                "sys": (key.split('|', 1)[0] if key else ''),
                "region": labels.get(region, (region or '').title()),
                "at": str(ended_at or '')[:16],
                "at_utc": ((ended_at or '').replace(' ', 'T') + 'Z') if ended_at else '',
                "mins": int(round((d.get('duration_s') or 0) / 60)),
            })
    conn.close()
    return render_template('replays.html', version=APP_VERSION, page='replays',
                           rows=rows, total=total, pg=pg, pages=pages,
                           date=date, sysq=sysq, who=who, mode='survival')


@app.route('/replays')
def replays_index():
    """Every match that has a replay, newest first - searchable by date and
    server number, ten a page. The browsable archive behind the menu entry."""
    try:
        pg = max(1, int(request.args.get('page', 1)))
    except (TypeError, ValueError):
        pg = 1
    date = str(request.args.get('date') or '').strip()[:10]
    sysq = str(request.args.get('sys') or '').strip()[:12]
    q = str(request.args.get('q') or '').strip()[:40]        # server name
    who = str(request.args.get('who') or '').strip()[:40]    # a player in it
    # Team mode is the archive; Survival (the same page over recorded rounds)
    # is one toggle away, mirroring the leaderboard's mode switch.
    mode = request.args.get('mode', 'team')
    if mode not in ('team', 'survival'):
        mode = 'team'
    if not re.fullmatch(r'\d{4}-\d{2}-\d{2}', date):
        date = ''
    if not sysq.isdigit():
        sysq = ''
    if mode == 'survival':
        return _survival_replays_page(pg, date, sysq, who)
    where, args = [], []
    if re.fullmatch(r'\d{4}-\d{2}-\d{2}', date):
        where.append("m.played_at LIKE ?")
        args.append(date + '%')
    else:
        date = ''
    if sysq.isdigit():
        where.append("m.sys_id = ?")
        args.append(int(sysq))
    else:
        sysq = ''
    if q:
        where.append("m.lobby_name LIKE ?")
        args.append('%' + q + '%')
    if who:
        # The roster is keyed by the account name a result was credited to,
        # so a search finds the match under the name it counted for.
        where.append("m.id IN (SELECT mp.match_row FROM match_players mp WHERE mp.norm_name = ?)")
        args.append(normalize_name(who))
    # The same filters over the no-result replays, which live in the replay
    # database with their own name/date/lobby.
    nr_where, nr_args = ["tr.no_result = 1"], []
    if date:
        nr_where.append("tr.at LIKE ?"); nr_args.append(date + '%')
    if sysq:
        nr_where.append("tr.sys_id = ?"); nr_args.append(int(sysq))
    if q:
        nr_where.append("tr.name LIKE ?"); nr_args.append('%' + q + '%')
    if who:
        nr_where.append("0")             # no-result replays have no credited roster
    nr_cond = " WHERE " + " AND ".join(nr_where)
    conn = db()
    try:
        conn.execute("ATTACH DATABASE ? AS r", (REPLAY_DB_PATH,))
    except sqlite3.Error:
        pass
    _ensure_replay_indexes(conn, 'r.')
    c = conn.cursor()
    # A match is replayable if it has a frozen score trajectory (match_replays)
    # OR a raw radar/win-prob trajectory (r.trueskill_replay, matched to this
    # match's lobby + end time). The player renders from the latter, so listing
    # only match_replays hid replays that were actually viewable (reported bug).
    # "Within an hour" is written as a window on the replay's end time so the
    # (sys_id, at) index answers it, instead of date arithmetic the database
    # had to evaluate for every match ever recorded.
    have = ("(EXISTS (SELECT 1 FROM match_replays mr WHERE mr.match_row = m.id) "
            "OR EXISTS (SELECT 1 FROM r.trueskill_replay tr WHERE tr.sys_id = m.sys_id "
            "AND tr.at > datetime(m.played_at, '-1 hour') "
            "AND tr.at < datetime(m.played_at, '+1 hour')))")
    full_cond = (" WHERE COALESCE(m.voided, 0) = 0 AND " + have
                 + ((" AND " + " AND ".join(where)) if where else ""))
    # The total only feeds "N replays, page X/Y" and only changes when a match
    # ends, but computing it means running the replayable-EXISTS across every
    # match ever (the row fetch below is cheap - it stops at 10). So cache it
    # briefly per filter; paging and revisits then skip the full scan entirely.
    _ckey = ('team', date, sysq, q, who)
    _now = time.time()
    _chit = _REPLAY_COUNT_CACHE.get(_ckey)
    if _chit and _now - _chit[1] < _REPLAY_COUNT_TTL:
        total = _chit[0]
    else:
        try:
            c.execute("SELECT COUNT(*) FROM matches m" + full_cond, args)
            total = c.fetchone()[0]
        except sqlite3.Error:
            total = 0
        try:
            c.execute("SELECT COUNT(*) FROM r.trueskill_replay tr" + nr_cond, nr_args)
            total += c.fetchone()[0]
        except sqlite3.Error:
            pass
        if len(_REPLAY_COUNT_CACHE) > 5000:
            _REPLAY_COUNT_CACHE.clear()
        _REPLAY_COUNT_CACHE[_ckey] = (total, _now)
    pages = max(1, (total + 9) // 10)
    pg = min(pg, pages)
    rows = []
    if total:
        # Scored matches and no-result replays in ONE list, newest first. Each
        # side is asked for the newest pg*10 it has and the two are merged
        # here. A single UNION had to build BOTH lists in full before it could
        # sort them, which meant re-checking every match ever recorded on every
        # visit; asked separately, each side walks its own newest-first index
        # and stops as soon as it has enough.
        want = pg * 10
        c.execute("SELECT 'm', m.id, '', m.lobby_name, m.sys_id, "
                  "COALESCE(m.region,'america'), m.played_at, "
                  "COALESCE(m.tracked_reads, 0) * 10, '' FROM matches m" + full_cond +
                  " ORDER BY m.played_at DESC, m.id DESC LIMIT ?", args + [want])
        got = c.fetchall()
        try:
            c.execute("SELECT 'nr', 0, tr.match_key, tr.name, tr.sys_id, "
                      "COALESCE(tr.region,'america'), tr.at, COALESCE(tr.dur_s, 0), "
                      "COALESCE(tr.reason, '') FROM r.trueskill_replay tr" + nr_cond +
                      " ORDER BY tr.at DESC LIMIT ?", nr_args + [want])
            got += c.fetchall()
        except sqlite3.Error:
            pass
        got.sort(key=lambda x: (str(x[6] or ''), x[1] or 0), reverse=True)
        got = got[(pg - 1) * 10: pg * 10]
        labels = dict(REGIONS)
        for kind, mid, key, name, sysid, region, at, secs, reason in got:
            rows.append({"kind": kind, "id": mid, "key": key or '',
                         "name": name or ("#%s" % sysid),
                         "sys": sysid, "region": labels.get(region, region),
                         "at": str(at or '')[:16],
                         "at_utc": ((at or '').replace(' ', 'T') + 'Z') if at else '',
                         "mins": int(round((secs or 0) / 60.0)),
                         "reason": reason or ''})
    conn.close()
    return render_template('replays.html', version=APP_VERSION, page='replays',
                           rows=rows, total=total, pg=pg, pages=pages,
                           date=date, sysq=sysq, q=q, who=who, mode='team')


def _live_ship_codes(d):
    """Ship id -> the hull that ship is flying, for one watcher reading.

    teams row = [name, score, tier+1, model, id, ..], and the site's ship
    code is (tier+1)*100 + (model_byte+1). Model 0 is a real ship (the
    Fly), so the test is for None, never for truth. The radar and the
    roster both draw from this, so they always agree.
    """
    codes = {}
    for k in ("team_1", "team_2", "team_3"):
        for r in (d.get("teams", {}).get(k) or []):
            if not r or len(r) < 5 or r[4] is None:
                continue
            try:
                tier, model = int(r[2]), int(r[3])
            except (TypeError, ValueError):
                continue
            if tier >= 1 and model >= 0:
                codes[r[4]] = tier * 100 + model + 1
    return codes


def _live_radar(d):
    """The live radar rows with the hull each ship is flying appended:
    [team, id, x, y] becomes [team, id, x, y, ship]."""
    codes = _live_ship_codes(d)
    out = []
    for e in (d.get("radar") or []):
        if not e or len(e) < 4:
            continue
        row = list(e[:4])
        c = codes.get(e[1])
        if c:
            row.append(c)
        out.append(row)
    return out


@app.route('/api/ships')
def api_ships():
    """Every ship silhouette, once. The live radar needs the same outlines the
    replay uses; sending them with each poll would be tens of kilobytes a
    second, so they are fetched once and cached hard - they never change."""
    out = {}
    for code in sorted(ship_shapes.SHIP_NAME):
        d = ship_shapes.ship_path(code)
        if d:
            out[str(code)] = {"d": d, "name": ship_shapes.ship_name(code)}
    resp = jsonify({"ships": out})
    resp.headers['Cache-Control'] = 'public, max-age=604800, immutable'
    return resp, 200


@app.route('/api/live/state', methods=['POST'])
def live_state_ingest():
    """The droplet feed posts one watched lobby's live team state here every
    ~10s. Stored in live.db (a separate file) for the owner-only /live view.
    Authenticated with the same shared key the tracker uses for results."""
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401
    d = request.json or {}
    try:
        sys_id = int(d.get("sys_id"))
    except (TypeError, ValueError):
        return jsonify({"error": "bad sys_id"}), 400
    counts = d.get("counts") or {}
    scores = d.get("scores") or {}
    top = d.get("top") or {}
    region = str(d.get("region") or "")[:16]
    name = str(d.get("name") or "")[:40]
    elapsed = float(d.get("elapsed") or 0)
    now = time.time()
    ct = {k: int(counts.get(k, 0) or 0) for k in LIVE_TEAMS}
    sc = {k: int(scores.get(k, 0) or 0) for k in LIVE_TEAMS}
    # FULL ship counts from the game's complete ship cache - the panel
    # counts cap at the visible 8, so this is what shows a 15-ship flood.
    fc = d.get("fullc")
    fc = ({k: int(fc.get(k, 0) or 0) for k in LIVE_TEAMS}
          if isinstance(fc, dict) else None)
    # Roster skill: who is on each team right now, joined to the leaderboard.
    # A player the board does not know counts as a fresh 1000 - same rule the
    # trainer uses, so live and training see skill identically.
    skill = {}
    rdet = {}
    _psc = d.get("pscores") if isinstance(d.get("pscores"), dict) else {}
    _psh = d.get("pships") if isinstance(d.get("pships"), dict) else {}
    rosters = d.get("rosters") or {}
    if isinstance(rosters, dict) and any(rosters.values()):
        try:
            _sc = db(timeout=3)
            _scc = _sc.cursor()
            for k in LIVE_TEAMS:
                names = [str(n)[:32] for n in (rosters.get(k) or [])][:16]
                if not names:
                    continue
                elos, wrs, games, known = [], [], 0, 0
                clans = {}
                _det = []
                for nm in names:
                    row = _scc.execute(
                        "SELECT elo, COALESCE(wins,0), COALESCE(losses,0), clan "
                        "FROM players WHERE norm_name = ?",
                        (normalize_name(nm),)).fetchone()
                    if row:
                        known += 1
                        elos.append(float(row[0]))
                        g = row[1] + row[2]
                        games += g
                        wrs.append((row[1] / g) if g else 0.5)
                        if row[3]:
                            clans[row[3]] = clans.get(row[3], 0) + 1
                        _det.append({"n": nm[:24], "e": round(float(row[0]), 1),
                                     "w": round((row[1] / g) if g else 0.5, 3),
                                     "g": g, "c": row[3] or None, "k": 1,
                                     "s": int(_psc.get(nm, 0) or 0),
                                     "sp": _psh.get(nm) or None})
                    else:
                        elos.append(1000.0)
                        wrs.append(0.5)
                        _det.append({"n": nm[:24], "e": 1000.0, "w": 0.5,
                                     "g": 0, "c": None, "k": 0,
                                     "s": int(_psc.get(nm, 0) or 0),
                                     "sp": _psh.get(nm) or None})
                rdet[k] = _det
                # The model uses the two best players, not the team average:
                # measured on 1,015 matches, one strong player carries real
                # predictive weight that a mean of eight would bury. Winrate,
                # experience and the largest same-clan group feed the
                # roster-depth features (measured worth keeping too).
                top2 = sorted(elos, reverse=True)[:2]
                skill[k] = {"elo": round(sum(elos) / len(elos), 1),
                            "top2": round(sum(top2) / len(top2), 1),
                            "wr": round(sum(wrs) / len(wrs), 3),
                            "stk": max(clans.values()) if clans else 0,
                            "known": known, "n": len(names), "games": games}
            _sc.close()
        except sqlite3.Error:
            skill = {}
    conn = live_db()
    c = conn.cursor()
    row = c.execute("SELECT payload FROM live WHERE sys_id=?", (sys_id,)).fetchone()
    traj = []
    if row:
        try:
            traj = (json.loads(row[0]) or {}).get("traj", [])
        except Exception:
            traj = []
    # A reset (a new match starting in the same lobby, or the feed's clock
    # restarting) begins a fresh trajectory - but the OLD one is stashed,
    # never discarded: the ended match's result usually arrives after the
    # reset, and its replay is built from the stash.
    _reset = bool(traj) and (elapsed < 12 or elapsed < traj[-1][0] - 30)
    if _reset:
        if len(traj) >= 6 and row:
            c.execute("INSERT INTO live_prev (sys_id, saved, payload) "
                      "VALUES (?,?,?) ON CONFLICT(sys_id) DO UPDATE SET "
                      "saved=excluded.saved, payload=excluded.payload",
                      (sys_id, now, row[0]))
            c.execute("DELETE FROM live_prev WHERE saved < ?", (now - 6 * 3600,))
        traj = []
    traj.append([round(elapsed, 1), ct, sc] + ([fc] if fc else []))
    traj = traj[-LIVE_TRAJ_CAP:]
    # Is somebody flooding this lobby right now? Raised while the match is
    # still live so it can be watched as it happens, not only judged after.
    live_flood, flood_worst = roster_flood(rosters)
    if flood_worst >= FLOOD_SIGNIFICANT:
        queue_flood_alert('live', sys_id, live_flood, flood_worst,
                          lobby_name=name, region=region)
    # Station health per team: [level, gems, mods_alive, mods_total,
    # damaged, destroyed, [12 module HP bytes]], decoded by the tracker
    # from the game's own station-state packet. Display-only here.
    sth = d.get('sthealth') if isinstance(d.get('sthealth'), dict) else None
    # Radar: [[team index, x, y], ...] latest frame; layout: the static
    # per-team module blueprints [[id, type, x, y, dir], ...].
    radar = d.get('radar') if isinstance(d.get('radar'), list) else None
    if radar:
        radar = [[int(e[0]), int(e[1]), int(e[2])] for e in radar[:64]
                 if isinstance(e, list) and len(e) == 3]
    stlay = d.get('stlayout') if isinstance(d.get('stlayout'), list) else None
    if radar:
        # Radar history rides the trajectory so replays can play it back.
        traj[-1] = traj[-1][:3] + [traj[-1][3] if len(traj[-1]) > 3 else {}, radar]
    if sth:
        # [level, gems, alive, total, weak, dead, [12 module HP bytes]] per
        # team. Only the parts a replay draws are kept: the whole match's
        # worth of these has to fit in one stored blob.
        _slim = {}
        for _k, _v in sth.items():
            if isinstance(_v, list) and len(_v) >= 7 and isinstance(_v[6], list):
                _slim[_k] = [_v[0], _v[1], _v[6]]
            elif isinstance(_v, list) and len(_v) >= 2:
                _slim[_k] = [_v[0], _v[1], None]
        if _slim:
            while len(traj[-1]) < 5:
                traj[-1].append(None)
            traj[-1] = traj[-1][:5] + [_slim]
    payload = {"counts": ct, "scores": sc,
               "top": {k: str(top.get(k, "") or "")[:24] for k in LIVE_TEAMS},
               "skill": skill, "rdet": rdet, "sth": sth,
               "welcome": d.get('welcome') if isinstance(d.get('welcome'),
                                                         dict) else None,
               "radar": radar, "stlay": stlay,
               "flood": live_flood, "flood_max": flood_worst,
               "traj": traj}
    c.execute("INSERT INTO live (sys_id, updated, elapsed, region, name, payload) "
              "VALUES (?,?,?,?,?,?) ON CONFLICT(sys_id) DO UPDATE SET "
              "updated=excluded.updated, elapsed=excluded.elapsed, "
              "region=excluded.region, name=excluded.name, payload=excluded.payload",
              (sys_id, now, elapsed, region, name, json.dumps(payload)))
    # Rows are upserted by sys_id and sys_ids only ever grow, so dead lobbies
    # used to accumulate forever - live.db reached 162MB of long-over matches
    # and filled the disk quota (1 Sep). A day-old row is a match long over;
    # prune on every push (a few hundred rows, the sweep costs nothing).
    c.execute("DELETE FROM live WHERE updated < ?", (now - 86400.0,))
    c.execute("DELETE FROM live_prev WHERE saved < ?", (now - 86400.0,))
    conn.commit()
    conn.close()
    return jsonify({"ok": True}), 200


@app.route('/api/live/matches')
def live_matches():
    """Every actively-watched lobby with live win probabilities.

    Public since 7.0.0; the flood alert board is an owner tool and is
    only attached for the owner."""
    _owner = is_site_owner()
    now = time.time()
    out = []
    w, model_meta = load_live_model()
    try:
        conn = live_db()
        c = conn.cursor()
        rows = c.execute("SELECT sys_id, updated, elapsed, region, name, payload "
                         "FROM live WHERE updated > ? ORDER BY region, sys_id",
                         (now - LIVE_STALE_SECONDS,)).fetchall()
        conn.close()
    except Exception:
        rows = []
    for sys_id, updated, elapsed, region, name, payload in rows:
        try:
            p = json.loads(payload) or {}
        except Exception:
            continue
        counts = p.get("counts", {})
        scores = p.get("scores", {})
        top = p.get("top", {})
        pskill = p.get("skill") or {}
        skills = {k: ((pskill.get(k) or {}).get("top2")
                      or (pskill.get(k) or {}).get("elo")) for k in LIVE_TEAMS}
        dpt = {k: ((pskill.get(k) or {}).get("wr", 0.5),
                   (pskill.get(k) or {}).get("games", 0),
                   (pskill.get(k) or {}).get("stk", 0)) for k in LIVE_TEAMS
               if pskill.get(k)}
        traj = p.get("traj", [])
        wnd = [(r_[0], r_[2]) for r_ in traj[-60:] if len(r_) >= 3]
        _stnow = p.get("sth") if isinstance(p.get("sth"), dict) else None
        if not _station_usable(_stnow):
            # The station feed goes blank for ~a minute when the game
            # drops the spectator connection. Stations do not un-level or
            # un-damage in that window, so the last real reading (up to
            # ~5 min back) is better evidence than silence - this is the
            # gap that let a 1v15 read 33% (Boretiralaris, 24 Aug).
            for _r in reversed(traj[-30:]):
                if (len(_r) > 5 and isinstance(_r[5], dict)
                        and _station_usable(_r[5])):
                    _stnow = _r[5]
                    break
        probs = win_probability(counts, scores, elapsed, weights=w,
                                skills=skills, depth=dpt, window=wnd,
                                stations=_stnow)
        history = []
        for i, row in enumerate(traj[-40:]):
            try:
                t, ct, sc = row[0], row[1], row[2]
                base_i = len(traj) - min(len(traj), 40) + i
                w_i = [(r_[0], r_[2]) for r_ in traj[max(0, base_i - 59):base_i + 1]
                       if len(r_) >= 3]
                _sti = row[5] if (len(row) > 5
                                  and isinstance(row[5], dict)) else None
                hp = win_probability(ct, sc, t, weights=w, skills=skills,
                                     depth=dpt, window=w_i, stations=_sti)
                history.append([round(t, 0), round(hp["team_1"], 3),
                                round(hp["team_2"], 3), round(hp["team_3"], 3)])
            except Exception:
                pass
        # Per-player impact: recompute the team's probability with each
        # player removed - the drop is what that player is worth to the
        # model right now (through ratings, win rate, experience and clan
        # stacking; the team's score is a team fact and stays put).
        _rdet = p.get("rdet") or {}

        def _agg(_plist):
            if not _plist:
                return None, None
            _el = [q["e"] for q in _plist]
            _t2 = sorted(_el, reverse=True)[:2]
            _cl = {}
            for q in _plist:
                if q.get("c"):
                    _cl[q["c"]] = _cl.get(q["c"], 0) + 1
            return (sum(_t2) / len(_t2),
                    (sum(q["w"] for q in _plist) / len(_plist),
                     sum(q.get("g", 0) for q in _plist),
                     max(_cl.values()) if _cl else 0))

        players_by_team = {}
        for k in LIVE_TEAMS:
            _plist = _rdet.get(k) or []
            if not _plist or probs.get(k) is None:
                continue
            if not WIN_PROB_ENABLED:
                # No prediction => no impact. Still surface the roster the
                # live viewer shows, ordered by score.
                players_by_team[k] = sorted(
                    [{"name": _pl["n"], "elo": _pl["e"],
                      "known": _pl.get("k", 0),
                      "score": int(_pl.get("s", 0) or 0),
                      "ship": ship_shapes.ship_name(_pl.get("sp")) or (_pl.get("sp") or None), "imp": None}
                     for _pl in _plist],
                    key=lambda q: -q["score"])
                continue
            _out = []
            for _i, _pl in enumerate(_plist):
                _rest = _plist[:_i] + _plist[_i + 1:]
                _sk2 = dict(skills)
                _dp2 = dict(dpt)
                _a = _agg(_rest)
                if _a is None or _a[0] is None:
                    _sk2[k] = None
                    _dp2.pop(k, None)
                else:
                    _sk2[k] = _a[0]
                    _dp2[k] = _a[1]
                try:
                    _hp = win_probability(counts, scores, elapsed, weights=w,
                                          skills=_sk2, depth=_dp2, window=wnd,
                                          stations=_stnow)
                    _imp = probs.get(k, 0.0) - _hp.get(k, 0.0)
                except Exception:
                    _imp = 0.0
                _out.append({"name": _pl["n"], "elo": _pl["e"],
                             "known": _pl.get("k", 0),
                             "score": int(_pl.get("s", 0) or 0),
                             "ship": ship_shapes.ship_name(_pl.get("sp")) or (_pl.get("sp") or None),
                             "imp": round(_imp, 4)})
            _out.sort(key=lambda q: -q["imp"])
            players_by_team[k] = _out

        _sth = p.get("sth") or {}
        _lay = p.get("stlay") or []
        _wl = p.get("welcome") or {}
        _wlteams = _wl.get("teams") if isinstance(_wl.get("teams"), list) else []
        def _lbl(k):
            i = int(k[-1]) - 1
            if i < len(_wlteams) and isinstance(_wlteams[i], dict):
                f = str(_wlteams[i].get("faction") or "").strip()
                if f:
                    return f[:28]
            return "Team %s" % k[-1]
        teams = [{"key": k, "label": _lbl(k),
                  "score": int(scores.get(k, 0) or 0),
                  "count": int(counts.get(k, 0) or 0),
                  "top": (top.get(k, "") if _owner else ""),
                  "skill": pskill.get(k) or None,
                  "players": (players_by_team.get(k) or []) if _owner else [],
                  "station": _sth.get(k) or None,
                  "layout": (_lay[_i] if _i < len(_lay) else None),
                  "prob": (round(probs.get(k, 0.0), 4)
                           if WIN_PROB_ENABLED else None)}
                 for _i, k in enumerate(LIVE_TEAMS)]
        out.append({"sys_id": sys_id, "region": region, "name": name,
                    "elapsed": int(elapsed), "age": round(now - updated, 1),
                    "welcome": p.get("welcome") or None,
                    "teams": teams, "history": history,
                    "radar": p.get("radar") or None,
                    "flood": p.get("flood") or {},
                    "flood_max": p.get("flood_max") or 0})
    flooded = [m for m in out if m["flood_max"] >= FLOOD_SIGNIFICANT]
    body = {"matches": out, "count": len(out),
            "prob_enabled": WIN_PROB_ENABLED,
            "model": model_meta or {"builtin": True}}
    if _owner:
        body["flood_alert"] = {"count": len(flooded),
                               "significant_at": FLOOD_SIGNIFICANT,
                               "lobbies": [m["sys_id"] for m in flooded]}
    return jsonify(body), 200


@app.route('/api/my/held')
def my_held_results():
    """Why a match you played did not appear on your record.

    Every decision the tracker or the rating engine declines to make is
    already written down with a reason - this hands the player their own
    ones in plain words instead of leaving the match silently missing
    (7.0.0)."""
    sub_id = current_user()
    if not sub_id:
        return jsonify({"held": []}), 200
    conn = db()
    c = conn.cursor()
    c.execute("SELECT norm_name FROM players WHERE google_sub = ?", (sub_id,))
    keys = [r[0] for r in c.fetchall() if r[0]]
    if not keys:
        conn.close()
        return jsonify({"held": []}), 200
    ph = ",".join("?" for _ in keys)
    c.execute("SELECT name, region, won, score, reason, played_at, sys_id "
              "FROM held_results WHERE norm_name IN (%s) "
              "ORDER BY id DESC LIMIT 25" % ph, keys)
    rows = c.fetchall()
    conn.close()
    WHY = {
        'dominance-flip': ("Your team led every rival by a distance and then lost to a "
                           "side that filled up mid-match. That result is set aside "
                           "rather than counted against you."),
        'protected': ("Protection is on for this name and no check-in was found for "
                      "this match, so the result was withheld - it could have been "
                      "somebody else playing under your name."),
        'resurgence': ("The team that won this match had collapsed to almost nobody "
                       "and then filled back up and came back. You were fighting the "
                       "other side by then, so this one is not counted against you."),
        'flood-cut': ("This match was swarmed by a flood of scripted ships. It is "
                      "rated as it stood when the swarm arrived, and the sides the "
                      "swarm landed on take no loss for it."),
        'joined-too-late': ("You checked in less than ten minutes before this match "
                            "ended. A few minutes at the end is not a match, so it "
                            "counts neither way."),
        'thin_margin_orphan': ("The match ended while nobody was watching it closely "
                               "enough, and the winner would have been a guess. It is "
                               "kept on record but not rated."),
    }
    return jsonify({"held": [{
        "name": r[0], "region": r[1], "won": bool(r[2]), "score": r[3],
        "reason": r[4], "at": r[5], "sys_id": r[6],
        "why": WHY.get(r[4], "This result was set aside for review."),
    } for r in rows]}), 200


@app.route('/api/live/model', methods=['POST'])
def live_model_update():
    """The daily retrain on the droplet posts refreshed win-probability weights
    here (same shared key as the tracker). Weights live in live.db, so the model
    improves without any code deploy. Rejected unless it is 10 valid numbers."""
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401
    d = request.json or {}
    w = d.get("weights")
    meta = d.get("meta") or {}
    if not (isinstance(w, list) and len(w) in (10, 13, 19, 23)
            and all(isinstance(x, (int, float)) for x in w)):
        return jsonify({"error": "weights must be 10, 13, 19 or 23 numbers"}), 400
    conn = live_db()
    conn.execute("INSERT INTO model (id, weights, meta, updated) VALUES (1,?,?,?) "
                 "ON CONFLICT(id) DO UPDATE SET weights=excluded.weights, "
                 "meta=excluded.meta, updated=excluded.updated",
                 (json.dumps(w), json.dumps(meta), time.time()))
    conn.commit()
    conn.close()
    return jsonify({"ok": True}), 200


@app.route('/api/shadow/wp_model', methods=['POST'])
def shadow_wp_model_update():
    """The daily FROM-T=0 shadow retrain (winprob/shadow_wp_train.py) posts its
    weights here. Stored in its own shadow_model row so /rawlive scores live
    lobbies with the freshest model - no code deploy. Kept apart from the live
    (20-min) model. Rejected unless it is exactly the feature count we expect."""
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401
    d = request.json or {}
    w = d.get("w") or d.get("weights")
    meta = d.get("meta") or {}
    nf = len(SHADOW_WP_FEATURES)
    if not (isinstance(w, list) and len(w) == nf
            and all(isinstance(x, (int, float)) for x in w)):
        return jsonify({"error": "w must be %d numbers" % nf}), 400
    conn = live_db()
    conn.execute("INSERT INTO shadow_model (id, weights, meta, updated) "
                 "VALUES (1,?,?,?) ON CONFLICT(id) DO UPDATE SET "
                 "weights=excluded.weights, meta=excluded.meta, "
                 "updated=excluded.updated",
                 (json.dumps(w), json.dumps(meta), time.time()))
    conn.commit()
    conn.close()
    return jsonify({"ok": True, "features": nf}), 200


@app.route('/api/live/skill_export')
def live_skill_export():
    """Everything the daily retrain needs to know player skill AT MATCH TIME:
    each rated player's current elo/wins/losses, plus every match delta with
    its timestamp. The trainer walks the deltas backwards from the current
    rating, so a match from last week is judged by last week's ratings - not
    today's, which would let the model peek at the future."""
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401
    conn = db()
    c = conn.cursor()
    players = {}
    for norm, elo, w_, l_, clan in c.execute(
            "SELECT norm_name, elo, COALESCE(wins,0), COALESCE(losses,0), clan "
            "FROM players WHERE COALESCE(wins,0)+COALESCE(losses,0) > 0 "
            "AND norm_name IS NOT NULL"):
        players[norm] = [round(float(elo), 2), w_, l_, clan or ""]
    history = [[at, norm, d] for at, norm, d in c.execute(
        "SELECT m.played_at, mp.norm_name, mp.delta FROM match_players mp "
        "JOIN matches m ON m.id = mp.match_row WHERE mp.delta IS NOT NULL "
        "ORDER BY m.played_at")]
    conn.close()
    return jsonify({"players": players, "history": history,
                    "starting_elo": STARTING_ELO}), 200


def repair_surrogates(obj):
    """Make every string in a payload UTF-8 encodable instead of fatal.

    Player names come from the game client, where an emoji is a surrogate
    PAIR. When such a pair survives the JSON round-trip as two lone
    surrogates, Python cannot encode it to UTF-8 and sqlite3 raises rather
    than storing it - which 500s the whole request and loses the ENTIRE
    match. Seen live 23 Aug 2026: one /api/game_end died inside
    account_for_ingame_name on a half-emoji in a player name, and nobody
    in that game was rated.

    Round-tripping through UTF-16 recombines a real pair back into the
    character it always was, so the name is repaired rather than mangled;
    a genuinely unpaired half becomes U+FFFD so it can at least be stored.
    Recurses through dicts and lists because names arrive as values, as
    list entries AND as dict KEYS - scores are keyed by player name.
    """
    if isinstance(obj, str):
        try:
            obj.encode('utf-8')
            return obj
        except UnicodeEncodeError:
            return obj.encode('utf-16', 'surrogatepass').decode('utf-16',
                                                                'replace')
    if isinstance(obj, dict):
        return {repair_surrogates(k): repair_surrogates(v)
                for k, v in obj.items()}
    if isinstance(obj, list):
        return [repair_surrogates(v) for v in obj]
    return obj


@app.route('/api/wins_recredit', methods=['POST'])
def api_wins_recredit():
    """Restore a win that the impersonation guard took by mistake.

    Takes {"rows": [{"match_id": .., "name": ..}, ..], "dry_run": bool}.

    The WIN only. A match may not create or destroy rating (7.0.0): the
    damping that balances the winners' gain against the losers' loss
    already ran without these players, so paying them now would mint points
    from nothing, and paying them out of their team-mates' gain would take
    rating from people who did nothing wrong. The row is written with a
    zero delta - their record gains the win and the match appears in their
    history, and no rating moves.

    Idempotent: a player already recorded in that match is left alone, and
    `recredits` has a unique index so a second run credits nobody twice.
    """
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401
    body = request.json or {}
    rows = body.get('rows') or []
    dry = bool(body.get('dry_run'))
    if not isinstance(rows, list):
        return jsonify({"error": "rows must be a list"}), 400
    conn = db()
    c = conn.cursor()
    now = time.strftime('%Y-%m-%d %H:%M:%S')
    done, already, no_match, no_player, sample = 0, 0, 0, 0, []
    for r in rows[:1000]:
        if not isinstance(r, dict):
            continue
        mid = str(r.get('match_id') or '')
        raw = str(r.get('name') or '')
        nn = normalize_name(raw)
        if not mid or not nn:
            continue
        m = c.execute("SELECT id FROM matches WHERE match_id = ? LIMIT 1", (mid,)).fetchone()
        if not m:
            no_match += 1
            continue
        mrow = m[0]
        p = c.execute("SELECT name FROM players WHERE norm_name = ? LIMIT 1", (nn,)).fetchone()
        if not p:
            no_player += 1
            continue
        seen = c.execute("SELECT 1 FROM match_players WHERE match_row = ? AND norm_name = ? "
                         "LIMIT 1", (mrow, nn)).fetchone()
        if seen:
            already += 1
            continue
        done += 1
        if len(sample) < 8:
            sample.append({"match_row": mrow, "name": p[0]})
        if dry:
            continue
        c.execute("INSERT INTO match_players (match_row, name, norm_name, won, delta, half, "
                  "score, played_as, team, ship, deaths) "
                  "VALUES (?, ?, ?, 1, 0, 0, 0, ?, 'win', NULL, NULL)",
                  (mrow, p[0], nn, raw))
        c.execute("UPDATE players SET wins = COALESCE(wins, 0) + 1 WHERE norm_name = ?", (nn,))
        c.execute("INSERT OR IGNORE INTO recredits (match_row, match_id, norm_name, name, at) "
                  "VALUES (?, ?, ?, ?, ?)", (mrow, mid, nn, p[0], now))
    if not dry:
        conn.commit()
    conn.close()
    return jsonify({"ok": True, "dry_run": dry, "credited": done,
                    "already_had_it": already, "match_not_found": no_match,
                    "player_not_found": no_player, "sample": sample}), 200


@app.route('/api/score_backfill', methods=['POST'])
def api_score_backfill():
    """Raise stored match scores to the peak each player actually reached.

    Takes {"rows": [{"match_id": .., "peaks": {in-game name: peak}}, ..],
    "dry_run": bool}. A row is matched by the name the player PLAYED under
    (`played_as`), falling back to the credited name, both normalized -
    rosters are rewritten to account names at the door, so matching on the
    credited name alone would miss everyone who plays under another name.
    A score is only ever raised, never lowered: a peak at or below what is
    stored leaves the row alone, so running this twice changes nothing the
    second time.
    """
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401
    data = request.get_json(silent=True) or {}
    rows = data.get('rows')
    if not isinstance(rows, list):
        return jsonify({"error": "rows must be a list"}), 400
    if len(rows) > 400:
        return jsonify({"error": "at most 400 matches per request"}), 400
    dry = bool(data.get('dry_run'))
    seen = found = raised = unchanged = unmatched = 0
    added = 0
    samples = []
    conn = db()
    c = conn.cursor()
    for item in rows:
        if not isinstance(item, dict):
            continue
        seen += 1
        mid = str(item.get('match_id') or '')[:128]
        peaks = item.get('peaks')
        if not mid or not isinstance(peaks, dict):
            continue
        c.execute("SELECT id FROM matches WHERE match_id = ?", (mid,))
        mrow = c.fetchone()
        if not mrow:
            continue
        found += 1
        # Several in-game names can normalize to one key; the best wins.
        by_key = {}
        for nm, pk in peaks.items():
            try:
                pk = int(pk)
            except (TypeError, ValueError):
                continue
            k = normalize_name(nm)
            if k and pk > by_key.get(k, -1):
                by_key[k] = pk
        c.execute("SELECT rowid, name, played_as, score FROM match_players "
                  "WHERE match_row = ?", (mrow[0],))
        for rid, pname, played_as, score in c.fetchall():
            pk = by_key.get(normalize_name(played_as or ''))
            if pk is None:
                pk = by_key.get(normalize_name(pname or ''))
            if pk is None:
                unmatched += 1
                continue
            cur = int(score or 0)
            if pk <= cur:
                unchanged += 1
                continue
            raised += 1
            added += pk - cur
            if len(samples) < 8:
                samples.append({"match_id": mid, "name": pname,
                                "from": (score if score is not None else None),
                                "to": pk})
            if not dry:
                c.execute("UPDATE match_players SET score = ? WHERE rowid = ?",
                          (pk, rid))
    if dry:
        conn.rollback()
    else:
        conn.commit()
    conn.close()
    return jsonify({"dry_run": dry, "matches_seen": seen, "matches_found": found,
                    "rows_raised": raised, "rows_unchanged": unchanged,
                    "rows_unmatched": unmatched, "points_added": added,
                    "samples": samples}), 200


@app.route('/api/game_end', methods=['POST'])
def game_end():
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401

    data = request.json
    if not data:
        return jsonify({"error": "No data provided"}), 400

    # Before ANY of it reaches sqlite - see repair_surrogates. One broken
    # emoji in one player's name used to cost the whole match.
    data = repair_surrogates(data)

    # Send every name through the bindings BEFORE anything else looks at
    # it, so a result played under any name lands on the right account.
    # Done at the door on purpose: nothing below here has to know that
    # accounts exist, so the rating rules are untouched.
    try:
        _conn = db()
        _c = _conn.cursor()
        _seen = {}
        _played_as = {}
        _sys = data.get('sys_id')

        def _to_account(nm):
            if nm not in _seen:
                _seen[nm] = account_for_ingame_name(_c, nm, _sys) or nm
            acct = _seen[nm]
            # Keep the original spelling against the account it was
            # credited to, so the match can show what they were called
            # even though the rating went somewhere else.
            if acct != nm:
                _played_as[acct] = nm
            return acct

        for _key in ('winning_team', 'losing_team_1', 'losing_team_2',
                     'all_players', 'half_elo', 'ambiguous',
                     'dominance_exempt'):
            _val = data.get(_key)
            if isinstance(_val, list):
                data[_key] = [_to_account(str(x)) for x in _val]
        # Scores are keyed by the same in-game names, and have to land on
        # the same account rows the results do.
        _sc = data.get('scores')
        if isinstance(_sc, dict):
            data['scores'] = {_to_account(str(k)): v for k, v in _sc.items()}
        # So is the presence share, which is looked up by the same key
        # half_elo is - rewrite it or a renamed player silently falls
        # back to flat half.
        _pr = data.get('presence')
        if isinstance(_pr, dict):
            data['presence'] = {_to_account(str(k)): v for k, v in _pr.items()}
        # Peak score decides whether a winner is eligible at all, and ships
        # and deaths are shown on the profile - all three are keyed by the
        # in-game name, so they have to follow the roster onto the account or
        # they simply miss for anyone playing under another name. Two names
        # can land on one account, so the peak is the higher of the two.
        # ship_scores is NOT here: it is keyed by ship id, and rewriting it
        # would break the check-in binding.
        _pk = data.get('peak_scores')
        if isinstance(_pk, dict):
            _byacct = {}
            for _k, _v in _pk.items():
                _a = _to_account(str(_k))
                try:
                    if _a not in _byacct or float(_v) > float(_byacct[_a]):
                        _byacct[_a] = _v
                except (TypeError, ValueError):
                    _byacct.setdefault(_a, _v)
            data['peak_scores'] = _byacct
        for _dk in ('ships', 'deaths'):
            _dv = data.get(_dk)
            if isinstance(_dv, dict):
                data[_dk] = {_to_account(str(_k)): _v for _k, _v in _dv.items()}
        data['played_as_map'] = _played_as
        # The result has landed - stop showing this lobby as "Scoring" on /play.
        if _sys is not None:
            try:
                _c.execute("DELETE FROM scoring_lobbies WHERE sys_id = ?", (_sys,))
                _conn.commit()
            except sqlite3.Error:
                pass
        _conn.close()
    except sqlite3.Error:
        pass

    winning_team = data.get('winning_team', [])
    losing_team_1 = data.get('losing_team_1', [])
    losing_team_2 = data.get('losing_team_2', [])
    losing_all = losing_team_1 + losing_team_2
    sys_id = data.get('sys_id')
    ambiguous = {normalize_name(n) for n in data.get('ambiguous', [])}
    # Players the tracker first saw in the back half of a match. They used
    # to be dropped from the result entirely, which meant somebody who
    # joined late and won came out level with somebody who never played.
    # Now they earn half. The winning team's top five are never in here -
    # the tracker exempts them before sending, because the roster panel is
    # ordered by score and those are the players who decided it.
    half_elo = {normalize_name(n) for n in data.get('half_elo', [])}

    # A team that led by a distance and lost anyway to a side that
    # filled up mid-match. The tracker decides this - only it can see
    # the scoreboard over time and who arrived - and the site applies
    # it: that team is not rated at all, and the winners take half,
    # because arriving late in numbers is not the same as beating the
    # lead that was already there.
    dominance_exempt = {normalize_name(n)
                        for n in (data.get('dominance_exempt') or [])}
    # Why they were excused. A flip means the losing side had already
    # earned the match; a resurgence means the winner came back from a
    # collapse the losers could not have answered. Both set results
    # aside, and a player deserves to be told which happened.
    _exempt_reason = str(data.get('exempt_reason') or 'dominance-flip')[:24]
    if data.get('winners_half'):
        half_elo |= {normalize_name(n) for n in winning_team}

    # A whole-match hold: the tracker sets hold_reason when a result is
    # too uncertain to rate but too real to lose - today that is the
    # thin-margin orphan rescue (the match ended unwatched and the
    # winner would be a score guess). Every player lands in
    # held_results for review; nothing is rated, nothing is discarded,
    # and the tracker's match_log keeps the full record for a later
    # decision.
    hold_reason = data.get('hold_reason')
    if hold_reason:
        hconn = db()
        hc = hconn.cursor()
        hmid = str(data.get('match_id') or ('sys%s-%s' % (sys_id, int(time.time()))))
        hnow = time.strftime('%Y-%m-%d %H:%M:%S')
        hpa = data.get('played_as_map') or {}
        hsc = data.get('scores') if isinstance(data.get('scores'), dict) else {}
        hwinners = {str(n) for n in winning_team}
        heveryone = list(dict.fromkeys(
            [str(n) for n in winning_team] + [str(n) for n in losing_all]))
        for hname in heveryone:
            hs = hsc.get(hname)
            try:
                hs = int(hs) if hs is not None else None
            except (TypeError, ValueError):
                hs = None
            hc.execute("INSERT INTO held_results (match_id, sys_id, region, name, norm_name, "
                       "played_as, won, score, reason, played_at) VALUES (?,?,?,?,?,?,?,?,?,?)",
                       (hmid, sys_id, str(data.get('region') or 'america'), hname,
                        normalize_name(hname), hpa.get(hname) or hname,
                        1 if hname in hwinners else 0, hs, str(hold_reason)[:40], hnow))
        hconn.commit()
        hconn.close()
        print("[game_end] held whole match %s (%s): %d players"
              % (hmid, hold_reason, len(heveryone)), flush=True)
        return jsonify({"status": "held", "reason": str(hold_reason)[:40],
                        "players": len(heveryone)}), 200

    # How much of the watched match each late arrival was actually in.
    # Keyed the same way half_elo is; anyone absent from it played the
    # whole thing (7.0.4).
    presence = {}
    for _n, _v in (data.get('presence') or {}).items():
        try:
            presence[normalize_name(_n)] = max(0.0, min(1.0, float(_v)))
        except (TypeError, ValueError):
            pass

    def scaled(raw, key):
        """A late arrival's swing, scaled by how much of the match they
        were there for; full for everyone else.

        Until 7.0.4 this was a flat half whether somebody arrived a
        minute in or twenty - the same result for two very different
        contributions. Now it follows the share of the watch they were
        actually present for, floored at LATE_JOIN_FLOOR so that turning
        up late is never worth nothing at all, and capped at half a
        swing so a latecomer can still never be paid like someone who
        played the whole match. Without a presence figure - an older
        tracker, or a match with no usable read count - it falls back to
        the flat half it always was.

        No rounding. Ratings are stored with decimals precisely so that
        half a swing is a real half - while these were whole numbers, an
        even match was worth one point and half of it rounded straight
        back to one, which made the rule do nothing at all."""
        if key in half_elo:
            share = presence.get(key)
            if share is None:
                raw *= 0.5
            else:
                raw *= max(LATE_JOIN_FLOOR, min(0.5, share))
        return raw

    conn = db()
    c = conn.cursor()

    # Only names whose owner switched protection ON are restricted to
    # lobbies they checked into. Everyone else - including registered
    # players who left it off - is rated automatically as always. That defeats impersonation, because an
    # impersonator cannot check in - doing so needs control of the owning
    # network. Names with no owner keep the old automatic behaviour, so
    # the leaderboard still grows on its own.
    c.execute("SELECT name FROM players WHERE strict_mode = 1")
    protected = {normalize_name(row[0]) for row in c.fetchall()}
    # Everyone who checked into THIS lobby, computed always (not only when a
    # protected player is present) because a check-in also proves you are the
    # real owner of a name against an impersonator flying the same one.
    # A check-in stamped AFTER the match was last observably alive does not
    # count: you cannot see a result and then check into it. Normal scoring
    # lands seconds after the end so nothing changes; this closes the window
    # on matches scored late (rescues, stuck-lobby timers).
    checked_in = set()
    if sys_id is not None:
        _ended = str(data.get('ended_at') or '')[:19]
        if re.fullmatch(r'\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}', _ended):
            c.execute("SELECT player FROM checkins WHERE sys_id = ? "
                      "AND created_at > datetime('now', ?) AND created_at <= ?",
                      (sys_id, f'-{CHECKIN_VALID_SECONDS} seconds', _ended))
        else:
            c.execute("SELECT player FROM checkins WHERE sys_id = ? "
                      "AND created_at > datetime('now', ?)",
                      (sys_id, f'-{CHECKIN_VALID_SECONDS} seconds'))
        checked_in = {normalize_name(row[0]) for row in c.fetchall()}

    # ---- Ship-bound crediting ------------------------------------------
    # A check-in binds the account to ONE ship id (the first ship flying
    # its play name to appear after the check-in). Credit those accounts
    # from THEIR ship: its team decides win or loss, its score is their
    # score. A same-name ship - even on another team - is somebody else,
    # so it can neither blur the result nor hang its loss on the owner.
    _bound_keys = set()
    _ships = data.get('ship_scores') if isinstance(data.get('ship_scores'), dict) else {}
    if sys_id is not None and _ships:
        c.execute("SELECT sub, ship_id FROM name_bindings WHERE sys_id = ?",
                  (sys_id,))
        for _sub, _ship_id in c.fetchall():
            _ent = _ships.get(str(_ship_id))
            if not _ent:
                continue
            _acct = account_name_for(c, _sub)
            if not _acct:
                continue
            _role = _ent.get('role')
            if _role not in ('win', 'lose1', 'lose2'):
                continue
            _key = normalize_name(_acct)
            _was_listed = any(normalize_name(p) == _key for p in
                              winning_team + losing_team_1 + losing_team_2)
            # One placement, decided by the ship - drop every name-based
            # occurrence (which may include an impersonator's) first.
            winning_team = [p for p in winning_team if normalize_name(p) != _key]
            losing_team_1 = [p for p in losing_team_1 if normalize_name(p) != _key]
            losing_team_2 = [p for p in losing_team_2 if normalize_name(p) != _key]
            try:
                _sc = int(_ent.get('score'))
            except (TypeError, ValueError):
                _sc = None
            # A check-in proves the ship is yours - it is NOT a route into
            # being rated (owner's ruling, 24 Aug 2026: "check-in should
            # just be used as confirmation that it's you"). An account the
            # roster rules never included is not rated for this match, win
            # or lose. The identity work still counts: they are added to
            # the checked-in set below, so protection knows they are real.
            # The original binding bug (a rostered winner dropped as a
            # dup) cannot regress here: the dup filter SKIPS at rating
            # time rather than removing names, so that player is listed
            # and never reaches this branch. This replaces the old
            # unlisted-cameo hold and unlisted-half-elo paths, both of
            # which only existed because unlisted players used to be
            # placed at all.
            if not _was_listed:
                _bound_keys.add(_key)
                print("[game_end] sys=%s ship-bound identity only: %r "
                      "checked in but the roster rules never included "
                      "them - not rated (would have been %s, score %s)"
                      % (sys_id, _acct, _role, _sc), flush=True)
                continue
            (winning_team if _role == 'win'
             else losing_team_1 if _role == 'lose1'
             else losing_team_2).append(_acct)
            if _sc is not None:
                if not isinstance(data.get('scores'), dict):
                    data['scores'] = {}
                data['scores'][_acct] = _sc
            _bound_keys.add(_key)
            print("[game_end] sys=%s ship-bound credit: %r -> %s (score %s)"
                  % (sys_id, _acct, _role, _sc), flush=True)
        if _bound_keys:
            losing_all = losing_team_1 + losing_team_2
            # A binding is proof of ownership (it comes from a check-in),
            # so the duplicate-name drop no longer applies to these.
            checked_in |= _bound_keys

    # A match the watcher cut at a flood (owner's rule, 20 Sep 2026): the
    # side that was ahead when the swarm arrived is paid, and every side it
    # landed on is excused. Sixty scripted ships arriving at once is not
    # something anyone could answer, so losing to one is not a result a
    # player earned - while the winners did beat what was in front of them
    # before it came, which is exactly what the cut scores. Set here rather
    # than by the tracker so it holds for every path a cut result arrives by.
    if isinstance(data.get('flood_cut'), dict) and data.get('flood_cut'):
        dominance_exempt = set(dominance_exempt) | {normalize_name(n)
                                                    for n in losing_all}
        _exempt_reason = 'flood-cut'

    def protected_without_checkin(player_name):
        key = normalize_name(player_name)
        return key in protected and key not in checked_in

    # What the game's own scoreboard said each player finished with.
    # Rewritten to account names at the door along with the rosters, so
    # the keys here match the names skip() will be asked about.
    final_scores = data.get('scores') if isinstance(data.get('scores'), dict) else {}
    # Peak score per player (highest the game ever showed them), when the
    # engine reports it - eligibility is judged on this, see MIN_RATED_PEAK.
    peak_scores = data.get('peak_scores') if isinstance(data.get('peak_scores'), dict) else {}

    # The tracker flags a name it saw more than once in the same lobby.
    # Two identical names means one is an impersonator and there is no way
    # to tell which, so neither is rated - UNLESS one of them checked in,
    # which an impersonator cannot do, so a check-in settles it in favour of
    # the real owner. (Confirmed live: L7 Tempest, match #5536 - checked in,
    # scored 15293, won, but a transient same-name read denied the win.)
    def skip_reason(player_name, losing=False):
        """Why this player is not rated, or None if they are.

        Split out from skip() so a drop can be recorded with its cause.
        The order matters and matches the original: the cheapest and most
        certain tests come first.
        """
        if not normalize_name(player_name):
            return 'unreadable-name'
        if is_default_name(player_name):
            return 'default-name'
        _peak = peak_scores.get(player_name)
        if _peak is not None:
            if not losing and _peak < MIN_RATED_PEAK:
                return 'low-score'
        else:
            _sc = final_scores.get(player_name)
            if not losing and _sc is not None and _sc < MIN_RATED_SCORE:
                return 'low-score'
        if (normalize_name(player_name) in ambiguous
                and normalize_name(player_name) not in checked_in):
            return 'duplicate-name'
        if protected_without_checkin(player_name):
            return 'protected'
        if normalize_name(player_name) in dominance_exempt:
            return _exempt_reason
        return None

    def skip(player_name, losing=False):
        # A name that normalises to nothing - one written entirely in
        # characters this strips, so Chinese, Cyrillic, Arabic, Korean or
        # Greek - would otherwise be looked up as the empty string, and match
        # whichever single row happens to hold it. Every such player's result
        # landed on one unrelated player. They cannot be told apart from each
        # other either, so the only honest thing is to rate none of them.
        if not normalize_name(player_name):
            return True
        if is_default_name(player_name):
            return True
        # Winners under MIN_RATED_SCORE: present, but barely played -
        # rating them hands wins to idlers. Losers have no floor: the
        # assembled losing team takes the loss whatever the panel says,
        # or dying on purpose becomes a way out of it.
        _peak = peak_scores.get(player_name)
        if _peak is not None:
            if not losing and _peak < MIN_RATED_PEAK:
                return True
        else:
            _sc = final_scores.get(player_name)
            if not losing and _sc is not None and _sc < MIN_RATED_SCORE:
                return True
        if normalize_name(player_name) in dominance_exempt:
            return True
        key = normalize_name(player_name)
        return (key in ambiguous and key not in checked_in) or protected_without_checkin(player_name)

    _in_w, _in_l = list(winning_team), list(losing_all)
    # Anyone whose result is being withheld by PROTECTION specifically.
    # The other reasons are noise (bots, unreadable names) or genuinely
    # unknowable (two people using one name), but a protected player is a
    # real person whose real match is being set aside on purpose - that is
    # worth being able to look up later.
    _held = [(p, 1, 'protected') for p in _in_w if skip_reason(p) == 'protected']
    _held += [(p, 0, 'protected') for p in _in_l
              if skip_reason(p, losing=True) == 'protected']
    # Kept too: a result set aside because the match was flipped is a
    # real match somebody played, and why it went unrated should be
    # answerable later.
    _held += [(p, 0, _exempt_reason) for p in _in_l
              if skip_reason(p, losing=True) == _exempt_reason]
    winning_team = [p for p in winning_team if not skip(p)]
    losing_all = [p for p in losing_all if not skip(p, losing=True)]
    # The same name on BOTH the winning and losing side is two different
    # people sharing a nickname - one account cannot have both won and lost
    # the same match, and there is no way to tell which player owns it. So
    # rate neither: the cross-team twin of the duplicate-name rule. Without
    # this the single row took a win AND a loss in one match (its team was
    # last-write-wins, so it even showed on the wrong side) - confirmed live
    # on "BODIE", match sb_live_5427.
    _both = ({normalize_name(p) for p in winning_team}
             & {normalize_name(p) for p in losing_all})
    # A ship-bound account was already placed on exactly one team by its
    # ship; it cannot be the unknowable cross-team case.
    _both -= _bound_keys
    if _both:
        print("[game_end] sys=%s dropping %d name(s) present on both sides: %r"
              % (sys_id, len(_both), sorted(_both)[:8]), flush=True)
        winning_team = [p for p in winning_team if normalize_name(p) not in _both]
        losing_all = [p for p in losing_all if normalize_name(p) not in _both]
        losing_team_1 = [p for p in losing_team_1 if normalize_name(p) not in _both]
        losing_team_2 = [p for p in losing_team_2 if normalize_name(p) not in _both]
    _lost = [p for p in _in_l if p not in losing_all]
    print("[game_end] sys=%s region=%s got W=%d L=%d -> kept W=%d L=%d%s"
          % (sys_id, data.get('region'), len(_in_w), len(_in_l),
             len(winning_team), len(losing_all),
             ("  DROPPED LOSERS: %r" % (_lost[:8],)) if _lost else ""),
          flush=True)

    # skip() has already dropped the game's own default nicknames, names read
    # twice in one lobby, and anything normalising to nothing - so what is
    # left is the count of genuine, distinct players.
    if data.get('abandoned'):
        real_players = len({normalize_name(p) for p in winning_team + losing_all})
        if real_players >= ABANDON_MAX_REAL_PLAYERS:
            conn.close()
            return jsonify({
                "status": "not_scored",
                "real_players": real_players,
                "reason": (f"abandoned mid-match with {real_players} real players still in it - "
                           f"{ABANDON_MAX_REAL_PLAYERS} or more means it was still being played"),
            }), 200

    # Winners get auto-registered at STARTING_ELO if they aren't already
    # in the table, so they have a pre-match rating to base the strength
    # calculation on - then the elo change below is applied on top.
    # Losers are still never inserted.
    # Clans with an admin are off limits to automatic tagging - their roster
    # is whatever their admin says it is.
    curated = curated_clans(c)
    known_tags = all_clan_tags(c)
    for player in winning_team + losing_all:
        if is_valid_name_format(player):
            tag = detect_clan(player, known_tags)
            c.execute(
                "INSERT OR IGNORE INTO players (name, elo, wins, losses, norm_name, clan) VALUES (?, ?, 0, 0, ?, ?)",
                (player, STARTING_ELO, normalize_name(player),
                 None if tag in curated else tag)
            )
    # An existing row predates clan tracking, or the tag was unreadable last
    # time. Fill it in when we finally see one, but never overwrite a tag we
    # already have with nothing - and never re-tag a name whose tag was taken
    # off by hand, or the correction would be undone on that player's next match.
    for player in winning_team + losing_all:
        tag = detect_clan(player, known_tags)
        if tag and tag not in curated:
            c.execute("UPDATE players SET clan = ? WHERE norm_name = ? "
                      "AND (clan IS NULL OR clan = '') "
                      "AND (clan_locked IS NULL OR clan_locked = 0)",
                      (tag, normalize_name(player)))
    conn.commit()

    # Snapshot pre-match elo for everyone involved, so both sides' elo
    # changes are based on ratings as they stood before this match.
    all_names = list(set(winning_team + losing_all))
    elo_map, games_map = {}, {}
    if all_names:
        placeholders = ",".join("?" for _ in all_names)
        keys = [normalize_name(n) for n in all_names]
        placeholders = ",".join("?" for _ in keys)
        c.execute(f"SELECT norm_name, elo, COALESCE(wins,0)+COALESCE(losses,0) "
                  f"FROM players WHERE norm_name IN ({placeholders})", keys)
        for _n, _e, _g in c.fetchall():
            elo_map[_n] = _e
            games_map[_n] = _g

    winning_team_rating = team_rating(winning_team, elo_map)
    # Each losing team stands on its own: a loser's context is THEIR
    # team, and in the three-way expectation each side faces the other
    # two separately rather than as one pooled opponent.
    _lose1_rating = team_rating(losing_team_1, elo_map) if losing_team_1 else None
    _lose2_rating = team_rating(losing_team_2, elo_map) if losing_team_2 else None
    _lose1_keys = {normalize_name(p) for p in losing_team_1}
    _rivals_of_winner = [r for r in (_lose1_rating, _lose2_rating) if r is not None]
    # Every opposing side excused - both losing teams flipped or beaten by
    # a resurgence - leaves the winner with nobody to be measured against,
    # and a win against nobody reads as certain, worth nothing. Fall back
    # to an average opponent: unknown strength is not the same as no
    # opposition, and they did win a real match.
    if not _rivals_of_winner:
        _rivals_of_winner = [float(STARTING_ELO)]

    # Expected-outcome elo: the swing depends on how surprising the result
    # was for THIS player. Their side of the comparison is their own elo
    # BLENDED half-and-half with their team's average (owner's rule,
    # 22 Aug 2026): who stood beside you is part of how surprising the
    # result was. Winning inside a stacked team pays less than carrying
    # weak allies to the same win, and losing with weak allies costs less
    # than a stacked side losing. The expectation itself is now the
    # three-way one (7.0.0) - see win_expectation.
    # (name, won, delta) for every player the result actually moved, so the
    # match is written down exactly as it was applied.
    applied = []

    # Pass one: what every result is worth at the STANDARD K, before
    # each player's own experience multiplier. Balancing on these keeps
    # the two things separate - the structural imbalance gets corrected,
    # a deliberate provisional boost does not get cancelled out.
    _pending = []
    for player in winning_team:
        _k = normalize_name(player)
        _eff = (elo_map.get(_k, STARTING_ELO) + winning_team_rating) / 2
        _pending.append((player, _k, 1,
                         scaled(ELO_K * (1 - win_expectation(_eff, _rivals_of_winner)), _k),
                         k_factor(games_map.get(_k, 0)) / ELO_K))
    for player in losing_all:
        _k = normalize_name(player)
        if _k in _lose1_keys:
            _mine, _other = _lose1_rating, _lose2_rating
        else:
            _mine, _other = _lose2_rating, _lose1_rating
        _eff = (elo_map.get(_k, STARTING_ELO)
                + (_mine if _mine is not None else STARTING_ELO)) / 2
        _rivals = [winning_team_rating] + ([_other] if _other is not None else [])
        _pending.append((player, _k, 0,
                         scaled(ELO_K * win_expectation(_eff, _rivals), _k),
                         k_factor(games_map.get(_k, 0)) / ELO_K))

    # A match must not create or destroy rating (7.0.0). The two sides
    # rarely hold the same number of RATED players, so the side with the
    # larger total is damped down to meet the smaller - never the other
    # way round, so no individual swing is ever inflated to balance the
    # books. Without this the pool drifts every game, which is what
    # drained 474,337 points out of it.
    _tg = sum(r for _, _, w, r, _m in _pending if w)
    _tl = sum(r for _, _, w, r, _m in _pending if not w)
    _fg = _fl = 1.0
    if _tg > 0 and _tl > 0:
        if _tg > _tl:
            _fg = _tl / _tg
        else:
            _fl = _tg / _tl

    updated_winners, updated_losers = [], []
    for player, _k, _won, _raw, _mult in _pending:
        if _won:
            gain = _raw * _fg * _mult
            c.execute("UPDATE players SET elo = ROUND(elo + ?, 2), "
                      "wins = wins + 1 WHERE norm_name = ?", (gain, _k))
            if c.rowcount > 0:
                updated_winners.append(player)
                applied.append((player, 1, round(gain, 2)))
        else:
            loss = _raw * _fl * _mult
            c.execute("UPDATE players SET elo = ROUND(MAX(500, elo - ?), 2), "
                      "losses = losses + 1 WHERE norm_name = ?", (loss, _k))
            if c.rowcount > 0:
                updated_losers.append(player)
                applied.append((player, 0, -round(loss, 2)))

    # What each player finished flying, and how often they died. Recorded
    # against the result so a profile can show a favourite ship; no rule
    # or rating reads them (7.0.0).
    _ships_by_name = {}
    for _n, _v in (data.get('ships') or {}).items():
        try:
            _ships_by_name[str(_n)] = int(_v)
        except (TypeError, ValueError):
            pass
    _deaths_by_name = {}
    for _n, _v in (data.get('deaths') or {}).items():
        try:
            _deaths_by_name[str(_n)] = int(_v)
        except (TypeError, ValueError):
            pass

    # Write the match itself down. INSERT OR IGNORE plus the empty check
    # means a match reported twice is stored once, matching the elo guard.
    _flood_json, _flood_max, _match_id = None, 0, None
    if applied:
        match_id = str(data.get('match_id') or f"sys{sys_id}-{int(time.time())}")
        now_ts = time.strftime('%Y-%m-%d %H:%M:%S')
        flood_json, flood_max = summarize_flood(data.get('dup_names'))
        # A lobby holding far more ships than the 24 the mode allows is a
        # flood however the names read - the swarm rarely surfaces in the
        # top-8 panel, but simstatus counts every ship (73 seen live in
        # lobby #862 while the panel summed twelve).
        try:
            _simpeak = int(data.get('sim_players_peak') or 0)
        except (TypeError, ValueError):
            _simpeak = 0
        # Kept as information only: a busy hour-long lobby sees far more than
        # 24 ships come and go, so this number alone is not a flood and no
        # longer raises the alert (it did, on nearly every match).
        if _simpeak >= 30:
            _fd = json.loads(flood_json) if flood_json else {}
            _fd["lobby"] = {"ships seen (mode allows 24)": _simpeak}
            flood_json = json.dumps(_fd, ensure_ascii=False)
        # A result the watcher cut at a flood: when, which name, how many
        # ships, and what the swarm did. The match then reads as what it was.
        _cut = data.get('flood_cut')
        if isinstance(_cut, dict) and _cut:
            _fd = json.loads(flood_json) if flood_json else {}
            _fd["flood_cut"] = {"at": _cut.get("at"), "name": str(_cut.get("name") or '')[:64],
                                "ships": _cut.get("ships"), "team": _cut.get("team"),
                                "impact": [str(x)[:120] for x in (_cut.get("impact") or [])][:6]}
            flood_json = json.dumps(_fd, ensure_ascii=False)
            try:
                flood_max = max(flood_max, int(_cut.get("ships") or 0))
            except (TypeError, ValueError):
                pass
        _flood_json, _flood_max, _match_id = flood_json, flood_max, match_id
        c.execute("INSERT OR IGNORE INTO matches (match_id, sys_id, played_at, "
                  "region, lobby_name, tracked_reads, flood, flood_max) "
                  "VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                  (match_id, sys_id, now_ts, str(data.get('region') or 'america'),
                   (str(data.get('lobby_name'))[:60] if data.get('lobby_name') else None),
                   int(data.get('tracked_reads') or 0), flood_json, flood_max))
        c.execute("SELECT id FROM matches WHERE match_id = ?", (match_id,))
        mrow = c.fetchone()
        if mrow:
            c.execute("SELECT COUNT(*) FROM match_players WHERE match_row = ?", (mrow[0],))
            if c.fetchone()[0] == 0:
                scores = data.get('scores') if isinstance(data.get('scores'), dict) else {}
                team_of = {}
                for _nm in winning_team:
                    team_of[normalize_name(_nm)] = 'win'
                for _nm in losing_team_1:
                    team_of[normalize_name(_nm)] = 'lose1'
                for _nm in losing_team_2:
                    team_of[normalize_name(_nm)] = 'lose2'
                # How long the watcher watched, so each player's share of
                # it reads as seconds. Absent on an older tracker, and then
                # nothing is recorded rather than a guess.
                try:
                    _watch_s = int(data.get('watch_s') or 0)
                except (TypeError, ValueError):
                    _watch_s = 0
                for pname, won, delta in applied:
                    raw_score = scores.get(pname)
                    try:
                        raw_score = int(raw_score) if raw_score is not None else None
                    except (TypeError, ValueError):
                        raw_score = None
                    # Falls back to the credited name, which is the right
                    # answer when no rewrite happened - an unclaimed player
                    # played as exactly who they appear to be.
                    played_as = (data.get('played_as_map') or {}).get(pname) or pname
                    # Anyone absent from the presence map played the whole
                    # watch - that is what it has always meant (7.0.4).
                    _share = presence.get(normalize_name(pname), 1.0)
                    _played = int(round(_watch_s * _share)) if _watch_s else None
                    c.execute("INSERT INTO match_players (match_row, name, norm_name, won, delta, half, score, played_as, team, ship, deaths, played_s) "
                              "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                              (mrow[0], pname, normalize_name(pname), won, delta,
                               1 if normalize_name(pname) in half_elo else 0,
                               raw_score, played_as,
                               team_of.get(normalize_name(pname),
                                           'win' if won else 'lose1'),
                               _ships_by_name.get(played_as)
                               or _ships_by_name.get(pname),
                               _deaths_by_name.get(played_as)
                               or _deaths_by_name.get(pname),
                               _played))

    # ---- A hosted event -------------------------------------------------
    # If this match was the event lobby we put up, the winning side is paid
    # here, from the rows just written, in the same transaction as the
    # rating. Not an event: costs one indexed lookup and does nothing.
    try:
        if mrow:
            event_settle_team(c, mrow[0], sys_id)
    except (sqlite3.Error, TypeError, ValueError, KeyError):
        pass

    # ---- Gems -----------------------------------------------------------
    # Paid from `applied`, the same list the rating was just written from, and
    # inside the same transaction. A player the roster rules left out is not
    # in it and is not paid, so gems inherit every gate that protects the
    # rating rather than needing a second set of their own.
    try:
        if applied and _match_id:
            _paid = award_match_gems(c, applied, _match_id)
            if _paid:
                print("[game_end] sys=%s gems paid to %d players (%d total)"
                      % (sys_id, len(_paid), sum(g for _n, g in _paid)), flush=True)
    except sqlite3.Error as _ge:
        print("[game_end] sys=%s gem award failed: %s" % (sys_id, str(_ge)[:80]),
              flush=True)

    # ---- Replay snapshot ------------------------------------------------
    # The live feed has been accumulating this match's trajectory (score/
    # count per ~10s read) in live.db for the /live view. The match just
    # ended, so freeze that trajectory against the match row - compressed,
    # a few KB - and the journal replay page can draw the whole game.
    # Old replays are pruned so this can never grow without bound.
    try:
        if applied and _match_id:
            c.execute("SELECT id FROM matches WHERE match_id = ?", (_match_id,))
            _mr = c.fetchone()
            _lconn = live_db()
            # Two candidate trajectories, tried in order: the CURRENT live
            # row, then the STASHED one the ingest set aside when a new
            # clock started in this lobby. The stash is the usual winner
            # for a late-arriving result: the next match resets the live
            # row BEFORE the ended match is scored (Albiratos #8039 lost
            # its 30-minute recording to a single fresh-clock frame that
            # landed 71 seconds before scoring). Every rejection is
            # logged; nothing is silent.
            _cands = []
            _lrow = _lconn.execute("SELECT updated, region, name, payload FROM live "
                                   "WHERE sys_id = ?", (sys_id,)).fetchone()
            if _lrow:
                _cands.append(("live", _lrow[0], _lrow[1], _lrow[2],
                               _lrow[3], 45 * 60))
            _prow = _lconn.execute("SELECT saved, payload FROM live_prev "
                                   "WHERE sys_id = ?", (sys_id,)).fetchone()
            if _prow:
                _cands.append(("stashed", _prow[0],
                               str(data.get('region') or ''),
                               str(data.get('lobby_name') or ''),
                               _prow[1], 4 * 3600))
            # The wrong-game discriminator: a finished game's totals dwarf
            # a fresh one's, so the trajectory's PEAK team score must reach
            # half the best reported player score. Peak, not final frame -
            # most matches end drained.
            _repmax = 0
            if isinstance(data.get('scores'), dict):
                for _v in data['scores'].values():
                    try:
                        _repmax = max(_repmax, int(_v))
                    except (TypeError, ValueError):
                        pass
            _now_t = time.time()
            _snap = None
            _whynot = []
            for _src, _ts, _rg, _nm, _ptxt, _maxage in _cands:
                if _now_t - _ts >= _maxage:
                    _whynot.append("%s: %d min stale" % (_src, int((_now_t - _ts) / 60)))
                    continue
                _lp = json.loads(_ptxt) or {}
                _traj = _lp.get("traj") or []
                if len(_traj) < 6:
                    _whynot.append("%s: only %d reads" % (_src, len(_traj)))
                    continue
                _trajmax = 0
                for _r in _traj:
                    _fm = max([int(v or 0) for v in (_r[2] or {}).values()] or [0])
                    if _fm > _trajmax:
                        _trajmax = _fm
                if _repmax > 0 and _trajmax < 0.5 * _repmax:
                    _whynot.append("%s: peak %d vs reported best %d - wrong game"
                                   % (_src, _trajmax, _repmax))
                    continue
                _snap = (_src, _lp, _traj, _rg, _nm)
                break
            _lconn.close()
            if _mr and _snap:
                _src, _lp, _traj, _rg, _nm = _snap
                _blob = zlib.compress(json.dumps({
                    "traj": _traj,
                    "skill": _lp.get("skill") or {},
                    "top": _lp.get("top") or {},
                    # The station blueprints. Without these the replay has
                    # module health with no station to draw it on, so the
                    # whole panel stays hidden.
                    "stlay": _lp.get("stlay") or [],
                    "welcome": _lp.get("welcome") or None,
                    "region": _rg, "name": _nm,
                }, separators=(',', ':')).encode('utf-8'), 6)
                c.execute("CREATE TABLE IF NOT EXISTS match_replays ("
                          "match_row INTEGER PRIMARY KEY, data BLOB, "
                          "created_at TEXT)")
                c.execute("INSERT OR IGNORE INTO match_replays "
                          "(match_row, data, created_at) VALUES (?,?,?)",
                          (_mr[0], sqlite3.Binary(_blob),
                           time.strftime('%Y-%m-%d %H:%M:%S')))
                c.execute("DELETE FROM match_replays WHERE "
                          "created_at < datetime('now', '-90 days')")
                print("[game_end] replay snapshot: match %s, %d reads, %d bytes "
                      "(%s trajectory)"
                      % (_mr[0], len(_traj), len(_blob), _src), flush=True)
            elif _mr:
                print("[game_end] replay skipped for match %s: %s"
                      % (_mr[0], "; ".join(_whynot) or "no live data for this lobby"),
                      flush=True)
    except Exception as _re:
        # A replay must never cost the result itself.
        print("[game_end] replay snapshot failed: %s" % _re, flush=True)

    if _held:
        _mid = str(data.get('match_id') or ('sys%s-%s' % (sys_id, int(time.time()))))
        _now = time.strftime('%Y-%m-%d %H:%M:%S')
        _pa = data.get('played_as_map') or {}
        for _name, _won, _reason in _held:
            _sc = final_scores.get(_name)
            try:
                _sc = int(_sc) if _sc is not None else None
            except (TypeError, ValueError):
                _sc = None
            c.execute("INSERT INTO held_results (match_id, sys_id, region, name, norm_name, "
                      "played_as, won, score, reason, played_at) VALUES (?,?,?,?,?,?,?,?,?,?)",
                      (_mid, sys_id, str(data.get('region') or 'america'), _name,
                       normalize_name(_name), _pa.get(_name) or _name, _won, _sc,
                       _reason, _now))
        conn.commit()
        print("[game_end] held %d result(s): %r"
              % (len(_held), [(n, r) for n, _, r in _held][:6]), flush=True)

    # Wins no longer complete claims (removed 17 Aug 2026, 6.16.0).
    # The old rule completed a claim when the NAME next won - which an
    # impostor could satisfy by waiting for the real owner to win.
    # Claims now complete through the deathmatch-ladder proof in the
    # bot, or by the owner deciding by hand.
    # A clan's record is counted per MEMBER per match (owner's rule: clan
    # wins stack). sys_id is what makes that possible - without it there is
    # no way to tell one match from another, so nothing is recorded.
    if sys_id is not None:
        # One row per rated clan member: every clanmate on the winning team
        # adds a clan win, every rated clanmate on a losing team adds a clan
        # loss. A clan split across teams records both sides - each member
        # carries their own result.
        now = time.strftime('%Y-%m-%d %H:%M:%S')

        def clan_of(nm):
            r2 = c.execute("SELECT clan FROM players WHERE norm_name = ?",
                           (normalize_name(nm),)).fetchone()
            return r2[0] if r2 and r2[0] else None

        for _pl, _won in ([(p, 1) for p in updated_winners]
                          + [(p, 0) for p in updated_losers]):
            _tag = clan_of(_pl)
            if _tag:
                c.execute("INSERT OR IGNORE INTO clan_results "
                          "(clan, sys_id, won, created_at, member) "
                          "VALUES (?, ?, ?, ?, ?)",
                          (_tag, sys_id, _won, now, normalize_name(_pl)))

    conn.commit()
    conn.close()
    # The boards this result changed, rebuilt now in the background so the
    # next visitor finds them ready instead of paying for the first build;
    # then anyone whose saved play name played this match without a check-in
    # is told.
    if _match_id:
        threading.Thread(target=_after_result, args=(_match_id,), daemon=True).start()

    # After the match is safely written: if it was flooded, put the finished
    # result in front of the owner with what it paid out, so it can be voided
    # if the flood decided it. Queued on its own connection, hence after close.
    if _flood_max >= FLOOD_SIGNIFICANT:
        queue_flood_alert('result', sys_id,
                          {"teams": json.loads(_flood_json) if _flood_json else {},
                           "winners": [{"name": p, "delta": d}
                                       for p, w, d in applied if w],
                           "losers": [{"name": p, "delta": d}
                                      for p, w, d in applied if not w]},
                          _flood_max, lobby_name=data.get('lobby_name'),
                          region=data.get('region'), match_id=_match_id,
                          dedupe_seconds=0)

    return jsonify({
        "status": "success",
        "updated_winners": updated_winners,
        "updated_losers": updated_losers
    }), 200


# Newest first. Add a new dict here whenever APP_VERSION is bumped.
# The changelog says what a visitor can SEE change. Not how it is built - no
# retry timings, memory figures, storage layout or background jobs. When
# something broke, say so plainly and say what it looked like from outside.
#
# Work on a surface only the owner can reach (My Maps, the map editor, the
# lobby builder) gets NO entry at all. It used to get a tagged line that the
# page hid; that was removed on the owner's instruction, 10 Sep 2026, because
# a hidden line is still a line that leaves by every other door. The private
# repository's history is where a record of that work lives.
#
# OWNER_TAG and the filters below stay as a backstop: if a tagged line is ever
# written again, nothing published can carry it.
OWNER_TAG = "@owner "


def void_match(c, match_row, reason):
    """Take a recorded result back. Every rating change it paid is reversed -
    elo, the win or the loss - for each player still carrying it (someone
    wiped to placement since the match no longer does, and is skipped); the
    rows go to the wipe archive under account 'void:<reason>' so the result
    stays auditable; they are deleted from the live tables so no board,
    history or recompute counts them again; and the match row is kept, marked
    voided, so the archive count and the replay listing skip it. Same cursor
    as the caller's transaction - commit is theirs. Returns
    {reversed, skipped, delta} or None when there is no such match."""
    m = c.execute("SELECT id, played_at, COALESCE(voided, 0) FROM matches WHERE id = ?",
                  (match_row,)).fetchone()
    if not m or m[2]:
        return None
    played_at = m[1] or ''
    now = time.strftime('%Y-%m-%d %H:%M:%S')
    reversed_n = skipped = 0
    total = 0.0
    for nn, won, delta in c.execute("SELECT norm_name, won, delta FROM match_players "
                                    "WHERE match_row = ?", (match_row,)).fetchall():
        p = c.execute("SELECT wiped_before FROM players WHERE norm_name = ?", (nn,)).fetchone()
        if not p or (p[0] and str(p[0]) >= played_at):
            skipped += 1
            continue
        c.execute("UPDATE players SET elo = elo - ?, "
                  "wins = MAX(0, COALESCE(wins, 0) - ?), "
                  "losses = MAX(0, COALESCE(losses, 0) - ?) WHERE norm_name = ?",
                  (float(delta or 0.0), 1 if won else 0, 0 if won else 1, nn))
        reversed_n += 1
        total += float(delta or 0.0)
    c.execute("INSERT INTO wiped_match_players "
              "(wiped_at, account, norm_name, match_row, match_id, played_at, "
              " region, won, delta, half, played_as, score, ship, deaths) "
              "SELECT ?, ?, mp.norm_name, mp.match_row, m.match_id, m.played_at, "
              " m.region, mp.won, mp.delta, mp.half, mp.played_as, mp.score, "
              " mp.ship, mp.deaths "
              "FROM match_players mp JOIN matches m ON m.id = mp.match_row "
              "WHERE mp.match_row = ?", (now, 'void:' + str(reason)[:120], match_row))
    c.execute("DELETE FROM match_players WHERE match_row = ?", (match_row,))
    c.execute("UPDATE matches SET voided = 1, void_reason = ? WHERE id = ?",
              (str(reason)[:200], match_row))
    return {"reversed": reversed_n, "skipped": skipped, "delta": round(total, 2)}


def move_result(c, match_row, from_norm, to_norm):
    """Re-credit one player's result in one match from one record to another:
    the match_players row is re-keyed to the destination (played_as kept),
    the rating change and the win or loss come off the source ledger and go
    onto the destination's, exactly as the ledger applied them (a loss keeps
    the 500 floor). For the name-trap case where a game under an alt name
    landed on that name's standalone record. Same cursor as the caller's
    transaction. Returns {delta, won, from, to} with both ledgers after, or
    None when the row is missing, the destination is missing, or the
    destination already has a row in that match."""
    src = c.execute("SELECT won, delta FROM match_players WHERE match_row = ? AND norm_name = ?",
                    (match_row, from_norm)).fetchone()
    dst = c.execute("SELECT name FROM players WHERE norm_name = ?", (to_norm,)).fetchone()
    if not src or not dst:
        return None
    if c.execute("SELECT 1 FROM match_players WHERE match_row = ? AND norm_name = ?",
                 (match_row, to_norm)).fetchone():
        return None
    won, delta = int(src[0] or 0), float(src[1] or 0.0)
    c.execute("UPDATE match_players SET name = ?, norm_name = ? "
              "WHERE match_row = ? AND norm_name = ?", (dst[0], to_norm, match_row, from_norm))
    c.execute("UPDATE players SET elo = ROUND(elo - ?, 2), "
              "wins = MAX(0, COALESCE(wins, 0) - ?), losses = MAX(0, COALESCE(losses, 0) - ?) "
              "WHERE norm_name = ?", (delta, 1 if won else 0, 0 if won else 1, from_norm))
    c.execute("UPDATE players SET elo = ROUND(MAX(500, elo + ?), 2), "
              "wins = COALESCE(wins, 0) + ?, losses = COALESCE(losses, 0) + ? "
              "WHERE norm_name = ?", (delta, 1 if won else 0, 0 if won else 1, to_norm))
    after = {}
    for k, nn in (("from", from_norm), ("to", to_norm)):
        r = c.execute("SELECT elo, wins, losses FROM players WHERE norm_name = ?", (nn,)).fetchone()
        after[k] = {"elo": r[0], "wins": r[1], "losses": r[2]} if r else None
    return {"delta": delta, "won": won, "from": after["from"], "to": after["to"]}


FORGOT_WINDOW_HOURS = 48      # how far back a missed result can be claimed
FORGOT_MATCH_HOURS = 6        # the match must end within this long of the check-in
FORGOT_MAX_RECORD_GAMES = 2   # the name's standalone record must still be this small
FORGOT_PER_DAY = 1            # successful claims per account per day


def claim_missed_result(c, sub_id, raw_name):
    """'I pressed Play here but played under a different name.' Shared by the
    website and the bot; does NOT commit. Returns (http_status, payload).

    The proof is the check-in: the account pressed Play on that lobby (a
    checkins row), and the named ship turned up in that lobby AFTER it, on a
    ship nobody else is bound to. No check-in, nothing to go on, nothing
    moves. Then the result that lobby's match paid to the name's standalone
    record is moved onto the account. Limits: only names without a record
    of their own (FORGOT_MAX_RECORD_GAMES games at most, never one another
    account owns or has checked in with), matches from the last
    FORGOT_WINDOW_HOURS, FORGOT_PER_DAY successful claims a day, and never a
    match the account already has a result in - one person is one ship."""
    name = str(raw_name or '').strip()[:40]
    if not name:
        return 400, {"ok": False, "message": "Which name did you play under?"}
    who = account_name_for(c, sub_id)
    if not who:
        return 400, {"ok": False, "message": "Set your account name first."}
    me = normalize_name(who)
    key = normalize_name(name)
    if not key or key == me:
        return 400, {"ok": False,
                     "message": "That is your own name - its results already count for you."}
    row = c.execute("SELECT name, google_sub, COALESCE(wins, 0) + COALESCE(losses, 0) "
                    "FROM players WHERE norm_name = ?", (key,)).fetchone()
    if row and row[1]:
        return 400, {"ok": False,
                     "message": "'%s' belongs to an account. If it is yours as well, "
                                "ask for a merge instead." % row[0]}
    if row and row[2] > FORGOT_MAX_RECORD_GAMES:
        return 400, {"ok": False,
                     "message": "'%s' has a record of its own by now, so its games "
                                "can't be moved automatically. Ask for a merge instead "
                                "(/merge) - attach a screenshot and it is reviewed by "
                                "hand, however old the record is." % row[0]}
    names = {name} | ({row[0]} if row else set())
    for nm in names:
        if c.execute("SELECT 1 FROM name_bindings WHERE in_game_name = ? AND sub != ? "
                     "LIMIT 1", (nm, sub_id)).fetchone():
            return 400, {"ok": False,
                         "message": "Another account has checked in under that name, "
                                    "so its games can't be moved to yours. If it is "
                                    "genuinely you, use Report."}
    now_t = time.time()
    now = time.strftime('%Y-%m-%d %H:%M:%S', time.gmtime(now_t))
    day_ago = time.strftime('%Y-%m-%d %H:%M:%S', time.gmtime(now_t - 86400))
    n_today = c.execute("SELECT COUNT(DISTINCT at) FROM credit_moves WHERE sub = ? "
                        "AND at > ? AND undone_at IS NULL", (sub_id, day_ago)).fetchone()[0]
    if n_today >= FORGOT_PER_DAY:
        return 429, {"ok": False, "message": "One of these a day - try again tomorrow, "
                     "or ask for a merge (/merge): reviewed by hand, no daily limit."}
    since = time.strftime('%Y-%m-%d %H:%M:%S', time.gmtime(now_t - FORGOT_WINDOW_HOURS * 3600))
    checkins = c.execute("SELECT sys_id, created_at FROM checkins WHERE sub = ? "
                         "AND COALESCE(bound, 0) = 0 AND created_at > ? "
                         "ORDER BY created_at", (sub_id, since)).fetchall()
    if not checkins:
        return 404, {"ok": False,
                     "message": "No Play check-in from you in the last %d hours. Only a "
                                "game you opened from the Play page here can be moved "
                                "automatically. For anything older, ask for a merge "
                                "(/merge): attach proof and it is reviewed by hand, with "
                                "no time limit." % FORGOT_WINDOW_HOURS}
    taken = {(r[0], r[1]) for r in c.execute("SELECT sys_id, ship_id FROM name_bindings").fetchall()}
    moved, done = [], set()
    for sys_id, created_at in checkins:
        # The named ship turned up in that lobby after the click, on a ship
        # nobody else is bound to.
        ship = None
        for an, ship_id, region in c.execute(
                "SELECT name, ship_id, region FROM appearances WHERE sys_id = ? "
                "AND at >= ? ORDER BY at", (sys_id, created_at)).fetchall():
            if normalize_name(an) == key and (sys_id, ship_id) not in taken:
                ship = (ship_id, region)
                break
        if ship is None:
            continue
        for mid, played_at in c.execute(
                "SELECT id, played_at FROM matches WHERE sys_id = ? AND played_at > ? "
                "AND played_at < datetime(?, ?) AND COALESCE(voided, 0) = 0 ORDER BY id",
                (sys_id, created_at, created_at, '+%d hours' % FORGOT_MATCH_HOURS)).fetchall():
            if mid in done:
                continue
            if c.execute("SELECT 1 FROM match_players WHERE match_row = ? AND norm_name = ?",
                         (mid, me)).fetchone():
                continue          # the account already has a result there
            r = move_result(c, mid, key, me)
            if not r:
                continue
            done.add(mid)
            c.execute("INSERT INTO credit_moves (at, sub, match_row, from_norm, to_norm, "
                      "played_as, delta, won, how) VALUES (?,?,?,?,?,?,?,?,?)",
                      (now, sub_id, mid, key, me, name, r["delta"], r["won"],
                       "check-in %s lobby %s ship %s" % (created_at, sys_id, ship[0])))
            c.execute("INSERT OR REPLACE INTO name_bindings "
                      "(sub, in_game_name, sys_id, ship_id, region, bound_at) "
                      "VALUES (?,?,?,?,?,?)", (sub_id, name, sys_id, ship[0], ship[1], now))
            taken.add((sys_id, ship[0]))
            moved.append({"match": mid, "at": (played_at or '')[:16], "won": r["won"],
                          "delta": r["delta"]})
    if not moved:
        return 404, {"ok": False,
                     "message": "Nothing to move. A game can be moved when you pressed "
                                "Play on that match here before joining, '%s' turned up "
                                "in it afterwards, and the result has been recorded."
                                % name}
    parts = ["%s %+.1f on %s" % ("win" if m["won"] else "loss", m["delta"], m["at"][5:])
             for m in moved]
    return 200, {"ok": True, "moved": moved, "account_name": who,
                 "message": "Moved to '%s': %s." % (who, "; ".join(parts))}


MISSED_WINDOW_HOURS = 48      # how long a notice stays open
MISSED_QUIET_DAYS = 7         # "not me" quiets that name for this long


def _after_result(match_id):
    prewarm_boards()
    notify_missed_results(match_id)


def notify_missed_results(match_id):
    """After a result is written: every account whose SAVED PLAY NAME finished
    this match on nobody's record - no check-in, so the name's own row got the
    result - gets a notice. Skipped when the account already has a result in
    the match (one person is one ship), when another account has ever checked
    in under the name, when the name has a record of its own, or when the
    account said "not me" for that name this week. Runs off the request path."""
    try:
        conn = db(timeout=6)
        c = conn.cursor()
        m = c.execute("SELECT id, sys_id FROM matches WHERE match_id = ?", (match_id,)).fetchone()
        if not m:
            conn.close()
            return 0
        mid, sys_id = m
        rows = c.execute("SELECT norm_name, name FROM match_players WHERE match_row = ?",
                         (mid,)).fetchall()
        if not rows:
            conn.close()
            return 0
        in_match = {r[0] for r in rows}
        ph = ",".join("?" for _ in rows)
        owned = {r[0] for r in c.execute(
            "SELECT norm_name FROM players WHERE google_sub IS NOT NULL AND google_sub != '' "
            "AND norm_name IN (%s)" % ph, [r[0] for r in rows]).fetchall()}
        cands = [(nn, nm) for nn, nm in rows if nn and nn not in owned]
        if not cands:
            conn.close()
            return 0
        by_norm = {}
        for sub, gn, acct in c.execute(
                "SELECT google_sub, game_name, norm_name FROM players WHERE google_sub IS NOT NULL "
                "AND google_sub != '' AND game_name IS NOT NULL AND game_name != ''").fetchall():
            k = normalize_name(gn)
            if k and k != acct:
                by_norm.setdefault(k, []).append((sub, acct))
        now = time.strftime('%Y-%m-%d %H:%M:%S', time.gmtime())
        quiet_since = time.strftime('%Y-%m-%d %H:%M:%S',
                                    time.gmtime(time.time() - MISSED_QUIET_DAYS * 86400))
        made = 0
        for nn, nm in cands:
            for sub, acct in by_norm.get(nn, []):
                if acct in in_match:
                    continue
                if c.execute("SELECT 1 FROM name_bindings WHERE in_game_name = ? AND sub != ? "
                             "LIMIT 1", (nm, sub)).fetchone():
                    continue
                if c.execute("SELECT 1 FROM missed_notices WHERE sub = ? AND norm = ? "
                             "AND status = 'declined' AND decided_at > ?",
                             (sub, nn, quiet_since)).fetchone():
                    continue
                rec = c.execute("SELECT COALESCE(wins, 0) + COALESCE(losses, 0) FROM players "
                                "WHERE norm_name = ?", (nn,)).fetchone()
                if rec and rec[0] > FORGOT_MAX_RECORD_GAMES:
                    continue
                c.execute("INSERT OR IGNORE INTO missed_notices (at, sub, name, norm, match_row, sys_id) "
                          "VALUES (?,?,?,?,?,?)", (now, sub, nm, nn, mid, sys_id))
                made += c.rowcount if c.rowcount and c.rowcount > 0 else 0
        conn.commit()
        conn.close()
        return made
    except sqlite3.Error:
        return 0


def missed_batches(c, sub_id):
    """This account's open notices from the last MISSED_WINDOW_HOURS, one batch
    per name, each game with its result as it stands on the name's own row.
    A game that has since moved or been voided drops out."""
    since = time.strftime('%Y-%m-%d %H:%M:%S',
                          time.gmtime(time.time() - MISSED_WINDOW_HOURS * 3600))
    out = {}
    for nid, name, norm, mid in c.execute(
            "SELECT id, name, norm, match_row FROM missed_notices WHERE sub = ? "
            "AND status = 'open' AND at > ? ORDER BY id", (sub_id, since)).fetchall():
        mp = c.execute("SELECT mp.won, mp.delta, m.played_at, m.sys_id, COALESCE(m.lobby_name, '') "
                       "FROM match_players mp JOIN matches m ON m.id = mp.match_row "
                       "WHERE mp.match_row = ? AND mp.norm_name = ? AND COALESCE(m.voided, 0) = 0",
                       (mid, norm)).fetchone()
        if not mp:
            c.execute("UPDATE missed_notices SET status = 'stale' WHERE id = ?", (nid,))
            continue
        b = out.setdefault(norm, {"name": name, "norm": norm, "games": [], "total": 0.0})
        b["games"].append({"match": mid, "at": (mp[2] or '')[:16], "won": bool(mp[0]),
                           "delta": round(float(mp[1] or 0), 1), "sys": mp[3], "lobby": mp[4]})
        b["total"] += float(mp[1] or 0)
    for b in out.values():
        b["total"] = round(b["total"], 1)
    return list(out.values())


def decide_missed(c, sub_id, raw_name, take):
    """One decision for every open game under that name. Take: each result is
    moved with move_result, wins and losses alike, under the same limits as
    the form (a name without a record of its own, one claim a day). Not me:
    the name is quiet for MISSED_QUIET_DAYS. Does NOT commit."""
    key = normalize_name(str(raw_name or '')[:40])
    batches = [b for b in missed_batches(c, sub_id) if b["norm"] == key]
    if not batches:
        return 404, {"ok": False, "message": "Nothing open under that name."}
    b = batches[0]
    now = time.strftime('%Y-%m-%d %H:%M:%S', time.gmtime())
    if not take:
        c.execute("UPDATE missed_notices SET status = 'declined', decided_at = ? "
                  "WHERE sub = ? AND norm = ? AND status = 'open'", (now, sub_id, key))
        return 200, {"ok": True, "moved": [],
                     "message": "Noted. We won't ask about '%s' again for a week." % b["name"]}
    who = account_name_for(c, sub_id)
    if not who:
        return 400, {"ok": False, "message": "Set your account name first."}
    me = normalize_name(who)
    row = c.execute("SELECT name, google_sub, COALESCE(wins, 0) + COALESCE(losses, 0) "
                    "FROM players WHERE norm_name = ?", (key,)).fetchone()
    if row and row[1]:
        return 400, {"ok": False, "message": "'%s' belongs to an account now." % row[0]}
    if row and row[2] > FORGOT_MAX_RECORD_GAMES:
        return 400, {"ok": False,
                     "message": "'%s' has a record of its own by now, so its games can't be "
                                "moved this way." % row[0]}
    if c.execute("SELECT 1 FROM name_bindings WHERE in_game_name = ? AND sub != ? LIMIT 1",
                 (b["name"], sub_id)).fetchone():
        return 400, {"ok": False,
                     "message": "Another account has checked in under that name, so its games "
                                "can't be moved to yours."}
    day_ago = time.strftime('%Y-%m-%d %H:%M:%S', time.gmtime(time.time() - 86400))
    n_today = c.execute("SELECT COUNT(DISTINCT at) FROM credit_moves WHERE sub = ? AND at > ? "
                        "AND undone_at IS NULL", (sub_id, day_ago)).fetchone()[0]
    if n_today >= FORGOT_PER_DAY:
        return 429, {"ok": False, "message": "One of these a day - try again tomorrow, "
                     "or ask for a merge (/merge): reviewed by hand, no daily limit."}
    moved = []
    for g in b["games"]:
        mid = g["match"]
        if c.execute("SELECT 1 FROM match_players WHERE match_row = ? AND norm_name = ?",
                     (mid, me)).fetchone():
            continue
        r = move_result(c, mid, key, me)
        if not r:
            continue
        c.execute("INSERT INTO credit_moves (at, sub, match_row, from_norm, to_norm, played_as, "
                  "delta, won, how) VALUES (?,?,?,?,?,?,?,?,?)",
                  (now, sub_id, mid, key, me, b["name"], r["delta"], r["won"],
                   "missed notice: saved play name, no check-in, lobby %s" % g["sys"]))
        c.execute("UPDATE missed_notices SET status = 'taken', decided_at = ? "
                  "WHERE sub = ? AND match_row = ?", (now, sub_id, mid))
        moved.append({"match": mid, "at": g["at"], "won": r["won"], "delta": r["delta"]})
    c.execute("UPDATE missed_notices SET status = 'stale', decided_at = ? "
              "WHERE sub = ? AND norm = ? AND status = 'open'", (now, sub_id, key))
    if not moved:
        return 404, {"ok": False, "message": "Nothing left to move under that name."}
    parts = ["%s %+.1f on %s" % ("win" if m["won"] else "loss", m["delta"], m["at"][5:])
             for m in moved]
    return 200, {"ok": True, "moved": moved, "account_name": who,
                 "message": "Moved to '%s': %s." % (who, "; ".join(parts))}


@app.route('/api/missed/decide', methods=['POST'])
def api_missed_decide():
    sub_id = current_user()
    if not sub_id:
        return jsonify({"ok": False, "message": "Sign in first."}), 401
    data = request.json or {}
    conn = db()
    c = conn.cursor()
    status, payload = decide_missed(c, sub_id, data.get('name'), bool(data.get('take')))
    if status == 200:
        conn.commit()
    conn.close()
    return jsonify(payload), status


def _discord_id_for(c, sub):
    """The Discord user to message for an account: the account itself when it
    signed in with Discord, else a linked Discord, else None."""
    if sub.startswith('discord:'):
        return sub.split(':', 1)[1]
    try:
        r = c.execute("SELECT discord_id FROM discord_links WHERE account_sub = ?", (sub,)).fetchone()
        return r[0] if r else None
    except sqlite3.Error:
        return None


@app.route('/api/bot/missed/pending')
def bot_missed_pending():
    """Open notices not yet sent by Discord message, one per account and name."""
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401
    conn = db()
    c = conn.cursor()
    since = time.strftime('%Y-%m-%d %H:%M:%S',
                          time.gmtime(time.time() - MISSED_WINDOW_HOURS * 3600))
    out, seen = [], set()
    for sub, name, norm, sys_id, n in c.execute(
            "SELECT sub, name, norm, MIN(sys_id), COUNT(*) FROM missed_notices "
            "WHERE status = 'open' AND dm_sent = 0 AND at > ? GROUP BY sub, norm "
            "ORDER BY MIN(id) LIMIT 20", (since,)).fetchall():
        # A nudge is a direct message, which is the loudest thing the bot
        # does, so it is the first thing "do not ping me" turns off.
        did = None if pings_off(c, sub) else _discord_id_for(c, sub)
        if not did or (sub, norm) in seen:
            continue
        seen.add((sub, norm))
        out.append({"sub": sub, "discord_id": did, "name": name, "games": n, "sys_id": sys_id})
    conn.close()
    return jsonify({"missed": out}), 200


@app.route('/api/bot/missed/delivered', methods=['POST'])
def bot_missed_delivered():
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401
    d = request.json or {}
    sub, name = str(d.get('sub') or ''), str(d.get('name') or '')
    if not sub or not name:
        return jsonify({"ok": False}), 200
    conn = db()
    c = conn.cursor()
    c.execute("UPDATE missed_notices SET dm_sent = 1 WHERE sub = ? AND norm = ? AND status = 'open'",
              (sub, normalize_name(name)))
    conn.commit()
    conn.close()
    return jsonify({"ok": True}), 200


@app.route('/api/forgot', methods=['POST'])
def api_forgot():
    """Played under a different name - move that game to my account."""
    sub_id = current_user()
    if not sub_id:
        return jsonify({"ok": False, "message": "Sign in first."}), 401
    data = request.json or {}
    conn = db()
    c = conn.cursor()
    status, payload = claim_missed_result(c, sub_id, data.get('name'))
    if status == 200:
        conn.commit()
    conn.close()
    return jsonify(payload), status


# ---- response times -----------------------------------------------------------
# Every request is timed on the way out. Each worker keeps a tally per
# (minute, route) in memory and writes it to live.db every _REQ_FLUSH_EVERY
# seconds, so a request costs a dictionary update, not a database write.
_REQ_BUF = {}                 # (minute, endpoint) -> [n, total_ms, max_ms, errors]
_REQ_FLUSH = {"at": 0.0}
_REQ_FLUSH_EVERY = 10
_REQ_KEEP_DAYS = 7


def _req_stats_table(c):
    c.execute("CREATE TABLE IF NOT EXISTS request_stats (minute TEXT, endpoint TEXT, "
              "n INTEGER, total_ms REAL, max_ms REAL, errors INTEGER, "
              "PRIMARY KEY (minute, endpoint))")


def _req_flush(force=False):
    now = time.time()
    if not _REQ_BUF or (not force and now - _REQ_FLUSH["at"] < _REQ_FLUSH_EVERY):
        return
    _REQ_FLUSH["at"] = now
    items = list(_REQ_BUF.items())
    _REQ_BUF.clear()
    try:
        conn = live_db()
        c = conn.cursor()
        _req_stats_table(c)
        for (minute, ep), (n, tot, mx, err) in items:
            c.execute("INSERT INTO request_stats (minute, endpoint, n, total_ms, max_ms, errors) "
                      "VALUES (?,?,?,?,?,?) ON CONFLICT(minute, endpoint) DO UPDATE SET "
                      "n = n + excluded.n, total_ms = total_ms + excluded.total_ms, "
                      "max_ms = MAX(max_ms, excluded.max_ms), errors = errors + excluded.errors",
                      (minute, ep, n, tot, mx, err))
        if int(now) % 30 == 0:
            c.execute("DELETE FROM request_stats WHERE minute < ?",
                      (time.strftime('%Y-%m-%d %H:%M', time.gmtime(now - _REQ_KEEP_DAYS * 86400)),))
        conn.commit()
        conn.close()
    except sqlite3.Error:
        pass


@app.before_request
def _req_start():
    request.environ['sb.t0'] = time.perf_counter()


@app.after_request
def _req_done(resp):
    try:
        t0 = request.environ.get('sb.t0')
        ep = request.endpoint
        if t0 is not None and ep and ep != 'static':
            ms = (time.perf_counter() - t0) * 1000.0
            err = 1 if resp.status_code >= 500 else 0
            key = (time.strftime('%Y-%m-%d %H:%M', time.gmtime()), ep)
            b = _REQ_BUF.get(key)
            if b is None:
                _REQ_BUF[key] = [1, ms, ms, err]
            else:
                b[0] += 1
                b[1] += ms
                b[2] = max(b[2], ms)
                b[3] += err
            _req_flush()
    except Exception:
        pass
    return resp


def request_stats(hours):
    """Requests, average and slowest response (ms) and errors over the last
    `hours`, overall and per route, slowest routes by total time first."""
    since = time.strftime('%Y-%m-%d %H:%M', time.gmtime(time.time() - hours * 3600))
    rules = {}
    for r in app.url_map.iter_rules():
        rules.setdefault(r.endpoint, r.rule)
    out = {"n": 0, "avg": 0.0, "max": 0.0, "errors": 0, "rows": []}
    try:
        conn = live_db()
        c = conn.cursor()
        _req_stats_table(c)
        tot = c.execute("SELECT COALESCE(SUM(n),0), COALESCE(SUM(total_ms),0), "
                        "COALESCE(MAX(max_ms),0), COALESCE(SUM(errors),0) FROM request_stats "
                        "WHERE minute >= ?", (since,)).fetchone()
        out.update({"n": tot[0], "avg": (tot[1] / tot[0]) if tot[0] else 0.0,
                    "max": tot[2], "errors": tot[3]})
        for ep, n, ms, mx, err in c.execute(
                "SELECT endpoint, SUM(n), SUM(total_ms), MAX(max_ms), SUM(errors) "
                "FROM request_stats WHERE minute >= ? GROUP BY endpoint "
                "ORDER BY SUM(total_ms) DESC LIMIT 60", (since,)).fetchall():
            out["rows"].append({"endpoint": ep, "path": rules.get(ep, ''), "n": n,
                                "avg": (ms / n) if n else 0.0, "max": mx, "errors": err,
                                "share": (100.0 * ms / tot[1]) if tot[1] else 0.0})
        conn.close()
    except sqlite3.Error:
        pass
    return out


@app.route('/dev/status')
def dev_status():
    """How fast the site answers: the last hour and the last day, overall
    and per route. Owner only."""
    if not is_site_owner():
        return redirect('/')
    _req_flush(force=True)
    lt, ls = last_watched()
    return render_template('dev_status.html', page='status', version=APP_VERSION,
                           hour=request_stats(1), day=request_stats(24),
                           latest_team=ago_text(lt), latest_survival=ago_text(ls))


def public_entries(entries):
    """Changelog entries as anyone outside the site may see them.

    Owner-only lines are dropped (not stripped of their tag - dropped), and an
    entry left with nothing to say is dropped with them. The changelog page has
    always done this; every other way out of the building must do it too, or the
    filter is decoration.

    <b>/<i> are the page's emphasis; Discord shows them as literal tags, so they
    become Discord's own on the way out and any other markup is removed."""
    out = []
    for e in entries or []:
        vis = [c for c in (e.get("changes") or []) if not c.startswith(OWNER_TAG)]
        if not vis:
            continue
        clean = []
        for c in vis:
            c = re.sub(r"</?b>", "**", c)
            c = re.sub(r"</?i>", "*", c)
            c = re.sub(r"<[^>]+>", "", c)
            clean.append(html.unescape(c).strip())
        d = dict(e)
        d["changes"] = clean
        out.append(d)
    return out

