# There is deliberately no window on how old a lobby may be when you check
# into it: half elo, not refusal, is what stops a latecomer collecting a
# full win for arriving at the end (see perform_checkin). The constant that
# used to set that window is gone rather than left here saying otherwise.


def tracker_limits(c):
    """Capacity and pickup age as the tracker last reported them."""
    c.execute("SELECT key, value FROM tracker_state")
    state = {k: v for k, v in c.fetchall()}
    def num(key, default):
        try:
            return int(state.get(key, default))
        except (TypeError, ValueError):
            return default
    max_age = state.get('max_age_seconds')
    try:
        max_age = int(max_age) if max_age is not None else None
    except (TypeError, ValueError):
        max_age = None
    return (num('capacity', 3), num('min_age_seconds', 1200), max_age,
            num('min_players', 0))


def describe_lobbies(rows, capacity, min_age, max_age=None, min_players=0):
    """Turn raw lobby rows into what a player needs to see: whether it is
    being watched, when it will be, and whether they can still check in.

    Check-in closes exactly when the tracker starts watching. Those were two
    unrelated constants before - 10 minutes and 20 - which left a dead zone
    where a protected player could neither check in nor be picked up, so
    joining between minutes 10 and 20 meant the match could never count for
    them however it went."""
    watched_now = sum(1 for r in rows if r[3])
    free_slots = max(0, capacity - watched_now)
    out = []
    for name, players, age, watching in rows:
        age = age or 0
        if watching:
            status, tone = "Tracked", "on"
        elif max_age is not None and age > max_age:
            # Past the tracker's own cut-off, so no worker will ever take
            # it however many slots are free. Saying "starting shortly"
            # here sent players into a match that could not count.
            status, tone = "too old to track", "off"
        elif min_players and (players or 0) < min_players:
            # The tracker will not spend a worker on a lobby this small,
            # whatever its age or how many slots are free. Saying "waiting
            # for a free slot" implied it was queued - one 2-player lobby
            # claimed that for nearly two hours.
            status, tone = f"needs {min_players} players to be tracked", "off"
        elif age < min_age:
            mins = max(1, -(-(min_age - age) // 60))
            status, tone = f"eligible in {mins} min", "soon"
        elif free_slots > 0:
            status, tone = "starting shortly", "soon"
        else:
            status, tone = "waiting for a free slot", "off"
        out.append({"name": name, "players": players, "mins": int(age // 60),
                    "watching": bool(watching), "status": status, "tone": tone,
                    "can_checkin": not (max_age is not None and age > max_age)
                                   and not (min_players and (players or 0) < min_players)})
    return out, watched_now


@app.route('/api/lobbies', methods=['POST'])
def push_lobbies():
    """The tracker pushes the live NA lobby list here.

    PythonAnywhere's free tier cannot make outbound calls to starblast.io,
    so the site has no way to fetch this itself - the bot has to hand it
    over."""
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401
    body = request.json or {}
    lobbies = body.get('lobbies', [])
    conn = db(timeout=PUSH_TIMEOUT_SECONDS)
    c = conn.cursor()
    # Claim the write lock before doing anything, rather than discovering
    # halfway through that it is not available. The tracker re-sends the
    # complete state on the next sweep, so giving up here costs nothing,
    # whereas hanging on blocks a web worker long after the tracker has
    # stopped waiting for the reply.
    try:
        c.execute("BEGIN IMMEDIATE")
    except sqlite3.OperationalError:
        conn.close()
        return jsonify({"status": "busy"}), 503
    for key in ('capacity', 'min_age_seconds', 'max_age_seconds'):
        if body.get(key) is not None:
            c.execute("INSERT OR REPLACE INTO tracker_state (key, value) VALUES (?, ?)",
                      (key, str(body[key])))
    # Pairs the tracker saw this cycle. Bounded and de-duplicated by the
    # primary key, so a noisy match cannot flood the table.
    now_ts = time.strftime('%Y-%m-%d %H:%M:%S')
    for pair in (body.get('name_fixes') or [])[:400]:
        try:
            ocr_name, real_name = str(pair[0])[:64], str(pair[1])[:64]
        except (TypeError, IndexError, ValueError):
            continue
        if not ocr_name or not real_name or ocr_name == real_name:
            continue
        c.execute("INSERT INTO name_map (ocr_name, real_name, seen, first_seen, last_seen) "
                  "VALUES (?, ?, 1, ?, ?) "
                  "ON CONFLICT(ocr_name, real_name) DO UPDATE SET "
                  "seen = seen + 1, last_seen = excluded.last_seen",
                  (ocr_name, real_name, now_ts, now_ts))

    # A watched lobby that vanishes this cycle = a match that just ended and is
    # being scored. Capture the previous watched set before the swap; any not in
    # the new push go into scoring_lobbies (shown as "Scoring" on /play until the
    # result lands or it times out); any that reappear are cleared (a transient
    # push gap, not a real end). game_end also clears them when the result posts.
    prev_watch = c.execute(
        "SELECT sys_id, name, players, region FROM live_lobbies "
        "WHERE watching = 1 AND COALESCE(mode, 'team') = 'team'"
    ).fetchall()
    new_ids = {lobby.get('id') for lobby in lobbies[:40] if lobby.get('id') is not None}

    c.execute("DELETE FROM live_lobbies WHERE COALESCE(mode, 'team') = 'team'")
    now = time.strftime('%Y-%m-%d %H:%M:%S')
    for lobby in lobbies[:40]:
        c.execute("INSERT OR REPLACE INTO live_lobbies (sys_id, name, players, age, updated_at, watching, region, mode) "
                  "VALUES (?,?,?,?,?,?,?, 'team')",
                  (lobby.get('id'), lobby.get('name'), lobby.get('players'), lobby.get('time'),
                   now, 1 if lobby.get('watching') else 0,
                   lobby.get('region') or 'america'))
    for sid, lname, lplayers, lregion in prev_watch:
        if sid not in new_ids:
            c.execute("INSERT OR IGNORE INTO scoring_lobbies "
                      "(sys_id, name, region, players, since) VALUES (?,?,?,?,?)",
                      (sid, lname, lregion or 'america', lplayers, now))
    if new_ids:
        c.execute("DELETE FROM scoring_lobbies WHERE sys_id IN (%s)"
                  % ",".join("?" * len(new_ids)), tuple(new_ids))
    c.execute("DELETE FROM scoring_lobbies WHERE since < datetime('now', '-100 seconds')")

    # Sightings of a ship id under a name. Kept for a short window - just
    # long enough for a check-in to be matched against one - then pruned.
    for ap in (body.get('appearances') or [])[:200]:
        try:
            c.execute("INSERT INTO appearances (sys_id, ship_id, name, region, at) "
                      "VALUES (?,?,?,?,?)",
                      (ap.get('sys_id'), ap.get('ship_id'), str(ap.get('name'))[:64],
                       ap.get('region'), ap.get('at') or now))
        except (TypeError, ValueError, sqlite3.Error):
            continue
    # Only prune occasionally. This is a full scan of a table that is
    # written several times a minute, and the rows it removes are ones
    # nothing has read for well over an hour - doing it every push spent
    # write-lock time on housekeeping that can wait.
    if random.randint(1, 20) == 1:
        c.execute("DELETE FROM appearances WHERE at < datetime('now', '-2 hours')")

    # Every push is a chance to match a fresh sighting to a waiting
    # check-in. Cheap - only unbound check-ins from the last few minutes
    # are considered.
    try:
        bind_appearances_to_checkins(c)
    except sqlite3.Error:
        pass
    conn.commit()
    conn.close()
    return jsonify({"status": "ok", "stored": len(lobbies[:40])}), 200


@app.route('/api/live_lobbies')
def live_lobbies():
    """Public list for the check-in picker. Deliberately exposes only the
    lobbies themselves - never who has checked in, since publishing that
    would tell an impersonator exactly which lobby to go and sit in."""
    conn = db()
    c = conn.cursor()
    capacity, min_age, max_age, min_players = tracker_limits(c)
    c.execute("SELECT sys_id, name, players, age, COALESCE(watching, 0), "
              "COALESCE(region, 'america') "
              "FROM live_lobbies WHERE updated_at > datetime('now', '-5 minutes') "
              "AND COALESCE(mode, 'team') = 'team' "
              "ORDER BY watching DESC, age DESC")
    rows = c.fetchall()
    # Survival lobbies are listed on their own terms: the team board's age and
    # capacity rules describe a team match and say nothing useful about a
    # survival round, which spends its first half filling up.
    surv_rows = c.execute(
        "SELECT sys_id, name, players, age, COALESCE(watching, 0), "
        "COALESCE(region, 'america') FROM live_lobbies "
        "WHERE updated_at > datetime('now', '-5 minutes') AND mode = 'survival' "
        "ORDER BY watching DESC, players DESC").fetchall()
    scoring_rows = c.execute(
        "SELECT sys_id, name, region, players FROM scoring_lobbies "
        "WHERE since > datetime('now', '-100 seconds') ORDER BY since DESC").fetchall()
    conn.close()
    described, watched_now = describe_lobbies([(r[1], r[2], r[3], r[4]) for r in rows],
                                              capacity, min_age, max_age, min_players)
    for lobby, raw in zip(described, rows):
        lobby["id"] = raw[0]
        lobby["age"] = raw[3]
        # Callers group by this. Without it the bot could only ever show one
        # undifferentiated list, which is wrong now that three regions are
        # watched at once.
        lobby["region"] = raw[5]
        lobby["region_label"] = REGION_LABELS.get(raw[5], raw[5])
    for lobby in described:
        lobby["mode"] = "team"
    for sid, sname, splayers, sage, swatch, sregion in surv_rows:
        described.append({
            "id": sid, "region": sregion,
            "region_label": REGION_LABELS.get(sregion, sregion),
            "name": sname or ("Lobby %d" % sid), "players": splayers or 0,
            "age": sage or 0, "mins": int((sage or 0) // 60),
            "watching": bool(swatch), "mode": "survival",
            "status": ("Being watched" if swatch else "Not watched yet"),
            "tone": ("watching" if swatch else "waiting"),
            # A survival check-in stays open until the watcher is on the lobby,
            # exactly like a team one - that is the moment it stops being a
            # promise and starts being evidence.
            "can_checkin": not swatch, "scoring": False})
    live_ids = {r[0] for r in rows} | {r[0] for r in surv_rows}
    for sid, sname, sregion, splayers in scoring_rows:
        if sid in live_ids:
            continue
        described.append({"id": sid, "region": sregion or "america",
                          "region_label": REGION_LABELS.get(sregion, sregion or "america"),
                          "name": sname or ("Lobby %d" % sid), "players": splayers or 0,
                          "age": 0, "mins": 0, "watching": False, "status": "Scoring",
                          "tone": "scoring", "can_checkin": False, "scoring": True})
    return jsonify({"lobbies": described, "minutes_to_check_in": min_age // 60,
                    "capacity": capacity, "watching": watched_now,
                    "regions": [{"key": k, "label": l} for k, l in REGIONS]}), 200


@app.route('/checkin/cancel', methods=['POST'])
def check_in_cancel():
    """Take back a check-in for a lobby the watcher has not reached yet.

    A check-in is only a promise until a watcher is on the lobby; after that it
    is the evidence that ties a result to you, so it stays. Cancelling before
    then costs nothing and lets someone who joined the wrong lobby correct it."""
    sub_id = current_user()
    if not sub_id:
        return jsonify({"ok": False, "message": "Sign in first."}), 401
    try:
        sys_id = int((request.json or {}).get('sys_id'))
    except (TypeError, ValueError):
        return jsonify({"ok": False, "message": "Which lobby?"}), 400
    conn = db()
    c = conn.cursor()
    watching = c.execute(
        "SELECT COALESCE(watching, 0) FROM live_lobbies WHERE sys_id = ?",
        (sys_id,)).fetchone()
    if watching and watching[0]:
        conn.close()
        return jsonify({"ok": False,
                        "message": "That lobby is being watched now - a check-in "
                                   "made before then is part of the record."}), 400
    n = c.execute("DELETE FROM checkins WHERE sub = ? AND sys_id = ?",
                  (sub_id, sys_id)).rowcount
    conn.commit()
    conn.close()
    return jsonify({"ok": True, "removed": n}), 200


@app.route('/protection', methods=['GET', 'POST'])
def protection():
    """Read or set a name's protection toggle.

    Protection ON means the name is only rated for matches it checked
    into, which is what stops someone else playing under it from moving
    the rating. It is deliberately opt-in: leaving it off keeps the
    ordinary automatic behaviour, so registering never silently costs a
    player their matches."""
    if request.method == 'GET':
        name = (request.args.get('name') or '').strip()
    else:
        name = str((request.json or {}).get('name', '')).strip()
    if not name:
        return jsonify({"message": "No name provided"}), 400

    conn = db()
    c = conn.cursor()
    c.execute("SELECT name, reg_ip, COALESCE(strict_mode, 0), prot_changed_at "
              "FROM players WHERE norm_name = ?", (normalize_name(name),))
    row = c.fetchone()
    if not row:
        conn.close()
        return jsonify({"message": f"'{name}' is not on the leaderboard."}), 404
    stored_name, reg_ip, enabled, changed_at = row

    def hours_left():
        """Hours still to wait before protection can be flipped again."""
        if not changed_at:
            return 0.0
        c.execute("SELECT (julianday('now') - julianday(?)) * 24.0", (changed_at,))
        gone = c.fetchone()[0]
        if gone is None:
            return 0.0
        return max(0.0, PROTECTION_COOLDOWN_HOURS - gone)

    if request.method == 'GET':
        left = hours_left()
        # Ownership is the account, not the network. Reporting reg_ip here
        # left every account created since ratings moved to accounts - none
        # of which ever gets a reg_ip - looking like it owned nothing, so
        # the toggle was disabled for precisely the players it is meant for.
        owned, _ = owner_check(c, stored_name, reg_ip)
        conn.close()
        # Only the person it belongs to is told. Anyone could ask this about
        # any name, which handed over a list of top players whose rating a
        # result played under their name would still move.
        out = {"name": stored_name, "owned": bool(owned),
               "hours_left": round(left, 1)}
        if owned or is_site_owner():
            out["enabled"] = bool(enabled)
        return jsonify(out), 200

    ok, err = owner_check(c, stored_name, reg_ip)
    if not ok:
        conn.close()
        return jsonify({"message": err}), 403

    want = 1 if (request.json or {}).get('enabled') else 0

    if not want:
        c.execute("SELECT COALESCE(game_name, '') FROM players WHERE name = ?",
                  (stored_name,))
        _gn = (c.fetchone() or [''])[0]
        if is_default_game_name(_gn):
            conn.close()
            return jsonify({"message": f"Your play name '{_gn}' is one of the game's "
                                       f"default names, so Protection stays on. Set a "
                                       f"play name of your own first.",
                            "enabled": True}), 400

    # No match history required. Protection is only useful BEFORE someone
    # else plays under your name, so demanding a tracked match first meant
    # your first match was always the exposed one - and after a board reset
    # that applied to everybody at once. The abuse it used to guard against
    # is much weaker now: an account name cannot be one already on the
    # board, results reach an account through the check-in binding, and a
    # misused name can be reported. Turning protection OFF is still always
    # allowed, so nobody can be stranded by it.

    if want != enabled:
        left = hours_left()
        if left > 0:
            conn.close()
            if left >= 1:
                wait = f"{int(left)} hour{'s' if int(left) != 1 else ''}"
            else:
                mins = max(1, int(left * 60))
                wait = f"{mins} minute{'s' if mins != 1 else ''}"
            return jsonify({"message": f"Protection can only be changed once a day. "
                                       f"Try again in {wait}.",
                            "enabled": bool(enabled)}), 429
        c.execute("UPDATE players SET strict_mode = ?, prot_changed_at = ? WHERE name = ?",
                  (want, time.strftime('%Y-%m-%d %H:%M:%S'), stored_name))
    conn.commit()
    conn.close()
    if want:
        return jsonify({"message": f"Protection is ON for '{stored_name}'. Only matches you check into will count.", "enabled": True}), 200
    return jsonify({"message": f"Protection is OFF for '{stored_name}'. All matches count, as normal.", "enabled": False}), 200


def perform_checkin(c, sub_id, sys_id):
    """Check an account into a lobby. Returns (http_status, payload).

    Shared by the website's /checkin and the bot's /api/bot/checkin. Two
    copies would drift the first time either was touched, and a check-in
    that means something different depending on where it was pressed is
    worse than one that lives in a single place.

    Does NOT commit - the caller owns the transaction.
    """
    if sys_id is None:
        return 400, {"ok": False, "message": "Which match? Pick one from the list."}
    try:
        sys_id = int(sys_id)
    except (TypeError, ValueError):
        return 400, {"ok": False, "message": "That lobby id is not valid."}

    # An account with no name has nowhere to put the result, so there is
    # nothing a check-in could achieve yet. Say so plainly rather than
    # accepting it and silently dropping the match later.
    who = account_name_for(c, sub_id)
    if not who:
        return 400, {"ok": False, "no_name": True,
                     "message": "Set your account name first - that is the name your "
                                "matches are recorded under."}

    c.execute("SELECT age FROM live_lobbies WHERE sys_id = ?", (sys_id,))
    lobby = c.fetchone()
    if not lobby:
        return 404, {"ok": False, "message": "That lobby is not in the current live list."}
    # No window. Half elo is what stops a latecomer collecting a full win
    # for arriving at the end, so refusing late check-ins only meant that
    # joining a match in progress could not be rated at all.
    lobby_age = lobby[0] or 0
    _, min_age, _max_age, _min_players = tracker_limits(c)

    # The name they will actually appear under, which is what has to be
    # said back to them. Falls back to the account name, which is what the
    # site assumes when no game name is set.
    c.execute("SELECT COALESCE(NULLIF(game_name, ''), name) FROM players WHERE name = ?",
              (who,))
    _row = c.fetchone()
    play_as = (_row[0] if _row else who) or who
    default_note = ""
    if is_default_game_name(play_as):
        c.execute("UPDATE players SET strict_mode = 1 WHERE name = ?", (who,))
        default_note = (" '%s' is one of the game's default names, so Protection "
                        "is on automatically - only matches you check into count."
                        % play_as)

    # Committing BEFORE you play is the whole point of a check-in
    # (owner's rule, 22 Aug 2026). If a ship with this account's name has
    # already appeared in this match, part of the outcome is already
    # known - accepting a check-in now would let a player wait until they
    # are clearly winning and only then commit. Re-pressing Play after a
    # legitimate check-in stays a harmless no-op.
    c.execute("SELECT 1 FROM checkins WHERE sub = ? AND sys_id = ? "
              "AND created_at > datetime('now', ?)",
              (sub_id, sys_id, '-' + str(CHECKIN_VALID_SECONDS) + ' seconds'))
    if c.fetchone():
        return 200, {"ok": True, "sys_id": sys_id, "late": lobby_age >= min_age,
                     "account_name": who, "play_as": play_as,
                     "message": f"Already checked in for this match as '{who}'."}
    _keys = {normalize_name(play_as), normalize_name(who)} - {''}
    if _keys:
        c.execute("SELECT name FROM appearances WHERE sys_id = ?", (sys_id,))
        for (_an,) in c.fetchall():
            if normalize_name(_an) in _keys:
                return 400, {"ok": False, "already_playing": True,
                             "message": f"A ship called '{play_as}' is already in that "
                                        f"match, so this check-in can't be taken: checking "
                                        f"in has to come before you join, or anyone could "
                                        f"claim a ship already flying. If that ship is you, "
                                        f"the match still counts for your account under "
                                        f"your play name or your clan's tag - the check-in "
                                        f"only adds proof of which ship. Next match, press "
                                        f"Play first."}

    # One live check-in per account. Without this you could check into
    # every fresh lobby at once, watch which one is going well and join
    # only that one - keeping every option open would cost nothing.
    # The reply NAMES what got cancelled (owner incident, 22 Aug 2026:
    # a check-in silently cancelled this way cost a 30k-score win - the
    # generic warning was true but nobody reads a sentence that is always
    # there).
    c.execute("SELECT DISTINCT sys_id FROM checkins WHERE sub = ? "
              "AND COALESCE(bound, 0) = 0 AND created_at > datetime('now', ?)",
              (sub_id, '-' + str(CHECKIN_VALID_SECONDS) + ' seconds'))
    _cancelled = [str(r[0]) for r in c.fetchall() if r[0] != sys_id]
    c.execute("DELETE FROM checkins WHERE sub = ? AND COALESCE(bound, 0) = 0 "
              "AND created_at > datetime('now', ?)",
              (sub_id, '-' + str(CHECKIN_VALID_SECONDS) + ' seconds'))
    c.execute("INSERT INTO checkins (player, sub, sys_id, created_at) VALUES (?,?,?,?)",
              (who, sub_id, sys_id, time.strftime('%Y-%m-%d %H:%M:%S')))
    late = lobby_age >= min_age
    note = (" This match is already under way, so your result counts at half value - "
            "and joining now only links to you if you have not already been playing."
            if late else
            " Play under any name you like - the first ship to appear is taken as yours.")
    cancel_note = ((" ⚠ This CANCELLED your check-in for lobby #%s - if you "
                    "still mean to play there, check in for it again before "
                    "joining." % ', #'.join(_cancelled))
                   if _cancelled else "")
    return 200, {"ok": True,
                 "message": f"Checked in for this match as '{who}'.{note}"
                            f"{default_note}{cancel_note}",
                 "sys_id": sys_id, "late": late,
                 "cancelled": _cancelled,
                 "account_name": who, "play_as": play_as}


@app.route('/checkin', methods=['POST'])
def check_in():
    """Declare that you are about to play a given lobby.

    You check in as an ACCOUNT, not as a name. That is the point: at the
    moment you press Play nobody knows yet which name you will appear
    under, and working that out is exactly what the check-in buys. The
    tracker reports every ship it sees; the first one to show up in this
    lobby after this row is written gets bound to you, and from then on
    that name's results are recorded against your account.
    """
    data = request.json or {}
    sub_id = current_user()
    if not sub_id:
        return jsonify({"message": "Sign in first, then press Play on the match "
                                   "you are about to join."}), 401
    conn = db()
    c = conn.cursor()
    status, payload = perform_checkin(c, sub_id, data.get('sys_id'))
    if status == 200:
        conn.commit()
    conn.close()
    return jsonify(payload), status




def perform_claim(c, me_sub, raw_name, raw_note, rate_src=None):
    """File a claim on an unowned leaderboard name.

    Shared by the website and the bot. Does NOT commit.
    """
    name = str(raw_name or '').strip()
    if not name:
        return 400, {"ok": False, "message": "No name provided."}
    note = str(raw_note or '').strip()[:200]

    # One name per account, the same rule registering follows. Without this
    # an account could register one name and then claim as many more as it
    # liked, which is the cap in name only.
    c.execute("SELECT name FROM players WHERE google_sub = ? "
              "AND (COALESCE(wins, 0) + COALESCE(losses, 0)) > 0", (me_sub,))
    held = [r[0] for r in c.fetchall()]
    if len(held) >= MAX_NAMES_PER_ACCOUNT:
        return 403, {"ok": False,
                     "message": f"Your account already has a name: '{held[0]}'. "
                                f"Remove it first if you want to claim a different one."}

    c.execute("SELECT name, google_sub FROM players WHERE norm_name = ?",
              (normalize_name(name),))
    row = c.fetchone()
    if not row:
        return 404, {"ok": False, "message": f"'{name}' is not on the leaderboard."}

    stored_name, owner_sub = row
    if owner_sub == me_sub:
        return 400, {"ok": False, "message": f"'{stored_name}' is already yours."}
    if owner_sub:
        return 400, {"ok": False,
                     "message": "That name already belongs to an account. If it is really "
                                "yours, report it and it will be looked at by hand."}

    c.execute("SELECT id FROM claim_requests WHERE name = ? AND google_sub = ? "
              "AND status = 'pending'", (stored_name, me_sub))
    if c.fetchone():
        return 400, {"ok": False,
                     "message": "You already have a pending claim for that name."}

    # Cap how many can be open at once. Each claim raises an alert, so an
    # unlimited supply is both a way to bury the genuine ones and a way to
    # flood the channel they are reported in.
    c.execute("SELECT COUNT(*) FROM claim_requests WHERE status = 'pending' "
              "AND google_sub = ?", (me_sub,))
    pending_mine = (c.fetchone() or [0])[0]
    if pending_mine >= MAX_PENDING_CLAIMS:
        return 429, {"ok": False,
                     "message": f"You already have {MAX_PENDING_CLAIMS} claims waiting. "
                                f"Wait for those to be looked at first."}
    if rate_hit(c, 'claim', MAX_PENDING_CLAIMS, '-1 day', src=rate_src):
        return 429, {"ok": False,
                     "message": f"You have started {MAX_PENDING_CLAIMS} claims in the "
                                f"last day, which is the limit - withdrawn ones "
                                f"included. Try again tomorrow."}

    c.execute("SELECT COALESCE(MAX(id), 0) FROM matches")
    from_match = c.fetchone()[0]
    c.execute("INSERT INTO claim_requests (name, ip, note, created_at, status, "
              "google_sub, verify_from) VALUES (?, ?, ?, ?, 'pending', ?, ?)",
              (stored_name, None, note, time.strftime('%Y-%m-%d %H:%M:%S'),
               me_sub, from_match))
    n = CLAIM_WINS_REQUIRED
    return 200, {"ok": True, "name": stored_name,
                 "message": f"Claim started for '{stored_name}'. Prove it is yours "
                            f"with one ranked Deathmatch game - the Discord bot's "
                            f"/proveclaim walks you through it - or wait for the "
                            f"owner to review it. The claim is shown on that "
                            f"player's page while it is open, so the real owner "
                            f"can report it."}


def perform_claim_decide(c, claim_id, approve, decided_by=""):
    """The site owner granting a claim without waiting for the tracked win.

    Every check the automatic path makes is made here too - the name must
    be unheld, the account must be under its cap, and a placeholder row
    with no record is discarded so the claimed row can take its place.
    Skipping them here would let a hand-approval do what the automatic
    path is careful never to do: hand somebody a name that is already
    someone else's. Does NOT commit.
    """
    c.execute("SELECT name, google_sub, status FROM claim_requests WHERE id = ?",
              (claim_id,))
    row = c.fetchone()
    if not row:
        return 404, {"ok": False, "message": "No such claim."}
    name, claimant, status = row
    if status != 'pending':
        return 400, {"ok": False, "name": name,
                     "message": f"That claim was already {status}."}
    if not approve:
        c.execute("UPDATE claim_requests SET status = 'declined' WHERE id = ?",
                  (claim_id,))
        return 200, {"ok": True, "approved": False, "name": name,
                     "sub_id": claimant,
                     "message": f"Claim on '{name}' declined."}
    if not claimant:
        return 400, {"ok": False, "name": name,
                     "message": f"'{name}' was claimed without signing in, so there "
                                f"is no account to give it to. It can only complete "
                                f"the usual way."}
    key = normalize_name(name)
    c.execute("SELECT google_sub FROM players WHERE norm_name = ?", (key,))
    held = (c.fetchone() or [None])[0]
    if held and held != claimant:
        c.execute("UPDATE claim_requests SET status = 'declined' WHERE id = ?",
                  (claim_id,))
        return 200, {"ok": False, "name": name,
                     "message": f"'{name}' already belongs to another account, so "
                                f"the claim was declined instead."}
    c.execute("SELECT COUNT(*) FROM players WHERE google_sub = ?", (claimant,))
    if c.fetchone()[0] > MAX_NAMES_PER_ACCOUNT:
        return 400, {"ok": False, "name": name,
                     "message": f"That account already holds {MAX_NAMES_PER_ACCOUNT} "
                                f"names."}
    c.execute("SELECT name, COALESCE(wins, 0) + COALESCE(losses, 0) "
              "FROM players WHERE google_sub = ?", (claimant,))
    mine = c.fetchone()
    if mine and normalize_name(mine[0]) != key:
        if mine[1] > 0:
            return 400, {"ok": False, "name": name,
                         "message": f"That account already plays as '{mine[0]}', which "
                                    f"has a record of its own."}
        c.execute("DELETE FROM players WHERE name = ?", (mine[0],))
    c.execute("UPDATE players SET google_sub = ?, wipe_available = 1 "
              "WHERE norm_name = ?", (claimant, key))
    c.execute("UPDATE claim_requests SET status = 'approved' WHERE id = ?", (claim_id,))
    # Anyone else waiting on the same name is answered by the same decision.
    c.execute("UPDATE claim_requests SET status = 'declined' WHERE status = 'pending' "
              "AND id != ? AND name IN (SELECT name FROM players WHERE norm_name = ?)",
              (claim_id, key))
    return 200, {"ok": True, "approved": True, "name": name, "sub_id": claimant,
                 "message": f"'{name}' now belongs to that account."}


def refund_rate(c, kind, n, src=None):
    """Give back n rate events, newest first. The undo of rate_hit.

    Only called when the thing the event paid for was itself undone, so
    the limit still counts real, standing actions.
    """
    src = src or ip_source()
    c.execute("DELETE FROM rate_events WHERE rowid IN ("
              "SELECT rowid FROM rate_events WHERE kind = ? AND src = ? "
              "ORDER BY created_at DESC LIMIT ?)", (kind, src, int(n)))


def perform_claim_withdraw(c, sub_id, name=None, rate_src=None):
    """Take back a claim you have not had answered yet. Does NOT commit.

    Withdrawn rather than deleted: the row is what shows a name was asked
    for and by whom, and a claim that vanishes without trace is how the
    same argument gets had twice.
    """
    if not sub_id:
        return 401, {"ok": False, "message": "Sign in first."}
    want = str(name or '').strip()
    c.execute("SELECT id, name FROM claim_requests WHERE google_sub = ? "
              "AND status = 'pending' ORDER BY id", (sub_id,))
    rows = c.fetchall()
    if want:
        key = normalize_name(want)
        rows = [r for r in rows if normalize_name(r[1]) == key]
    if not rows:
        return 404, {"ok": False,
                     "message": f"You have no claim waiting on '{want}'." if want
                                else "You have no claim waiting."}
    c.executemany("UPDATE claim_requests SET status = 'withdrawn' WHERE id = ?",
                  [(r[0],) for r in rows])
    refund_rate(c, 'claim', len(rows), src=rate_src)
    names = ", ".join(r[1] for r in rows)
    return 200, {"ok": True, "withdrawn": [r[1] for r in rows],
                 "message": f"Claim on '{names}' withdrawn. You can claim it again "
                            f"whenever you like."}


@app.route('/claim/mine')
def claim_mine():
    """The claims this account is waiting on, so they can be taken back."""
    sub_id = current_user()
    if not sub_id:
        return jsonify({"claims": []}), 200
    conn = db()
    c = conn.cursor()
    c.execute("SELECT name, created_at FROM claim_requests WHERE google_sub = ? "
              "AND status = 'pending' ORDER BY id", (sub_id,))
    out = [{"name": r[0], "at": r[1]} for r in c.fetchall()]
    conn.close()
    return jsonify({"claims": out}), 200


@app.route('/claim/withdraw', methods=['POST'])
def claim_withdraw():
    """Take back a claim that has not been decided."""
    sub_id = current_user()
    conn = db()
    c = conn.cursor()
    status, payload = perform_claim_withdraw(c, sub_id,
                                             (request.json or {}).get('name'))
    if status == 200:
        conn.commit()
    conn.close()
    return jsonify(payload), status


@app.route('/claim', methods=['POST'])
def claim_name():
    """Request ownership of a name that has no owner.

    Nothing is granted instantly - an instant claim would let anyone
    seize a top player's name and rename it. The claim completes on its
    own once the name wins a tracked match after filing, and while it is
    open it is shown publicly on that player's page so the real owner
    can see it and report it."""
    data = request.json or {}
    me_sub = current_user()
    if not me_sub:
        return jsonify({"message": "Sign in first - use the button at the top "
                                   "of the page."}), 401
    conn = db()
    c = conn.cursor()
    status, payload = perform_claim(c, me_sub, data.get('name'), data.get('note'))
    if status == 200:
        conn.commit()
    conn.close()
    return jsonify(payload), status


def account_name_for(c, sub_id):
    """The name this account plays under on the leaderboard, or None."""
    if not sub_id:
        return None
    # Deterministic on purpose. A grandfathered account holds two rows and
    # a bare LIMIT 1 returned whichever the table felt like, so the Play
    # page could say one name and a check-in be recorded under the other.
    c.execute("SELECT name FROM players WHERE google_sub = ? "
              "ORDER BY (COALESCE(wins, 0) + COALESCE(losses, 0)) DESC, name LIMIT 1",
              (sub_id,))
    row = c.fetchone()
    return row[0] if row else None


def bind_appearances_to_checkins(c):
    """Turn 'someone checked in' plus 'a ship appeared' into 'that is them'.

    Only appearances AFTER a check-in in the SAME lobby count, and only
    within BINDING_WINDOW_SECONDS - a name that turns up half an hour later
    is somebody else. Each check-in binds once.
    """
    c.execute("SELECT rowid, sub, sys_id, created_at FROM checkins "
              "WHERE sub IS NOT NULL AND COALESCE(bound, 0) = 0 "
              "AND created_at > datetime('now', ?) ORDER BY created_at",
              (f'-{BINDING_WINDOW_SECONDS} seconds',))
    pending = c.fetchall()
    # A ship that has already been matched to somebody cannot also be
    # somebody else. Without this, two people pressing Play on the same
    # lobby both took the earliest join after their own click - which is
    # the same join - and one of them was credited with the other's game.
    c.execute("SELECT sys_id, ship_id FROM name_bindings")
    taken = {(r[0], r[1]) for r in c.fetchall()}
    for rowid, sub_id, sys_id, created_at in pending:
        # What this account says it plays as, falling back to the account
        # name - which is what the play name defaults to anyway.
        c.execute("SELECT game_name, name FROM players WHERE google_sub = ? "
                  "ORDER BY (COALESCE(wins, 0) + COALESCE(losses, 0)) DESC, name LIMIT 1",
                  (sub_id,))
        _row = c.fetchone()
        _claim = (_row[0] or _row[1]) if _row else ''
        expect = normalize_name(_claim)
        expect_skel = skeleton(_claim)
        if not expect:
            continue
        c.execute("SELECT name, ship_id, region FROM appearances "
                  "WHERE sys_id = ? AND at >= ? ORDER BY at",
                  (sys_id, created_at))
        hit = None
        for cand in c.fetchall():
            if (sys_id, cand[1]) in taken:
                continue
            # Exact identity match first; then the confusable-tolerant
            # skeleton, so a stylised in-game name still binds to the ship the
            # player checked in as (safe - this is their own explicit claim).
            if (normalize_name(cand[0]) == expect
                    or (expect_skel and skeleton(cand[0]) == expect_skel)):
                hit = cand
                break
        if not hit:
            continue
        name, ship_id, region = hit
        taken.add((sys_id, ship_id))
        # A self-binding (account name == play name) used to be skipped as
        # a no-op. It is not one any more: the binding carries the SHIP ID,
        # which is what credits the real owner when an impersonator flies
        # the same name (L7 Tempest, match #5536 - checked in, denied by a
        # name duplicate). Every check-in binds its ship now.
        c.execute("INSERT OR REPLACE INTO name_bindings "
                  "(sub, in_game_name, sys_id, ship_id, region, bound_at) "
                  "VALUES (?,?,?,?,?,?)",
                  (sub_id, name, sys_id, ship_id, region,
                   time.strftime('%Y-%m-%d %H:%M:%S')))
        c.execute("UPDATE checkins SET bound = 1 WHERE rowid = ?", (rowid,))


_PLAY_CACHE = {"ts": 0.0, "map": {}}


def play_name_map(c):
    """normalised play name -> (sub, account name), for every account that
    has declared one. Rebuilt every minute, and at once when one is set.

    A name two accounts both claim is left out: it belongs to neither. So is
    a play name that is some OTHER account's account name - an account name
    outranks a play-name claim, or setting your play name to TEKIT would
    collect TEKIT's results. Default game names and names that normalise to
    nothing never map to anybody.
    """
    now = time.time()
    if now - _PLAY_CACHE["ts"] < 60:
        return _PLAY_CACHE["map"]
    owned = {}
    claims = {}
    try:
        for sub, name, game in c.execute(
                "SELECT google_sub, name, game_name FROM players "
                "WHERE google_sub IS NOT NULL AND google_sub != '' AND " + NOT_SANDBOX
        ).fetchall():
            nk = normalize_name(name)
            if nk:
                owned[nk] = sub
            gk = normalize_name(game or "")
            if game and gk and gk != nk and not is_default_game_name(game):
                claims.setdefault(gk, []).append((sub, name))
    except sqlite3.Error:
        return _PLAY_CACHE["map"]
    m = {}
    for gk, who in claims.items():
        if len(who) != 1:
            continue                              # two accounts, nobody's name
        sub, name = who[0]
        if gk in owned and owned[gk] != sub:
            continue                              # somebody's ACCOUNT name
        m[gk] = (sub, name)
    _PLAY_CACHE["ts"], _PLAY_CACHE["map"] = now, m
    return m


def account_for_ingame_name(c, name, sys_id=None):
    """The account this in-game name belongs to, or None.

    First a check-in binding for THIS lobby - proof that one particular ship
    was this account, scoped to the lobby on purpose so a single check-in is
    never a standing claim on a name. Failing that, the play name: an account
    that has declared it plays as this name gets the result, no check-in
    needed. Failing that, a clan tag: the tag in any of its stylings plus the
    name of a member of that clan is that member. The check-in keeps its job
    - saying which ship - and Protection still holds a protected account's
    result unless it was checked in.
    """
    if not name:
        return None
    if sys_id is not None:
        c.execute("SELECT sub FROM name_bindings WHERE in_game_name = ? AND sys_id = ? "
                  "LIMIT 1", (name, sys_id))
        row = c.fetchone()
        if row:
            return account_name_for(c, row[0])
    key = normalize_name(name)
    if not key:
        return None
    hit = play_name_map(c).get(key)
    if hit:
        return hit[1]
    return clan_member_for_tagged_name(c, name)


def current_user():
    """The signed-in Google account id, or None if nobody is signed in."""
    return session.get('google_sub')


def is_site_owner():
    """True when the REAL signed-in account is an owner. While the owner
    is impersonating the sandbox, current_user() is the sandbox - so the
    stashed real id is what counts."""
    real = session.get('dev_real_owner') or current_user()
    return real in OWNER_SUBS


def safe_next(raw):
    """A path on this site to return to after signing in, or None.

    Only our own paths. A value with a scheme, or a second leading slash,
    is a link to somebody else's site, and sending a freshly signed-in
    player there is how an invite link would be turned into a way of
    harvesting them. Anything that is not plainly local is dropped rather
    than repaired.
    """
    s = str(raw or '')
    if not s or len(s) > 200:
        return None
    if not s.startswith('/') or s.startswith('//'):
        return None
    if '\\' in s or any(ch < ' ' for ch in s):
        return None
    return s


def owner_check(c, stored_name, reg_ip):
    """May the current visitor act on this name? Returns (ok, error).

    Ownership is the signed-in account, and nothing else. The reg_ip
    parameter is historical - addresses are no longer recorded anywhere,
    and a network never proved identity to begin with. An unowned name
    is taken through a claim, which completes once the name wins a
    tracked match after filing.
    """
    me_sub = current_user()
    c.execute("SELECT google_sub FROM players WHERE name = ?", (stored_name,))
    row = c.fetchone()
    owner_sub = row[0] if row else None

    if owner_sub:
        if me_sub and me_sub == owner_sub:
            return True, None
        return False, ("That name belongs to another account. Sign in with the "
                       "account that owns it.")

    # No account on the name means nobody owns it - there is no network
    # fallback any more. Matching an address only ever proved somebody was
    # on the same wifi, which is why housemates, schools and mobile networks
    # could all edit each other's names. Claiming is the only route in, and
    # it is reviewed by a person.
    if not me_sub:
        return False, ("Sign in first, then use Claim to ask for this name.")
    return False, ("Nobody owns that name yet. Use Claim to ask for it - "
                   "prove a claim with one ranked Deathmatch game (the Discord bot walks you through it), or the owner reviews it by hand.")


@app.route('/auth/google', methods=['POST'])
def auth_google():
    """Sign in with the token Google's button hands to the browser.

    The signature is checked against Google's published keys and the
    token must have been issued for this site specifically, so a token
    minted for some other app cannot be replayed here. Only the opaque
    account id is kept - never the email or the name - which leaves the
    leaderboard holding no personal data about anyone.
    """
    try:
        from google.oauth2 import id_token as google_id_token
        from google.auth.transport import requests as google_requests
    except ImportError:
        return jsonify({"message": "Sign-in is temporarily unavailable."}), 503

    token = str((request.json or {}).get('credential', '')).strip()
    if not token:
        return jsonify({"message": "No sign-in token was received."}), 400

    try:
        claims = google_id_token.verify_oauth2_token(
            token, google_requests.Request(), GOOGLE_CLIENT_ID
        )
    except Exception:
        # Covers a bad signature, the wrong audience and an expired token.
        # The reason is deliberately not echoed back to the browser.
        return jsonify({"message": "That sign-in could not be verified. Please try again."}), 401

    if claims.get('iss') not in ('accounts.google.com', 'https://accounts.google.com'):
        return jsonify({"message": "That sign-in could not be verified."}), 401
    sub_id = str(claims.get('sub') or '')
    if not sub_id:
        return jsonify({"message": "That sign-in could not be verified."}), 401

    session.permanent = True
    session['google_sub'] = sub_id
    return jsonify({"message": "Signed in."}), 200


def remember_discord_user(sub_id, username, display):
    """Keep the handle behind a Discord identity current."""
    conn = db()
    c = conn.cursor()
    c.execute("INSERT OR REPLACE INTO discord_users (sub, username, display, updated_at) "
              "VALUES (?, ?, ?, ?)",
              (sub_id, username or '', display or '',
               time.strftime('%Y-%m-%d %H:%M:%S')))
    conn.commit()
    conn.close()


def discord_handle(c, sub_id):
    """The Discord handle behind an identity, or None for a Google one."""
    if not sub_id or not str(sub_id).startswith('discord:'):
        return None
    c.execute("SELECT username, display FROM discord_users WHERE sub = ?", (sub_id,))
    row = c.fetchone()
    if not row:
        return None
    return row[1] or row[0] or None


def account_for_discord_id(c, discord_id):
    """The account a Discord identity should act as: the account it is bound
    to in Settings, or its own 'discord:<id>' identity when unbound. Used
    everywhere a Discord id becomes an account - the site's Discord sign-in
    and every bot endpoint - so a bound player is ONE account however they
    arrive."""
    did = str(discord_id or '').strip()
    if not did:
        return None
    c.execute("SELECT account_sub FROM discord_links WHERE discord_id = ?", (did,))
    row = c.fetchone()
    return (row[0] if row and row[0] else 'discord:' + did)


def discord_account(discord_id):
    """account_for_discord_id with its own short-lived connection, for the
    bot routes that resolve the id before they open a cursor of their own."""
    did = str(discord_id or '').strip()
    if not did:
        return None
    conn = db()
    try:
        return account_for_discord_id(conn.cursor(), did)
    finally:
        conn.close()


def linked_discord_for(c, account_sub):
    """The Discord {id, username, display} bound to this account, or None."""
    if not account_sub:
        return None
    c.execute("SELECT discord_id, username, display FROM discord_links "
              "WHERE account_sub = ?", (account_sub,))
    row = c.fetchone()
    if not row:
        return None
    return {"id": row[0], "username": row[1], "display": row[2]}


def pings_off(c, sub):
    """Whether this account has asked the bot not to @ them. Anything it
    cannot answer is False, because the quiet default here is to behave as
    the site always has."""
    if not sub:
        return False
    try:
        r = c.execute("SELECT COALESCE(no_ping, 0) FROM players WHERE google_sub = ?",
                      (sub,)).fetchone()
    except sqlite3.Error:
        return False
    return bool(r and r[0])


def set_pings(c, sub, on):
    """on=True means 'you may @ me'. Returns what it now is."""
    c.execute("UPDATE players SET no_ping = ? WHERE google_sub = ?",
              (0 if on else 1, sub))
    return bool(on)


def pingable_discord_id(c, sub):
    """The snowflake to @, or None - either because there is no Discord
    account behind this one, or because they have asked us not to. Every
    feed asks this instead of asking for the id directly, so 'do not ping
    me' cannot be honoured in one feed and forgotten in the next."""
    if pings_off(c, sub):
        return None
    return discord_id_for_owner(c, sub)


def discord_id_for_owner(c, owner_sub):
    """The Discord snowflake to @mention for an account, or None if it has no
    reachable Discord. Covers both ways an account can be on Discord: signed
    in with Discord directly (the sub itself is 'discord:<id>'), or a Google
    account that linked one (discord_links)."""
    if not owner_sub:
        return None
    if owner_sub.startswith("discord:"):
        return owner_sub.split(":", 1)[1]
    link = linked_discord_for(c, owner_sub)
    return link["id"] if link else None


@app.route('/auth/discord')
def auth_discord_start():
    """Send the player to Discord to approve a sign-in - or, with ?mode=link
    while already signed in, to BIND their Discord to the current account
    instead of switching to it."""
    if not (DISCORD_CLIENT_ID and not DISCORD_CLIENT_ID.startswith('DISCORD_CLIENT_ID')
            and DISCORD_CLIENT_SECRET):
        return redirect('/?signin=unavailable')
    from urllib.parse import urlencode
    link_mode = request.args.get('mode') == 'link'
    # Linking needs an account to bind to; bounce to the account page if not
    # signed in rather than silently turning it into a plain sign-in.
    if link_mode and not current_user():
        return redirect('/account')
    # The state is what stops someone handing you a link that quietly signs
    # you into *their* account: the value has to come back unchanged, and
    # only this browser's session knows what was sent.
    state = secrets.token_urlsafe(24)
    session.permanent = True
    session['discord_state'] = state
    session['discord_mode'] = 'link' if link_mode else 'signin'
    # Bind to whoever started the link, read back at the callback.
    session['discord_link_account'] = current_user() if link_mode else None
    # Where to go once Discord sends them back. An invite link needs this:
    # without it the player signs in and lands on the front page, with no
    # sign of the clan they were trying to join.
    session['discord_next'] = safe_next(request.args.get('next'))
    return redirect(DISCORD_AUTHORIZE_URL + '?' + urlencode({
        'client_id': DISCORD_CLIENT_ID,
        'redirect_uri': DISCORD_REDIRECT_URI,
        'response_type': 'code',
        'scope': 'identify',
        'state': state,
        'prompt': 'none',
    }))


@app.route('/auth/discord/callback')
def auth_discord_callback():
    """Finish the sign-in Discord just sent back.

    Only `identify` is asked for, so what comes back is an account id and a
    handle - no email, and nothing that could be used to contact anyone.
    """
    expected = session.pop('discord_state', None)
    given = request.args.get('state', '')
    if not expected or not given or not secrets.compare_digest(str(given), str(expected)):
        return redirect('/?signin=expired')
    if request.args.get('error'):
        # The player pressed Cancel on Discord's screen. Nothing to say.
        return redirect('/')
    code = request.args.get('code', '')
    if not code:
        return redirect('/?signin=failed')

    try:
        import requests as _rq
    except ImportError:
        return redirect('/?signin=unavailable')

    try:
        tok = _rq.post(
            DISCORD_API + '/oauth2/token',
            data={
                'client_id': DISCORD_CLIENT_ID,
                'client_secret': DISCORD_CLIENT_SECRET,
                'grant_type': 'authorization_code',
                'code': code,
                'redirect_uri': DISCORD_REDIRECT_URI,
            },
            headers={'Content-Type': 'application/x-www-form-urlencoded'},
            timeout=10,
        )
        if tok.status_code != 200:
            return redirect('/?signin=failed')
        access = (tok.json() or {}).get('access_token')
        if not access:
            return redirect('/?signin=failed')
        who = _rq.get(DISCORD_API + '/users/@me',
                      headers={'Authorization': 'Bearer ' + access}, timeout=10)
        if who.status_code != 200:
            return redirect('/?signin=failed')
        info = who.json() or {}
    except Exception:
        # A network hiccup between here and Discord is not the player's
        # problem to read a stack trace about.
        return redirect('/?signin=failed')

    discord_id = str(info.get('id') or '')
    if not discord_id:
        return redirect('/?signin=failed')

    username = info.get('username') or ''
    display = info.get('global_name') or info.get('username') or ''
    sub_id = 'discord:' + discord_id
    # Keep the handle current whichever path we take.
    remember_discord_user(sub_id, username, display)

    mode = session.pop('discord_mode', 'signin')
    link_account = session.pop('discord_link_account', None)

    if mode == 'link':
        # Bind this VERIFIED Discord to the account that started the link.
        # The session identity is left untouched: they stay on their account.
        if not link_account:
            return redirect('/account?link=failed')
        conn = db()
        c = conn.cursor()
        # Conflict 1: this Discord already has its own account here with a
        # record - two rating histories must not be merged silently.
        c.execute("SELECT 1 FROM players WHERE google_sub = ? LIMIT 1", (sub_id,))
        owns_account = c.fetchone() is not None
        # Conflict 2: already bound to a different account.
        c.execute("SELECT account_sub FROM discord_links WHERE discord_id = ?",
                  (discord_id,))
        bound = c.fetchone()
        if (owns_account and sub_id != link_account) or (bound and bound[0] != link_account):
            conn.close()
            return redirect('/account?link=taken')
        # Re-linking replaces the account's previous Discord.
        c.execute("DELETE FROM discord_links WHERE account_sub = ?", (link_account,))
        c.execute("INSERT INTO discord_links "
                  "(account_sub, discord_id, username, display, linked_at) "
                  "VALUES (?, ?, ?, ?, ?)",
                  (link_account, discord_id, username, display,
                   time.strftime('%Y-%m-%d %H:%M:%S')))
        conn.commit()
        conn.close()
        return redirect('/account?link=ok')

    # Sign-in: land on the BOUND account if this Discord is linked, otherwise
    # on its own identity. This is what lets "Sign in with Discord" reach a
    # Google account it was bound to - one account, never two.
    conn = db()
    c = conn.cursor()
    account = account_for_discord_id(c, discord_id)
    conn.close()
    session.permanent = True
    session['google_sub'] = account
    back = safe_next(session.pop('discord_next', None))
    return redirect(back or '/?signin=ok')


# The game's own default commander names, extracted from the
# starblast.io client on 17 Aug 2026 (44 names). Half the ships in any
# lobby wear one, so an account playing under one can never be told
# apart from strangers by name alone - Protection is therefore forced
# on while a default name is the play name: only checked-in matches
# count, which shields the account AND every stranger sharing the name.
DEFAULT_GAME_NAMES = {normalize_name(_n) for _n in (
    'Arkady Darell', 'Bel Riose', 'Cleon I', 'Dors Venabili',
    'Ebling Mis', 'Gaal Dornick', 'Hari Seldon', 'Hober Mallow',
    'Janov Pelorat', 'The Mule', 'Preem Palver', 'R.D. Olivaw',
    'R.G. Reventlov', 'Raych Seldon', 'Salvor Hardin', 'Wanda Seldon',
    'Yugo Amaryl', 'James T. Kirk', 'Leonard McCoy', 'Hikaru Sulu',
    'Montgomery Scott', 'Spock', 'Picard', 'Christine Chapel',
    'Nyota Uhura', 'Pavel Chekov', 'Ford', 'Zaphod', 'Marvin',
    'Anakin', 'Luke', 'Leia', 'Ackbar', 'Tarkin', 'Jabba', 'Rey',
    'Kylo', 'Han', 'Vader', 'D.A.R.Y.L.', 'HAL 9000',
    'Lyta Alexander', 'Stephen Franklin', 'Lennier')}


def is_default_game_name(name):
    """Whether this is one of the names the game hands out for free."""
    return normalize_name(str(name or '')) in DEFAULT_GAME_NAMES


# How many ships sharing one name before a match is worth a human look.
# Measured over 1077 matches: at 5+ the swarmed team lost every single time,
# which is what being flooded looks like. 3-4 also catches ordinary noise,
# so that range is recorded but not flagged.
FLOOD_SIGNIFICANT = 5


def roster_flood(rosters):
    """Live flood reading from the current rosters: per team, the name with
    the most ships flying under it right now, ignoring the game's own default
    nicknames. Returns ({team: {"name":.., "n":..}}, worst_n)."""
    out = {}
    worst = 0
    for team, names in (rosters or {}).items():
        if not isinstance(names, (list, tuple)) or not names:
            continue
        tally = {}
        for nm in names:
            nm = str(nm)
            if is_default_game_name(nm) or not normalize_name(nm):
                continue
            tally[nm] = tally.get(nm, 0) + 1
        if not tally:
            continue
        top = max(tally, key=lambda k: tally[k])
        if tally[top] >= 2:
            out[str(team)] = {"name": top[:64], "n": tally[top]}
            worst = max(worst, tally[top])
    return out, worst


def live_flood_count():
    """How many lobbies are being flooded right now. Cheap enough to answer
    on every /me, and it is what makes the alert reach the owner wherever
    they are on the site."""
    try:
        conn = live_db()
        rows = conn.execute("SELECT payload FROM live WHERE updated > ?",
                            (time.time() - LIVE_STALE_SECONDS,)).fetchall()
        conn.close()
    except Exception:
        return 0
    n = 0
    for (payload,) in rows:
        try:
            if (json.loads(payload) or {}).get("flood_max", 0) >= FLOOD_SIGNIFICANT:
                n += 1
        except (TypeError, ValueError):
            pass
    return n


def queue_flood_alert(kind, sys_id, detail, worst, lobby_name=None,
                      region=None, match_id=None, dedupe_seconds=1800):
    """Put a flood in front of the owner, once. A live flood re-alerting
    every ten seconds would be noise, so the same lobby stays quiet for
    `dedupe_seconds` after an alert of the same kind."""
    try:
        conn = db(timeout=4)
        c = conn.cursor()
        if dedupe_seconds:
            c.execute("SELECT 1 FROM flood_alerts WHERE kind = ? AND sys_id = ? "
                      "AND created_at > datetime('now', ?) LIMIT 1",
                      (kind, sys_id, '-%d seconds' % int(dedupe_seconds)))
            if c.fetchone():
                conn.close()
                return False
        c.execute("INSERT INTO flood_alerts (kind, sys_id, match_id, lobby_name, "
                  "region, worst, detail, created_at, delivered) "
                  "VALUES (?,?,?,?,?,?,?,?,0)",
                  (kind, sys_id, match_id, lobby_name, region, int(worst or 0),
                   json.dumps(detail, ensure_ascii=False),
                   time.strftime('%Y-%m-%d %H:%M:%S')))
        conn.commit()
        conn.close()
        return True
    except sqlite3.Error:
        return False


def summarize_flood(dup_names):
    """Turn the watcher's raw duplicate-ship counts into stored evidence.

    `dup_names` is {team: {name: most ships seen sharing that name at once}}.
    The game's own default nicknames are dropped: everyone who never typed a
    name is 'VADER', so duplicates of those are ordinary rather than a flood.
    Returns (json_or_None, worst_count) - the number is what makes a match
    findable later; the detail is what makes it assessable.
    """
    if not isinstance(dup_names, dict):
        return None, 0
    kept = {}
    worst = 0
    for team, names in dup_names.items():
        if not isinstance(names, dict):
            continue
        for nm, count in names.items():
            try:
                count = int(count)
            except (TypeError, ValueError):
                continue
            if count < 2 or is_default_game_name(nm) or not normalize_name(nm):
                continue
            kept.setdefault(str(team), {})[str(nm)[:64]] = count
            worst = max(worst, count)
    if not kept:
        return None, 0
    return json.dumps(kept, ensure_ascii=False), worst


def perform_set_game_name(c, sub_id, raw_name):
    """Set (or clear) the name this account currently plays under.

    Shared by the website and the bot so both enforce the same rules.
    Does NOT commit - the caller owns the transaction.
    """
    name = str(raw_name or '').strip()[:32]
    who = account_name_for(c, sub_id)
    if not who:
        return 400, {"ok": False, "no_name": True,
                     "message": "Set your account name first - that is the name your "
                                "matches are recorded under."}
    if name and is_blocked_word(name):
        return 400, {"ok": False,
                     "message": "That name isn't allowed. Please choose another."}
    c.execute("UPDATE players SET game_name = ? WHERE name = ?", (name or None, who))
    _PLAY_CACHE["ts"] = 0.0                       # results follow the new name at once
    try:
        c.execute("INSERT INTO play_name_log (sub, name, at) VALUES (?,?,?)",
                  (sub_id, name or '', time.strftime('%Y-%m-%d %H:%M:%S', time.gmtime())))
    except sqlite3.Error:
        pass
    if not name:
        return 200, {"ok": True, "game_name": "",
                     "message": "Cleared. Your profile no longer says what you play as."}
    if is_default_game_name(name):
        c.execute("UPDATE players SET strict_mode = 1 WHERE name = ?", (who,))
        return 200, {"ok": True, "game_name": name, "protection_forced": True,
                     "message": f"Noted - you play as '{name}'. That is one of the "
                                f"game's default names, which many players wear at "
                                f"once - so Protection is now ON automatically: only "
                                f"matches you check into count, and it stays on "
                                f"while you use a default name."}
    if normalize_name(name) != normalize_name(who):
        return 200, {"ok": True, "game_name": name, "differs": True,
                     "message": f"Noted - you play as '{name}'. That is not your account "
                                f"name, so a game under it only counts if you press "
                                f"Check in & play here first - whether Protection is on "
                                f"or off. It then appears under '{who}'."}
    return 200, {"ok": True, "game_name": name,
                 "message": f"Noted - you play as '{name}', your account name. Your games "
                            f"count as usual; with Protection on, only the ones you "
                            f"check into."}


@app.route('/account/gamename', methods=['POST'])
def set_game_name():
    """Set the name this account currently plays under in Starblast.

    Free to change as often as you like, because it is a statement about
    what to expect rather than a claim on anything: it never routes a
    result by itself. Pressing Play is what ties a match to you, and that
    works whatever you are called at the time. Sending an empty value
    clears it.
    """
    sub_id = current_user()
    if not sub_id:
        return jsonify({"message": "Sign in first."}), 401
    conn = db()
    c = conn.cursor()
    status, payload = perform_set_game_name(c, sub_id, (request.json or {}).get('name', ''))
    if status == 200:
        conn.commit()
    conn.close()
    return jsonify(payload), status


def board_name_readings(name, clan):
    """Every plain-letter reading of a leaderboard row a person might type.

    The whole name, and the name without its clan tag - somebody wearing a
    tag types their own name, not the tag as well.
    """
    out = set()
    whole = clean_clan_tag(name)
    if whole:
        out.add(whole)
    if not clan:
        return out
    bare = clean_clan_tag(display_name(name, clan))
    if bare:
        out.add(bare)
    key = clean_clan_tag(clan)
    if key and len(whole) > len(key):
        if whole.startswith(key):
            out.add(whole[len(key):])
        if whole.endswith(key):
            out.add(whole[:-len(key)])
    return out


def similar_board_name(c, name, sub_id):
    """An unclaimed row that READS the same as this name, or None.

    The trap this closes, hit twice on 14 Aug: a player sets a plain
    account name while playing under a styled version of it. Their matches
    land on the styled row, which they do not own, and their own row sits
    at 0-0 for ever with nothing to say why. The fold is the one the search
    box already uses, so KASANE TETO and the styled form read alike.

    Only rows with a record and no owner are offered. An empty row is
    nothing to claim, and a row that belongs to somebody else is not theirs
    to take. Where several read the same, the busiest one wins.
    """
    want = clean_clan_tag(name)
    if len(want) < 2:
        return None
    mine = normalize_name(name)
    c.execute("SELECT name, clan, COALESCE(wins, 0), COALESCE(losses, 0), norm_name "
              "FROM players WHERE (google_sub IS NULL OR google_sub = '') "
              "AND COALESCE(wins, 0) + COALESCE(losses, 0) > 0")
    best = None
    for row_name, clan, wins, losses, norm in c.fetchall():
        if norm == mine:
            continue
        if want not in board_name_readings(row_name, clan):
            continue
        if best is None or wins + losses > best[1] + best[2]:
            best = (row_name, wins, losses)
    return best


@app.route('/account/name', methods=['POST'])
def set_account_name():
    """Set or change the name this account appears under.

    This replaces name registration. The name is a label for the account,
    not a claim on anyone else's results - taking over an existing row is
    what /claim is for, and that needs evidence you actually played as it.
    """
    sub_id = current_user()
    if not sub_id:
        return jsonify({"message": "Sign in first."}), 401
    name = str((request.json or {}).get('name', '')).strip()
    anyway = bool((request.json or {}).get('anyway'))
    if not is_valid_name_format(name):
        return jsonify({"message": "That name cannot be used. Try another."}), 400
    if is_blocked_word(name):
        return jsonify({"message": "That name isn't allowed. Please choose another."}), 400
    if is_default_name(name):
        return jsonify({"message": "That is one of Starblast's default names - too many "
                                   "players share it. Pick a name of your own."}), 400

    conn = db()
    c = conn.cursor()
    # A clan tag in an account name is the tag's job done twice: it comes
    # from the clan and shows beside the name wherever the name is. Asked,
    # not refused - a name can genuinely start with what a tag folds to.
    if not bool((request.json or {}).get('keep_tag')):
        carried = tag_carried(c, name)
        if carried:
            conn.close()
            return jsonify({
                "message": f"'{name}' carries the {carried['shown']} clan tag. Your account "
                           f"name is just you - the tag comes from joining the clan and "
                           f"shows beside your name everywhere. Save it as "
                           f"'{carried['bare']}' instead?",
                "tag_prompt": True, "tag": carried["tag"], "shown": carried["shown"],
                "bare": carried["bare"]}), 409
    c.execute("BEGIN IMMEDIATE")
    key = normalize_name(name)
    c.execute("SELECT google_sub FROM players WHERE norm_name = ?", (key,))
    taken = c.fetchone()
    if taken and taken[0] and taken[0] != sub_id:
        conn.close()
        return jsonify({"message": f"'{name}' already belongs to another account."}), 403
    if taken and not taken[0]:
        conn.close()
        return jsonify({"message": f"'{name}' is already on the leaderboard as an "
                                   f"unverified player. Use Claim to take it over.",
                        "claim_name": name}), 409

    # Already one of this account's own rows - including the case where it
    # is the name they are currently using. Nothing to move, and trying to
    # would rename some other row on top of it.
    if taken and taken[0] == sub_id:
        c.execute("SELECT name FROM players WHERE norm_name = ?", (key,))
        row = c.fetchone()
        conn.commit()
        conn.close()
        return jsonify({"message": f"Your account name is '{row[0] if row else name}'."}), 200

    # A row that READS like the name they typed. Their matches are landing
    # there and not here, and until now nothing said so - two players spent
    # the day at 0-0 while a styled version of their name collected the
    # record. Refusing outright would trap anyone whose name genuinely
    # reads like somebody else's, so this is a question, not a wall.
    if not anyway:
        near = similar_board_name(c, name, sub_id)
        if near:
            conn.close()
            return jsonify({
                "message": f"'{near[0]}' is already on the leaderboard and reads the same "
                           f"as '{name}' - it has a {near[1]}-{near[2]} record. If that is "
                           f"you, claim it: that row is where your matches are landing.",
                "claim_name": near[0],
                "suggest_claim": True,
            }), 409

    # An account is meant to hold one name, but the grandfathered ones hold
    # two, and updating on google_sub moved BOTH rows to the same
    # norm_name - which the unique index refused, failing every save. Pick
    # one row and rename that, keyed on its own primary key. The one with a
    # record is the one that matters, and the tie-break keeps it stable
    # rather than leaving it to whatever order the table returns.
    c.execute("SELECT name FROM players WHERE google_sub = ? "
              "ORDER BY (COALESCE(wins, 0) + COALESCE(losses, 0)) DESC, name LIMIT 1",
              (sub_id,))
    mine = c.fetchone()
    if mine:
        c.execute("SELECT COALESCE(name_changes, 0) FROM players WHERE name = ?", (mine[0],))
        used = (c.fetchone() or [0])[0]
        if used >= MAX_ACCOUNT_NAME_CHANGES:
            conn.close()
            return jsonify({"message": f"Your account name has already been changed "
                                       f"{used} time{'' if used == 1 else 's'}, which is the "
                                       f"limit - it is how other players recognise you on the "
                                       f"board. The name you PLAY under can still be changed "
                                       f"whenever you like."}), 403
        c.execute("UPDATE players SET name_changes = COALESCE(name_changes, 0) + 1 "
                  "WHERE name = ?", (mine[0],))
        # The record is keyed by norm_name in a dozen tables and follows the
        # row only if carried - a rename used to orphan every match the
        # account had played (fafa lost 43 matches to this, fixed 8.5.6).
        rekey_identity(c, mine[0], name)
        # The play name defaults to the account name, and follows it while
        # it has never been set to anything else - most people play under
        # the name they signed up with, and making them type it twice to
        # say so is busywork.
        c.execute("UPDATE players SET game_name = ? WHERE name = ? AND "
                  "(game_name IS NULL OR game_name = '' OR game_name = ?)",
                  (name, name, mine[0]))
        _PLAY_CACHE["ts"] = 0.0
        left = MAX_ACCOUNT_NAME_CHANGES - (used + 1)
        msg = (f"Your account name is now '{name}'. "
               + (f"You can change it {left} more time." if left
                  else "That was your last change."))
    else:
        c.execute("INSERT INTO players (name, elo, wins, losses, norm_name, google_sub) "
                  "VALUES (?, ?, 0, 0, ?, ?)", (name, STARTING_ELO, key, sub_id))
        msg = f"Your account name is '{name}'."
    landed = join_own_clans(c, sub_id)
    if landed:
        msg += f" You are now on the {landed[0][0]} roster."
    conn.commit()
    conn.close()
    return jsonify({"message": msg}), 200


# A sandbox account is given a plausible rating so that the parts of the site
# which read one have something to read. These bound what can be asked for:
# far enough apart to see the site at both ends, not so far as to be nonsense.
SANDBOX_ELO_MIN, SANDBOX_ELO_MAX = 100, 4000
SANDBOX_ELO_DEFAULT = 1400
SANDBOX_GAMES_MAX = 999
SANDBOX_GAMES_DEFAULT = 20
SANDBOX_NAME = "SANDBOX"


def _wipe_sandbox(c, sub=None):
    """Everything one test account owns. It is never a real person, so this
    is always safe - and it runs on the way in AND on the way out, so a test
    account with a rating never outlives the test that made it. Each tester
    key has its own account, so wiping one never touches another's."""
    SANDBOX_SUB = sub or globals()["SANDBOX_SUB"]
    # Its gems and purchases too, or a later sandbox under the same name
    # inherits ships it never bought this time round.
    try:
        c.execute("DELETE FROM gem_ledger WHERE owner_kind = 'player' AND owner IN "
                  "(SELECT norm_name FROM players WHERE google_sub = ?)", (SANDBOX_SUB,))
    except sqlite3.Error:
        pass
    c.execute("DELETE FROM free_agents WHERE norm_name IN "
              "(SELECT norm_name FROM players WHERE google_sub = ?)", (SANDBOX_SUB,))
    c.execute("DELETE FROM players WHERE google_sub = ?", (SANDBOX_SUB,))
    c.execute("DELETE FROM claim_requests WHERE google_sub = ?", (SANDBOX_SUB,))
    # Anyone it asked to be friends with, so a real player is not left with a
    # request from an account that no longer exists.
    for tb, col in (("friends", "a"), ("friends", "b")):
        try:
            c.execute("DELETE FROM %s WHERE %s IN (SELECT norm_name FROM players "
                      "WHERE google_sub = ?)" % (tb, col), (SANDBOX_SUB,))
        except sqlite3.Error:
            pass
    try:
        c.execute("DELETE FROM friends WHERE requester LIKE ?", (SANDBOX_NAME + '%',))
    except sqlite3.Error:
        pass


def _sandbox_free_name(c):
    """A name for the sandbox that no real player already holds. The row has
    to satisfy the same unique index every player does, and the test must not
    fail because somebody out there is called SANDBOX."""
    for n in range(0, 50):
        want = SANDBOX_NAME if n == 0 else "%s%d" % (SANDBOX_NAME, n)
        if not c.execute("SELECT 1 FROM players WHERE norm_name = ? LIMIT 1",
                         (normalize_name(want),)).fetchone():
            return want
    return "%s%d" % (SANDBOX_NAME, int(time.time()) % 100000)


def _enter_sandbox(c, body, sub=None):
    """Wipe this test account and, in account mode, give it a name, a rating
    and - optionally - some gems so the shop can be tried. Returns
    (mode, name)."""
    SANDBOX_SUB = sub or globals()["SANDBOX_SUB"]
    mode = 'account' if str(body.get('mode') or 'new') == 'account' else 'new'

    def _num(key, default, lo, hi):
        try:
            return max(lo, min(hi, int(body.get(key, default))))
        except (TypeError, ValueError):
            return default

    _wipe_sandbox(c, SANDBOX_SUB)
    name = None
    if mode == 'account':
        elo = _num('elo', SANDBOX_ELO_DEFAULT, SANDBOX_ELO_MIN, SANDBOX_ELO_MAX)
        games = _num('games', SANDBOX_GAMES_DEFAULT, 0, SANDBOX_GAMES_MAX)
        gems = _num('gems', 0, 0, 1000000)
        wins = int(round(games * 0.6))
        name = _sandbox_free_name(c)
        c.execute("INSERT INTO players (name, norm_name, elo, wins, losses, "
                  "google_sub) VALUES (?, ?, ?, ?, ?, ?)",
                  (name, normalize_name(name), float(elo), wins, games - wins,
                   SANDBOX_SUB))
        if gems:
            # Through the ledger like everything else; wiped with the rest.
            gem_grant(c, "player", normalize_name(name), gems, "sandbox", "v1")
        session['dev_elo'] = elo
    else:
        session.pop('dev_elo', None)
    session['dev_mode'] = mode
    return mode, name


@app.route('/dev/preview', methods=['GET', 'POST'])
def dev_preview():
    """A preview-key session: the sandbox account with the unreleased
    surfaces visible, and nothing an owner can do. GET is a bare form so the
    key travels in a POST body, never a URL. 404 unless some key can open
    it; a wrong key is also a 404, so the route never confirms it exists."""
    if not preview_any_live():
        abort(404)
    if request.method == 'GET':
        return render_template('preview_enter.html', page='preview',
                               version=APP_VERSION,
                               elo=SANDBOX_ELO_DEFAULT, gems=30000), 200
    body = request.get_json(silent=True) or request.form or {}
    given = str(body.get('key') or '')
    conn = db()
    c = conn.cursor()
    kid, kind = preview_key_match(c, given)
    master = bool(PREVIEW_KEY and given and hmac.compare_digest(given, PREVIEW_KEY))
    if not kid and not master:
        conn.close()
        abort(404)
    if kid and kind == "access":
        # An access key does not move anybody anywhere: it says "this person
        # may see the unreleased half of the site, as themselves". Everything
        # they then do is real - real gems, real claims, real events.
        if not current_user():
            conn.close()
            return render_template('preview_enter.html', page='preview', version=APP_VERSION,
                                   elo=SANDBOX_ELO_DEFAULT, gems=30000,
                                   need_signin=True), 200
        c.execute("UPDATE preview_keys SET uses = COALESCE(uses, 0) + 1, last_used_at = ? "
                  "WHERE id = ?", (_stamp(), kid))
        # Test money, so they can try the whole shop rather than window-shop it.
        me = my_player(c)
        if me:
            gem_grant(c, "player", me[1], PREVIEW_CREDIT, "preview-credit", "key%d" % kid)
        conn.commit()
        conn.close()
        session['preview'] = True
        session['preview_key'] = kid
        session['preview_kind'] = 'access'
        return redirect('/')
    # Each tester key has its own test account, so two testers at once do not
    # wipe each other's ships, gems and clan.
    tester_sub = SANDBOX_SUB if master else ("%s:%d" % (SANDBOX_SUB, kid))
    mode, name = _enter_sandbox(c, {"mode": "account",
                                    "elo": body.get("elo", SANDBOX_ELO_DEFAULT),
                                    "games": body.get("games", SANDBOX_GAMES_DEFAULT),
                                    "gems": body.get("gems", 30000)}, tester_sub)
    if kid:
        c.execute("UPDATE preview_keys SET uses = COALESCE(uses, 0) + 1, last_used_at = ? "
                  "WHERE id = ?", (_stamp(), kid))
    conn.commit()
    conn.close()
    session.pop('dev_real_owner', None)      # never an owner, whatever was there
    session['google_sub'] = tester_sub
    session['preview'] = True
    session['preview_key'] = kid
    session['preview_kind'] = 'sandbox'
    # A test account has no history, so it has reached no tier, so the hangar
    # would be shut to it. A sandbox is for looking at everything: it starts
    # at the top tier you can climb to, and the bar's picker moves it.
    session['preview_level'] = ranks.TOP_CLIMBABLE
    if request.is_json:
        return jsonify({"ok": True, "name": name}), 200
    return redirect('/')


@app.route('/dev/actas', methods=['POST'])
def dev_actas():
    """Owner steps into the sandbox account. Verified against the REAL
    current user, and the real id is stashed so /dev/restore can only ever
    hand it back.

    mode 'new' (the default) is a nameless newcomer - the site as somebody
    arriving for the first time sees it. mode 'account' is a settled player:
    a name and a rating you pick, so the surfaces that only exist once you
    have a record can be looked at, and looked at at a chosen standard.
    """
    if current_user() not in OWNER_SUBS:
        return jsonify({"error": "Not allowed."}), 403
    body = request.get_json(silent=True) or {}
    conn = db()
    c = conn.cursor()
    mode, name = _enter_sandbox(c, body)
    conn.commit()
    conn.close()
    session['dev_real_owner'] = current_user()
    session.pop('preview', None)
    session['google_sub'] = SANDBOX_SUB
    return jsonify({"ok": True, "mode": mode, "name": name}), 200


@app.route('/api/my/pings', methods=['GET', 'POST'])
def my_pings():
    """Whether the Discord bot may @ you. GET reads it, POST sets it.

    It does not silence the bot - results, rank-ups and the rest still say
    what happened, and still name you. It stops them notifying you."""
    sub = current_user()
    if not sub:
        return jsonify({"ok": False, "message": "Sign in first."}), 401
    conn = db()
    c = conn.cursor()
    if request.method == 'GET':
        on = not pings_off(c, sub)
        linked = bool(discord_id_for_owner(c, sub))
        conn.close()
        return jsonify({"ok": True, "pings": on, "discord": linked}), 200
    want = bool((request.get_json(silent=True) or {}).get("pings"))
    set_pings(c, sub, want)
    conn.commit()
    conn.close()
    return jsonify({"ok": True, "pings": want,
                    "message": ("The bot will @ you again." if want
                                else "The bot will name you without the ping.")}), 200


@app.route('/api/bot/pings', methods=['GET', 'POST'])
def bot_pings():
    """The same switch, for the bot's own command. Keyed by the Discord id,
    which is what a command knows about the person who ran it."""
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401
    if request.method == 'GET':
        did = str(request.args.get('discord_id', '')).strip()
        body = {}
    else:
        body = request.get_json(silent=True) or {}
        did = str(body.get('discord_id', '')).strip()
    if not did:
        return jsonify({"error": "Which account?"}), 400
    conn = db()
    c = conn.cursor()
    sub = account_for_discord_id(c, did)
    has_row = bool(sub and c.execute("SELECT 1 FROM players WHERE google_sub = ?",
                                     (sub,)).fetchone())
    if not has_row:
        conn.close()
        return jsonify({"ok": False, "linked": False,
                        "message": "That Discord has no account on the site yet."}), 200
    if request.method == 'POST' and 'pings' in body:
        set_pings(c, sub, bool(body.get('pings')))
        conn.commit()
    on = not pings_off(c, sub)
    conn.close()
    return jsonify({"ok": True, "linked": True, "pings": on}), 200


@app.route('/dev/level', methods=['POST'])
def dev_level():
    """A tester chooses the tier their session looks at the site from. Only
    inside a preview, only their own account, and 0 puts it back to whatever
    they have actually earned."""
    if not preview_session_ok() and current_user() not in OWNER_SUBS:
        abort(404)
    try:
        lvl = int((request.get_json(silent=True) or {}).get("level") or 0)
    except (TypeError, ValueError):
        lvl = 0
    if lvl and not ranks.RANK_BY_LEVEL.get(lvl):
        return jsonify({"ok": False, "message": "No such tier."}), 400
    if lvl:
        session["preview_level"] = lvl
    else:
        session.pop("preview_level", None)
    r = ranks.RANK_BY_LEVEL.get(lvl)
    return jsonify({"ok": True, "level": lvl,
                    "message": ("Looking at the site as %s." % r["name"]) if r
                               else "Back to the tier you have earned."}), 200


@app.route('/dev/restore', methods=['POST'])
def dev_restore():
    """Return to the real owner account. Safe by construction: it only
    restores the id a prior owner-verified /dev/actas stashed - and it takes
    the test account back out, so a row with a rating never outlives the
    test that created it."""
    real = session.pop('dev_real_owner', None)
    was_preview = bool(session.pop('preview', None))
    was_access = session.pop('preview_kind', None) == 'access'
    mine = session.get('google_sub') or SANDBOX_SUB
    session.pop('preview_key', None)
    session.pop('dev_mode', None)
    session.pop('dev_elo', None)
    session.pop('preview_level', None)
    # An access session never moved anybody anywhere: it only lifted the
    # curtain on their own account. Putting it back is exactly that and
    # nothing else - no wipe (there is no test account to wipe) and no
    # sign-out (it is their real one).
    if was_access:
        return jsonify({"ok": True}), 200
    if real or was_preview:
        conn = db()
        c = conn.cursor()
        # Only this tester's account, never everyone's.
        _wipe_sandbox(c, mine if str(mine).startswith(SANDBOX_SUB) else SANDBOX_SUB)
        conn.commit()
        conn.close()
    if real:
        session['google_sub'] = real
    elif was_preview:
        session.clear()                      # a preview session has nothing to go back to
    return jsonify({"ok": True}), 200


@app.route('/logout', methods=['POST'])
def logout():
    session.clear()
    return jsonify({"message": "Signed out."}), 200


def current_lang():
    """The language for this request.

    ?lang= wins so a link can carry it, then the cookie, then whatever the
    browser asks for in Accept-Language. English if none of that fits.
    """
    asked = str(request.args.get('lang', '')).strip().lower()
    if asked in i18n.LANG_KEYS:
        return asked
    cookie = str(request.cookies.get('lang', '')).strip().lower()
    if cookie in i18n.LANG_KEYS:
        return cookie
    for chunk in str(request.headers.get('Accept-Language', '')).split(','):
        code = chunk.split(';')[0].strip().lower()[:2]
        if code in i18n.LANG_KEYS:
            return code
    return i18n.DEFAULT_LANG


@app.context_processor
def inject_lang():
    """t(), the language list, and whether to show the Your clan tab."""
    lang = current_lang()
    mine = None
    sub_id = current_user()
    if sub_id:
        # One indexed look-up per page for signed-in visitors. The nav is
        # rendered on every page, so this cannot be any heavier than that.
        try:
            conn = db()
            c = conn.cursor()
            tags = clan_admin_tags(c, sub_id)
            if not tags:
                # A member's clan counts too (9.31.0): the tab is for
                # everyone on a roster, not only the people who run it.
                c.execute("SELECT clan FROM players WHERE google_sub = ? AND clan IS NOT NULL "
                          "AND clan != '' LIMIT 1", (sub_id,))
                _m = c.fetchone()
                if _m and _m[0]:
                    tags = [_m[0]]
            if tags:
                mine = {"tag": tags[0], "display": clan_display(c, tags[0]),
                        "role": clan_role(c, sub_id, tags[0]), "count": len(tags)}
            conn.close()
        except Exception:
            mine = None
    return {"t": lambda text: i18n.translate(text, lang),
            "lang": lang, "langs": i18n.LANGS, "my_clan": mine}


@app.route('/lang/<code>')
def set_lang(code):
    """Remember a language and go back where you were."""
    code = str(code or '').lower()
    if code not in i18n.LANG_KEYS:
        return redirect('/')
    back = request.referrer or '/'
    # Only ever back into this site: a referrer is attacker-controllable
    # and an open redirect is not worth a convenience.
    if not back.startswith(request.host_url):
        back = '/'
    resp = redirect(back)
    resp.set_cookie('lang', code, max_age=60 * 60 * 24 * 365,
                    samesite='Lax', path='/')
    return resp


def notice_invites(c, sub_id):
    """Clan invitations waiting on this account's names. Actionable,
    so they count on the badge until actually answered."""
    if not sub_id:
        return []
    c.execute("SELECT i.id, i.clan, i.name, COALESCE(i.gems, 0) FROM clan_invites i "
              "JOIN players p ON p.name = i.name "
              "WHERE i.status = 'pending' AND i.direction = 'invite' "
              "AND p.google_sub = ? ORDER BY i.id", (sub_id,))
    return [{"id": r[0], "clan": r[1], "name": r[2], "gems": r[3] or 0} for r in c.fetchall()]


def notice_updates(c, sub_id):
    """Decisions this account has not seen yet - claims, clan
    applications and leader requests, wherever they were decided.
    Withdrawn claims are the account's own doing and never listed."""
    if not sub_id:
        return []
    out = []
    c.execute("SELECT id, name, status FROM claim_requests "
              "WHERE google_sub = ? AND status IN ('approved', 'declined') "
              "AND COALESCE(seen, 0) = 0 ORDER BY id", (sub_id,))
    for r in c.fetchall():
        out.append({"kind": "claim", "id": r[0], "text":
                    ("Your claim on '%s' was approved - the name is yours." % r[1])
                    if r[2] == 'approved' else
                    ("Your claim on '%s' was declined." % r[1])})
    c.execute("SELECT id, clan, name, status FROM clan_invites "
              "WHERE invited_by = ? AND direction = 'application' "
              "AND status IN ('approved', 'declined') "
              "AND COALESCE(seen, 0) = 0 ORDER BY id", (sub_id,))
    for r in c.fetchall():
        out.append({"kind": "application", "id": r[0], "text":
                    ("%s accepted '%s' - you are in." % (r[1], r[2]))
                    if r[3] == 'approved' else
                    ("%s declined '%s'." % (r[1], r[2]))})
    c.execute("SELECT id, tag, status, COALESCE(kind, 'leader') "
              "FROM clan_leader_requests "
              "WHERE google_sub = ? AND status IN ('approved', 'denied') "
              "AND COALESCE(seen, 0) = 0 ORDER BY id", (sub_id,))
    for r in c.fetchall():
        if r[3] == 'tag':
            out.append({"kind": "leader", "id": r[0], "text":
                        ("Your request for the tag '%s' was approved - claim it "
                         "on the Clans page." % (r[1] or ''))
                        if r[2] == 'approved' else
                        ("Your request for the tag '%s' was denied." % (r[1] or ''))})
        else:
            out.append({"kind": "leader", "id": r[0], "text":
                        "Your request to run a clan was approved - create it on the Clans page."
                        if r[2] == 'approved' else
                        "Your request to run a clan was denied."})
    return out


def notice_result_count(c, sub_id):
    """Match results recorded since this account last opened its page.
    Counts across every name the account owns, and the account page
    clears the same set, so the badge can never get stuck."""
    if not sub_id:
        return 0
    c.execute("SELECT COUNT(*) FROM match_players mp "
              "JOIN players p ON p.norm_name = mp.norm_name "
              "WHERE p.google_sub = ? AND COALESCE(mp.seen, 0) = 0", (sub_id,))
    return c.fetchone()[0]


@app.route('/me')
def me():
    """Who is signed in, and which names they own."""
    sub_id = current_user()
    if not sub_id:
        return jsonify({"logged_in": False, "names": []}), 200
    conn = db()
    c = conn.cursor()
    c.execute("SELECT name FROM players WHERE google_sub = ? ORDER BY name", (sub_id,))
    names = [row[0] for row in c.fetchall()]
    # The name results are recorded under, and the clan it is in. The clan
    # page needs both to know whether to offer applying: you cannot apply
    # without a name, and you cannot apply while already in a clan.
    account_name = account_name_for(c, sub_id)
    my_clan = None
    if account_name:
        c.execute("SELECT clan FROM players WHERE name = ?", (account_name,))
        my_clan = (c.fetchone() or [None])[0]

    # Which provider signed you in, so the header can say so. The Google
    # flow labels itself from the browser; Discord has to be told from here
    # because nothing about that sign-in touches the page.
    provider = 'discord' if str(sub_id).startswith('discord:') else 'google'
    label = discord_handle(c, sub_id) if provider == 'discord' else None

    # Which match this account is currently checked into, if any. Without
    # this the Play page cannot show that you are already checked in - and
    # since checking into a second lobby silently cancels the first, an
    # invisible check-in is one you can lose by clicking again.
    checkin = None
    if names:
        c.execute("SELECT sys_id, created_at FROM checkins WHERE sub = ? "
                  "AND created_at > datetime('now', ?) ORDER BY id DESC LIMIT 1",
                  (sub_id, f'-{CHECKIN_VALID_SECONDS} seconds'))
        row = c.fetchone()
        if row:
            checkin = {"sys_id": row[0], "at": row[1]}
    conn.close()
    # Its own short-lived connection on purpose: the one above is already
    # closed by this point, and reaching for it threw
    # "Cannot operate on a closed database" on EVERY /me call - which the
    # pages read to decide whether you are signed in, so a working sign-in
    # looked like being signed out the moment you changed tab.
    _gn = None
    try:
        _c2 = db()
        _gn = _c2.execute("SELECT game_name FROM players WHERE google_sub = ? "
                          "AND game_name IS NOT NULL LIMIT 1", (sub_id,)).fetchone()
        _c2.close()
    except sqlite3.Error:
        pass
    stats = None
    if account_name:
        try:
            _c3 = db()
            _row = _c3.execute("SELECT elo, COALESCE(wins,0), COALESCE(losses,0) "
                               "FROM players WHERE norm_name = ?",
                               (normalize_name(account_name),)).fetchone()
            if _row:
                _rank = _c3.execute("SELECT COUNT(*) + 1 FROM players WHERE elo > ?",
                                    (_row[0],)).fetchone()[0]
                stats = {"elo": round(_row[0], 2), "rank": _rank,
                         "wins": _row[1], "losses": _row[2]}
            _c3.close()
        except sqlite3.Error:
            pass
    # Own short-lived connection, same as stats above - the main one
    # is long closed and reusing it is the recurring closed-DB trap.
    admin_of = []
    notices = {"invites": 0, "updates": 0, "results": 0, "total": 0}
    try:
        _c4 = db()
        _cc = _c4.cursor()
        admin_of = clan_admin_tags(_cc, sub_id)
        _inv = len(notice_invites(_cc, sub_id))
        _upd = len(notice_updates(_cc, sub_id))
        _res = notice_result_count(_cc, sub_id)
        _c4.close()
        notices = {"invites": _inv, "updates": _upd, "results": _res,
                   "total": _inv + _upd + _res}
    except sqlite3.Error:
        pass
    # The menu entries this account may use. Sent from here rather than written
    # into every page: a link hidden with CSS is still a link in view-source, and
    # so is its label sitting in an inline script.
    _owner_now = is_site_owner()
    _custom_now = _user_meets_custom_gate(sub_id)
    _nav = []
    if _custom_now or _owner_now:
        _nav.append({"t": "a", "href": "/customgame", "id": "customTab",
                     "label": "Warden lobby", "badge": "NEW", "colour": "#ff7b53"})
    if _owner_now:
        _nav.append({"t": "a", "href": "/mymaps", "id": "mapsTab",
                     "label": "My Maps", "badge": "NEW", "colour": "#ff7b53"})
        _nav.append({"t": "s", "id": "ownerSec", "label": "Owner"})
        _nav.append({"t": "a", "href": "/flood", "id": "floodTab", "label": "Flood review"})
        _nav.append({"t": "a", "href": "/dev/merges", "id": "mergesTab", "label": "Merge requests"})
    # Unreleased: the gem economy. Sent only while it is visible to this
    # account, so a visitor's page never learns the entry exists.
    _gems = None
    if gems_visible() and account_name:
        _nav.append({"t": "a", "href": "/achievements", "id": "achTab",
                     "label": "Achievements", "badge": "NEW", "colour": "#8ef3ff"})
        _nav.append({"t": "a", "href": "/shop", "id": "shopTab", "top": True,
                     "label": "Shop", "badge": "NEW", "colour": "#8ef3ff"})
        _nav.append({"t": "a", "href": "/agents", "id": "agentsTab",
                     "label": "Free agents", "badge": "NEW", "colour": "#8ef3ff"})
        _nav.append({"t": "a", "href": "/events", "id": "eventsTab", "top": True,
                     "label": "Events", "badge": "NEW", "colour": "#f0c04a"})
        try:
            _c5 = db()
            _gems = gem_balance(_c5.cursor(), "player", normalize_name(account_name))
            _c5.close()
        except sqlite3.Error:
            _gems = None
    # The flood toast links to the review page; only the owner is told it exists.
    _flood_link = {"href": "/flood", "label": "Flood review"} if _owner_now else None
    return jsonify({"logged_in": True, "account_name": account_name, "clan": my_clan, "names": names, "checkin": checkin, "stats": stats, "admin_of": admin_of, "notices": notices,
                    "nav": _nav, "flood_link": _flood_link, "gems": _gems,
                    # Reveals the owner-only live win-probability tab in the menu.
                    "is_owner": is_site_owner(),
                    # Reveals the "Odyssey lobby" tab: any established Odyssey
                    # player can see/join it (only the owner can host one).
                    "custom_view": _user_meets_custom_gate(sub_id),
                    # Lobbies being flooded right this moment, so the alert
                    # can follow the owner onto any page of the site.
                    "live_flood": (live_flood_count() if is_site_owner() else 0),
                    # Defaults to the account name: that is what most
                    # people are called in game, and a blank box on Play
                    # reads as "unknown" rather than "same as my name".
                    "game_name": (_gn[0] if _gn and _gn[0]
                                  else (names[0] if names else "")),
                    "provider": provider, "label": label}), 200


def join_date(stamp):
    """`2026-08-12 18:20:04` as `12 Aug 2026`.

    A day is as precise as this needs to be, and an empty string for the
    members who were already in a clan before dates were kept - showing
    them a made-up date would be worse than showing them none.
    """
    months = ("Jan", "Feb", "Mar", "Apr", "May", "Jun",
              "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")
    try:
        year, month, day = str(stamp or "")[:10].split("-")
        return "%d %s %s" % (int(day), months[int(month) - 1], year)
    except (ValueError, IndexError):
        return ""


@app.route('/clan/<tag>')
def clan_page(tag):
    """Everyone currently carrying one clan tag, ranked as the leaderboard
    ranks them."""
    known = canonical_clan_tag(tag)
    if not known:
        return render_template('clan.html', clan=None, query=tag,
                               version=APP_VERSION, contact=CONTACT_HANDLE,
                               page='clans'), 404

    conn = db()
    c = conn.cursor()
    c.execute("SELECT name, elo, wins, losses, google_sub, clan_joined_at, "
              "COALESCE(strict_mode, 0), contract_clan, contract_until "
              "FROM players WHERE clan = ? AND " + NOT_SANDBOX, (known,))
    rows = c.fetchall()
    c.execute("SELECT google_sub, COALESCE(role, 'leader') FROM clan_admins WHERE clan = ?",
              (known,))
    roles = {r[0]: r[1] for r in c.fetchall() if r[0]}
    admin_subs = set(roles)
    role_labels = clan_custom_labels(c, known)
    # Rank is the player's place on the WHOLE leaderboard, not within the
    # clan: a member shown as #12 has to mean the same thing on both pages.
    ranks = {}
    for row in rows:
        c.execute("SELECT COUNT(*) + 1 FROM players WHERE elo > ?", (row[1],))
        ranks[row[0]] = c.fetchone()[0]
    c.execute("SELECT COALESCE(SUM(won), 0), COALESCE(SUM(1 - won), 0) "
              "FROM clan_results WHERE clan = ?", (known,))
    clan_wins, clan_losses = c.fetchone()
    apps = clan_applications(c, known)
    c.execute("SELECT region, bio, theme FROM clans WHERE tag = ?", (known,))
    _cr = c.fetchone() or (None, None, None)
    region_key = _cr[0] or ""
    clan_bio = _cr[1] or ""
    clan_theme = (_cr[2] or "") if (_cr[2] in CLAN_THEMES) else ""
    role_colors = clan_role_colors(c, known)
    shown_tag = clan_display(c, known)
    conn.close()

    rows.sort(key=leaderboard_sort_key)
    # Each member's skill division (top-X% ship rank), the same one shown on
    # the leaderboard and their profile. `ranks` is a local dict here (place
    # within the clan), so reach the module via division_map() instead.
    _divmap = division_map()
    # Worn emblems for the roster - defined HERE. 9.23.0 referenced these two
    # names in the member dict without defining them, and every clan page was
    # a 500 for the 35 minutes until a live check finally looked at the status.
    _ships_ok_c = gems_visible()
    _shipmap_c = display_ship_map() if _ships_ok_c else {}

    members = []
    total_wins = total_losses = total_elo = 0
    for name, elo, wins, losses, owner_sub, joined, protected, _cclan, _cuntil in rows:
        wins = wins or 0
        losses = losses or 0
        played = wins + losses
        total_wins += wins
        total_losses += losses
        total_elo += elo
        _role = roles.get(owner_sub, "")
        members.append({
            "name": name, "display": display_name(name, known, shown_tag),
            "admin": bool(owner_sub) and owner_sub in admin_subs,
            "role": _role,
            "role_label": role_label_for(_role, role_labels),
            "role_color": role_colors.get(_role or "player", role_colors["player"]),
            # a blue dot for anyone with an account. Whether their rating is
            # protected is theirs to know - see the note on /protection.
            "has_account": bool(owner_sub),
            "contract": contract_until(_cclan, _cuntil, known),
            "elo": f"{elo:.1f}", "wins": wins, "losses": losses,
            "winrate": f"{round(100 * wins / played)}%" if played else "-",
            "rank": ranks[name],
            "emblem": worn_emblem(normalize_name(name), _shipmap_c, _ships_ok_c)[0],
            "emblem_color": worn_emblem(normalize_name(name), _shipmap_c, _ships_ok_c)[1],
            "mythic": worn_emblem(normalize_name(name), _shipmap_c, _ships_ok_c)[2],
            "division": (_divmap.get(normalize_name(name))
                         if played >= PROVISIONAL_GAMES else None),
            "joined": join_date(joined),
        })

    # The sum of the members' own records, which is every match they have
    # ever played rather than only those since clan tracking began.
    # clan_results now ALSO counts per member (owner's stacking rule, 6.29.0),
    # so the two agree in spirit; the lifetime sum stays on display because
    # it carries the longer history.
    clan_wins, clan_losses = total_wins, total_losses
    played = clan_wins + clan_losses
    # Survival: every round a current member has won, added together - the
    # survival board keeps its own record per name.
    surv_wins = surv_rounds = 0
    _norms = [normalize_name(r[0]) for r in rows if r[0]]
    if _norms:
        # The page's own connection is closed by here (the dict is built
        # from what was read); one short read of its own.
        _cs = db()
        try:
            _sr = _cs.execute("SELECT COALESCE(SUM(wins), 0), COALESCE(SUM(rounds), 0) "
                              "FROM survival_players WHERE norm_name IN (%s)"
                              % ",".join("?" for _ in _norms), _norms).fetchone()
        except sqlite3.Error:
            _sr = (0, 0)
        finally:
            _cs.close()
        surv_wins, surv_rounds = int(_sr[0] or 0), int(_sr[1] or 0)
    clan = {
        "tag": known,
        "members": members,
        "size": len(members),
        "avg_elo": f"{total_elo / len(members):.1f}" if members else "0.0",
        "wins": clan_wins,
        "losses": clan_losses,
        "winrate": f"{round(100 * clan_wins / played)}%" if played else "-",
        "played": played,
        "surv_wins": surv_wins,
        "surv_rounds": surv_rounds,
    }
    clan["applications"] = apps
    clan["region"] = region_key
    clan["region_label"] = REGION_LABELS.get(region_key, "")
    clan["regions"] = REGIONS
    clan["bio"] = clan_bio
    clan["theme"] = clan_theme
    clan["theme_color"] = CLAN_THEMES.get(clan_theme, "")
    clan["role_colors"] = role_colors
    # "run by" means the leader. Co-leaders and moderators are shown on
    # their own rows rather than in the heading, or a big clan's heading
    # would be a list of staff.
    clan["admins"] = [m["name"] for m in members if m["role"] == 'leader']
    conn2 = db()
    c2 = conn2.cursor()
    clan["display"] = clan_display(c2, known)
    clan["treasury"] = gem_balance(c2, "clan", known) if _ships_ok_c else None
    clan["member_rate"], clan["mod_rate"] = clan_pay_rates(c2, known) if _ships_ok_c else (0, 0)
    clan["paid_week"] = clan_paid_week(c2, known) if _ships_ok_c else None
    clan["cv"] = clan_view(known, _ships_ok_c, c2)
    if _ships_ok_c:
        for m in members:
            m["rate"] = clan_member_rate(c2, known, normalize_name(m["name"]))
    clan["your_role"] = clan_role(c2, current_user(), known) or ""
    clan["can_manage"] = clan_rank(clan["your_role"]) >= clan_rank('coleader')
    clan["is_leader"] = clan["your_role"] == 'leader'
    conn2.close()
    return render_template('clan.html', clan=clan, version=APP_VERSION,
                           contact=CONTACT_HANDLE, page='clans',
                           client_id=GOOGLE_CLIENT_ID, role_help=CLAN_ROLE_HELP)


def _stamp():
    return time.strftime('%Y-%m-%d %H:%M:%S', time.gmtime())


def gem_grant(c, kind, owner, amount, reason, ref=""):
    """Pay (or charge) an owner, once. Returns the amount that actually moved.

    The ledger row is written first and the balance follows it, both inside
    whatever transaction the caller is already in. If the row is a duplicate -
    same owner, same reason, same reference - the unique index swallows it and
    nothing moves, which is what makes every caller safe to re-run.

    Does NOT commit: a gem must land in the same transaction as the thing that
    earned it, or a crash between the two invents or loses money.
    """
    if not owner or not amount:
        return 0
    try:
        c.execute("INSERT OR IGNORE INTO gem_ledger "
                  "(owner_kind, owner, amount, reason, ref, at) "
                  "VALUES (?, ?, ?, ?, ?, ?)",
                  (kind, owner, int(amount), reason, str(ref or ""), _stamp()))
        if not c.rowcount:
            return 0                      # already paid for this exact thing
        if kind == "clan":
            c.execute("UPDATE clans SET gems = COALESCE(gems, 0) + ? WHERE tag = ?",
                      (int(amount), owner))
        else:
            c.execute("UPDATE players SET gems = COALESCE(gems, 0) + ? "
                      "WHERE norm_name = ?", (int(amount), owner))
        if not c.rowcount:
            # Nobody to carry it: a ledger row with no balance behind it is
            # a debt the site would owe forever (five players were short by
            # exactly one such grant). Take the row back out.
            c.execute("DELETE FROM gem_ledger WHERE owner_kind = ? AND owner = ? "
                      "AND reason = ? AND ref = ?", (kind, owner, reason, str(ref or "")))
            return 0
        return int(amount)
    except sqlite3.Error:
        return 0


def gems_visible():
    """Whether the person looking is allowed to see any of this yet: everyone
    once released; until then the owner, or a preview-key session."""
    return GEMS_PUBLIC or is_site_owner() or preview_session_ok()


def gem_balance(c, kind, owner):
    """What an owner has now, from the cached column."""
    if not owner:
        return 0
    try:
        if kind == "clan":
            r = c.execute("SELECT COALESCE(gems, 0) FROM clans WHERE tag = ?",
                          (owner,)).fetchone()
        else:
            r = c.execute("SELECT COALESCE(gems, 0) FROM players WHERE norm_name = ?",
                          (owner,)).fetchone()
        return int(r[0]) if r else 0
    except sqlite3.Error:
        return 0


def gem_clan_officers(c, tag):
    """norm_names of everyone who runs a clan and is paid on it: the leader
    and each co-leader. Not moderators. Only officers with a player row -
    gems have nowhere else to land."""
    if not tag:
        return []
    try:
        return [r[0] for r in c.execute(
            "SELECT DISTINCT p.norm_name FROM clan_admins a "
            "JOIN players p ON p.google_sub = a.google_sub "
            "WHERE a.clan = ? AND COALESCE(a.role, 'leader') IN ('leader', 'coleader') "
            "AND p.norm_name IS NOT NULL", (tag,)).fetchall()]
    except sqlite3.Error:
        return []


def gem_clan_officers_by_role(c, tag):
    """[(norm_name, role)] for the leader and each co-leader with a player
    row - the two roles paid a cut of every member win."""
    if not tag:
        return []
    try:
        return [(r[0], r[1]) for r in c.execute(
            "SELECT DISTINCT p.norm_name, COALESCE(a.role, 'leader') FROM clan_admins a "
            "JOIN players p ON p.google_sub = a.google_sub "
            "WHERE a.clan = ? AND COALESCE(a.role, 'leader') IN ('leader', 'coleader') "
            "AND p.norm_name IS NOT NULL", (tag,)).fetchall()]
    except sqlite3.Error:
        return []


def clan_coleader_cap(c, tag):
    """How many co-leaders this clan may have: the site's cap plus any slots
    it bought."""
    try:
        r = c.execute("SELECT COALESCE(coleader_slots, 0) FROM clans WHERE tag = ?", (tag,)).fetchone()
    except sqlite3.Error:
        r = None
    return CLAN_COLEADER_MAX + (int(r[0]) if r and r[0] else 0)


def clan_pay_rates(c, tag):
    """(member rate, moderator rate) the clan pays per team win."""
    try:
        r = c.execute("SELECT COALESCE(member_rate, 0), COALESCE(mod_rate, 0) FROM clans "
                      "WHERE tag = ?", (tag,)).fetchone()
    except sqlite3.Error:
        r = None
    if not r:
        return 0, 0
    return (max(0, min(CLAN_RATE_MAX, int(r[0] or 0))),
            max(0, min(CLAN_RATE_MAX, int(r[1] or 0))))


def clan_member_rate(c, tag, nn):
    """What THIS member is paid per team win: a running contract's rate,
    else the clan's rate for their role. Officers have their cuts instead."""
    try:
        r = c.execute("SELECT google_sub, contract_clan, contract_until, COALESCE(contract_rate, 0) "
                      "FROM players WHERE norm_name = ?", (nn,)).fetchone()
    except sqlite3.Error:
        return 0
    if not r:
        return 0
    sub, cclan, cuntil, crate = r
    role = clan_role(c, sub, tag) if sub else ""
    if role in ('leader', 'coleader'):
        return 0
    if contract_until(cclan, cuntil, tag) and crate:
        return max(0, min(CLAN_RATE_MAX, int(crate)))
    member_rate, mod_rate = clan_pay_rates(c, tag)
    return mod_rate if role == 'moderator' else member_rate


def clan_pay_member_win(c, tag, nn, ref, survival=False):
    """The clan side of one member win, all in the caller's transaction:
    the treasury's deposit, the leader's and co-leaders' cuts (minted, like
    the deposit), and the member's own per-win pay taken back out of that
    deposit. Returns what the member was paid by the clan."""
    deposit = GEM_SURVIVAL_CLAN_WIN if survival else GEM_CLAN_WIN
    reason = "survival-member-win" if survival else "member-win"
    gem_grant(c, "clan", tag, deposit, reason, ref)
    for officer, role in gem_clan_officers_by_role(c, tag):
        if role == 'leader':
            cut = GEM_SURVIVAL_LEADER_WIN if survival else GEM_LEADER_WIN
        else:
            cut = GEM_SURVIVAL_COLEADER_WIN if survival else GEM_COLEADER_WIN
        gem_grant(c, "player", officer, cut, reason, ref)
    rate = clan_member_rate(c, tag, nn)
    if rate <= 0:
        return 0
    pay = min(rate * (2 if survival else 1), deposit)
    if gem_clan_charge(c, tag, pay, "member-pay", ref) != "ok":
        return 0
    escrow_tick(c, nn=nn)          # a win is as good a moment as any to pay up
    return gem_grant(c, "player", nn, pay, "clan-pay", ref)


def clan_paid_week(c, tag):
    """What left the treasury in the last seven days, by reason."""
    out = {"member-pay": 0, "salary": 0, "hire": 0, "purchase": 0, "total": 0}
    try:
        for reason, amt in c.execute(
                "SELECT reason, COALESCE(-SUM(amount), 0) FROM gem_ledger WHERE owner_kind = 'clan' "
                "AND owner = ? AND amount < 0 AND at >= datetime('now', '-7 days') GROUP BY reason",
                (tag,)).fetchall():
            out[reason] = int(amt or 0)
            out["total"] += int(amt or 0)
    except sqlite3.Error:
        pass
    return out


# ---- The clan shop ---------------------------------------------------
# What a clan buys with its treasury. Looks dress the clan band and the tag
# every member wears; the emblem is a ship beside the tag; perks are timed
# (a week) or permanent slots. Officers buy; the treasury pays; a clan's
# money never buys a player's own items (that rule stands).
CLAN_PERK_DAYS = 7
