@app.route('/agents/hire', methods=['POST'])
def agents_hire():
    """Pay a free agent's price from the treasury and put them on the
    roster - the join, the tag rule and the ledger all in one transaction.
    Keyed on the listing, so a double click hires once."""
    if not gems_visible():
        abort(404)
    sub = current_user()
    if not sub:
        return jsonify({"ok": False, "message": "Sign in first."}), 401
    body = request.get_json(silent=True) or {}
    conn = db()
    c = conn.cursor()
    known = canonical_clan_tag(str(body.get("clan") or ""), all_clan_tags(c))
    if not known:
        conn.close()
        return jsonify({"ok": False, "message": "No clan with that tag."}), 404
    if not may_manage(c, sub, known):
        conn.close()
        return jsonify({"ok": False,
                        "message": f"Only the leader or a co-leader can hire for {known}."}), 403
    nn = normalize_name(str(body.get("name") or ""))
    a = c.execute("SELECT name, price, listed_at, COALESCE(days, 30), COALESCE(rate, 0) "
                  "FROM free_agents WHERE norm_name = ?", (nn,)).fetchone()
    if not a:
        conn.close()
        return jsonify({"ok": False, "message": "They are not on the list any more."}), 404
    p = c.execute("SELECT name, clan FROM players WHERE norm_name = ?", (nn,)).fetchone()
    if not p or p[1]:
        c.execute("DELETE FROM free_agents WHERE norm_name = ?", (nn,))
        conn.commit()
        conn.close()
        return jsonify({"ok": False,
                        "message": (f"{p[0]} has joined {p[1]} since - the listing is gone."
                                    if p else "That player is gone.")}), 400
    price = int(a[1] or 0)
    ref = f"hire:{nn}:{a[2]}"
    st = gem_clan_charge(c, known, price, "hire", ref)
    if st == "short":
        conn.rollback()
        have = gem_balance(c, "clan", known)
        conn.close()
        return jsonify({"ok": False,
                        "message": f"{p[0]} asks {price:,} gems and {known}'s treasury has "
                                   f"{have:,}. Top it up first."}), 400
    if st == "duplicate":
        conn.rollback()
        conn.close()
        return jsonify({"ok": False, "message": "Already hired."}), 400
    days = int(a[3] or AGENT_CONTRACT_DEFAULT)
    # A month or more is paid across the term rather than on the day: the
    # first week now, the rest week by week while the contract runs.
    first = escrow_open(c, known, nn, price, days,
                        time.strftime("%Y-%m-%d %H:%M:%S",
                                      time.gmtime(time.time() + days * 86400)))
    gem_grant(c, "player", nn, first, "hire", ref)
    # The listing goes before the join: the join may rename the row (the
    # tag comes off), and a rename carries the listing with it.
    rate = max(0, min(CLAN_RATE_MAX, int(a[4] or 0)))
    c.execute("DELETE FROM free_agents WHERE norm_name = ?", (nn,))
    # The term goes on before the tag comes off: the join may rename the
    # row, and the row carries these columns with it.
    c.execute("UPDATE players SET clan = ?, clan_locked = 0, contract_clan = ?, "
              "contract_until = datetime('now', ?), contract_rate = ? WHERE norm_name = ?",
              (known, known, "+%d days" % days, rate, nn))
    strip_tag_on_join(c, p[0], known)
    conn.commit()
    conn.close()
    weekly = price - first
    return jsonify({"ok": True, "days": days, "rate": rate, "escrow": weekly,
                    "message": f"{display_name(p[0], known)} joined {known}"
                               + (f" for {price:,} gems" if price else "")
                               + (f", +{rate} a win" if rate else "")
                               + f", on a {contract_term(days)} contract."
                               + (f" {first:,} paid now, {weekly:,} across the term."
                                  if weekly else "")})


@app.route('/shop')
def shop_page():
    """Every ship and every look: what it costs today, which you own, which
    you are wearing - and the few on sale until midnight."""
    if not gems_visible():
        abort(404)
    conn = db()
    c = conn.cursor()
    me = my_player(c)
    own, worn, balance, division, owned_cos, worn_cos = {}, None, 0, None, set(), {}
    my_level = 0
    if me:
        own = owned_ships(c, me[1])
        r = c.execute("SELECT display_ship, COALESCE(wins,0)+COALESCE(losses,0), cosmetics "
                      "FROM players WHERE norm_name = ?", (me[1],)).fetchone()
        worn = r[0] if r else None
        if r and r[1] >= PROVISIONAL_GAMES:
            division = division_map().get(me[1])
        worn_cos = _worn_cosmetics(r[2]) if r else {}
        owned_cos = owned_cosmetics(c, me[1])
        balance = gem_balance(c, "player", me[1])
        my_level = gem_peak_level(c, me[1])
    # The clan's shop, for whoever runs one: bought from the treasury, on
    # the same page as everything else so there is one place to spend.
    clan_shop, clan_tag, clan_disp, clan_theme_color, clan_cap = None, None, None, "", CLAN_COLEADER_MAX
    sub_id = current_user()
    if sub_id:
        for t in clan_admin_tags(c, sub_id):
            if may_manage(c, sub_id, t):
                clan_tag = t
                clan_shop = clan_shop_state(c, t)
                clan_disp = clan_display(c, t)
                clan_cap = clan_coleader_cap(c, t)
                _th = c.execute("SELECT theme FROM clans WHERE tag = ?", (t,)).fetchone()
                clan_theme_color = CLAN_THEMES.get((_th[0] if _th else "") or "", "")
                break
    conn.close()
    sale_map, _day = featured_today()
    sale_order = {k: i for i, k in enumerate(sale_map)}
    by_level = ranks.RANK_BY_LEVEL
    tiers, featured = {}, []
    for item in ship_catalog():
        item["own"] = own.get(item["code"])
        item["worn"] = (worn == item["code"])
        item["sale"] = sale_map.get(("ship", item["code"]))
        item["pay"] = item["sale"]["price"] if item["sale"] else item["price"]
        item["can"] = balance >= item["pay"]
        item["unlock_rank"] = by_level.get(item["unlock_level"]) if item["unlock_level"] else None
        # A hull a tier hands out is never on sale: reaching the tier IS how
        # you get it. Everything else needs its own tier flown first.
        item["earn_only"] = bool(item["unlock_level"]) and \
            item["buy_level"] == item["unlock_level"] and not item["mythic"]
        item["may_buy"] = my_level >= item["buy_level"]
        item["need_rank"] = by_level.get(item["buy_level"])
        tiers.setdefault(item["tier"], []).append(item)
        if item["sale"]:
            featured.append({"kind": "ship", "item": item, "o": sale_order[("ship", item["code"])]})
    mythic = [i for i in tiers.get(7, []) if i["mythic"]]
    tiers[7] = [i for i in tiers.get(7, []) if not i["mythic"]]
    ach_names = {a["key"]: a["name"] for a in gem_achievement_catalog()}
    cos_sections = []
    for slot, label in COSMETIC_SLOTS:
        items = []
        for ci in cosmetic_catalog():
            if ci["slot"] != slot:
                continue
            ci["via_name"] = ach_names.get(ci["via"]) if ci["via"] else None
            ci["own"] = ci["id"] in owned_cos
            ci["worn"] = worn_cos.get(slot) == ci["id"]
            ci["sale"] = sale_map.get(("cos", ci["id"]))
            ci["pay"] = ci["sale"]["price"] if ci["sale"] else ci["price"]
            ci["can"] = balance >= ci["pay"]
            items.append(ci)
            if ci["sale"]:
                featured.append({"kind": "cos", "item": ci, "o": sale_order[("cos", ci["id"])]})
        cos_sections.append({"slot": slot, "label": label, "items": items,
                             "note": COSMETIC_NOTES.get(slot, "")})
    featured.sort(key=lambda f: f["o"])
    # Everything worn, in one strip at the top, so taking a look back off
    # does not mean hunting the catalogue for the tile it came from.
    wearing = []
    if worn:
        _sn = next((i["name"] for i in ship_catalog() if i["code"] == worn), None)
        if _sn:
            wearing.append({"label": "Hull", "name": _sn, "code": worn, "item": None,
                            "slot": "ship"})
    for _slot, _lab in COSMETIC_SLOTS:
        _id = worn_cos.get(_slot)
        _it = COSMETIC_BY_ID.get(_id) if _id else None
        if _it:
            wearing.append({"label": _lab.rstrip("s"), "name": _it["name"],
                            "code": None, "item": _it["id"], "slot": _slot})
    rank_color = division["color"] if division else "#8b949e"
    return render_template('shop.html', version=APP_VERSION, page='shop',
                           signed_in=bool(me), me_name=(me[0] if me else None),
                           tiers=[tiers[t] for t in sorted(tiers)], nships=len(ship_catalog()),
                           mythic=mythic, balance=balance, division=division,
                           worn=worn, preview=not GEMS_PUBLIC,
                           mythic_color=MYTHIC_COLOR, mythic_glow=MYTHIC_GLOW,
                           rank_color=rank_color,
                           prev_ship=worn or (division["ship"] if division else 101),
                           cos_sections=cos_sections, featured=featured, wearing=wearing,
                           resets_in=featured_resets_in(),
                           clan_shop=clan_shop, clan_tag=clan_tag, clan_display=clan_disp,
                           clan_theme_color=clan_theme_color, coleader_cap=clan_cap,
                           slots_max=CLAN_COLEADER_SLOTS_MAX)



@app.route('/shop/buy', methods=['POST'])
def shop_buy():
    """Buy a ship or a look. Once, at today's price, and only with gems that
    are actually there."""
    if not gems_visible():
        abort(404)
    conn = db()
    c = conn.cursor()
    me = my_player(c)
    if not me:
        conn.close()
        return jsonify({"ok": False, "message": "Sign in first."}), 401
    body = request.get_json(silent=True) or {}
    if body.get("item") is not None:
        ci = COSMETIC_BY_ID.get(str(body.get("item")))
        if not ci:
            conn.close()
            return jsonify({"ok": False, "message": "No such item."}), 404
        if ci["id"] in owned_cosmetics(c, me[1]):
            conn.close()
            return jsonify({"ok": False, "message": "You already have %s." % ci["name"]}), 200
        if ci["via"]:
            conn.close()
            _an = next((a["name"] for a in gem_achievement_catalog() if a["key"] == ci["via"]), ci["via"])
            return jsonify({"ok": False, "message": "%s is not for sale - it comes with the "
                            "%s achievement." % (ci["name"], _an)}), 200
        pay, _sale = shop_price("cos", ci["id"], ci["price"])
        got = gem_charge(c, me[1], pay, "purchase", "cos-%s" % ci["id"])
        name = ci["name"]
    else:
        try:
            code = int(body.get("code"))
        except (TypeError, ValueError):
            conn.close()
            return jsonify({"ok": False, "message": "Which ship?"}), 400
        item = next((i for i in ship_catalog() if i["code"] == code), None)
        if not item:
            conn.close()
            return jsonify({"ok": False, "message": "No such ship."}), 404
        if code in owned_ships(c, me[1]):
            conn.close()
            return jsonify({"ok": False, "message": "You already have the %s." % item["name"]}), 200
        may, need = ship_buyable(c, me[1], item)
        if not may:
            conn.close()
            if item.get("earn_only_gate"):
                return jsonify({"ok": False,
                                "message": "The %s is not for sale - reach %s and it is "
                                           "yours." % (item["name"], need["name"])}), 200
            return jsonify({"ok": False,
                            "message": "The %s is flown by the %s tier. Climb to it and "
                                       "it is on sale to you."
                                       % (item["name"], need["name"])}), 200
        pay, _sale = shop_price("ship", code, item["price"])
        got = gem_charge(c, me[1], pay, "purchase", "ship-%d" % code)
        name = "the " + item["name"]
    if got == "short":
        conn.close()
        return jsonify({"ok": False, "message": "Not enough gems - %s is %s."
                        % (name, format(pay, ","))}), 200
    if got == "duplicate":
        conn.close()
        return jsonify({"ok": False, "message": "You already have %s." % name}), 200
    conn.commit()
    balance = gem_balance(c, "player", me[1])
    conn.close()
    return jsonify({"ok": True, "message": "%s is yours." % (name[0].upper() + name[1:]),
                    "balance": balance, "paid": pay}), 200


@app.route('/shop/equip', methods=['POST'])
def shop_equip():
    """Wear something you own: a ship as your emblem (code, or none to go
    back to your rank's), or a look in its slot (item, or slot + no item to
    take it off)."""
    if not gems_visible():
        abort(404)
    conn = db()
    c = conn.cursor()
    me = my_player(c)
    if not me:
        conn.close()
        return jsonify({"ok": False, "message": "Sign in first."}), 401
    body = request.get_json(silent=True) or {}
    if "item" in body or "slot" in body:
        r = c.execute("SELECT cosmetics FROM players WHERE norm_name = ?", (me[1],)).fetchone()
        worn = _worn_cosmetics(r[0] if r else None)
        raw = body.get("item")
        if raw in (None, "", 0, "0"):
            slot = str(body.get("slot") or "")
            labels = dict(COSMETIC_SLOTS)
            if slot not in labels:
                conn.close()
                return jsonify({"ok": False, "message": "Which slot?"}), 400
            was = COSMETIC_BY_ID.get(worn.pop(slot, ""), {}).get("name")
            msg = ("Took off %s." % was) if was else "Nothing was on."
        else:
            ci = COSMETIC_BY_ID.get(str(raw))
            if not ci:
                conn.close()
                return jsonify({"ok": False, "message": "No such item."}), 404
            if ci["id"] not in owned_cosmetics(c, me[1]):
                conn.close()
                return jsonify({"ok": False, "message": "You do not have %s." % ci["name"]}), 200
            worn[ci["slot"]] = ci["id"]
            msg = "Now wearing %s." % ci["name"]
        c.execute("UPDATE players SET cosmetics = ? WHERE norm_name = ?",
                  (json.dumps(worn) if worn else None, me[1]))
        conn.commit()
        conn.close()
        _COS_CACHE["ts"] = 0.0
        return jsonify({"ok": True, "message": msg, "worn": worn}), 200
    raw = body.get("code")
    if raw in (None, "", 0, "0"):
        c.execute("UPDATE players SET display_ship = NULL WHERE norm_name = ?", (me[1],))
        conn.commit()
        conn.close()
        _SHIP_CACHE["ts"] = 0.0
        return jsonify({"ok": True, "message": "Back to your rank's ship.", "code": None}), 200
    try:
        code = int(raw)
    except (TypeError, ValueError):
        conn.close()
        return jsonify({"ok": False, "message": "Which ship?"}), 400
    if code not in owned_ships(c, me[1]):
        conn.close()
        return jsonify({"ok": False, "message": "You do not have that ship."}), 200
    c.execute("UPDATE players SET display_ship = ? WHERE norm_name = ?", (code, me[1]))
    conn.commit()
    conn.close()
    _SHIP_CACHE["ts"] = 0.0
    return jsonify({"ok": True, "message": "Now flying the %s." % ship_shapes.ship_name(code),
                    "code": code}), 200


@app.route('/social')
def social_page():
    """Friends, requests, and your clan - the social half of the site."""
    conn = db()
    c = conn.cursor()
    me = my_player(c)
    if not me:
        conn.close()
        return render_template('social.html', version=APP_VERSION, page='social',
                               signed_in=False, friends=[], incoming=[],
                               outgoing=[], clan=None)

    # Their division, so a row can wear the same emblem the leaderboard gives
    # them. Already computed when the board was built; this only looks it up.
    dmap = division_map()
    _ships_ok = gems_visible()
    _shipmap = display_ship_map() if _ships_ok else {}
    # And their place on the board. One sorted pass beats a COUNT per person:
    # the profile's "COUNT(*)+1 WHERE elo > ?" is a scan each time, and this
    # page asks for a whole clan at once.
    c.execute("SELECT elo FROM players")
    _elos = sorted((r[0] or 0) for r in c.fetchall())
    _total = len(_elos)

    def place(e):
        """#N on the all-time board, counting everyone above them."""
        return _total - bisect.bisect_right(_elos, e or 0) + 1

    def card(nn):
        c.execute("SELECT name, elo, COALESCE(wins,0), COALESCE(losses,0), clan "
                  "FROM players WHERE norm_name = ? LIMIT 1", (nn,))
        r = c.fetchone()
        if not r:
            return None
        return {"norm": nn, "name": r[0], "elo": r[1] or 0,
                "wins": r[2], "losses": r[3], "clan": r[4] or "",
                "division": dmap.get(nn),
                "rank": place(r[1]), "rank_of": _total,
                "emblem": worn_emblem(nn, _shipmap, _ships_ok)[0],
                "emblem_color": worn_emblem(nn, _shipmap, _ships_ok)[1],
                "mythic": worn_emblem(nn, _shipmap, _ships_ok)[2]}

    fr = [x for x in (card(n) for n in friends_of(c, me[1])) if x]
    inc = [x for x in (card(n) for n in friend_requests_in(c, me[1])) if x]
    c.execute("SELECT a, b FROM friends WHERE state = 'pending' AND requester = ?",
              (me[1],))
    out = [x for x in (card(b if a == me[1] else a) for a, b in c.fetchall()) if x]

    # Clanmates count as your people too: you already share a tag in public,
    # so being told they are in a lobby is not a disclosure friendship adds.
    mates = []
    c.execute("SELECT clan FROM players WHERE google_sub = ? AND clan IS NOT NULL "
              "AND clan != '' LIMIT 1", (current_user(),))
    _mc = c.fetchone()
    my_tag = _mc[0] if _mc else None
    if my_tag:
        c.execute("SELECT norm_name FROM players WHERE clan = ? AND norm_name IS NOT NULL",
                  (my_tag,))
        friend_norms = set(f["norm"] for f in fr)
        for (nn,) in c.fetchall():
            if nn and nn != me[1] and nn not in friend_norms:
                mates.append(nn)

    # When each of them last finished a match. One grouped query over an
    # indexed column beats asking per person, and the page asks about a whole
    # clan.
    def last_seen_map(norms):
        out = {}
        norms = [n for n in norms if n]
        for i in range(0, len(norms), 400):
            chunk = norms[i:i + 400]
            qs = ",".join("?" * len(chunk))
            try:
                for nn, when in c.execute(
                        "SELECT mp.norm_name, MAX(m.played_at) FROM match_players mp "
                        "JOIN matches m ON m.id = mp.match_row "
                        "WHERE mp.norm_name IN (%s) GROUP BY mp.norm_name" % qs,
                        chunk).fetchall():
                    if when:
                        out[nn] = when
            except sqlite3.Error:
                pass
        return out

    live = people_playing(c, [f["norm"] for f in fr] + mates)

    # Clanmates get their own list: you share a tag with them whether or not
    # you ever pressed a button about it.
    mate_cards = [x for x in (card(n) for n in mates) if x]
    # What the button on a clanmate's tile should say: nothing to press if you
    # are already friends, and nothing to press again if you have asked.
    asked = set()
    for _a, _b in c.execute("SELECT a, b FROM friends WHERE state = 'pending' "
                            "AND requester = ?", (me[1],)).fetchall():
        asked.add(_b if _a == me[1] else _a)
    friend_norms = set(f["norm"] for f in fr)
    for p in mate_cards:
        p["rel"] = ("friend" if p["norm"] in friend_norms
                    else "asked" if p["norm"] in asked else "none")
    seen_map = last_seen_map([f["norm"] for f in fr] + [m["norm"] for m in mate_cards])
    for p in fr + mate_cards:
        p["playing"] = live.get(p["norm"])
        p["last"] = ago(seen_map.get(p["norm"]))
    mate_cards.sort(key=lambda p: (0 if p.get("playing") else 1, -p["elo"]))
    fr.sort(key=lambda f: (0 if f.get("playing") else 1, -f["elo"]))

    # Everyone of yours who is in a lobby right now, friends and clanmates
    # together - one card answers "is anyone on?".
    onnow = []
    for nn, info in live.items():
        p = card(nn)
        if not p:
            continue
        p["playing"] = info
        p["is_friend"] = nn in set(f["norm"] for f in fr)
        p["last"] = ago(seen_map.get(nn))
        onnow.append(p)
    onnow.sort(key=lambda p: (0 if p["is_friend"] else 1, -p["elo"]))

    # The name they play under, so Join can copy it into the clipboard exactly
    # as the Play page does - the check-in binds an account, and the watcher
    # still has to be able to recognise the ship.
    c.execute("SELECT COALESCE(NULLIF(game_name, ''), name) FROM players "
              "WHERE google_sub = ? LIMIT 1", (current_user(),))
    _gn = c.fetchone()
    play_name = _gn[0] if _gn else me[0]

    c.execute("SELECT COALESCE(hide_presence, 0) FROM players WHERE norm_name = ?",
              (me[1],))
    _hp = c.fetchone()
    hidden = bool(_hp and _hp[0])

    c.execute("SELECT clan FROM players WHERE google_sub = ? AND clan IS NOT NULL "
              "AND clan != '' LIMIT 1", (current_user(),))
    row = c.fetchone()
    clan = None
    if row and row[0]:
        c.execute("SELECT COUNT(*) FROM players WHERE clan = ?", (row[0],))
        clan = {"tag": row[0], "members": (c.fetchone() or [0])[0]}

    # Clans to ask, but only for somebody who could actually ask: /clan/apply
    # turns down anyone already in one, so the section would be a row of
    # buttons that always fail.
    clan_recs, clan_more, clan_order = [], [], ""
    if not clan:
        c.execute("SELECT elo, COALESCE(wins, 0) + COALESCE(losses, 0) "
                  "FROM players WHERE norm_name = ?", (me[1],))
        _mine = c.fetchone()
        _my_elo = (_mine[0] if _mine else 0) or 0
        _my_played = (_mine[1] if _mine else 0) or 0
        # Where they actually play, not where they say they do - the region
        # most of their matches happened in.
        _my_region = ""
        if _my_played:
            _rs = [r for r in region_split(c, me[0]) if r["played"]]
            if _rs:
                _my_region = max(_rs, key=lambda r: r["played"])["key"]
        clan_recs, clan_more = clan_suggestions(c, me[0], _my_elo,
                                                _my_played, _my_region)
        clan_order = "nearest your rating" if _my_played else "biggest first"
    conn.close()
    return render_template('social.html', version=APP_VERSION, page='social',
                           signed_in=True, me=me[0], play_name=play_name,
                           friends=fr, incoming=inc, outgoing=out, clan=clan,
                           onnow=onnow, my_tag=my_tag, hidden=hidden,
                           mates=mate_cards, clan_recs=clan_recs,
                           clan_more=clan_more, clan_order=clan_order)


@app.route('/api/social/live')
def api_social_live():
    """Just the parts of the Social page that change: who is in a match, and
    when each of your people last played. The page patches itself with this
    rather than reloading, so a half-typed name or an open dialog survives."""
    conn = db()
    c = conn.cursor()
    me = my_player(c)
    if not me:
        conn.close()
        return jsonify({"signed_in": False, "playing": {}}), 200
    mine = friends_of(c, me[1])
    friend_set = set(mine)
    c.execute("SELECT clan FROM players WHERE google_sub = ? AND clan IS NOT NULL "
              "AND clan != '' LIMIT 1", (current_user(),))
    row = c.fetchone()
    if row and row[0]:
        c.execute("SELECT norm_name FROM players WHERE clan = ? AND norm_name IS NOT NULL",
                  (row[0],))
        for (nn,) in c.fetchall():
            if nn and nn != me[1] and nn not in friend_set:
                mine.append(nn)
    live = people_playing(c, mine)
    conn.close()
    return jsonify({"signed_in": True,
                    "playing": live,
                    "friends_live": sum(1 for n in live if n in friend_set),
                    "mates_live": sum(1 for n in live if n not in friend_set)}), 200


