@app.route('/api/held')
def api_held_route():
    """Results withheld by protection. Never rendered on the site - showing
    them would undo the thing the player asked for - but kept so a wrong
    call can be found and put right."""
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401
    who = str(request.args.get('name', '')).strip()
    conn = db()
    c = conn.cursor()
    if who:
        c.execute("SELECT id, match_id, region, name, played_as, won, score, reason, played_at "
                  "FROM held_results WHERE norm_name = ? ORDER BY id DESC LIMIT 200",
                  (normalize_name(who),))
    else:
        c.execute("SELECT id, match_id, region, name, played_as, won, score, reason, played_at "
                  "FROM held_results ORDER BY id DESC LIMIT 200")
    out = [{"id": r[0], "match_id": r[1], "region": r[2], "name": r[3],
            "played_as": r[4], "won": bool(r[5]), "score": r[6],
            "reason": r[7], "at": r[8]} for r in c.fetchall()]
    c.execute("SELECT COUNT(*) FROM held_results")
    total = (c.fetchone() or [0])[0]
    conn.close()
    return jsonify({"held": out, "shown": len(out), "total": total}), 200


@app.route('/api/bot/name', methods=['POST'])
def bot_set_name_route():
    """Set or change the account name from Discord.

    The same thing the Settings page does. /api/bot/register can only add a
    name to an account that has none, so someone who wanted to correct a
    typo had to come to the site - which is exactly the sort of errand a
    bot should save.
    """
    if not bot_authorised():
        return jsonify({"error": "Unauthorized"}), 401
    data = request.json or {}
    discord_id = str(data.get('discord_id', '')).strip()
    name = str(data.get('name', '')).strip()
    if not discord_id:
        return jsonify({"error": "no discord_id"}), 400
    sub_id = discord_account(discord_id)
    if not is_valid_name_format(name):
        return jsonify({"ok": False, "message": "That name cannot be used. Try another."}), 200
    if is_blocked_word(name):
        return jsonify({"ok": False, "message": "That name isn't allowed. Please choose another."}), 200
    if is_default_name(name):
        return jsonify({"ok": False, "message": "That is one of Starblast's default names - too "
                                                "many players share it. Pick a name of your own."}), 200

    conn = db()
    c = conn.cursor()
    c.execute("BEGIN IMMEDIATE")
    key = normalize_name(name)
    c.execute("SELECT google_sub FROM players WHERE norm_name = ?", (key,))
    taken = c.fetchone()
    if taken and taken[0] and taken[0] != sub_id:
        conn.close()
        return jsonify({"ok": False,
                        "message": f"'{name}' already belongs to another account."}), 200
    if taken and not taken[0]:
        conn.close()
        return jsonify({"ok": False, "claimable": True,
                        "message": f"'{name}' is already on the leaderboard as an unverified "
                                   f"player. Claim it on the site to take it over."}), 200
    if taken and taken[0] == sub_id:
        c.execute("SELECT name FROM players WHERE norm_name = ?", (key,))
        row = c.fetchone()
        conn.commit()
        conn.close()
        return jsonify({"ok": True, "name": row[0] if row else name,
                        "message": f"Your name is already '{row[0] if row else name}'."}), 200

    # One row moves, chosen the same way the site chooses it - an account
    # holding two grandfathered names must not have both renamed at once.
    c.execute("SELECT name FROM players WHERE google_sub = ? "
              "ORDER BY (COALESCE(wins, 0) + COALESCE(losses, 0)) DESC, name LIMIT 1",
              (sub_id,))
    mine = c.fetchone()
    if mine:
        rekey_identity(c, mine[0], name)
        msg = f"Your name is now '{name}' (was '{mine[0]}')."
    else:
        c.execute("INSERT INTO players (name, elo, wins, losses, reg_ip, norm_name, google_sub) "
                  "VALUES (?, ?, 0, 0, ?, ?, ?)",
                  (name, STARTING_ELO, 'discord-bot', key, sub_id))
        msg = f"Your name is '{name}'."
    landed = join_own_clans(c, sub_id)
    if landed:
        msg += f" You are now on the {landed[0][0]} roster."
    conn.commit()
    conn.close()
    return jsonify({"ok": True, "name": name, "message": msg}), 200


@app.route('/api/bot/protection', methods=['GET', 'POST'])
def bot_protection_route():
    """Read or set protection on the account's own name.

    Deliberately offers no way to name a target: from Discord you can only
    change your own. The rules are the site's - it needs match history to
    switch on, and it can only be changed once a day.
    """
    if not bot_authorised():
        return jsonify({"error": "Unauthorized"}), 401
    if request.method == 'GET':
        discord_id = str(request.args.get('discord_id', '')).strip()
        want = None
    else:
        data = request.json or {}
        discord_id = str(data.get('discord_id', '')).strip()
        want = 1 if data.get('enabled') else 0
    if not discord_id:
        return jsonify({"error": "no discord_id"}), 400
    sub_id = discord_account(discord_id)

    conn = db()
    c = conn.cursor()
    name = account_name_for(c, sub_id)
    if not name:
        conn.close()
        return jsonify({"ok": False, "message": "You have no name on this account yet. "
                                                "Set one with /setname first."}), 200
    c.execute("SELECT COALESCE(strict_mode, 0), prot_changed_at, "
              "COALESCE(wins, 0) + COALESCE(losses, 0) FROM players WHERE name = ?", (name,))
    row = c.fetchone()
    enabled, changed_at, played = (row[0], row[1], row[2]) if row else (0, None, 0)

    def hours_left():
        if not changed_at:
            return 0.0
        c.execute("SELECT (julianday('now') - julianday(?)) * 24.0", (changed_at,))
        gone = (c.fetchone() or [None])[0]
        return 0.0 if gone is None else max(0.0, PROTECTION_COOLDOWN_HOURS - gone)

    if want is None:
        left = hours_left()
        conn.close()
        return jsonify({"ok": True, "name": name, "enabled": bool(enabled),
                        "hours_left": round(left, 1), "played": played}), 200

    # Same as the site: no match history needed. See the note there.
    if want != enabled:
        left = hours_left()
        if left > 0:
            conn.close()
            wait = (f"{int(left)} hours" if left >= 1
                    else f"{max(1, int(left * 60))} minutes")
            return jsonify({"ok": False, "name": name, "enabled": bool(enabled),
                            "message": f"Protection can only be changed once a day. "
                                       f"Try again in {wait}."}), 200
        c.execute("UPDATE players SET strict_mode = ?, prot_changed_at = ? WHERE name = ?",
                  (want, time.strftime('%Y-%m-%d %H:%M:%S'), name))
    conn.commit()
    conn.close()
    if want:
        return jsonify({"ok": True, "name": name, "enabled": True,
                        "message": f"Protection is ON for '{name}'. Only matches you press "
                                   f"Play on will count, and your rating shows as confirmed."}), 200
    return jsonify({"ok": True, "name": name, "enabled": False,
                    "message": f"Protection is OFF for '{name}'. Your rating is no longer "
                               f"marked as confirmed, and every match counts again."}), 200


@app.route('/api/bot/register', methods=['POST'])
def bot_register_route():
    """Register a name against a Discord account.

    Every rule /register applies is applied here too - shape, blocklist,
    default names, the one-name cap and the duplicate check - because this
    is the same act done from a different place. The account it lands on is
    the same identity Discord sign-in produces, so a name registered from
    the bot is simply there when the player signs into the site.
    """
    if not bot_authorised():
        return jsonify({"error": "Unauthorized"}), 401
    data = request.json or {}
    discord_id = str(data.get('discord_id', '')).strip()
    name = str(data.get('name', '')).strip()
    if not discord_id:
        return jsonify({"ok": False, "message": "No Discord account was given."}), 400
    if not name:
        return jsonify({"ok": False, "message": "No name provided."}), 400

    if not is_valid_name_format(name):
        return jsonify({"ok": False, "message": "Name must be 1-16 letters or digits, and cannot end in a digit."}), 200
    if is_blocked_word(name):
        return jsonify({"ok": False, "message": "That name isn't allowed. Please choose another."}), 200
    if is_default_name(name):
        return jsonify({"ok": False, "message": "That is one of Starblast's default names, given to anyone who joins without typing one. Too many players share it for it to be tracked. Pick a name of your own in game."}), 200

    # Keep the handle current against the Discord identity itself, but
    # register the name on the account this Discord acts as - its own, or the
    # one it is bound to.
    if data.get('username'):
        remember_discord_user('discord:' + discord_id, data.get('username'),
                              data.get('display') or data.get('username'))
    sub_id = discord_account(discord_id)

    conn = db()
    c = conn.cursor()
    c.execute("BEGIN IMMEDIATE")
    c.execute("SELECT name FROM players WHERE google_sub = ?", (sub_id,))
    already = [row[0] for row in c.fetchall()]
    if len(already) >= MAX_NAMES_PER_ACCOUNT:
        conn.close()
        return jsonify({"ok": False, "held": already[0],
                        "message": f"Your account already has a name: '{already[0]}'. Remove it on the site first if you want a different one."}), 200

    c.execute("SELECT name FROM players WHERE norm_name = ?", (normalize_name(name),))
    taken = c.fetchone()
    if taken:
        conn.close()
        return jsonify({"ok": False, "taken": taken[0],
                        "message": f"'{taken[0]}' is already registered. If it is yours, claim it on the site."}), 200

    c.execute("INSERT INTO players (name, elo, wins, losses, reg_ip, norm_name, google_sub) "
              "VALUES (?, ?, 0, 0, ?, ?, ?)",
              (name, STARTING_ELO, 'discord-bot', normalize_name(name), sub_id))
    conn.commit()
    conn.close()
    return jsonify({"ok": True, "name": name,
                    "message": f"'{name}' is registered to your Discord account."}), 200


@app.route('/report', methods=['POST'])
def report_name():
    """Report that somebody has taken, or is trying to take, your name.

    Claims complete automatically once the claimant wins as that name, which
    is a cost rather than a proof - nothing observed in game can tell a real
    owner from someone wearing their name. This is the recourse. It does not
    undo anything on its own; it raises an alert for a person to look at,
    because deciding who someone really is needs knowledge the site does not
    have.
    """
    data = request.json or {}
    name = str(data.get('name', '')).strip()
    note = str(data.get('note', '')).strip()[:300]
    if not name:
        return jsonify({"message": "Which name are you reporting?"}), 400

    conn = db()
    c = conn.cursor()
    c.execute("SELECT name FROM players WHERE norm_name = ?", (normalize_name(name),))
    row = c.fetchone()
    if not row:
        conn.close()
        return jsonify({"message": f"'{name}' is not on the leaderboard."}), 404
    stored_name = row[0]

    me_now = current_user()
    if me_now:
        c.execute("SELECT COUNT(*) FROM name_reports WHERE status = 'open' "
                  "AND reported_by = ?", (me_now,))
        if (c.fetchone() or [0])[0] >= MAX_PENDING_CLAIMS:
            conn.close()
            return jsonify({"message": "You already have several reports open. "
                                       "Wait for those to be looked at first."}), 429
    if rate_hit(c, 'name_report', MAX_PENDING_CLAIMS, '-1 day'):
        conn.close()
        return jsonify({"message": "You already have several reports open. "
                                   "Wait for those to be looked at first."}), 429

    c.execute("INSERT INTO name_reports (name, reported_by, ip, note, created_at, status) "
              "VALUES (?, ?, ?, ?, ?, 'open')",
              (stored_name, current_user(), None, note, time.strftime('%Y-%m-%d %H:%M:%S')))
    conn.commit()
    conn.close()
    return jsonify({"message": f"Reported '{stored_name}'. {CONTACT_HANDLE} will look at it by "
                               f"hand - nothing changes automatically."}), 200


CUSTOM_GATE_MIN_LEVEL = 7           # Warden (ranks.py level 7) and above
CUSTOM_OWNER_ONLY = True            # TESTING: only the owner can open/see/play the lobby

# ---------- custom-game builder (owner-hosted; unrated when non-default) -------
# Each option: (default, kind, ...). int/float clamp to [a, b]; 'choice' must be
# in the list; 'str' trims to max length. The DEFAULTS below are the rated
# preset: a game left at every default with no imported mod is the standard
# team lobby and counts on the board; change anything (or import a mod) and it
# becomes unrated. (Matches the user's rule: "if it's not default, it's not
# rated".)
# The full option set the game accepts (starblast-modding README), with the
# TEAM-mode defaults - so a form left at every default is exactly the standard
# public lobby. Kinds: int/float (min, max), choice (list), str (max len), bool.
CUSTOM_GAME_OPTIONS = {
    # map
    "map_name":        ("", "str", 24),
    "map_size":        (80, "int", 20, 200),          # even only (normalize rounds down)
    "map_id":          (0, "int", 0, 9999),           # the "map pattern" seed; 0 = let the game pick
    "map_density":     (1.0, "float", 0.0, 1.0),      # server clamps at 1; 1 = its automatic density (not forwarded)
    # game
    # survival is here for the MAP-TEST lobby (My Maps > Play). The Odyssey lobby
    # page hard-codes team, and a survival config is never all-defaults, so it
    # can never be rated. Probed 11 Sep 2026: the game's survival defaults are
    # survival_time 30 (minutes), survival_level 8, no teams, healing off.
    "root_mode":       ("team", "choice", ["team", "survival"]),
    "friendly_colors": (3, "int", 1, 5),              # number of teams; the game allows up to 5
    "max_players":     (70, "int", 1, 240),
    "survival_time":   (30, "int", 1, 120),           # minutes until the field locks (survival)
    "survival_level":  (8, "int", 1, 8),              # level that also locks it (8 = never)
    # resources
    "crystal_value":   (2.5, "float", 0.0, 10.0),     # the server's team default (probed 9 Sep 2026)
    "crystal_drop":    (1.0, "float", 0.0, 1.0),      # share of gems collectible when drained
    "weapon_drop":     (0.0, "float", 0.0, 10.0),
    "release_crystal": (True, "bool"),
    "asteroids_strength": (1.0, "float", 0.0, 1000.0),
    # ships & lives
    "starting_ship":   (101, "int", 100, 704),        # ship code (tier*100+model)
    "starting_ship_maxed": (False, "bool"),
    "max_level":       (7, "int", 1, 7),
    "lives":           (4, "int", 1, 5),
    "maxtierlives":    (0, "int", 0, 5),              # lives at max level (0 = same as lives)
    # flight
    "speed_mod":       (1.2, "float", 0.0, 2.0),
    "friction_ratio":  (1.0, "float", 0.0, 2.0),
    "strafe":          (0.0, "float", 0.0, 1.0),
    "rcs_toggle":      (True, "bool"),
    "projectile_speed": (1.0, "float", 0.0, 3.0),
    # shields / power / healing
    "shield_regen_factor": (1.0, "float", 0.0, 3.0),
    "power_regen_factor":  (1.0, "float", 0.0, 3.0),
    "healing_enabled": (True, "bool"),
    "healing_ratio":   (0.5, "float", 0.0, 2.0),
    "invulnerable_ships": (False, "bool"),
    # weapons
    "weapons_store":   (True, "bool"),
    "mines_self_destroy": (True, "bool"),
    "mines_destroy_delay": (18000, "int", 0, 60000),  # ticks; 60 = 1 s
    # stations (team mode)
    "station_size":    (2, "int", 1, 5),
    "station_crystal_capacity": (1.0, "float", 0.1, 10.0),   # gems to fill a station (x)
    "station_repair_threshold": (0.25, "float", 0.0, 1.0),
    "station_regeneration": (1.0, "float", 0.0, 2.0),
    "auto_assign_teams": (False, "bool"),
    "all_ships_can_dock": (False, "bool"),
    "all_ships_can_respawn": (False, "bool"),
    # hud & sound
    "radar_zoom":      (2, "choice", [1, 2, 4]),
    "auto_refill":     (False, "bool"),
    "soundtrack":      ("", "choice", ["", "procedurality.mp3", "argon.mp3", "crystals.mp3",
                                       "red_mist.mp3", "civilisation.mp3", "warp_drive.mp3"]),
}


def custom_spec():
    """CUSTOM_GAME_OPTIONS as plain JSON for the lobby page, so the form is built
    from the same defaults/ranges the server enforces."""
    out = {}
    for k, s in CUSTOM_GAME_OPTIONS.items():
        d = {"default": s[0], "kind": s[1]}
        if s[1] in ("int", "float"):
            d["min"], d["max"] = s[2], s[3]
        elif s[1] == "choice":
            d["choices"] = list(s[2])
        elif s[1] == "str":
            d["max"] = s[2]
        out[k] = d
    return out
# A custom asteroid map is Starblast's "painted" grid: a string of map_size
# rows x map_size chars, each char a digit 0-9 (asteroid size) or space (empty).
CUSTOM_MAP_MAX_CHARS = 45000        # ~200x200 grid + newlines


def normalize_custom_map(raw):
    """Keep only digits, spaces and newlines; cap the size. Empty -> ''."""
    s = str(raw or "")
    if not s.strip():
        return ""
    s = re.sub(r'[^0-9 \n]', ' ', s)
    return s[:CUSTOM_MAP_MAX_CHARS]
CUSTOM_MOD_MAX = 200000             # imported mod source cap (chars)


def normalize_custom_options(raw):
    """Validate/clamp a submitted options dict against CUSTOM_GAME_OPTIONS.
    Unknown keys dropped, each value coerced into range; returns a full dict
    with every option present (defaults filled in)."""
    raw = raw or {}
    out = {}
    for key, spec in CUSTOM_GAME_OPTIONS.items():
        default, kind = spec[0], spec[1]
        v = raw.get(key, default)
        try:
            if kind == "int":
                v = max(spec[2], min(spec[3], int(round(float(v)))))
                if key == "map_size":
                    v -= v % 2                       # the game wants an even map size
            elif kind == "float":
                v = max(spec[2], min(spec[3], round(float(v), 3)))
            elif kind == "choice":
                if spec[2] and isinstance(spec[2][0], int) and not isinstance(v, bool):
                    v = int(round(float(v)))
                v = v if v in spec[2] else default
            elif kind == "str":
                v = str(v)[:spec[2]]
            elif kind == "bool":
                v = v if isinstance(v, bool) else (str(v).strip().lower() in ("1", "true", "yes", "on"))
        except (TypeError, ValueError):
            v = default
        out[key] = v
    return out


def custom_is_rated(opts, mod_code):
    """Rated ONLY when every option is at its default and no mod is imported."""
    if (mod_code or "").strip():
        return False
    return all(opts.get(k) == spec[0] for k, spec in CUSTOM_GAME_OPTIONS.items())


@app.route('/api/customgate')
def api_customgate():
    """Gate check for the Odyssey-only custom lobby. Given an in-game name,
    says whether that player may be in the lobby: they must be a VERIFIED
    account (their name is claimed) AND an established Odyssey-rank (or above)
    player. The modding host calls this per joining ship and kicks anyone the
    answer says isn't ok. Key-gated - only the host should ask."""
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401
    name = str(request.args.get('name') or '').strip()
    key = normalize_name(name)
    if not key:
        return jsonify({"ok": False, "verified": False, "reason": "no-name"}), 200
    conn = db()
    c = conn.cursor()
    row = c.execute("SELECT google_sub, COALESCE(wins, 0) + COALESCE(losses, 0) "
                    "FROM players WHERE norm_name = ?", (key,)).fetchone()
    conn.close()
    verified = bool(row and row[0])
    played = int(row[1]) if row else 0
    established = played >= PROVISIONAL_GAMES
    div = division_map().get(key)
    level = int(div["level"]) if div else 0
    # The IN-GAME rule is always Warden (verified + established + Warden tier),
    # even while the lobby is owner-only to SEE/open. That way it's already the
    # right rule when it opens to all Wardens. The owner is always allowed too,
    # via the pre-seeded allow-set (/api/customgame/allowed), so they can test.
    ok = verified and established and level >= CUSTOM_GATE_MIN_LEVEL
    if not verified:
        reason = "not-verified"
    elif not established:
        reason = "provisional"
    elif level < CUSTOM_GATE_MIN_LEVEL:
        reason = "below-odyssey"
    else:
        reason = "ok"
    return jsonify({"ok": ok, "verified": verified, "established": established,
                    "division": (div["name"] if div else None), "level": level,
                    "min_level": CUSTOM_GATE_MIN_LEVEL, "reason": reason}), 200


@app.route('/api/customgame/allowed')
def api_customgame_allowed():
    """Key-gated. The host pre-seeds an ALWAYS-ALLOW set from this at game
    start - the owner's own names - so the owner/tester is never touched by the
    kick logic regardless of which of their names they use. Everyone else is
    decided by the Odyssey gate (/api/customgate). Names are raw display names;
    the host lowercases (JS) so unicode case-folding matches its own key."""
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401
    names = []
    if OWNER_SUBS:
        subs = list(OWNER_SUBS)
        conn = db()
        c = conn.cursor()
        q = ("SELECT name FROM players WHERE google_sub IN (%s) AND name IS NOT NULL"
             % ",".join("?" * len(subs)))
        for r in c.execute(q, subs).fetchall():
            nm = (r[0] or "").strip()
            if nm:
                names.append(nm)
        conn.close()
    return jsonify({"owner_only": bool(CUSTOM_OWNER_ONLY), "names": names}), 200


def _user_meets_custom_gate(sub_id):
    """True if the account owns an established Odyssey-rank (or above) name -
    the bar to SEE the join link on /customgame and to JOIN the lobby (the same
    rank the in-lobby kick enforces). The owner always qualifies. NOTE: HOSTING
    (opening a lobby) is owner-only - see _can_host_custom; any Odyssey player
    may join a lobby the owner has opened."""
    if not sub_id:
        return False
    if sub_id in OWNER_SUBS:            # the owner can always see/join the lobby
        return True
    conn = db()
    c = conn.cursor()
    names = [r[0] for r in c.execute(
        "SELECT norm_name FROM players WHERE google_sub = ? "
        "AND COALESCE(wins, 0) + COALESCE(losses, 0) >= ? AND norm_name IS NOT NULL",
        (sub_id, PROVISIONAL_GAMES)).fetchall()]
    conn.close()
    if not names:
        return False
    dm = division_map()
    return any((dm.get(nn) or {}).get("level", 0) >= CUSTOM_GATE_MIN_LEVEL
               for nn in names)


def _can_host_custom(sub_id):
    """The owner may always OPEN/host a lobby. So may the leader or a co-leader
    of a clan that bought the Lobby host perk, while it runs. Everyone else -
    even Odyssey - can only join one that is open."""
    if not sub_id:
        return False
    if sub_id in OWNER_SUBS:
        return True
    if not gems_visible():
        return False
    try:
        conn = db()
        ok = clan_hosts_lobby(conn.cursor(), sub_id)
        conn.close()
    except sqlite3.Error:
        ok = False
    return ok


@app.route('/api/customgame/set', methods=['POST'])
def api_customgame_set():
    """The droplet host reports the live lobby's join link here (key-gated).
    An empty link means the lobby went down; either way this answers/clears the
    pending open request."""
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401
    d = request.json or {}
    link = str(d.get('link') or '')[:200]
    conn = db()
    c = conn.cursor()
    c.execute("INSERT INTO custom_game (id, link, sid, region, password, expires_at, updated_at, wanted_at) "
              "VALUES (1,?,?,?,?,?,?, '') ON CONFLICT(id) DO UPDATE SET link=excluded.link, "
              "sid=excluded.sid, region=excluded.region, password=excluded.password, "
              "expires_at=excluded.expires_at, updated_at=excluded.updated_at, wanted_at=''",
              (link, d.get('sid'), str(d.get('region') or '')[:16],
               str(d.get('password') or '')[:40], str(d.get('expires_at') or '')[:32],
               time.strftime('%Y-%m-%d %H:%M:%S')))
    # A link success clears any prior error; an explicit error is stored; a plain
    # "clear the link" (no error field, e.g. finish/boot) leaves the error alone
    # so a mod rejection's message survives the finish() clear that follows it.
    if link:
        # fresh lobby up: clear any prior error and any stale stop request
        c.execute("UPDATE custom_game SET last_error='', stop_requested=0 WHERE id = 1")
    elif 'error' in d:
        c.execute("UPDATE custom_game SET last_error=? WHERE id = 1",
                  (str(d.get('error') or '')[:400],))
    if d.get('extracted'):
        try:
            c.execute("UPDATE custom_game SET extracted_json=? WHERE id = 1",
                      (json.dumps(d.get('extracted'))[:2000],))
        except (TypeError, ValueError):
            pass
    conn.commit()
    conn.close()
    return jsonify({"ok": True}), 200


@app.route('/api/customgame/open', methods=['POST'])
def api_customgame_open():
    """The host (owner only) asks to open a lobby. Sets the 'wanted' flag the
    droplet host polls; the host then creates the game and reports its link back
    via /set. Any Odyssey player can then JOIN it, but only the owner opens one."""
    sub_id = current_user()
    if not sub_id:
        return jsonify({"ok": False, "message": "Sign in first."}), 401
    if not _can_host_custom(sub_id):
        return jsonify({"ok": False, "message": "Only the host can open a lobby."}), 403
    # Optional custom config (owner-built): options + an imported mod. Absent =
    # the standard rated lobby. Anything non-default (or a mod) => unrated.
    body = request.json or {}
    opts = normalize_custom_options(body.get("options") or {})
    mod_code = str(body.get("mod_code") or "")[:CUSTOM_MOD_MAX]
    custom_map = normalize_custom_map(body.get("custom_map"))
    if not re.search(r'[1-9]', custom_map):     # a blank grid is no custom map at all
        custom_map = ''
    join_gate = body.get("join_gate")
    join_gate = join_gate if join_gate in ("odyssey", "open") else "odyssey"
    rated = 1 if (custom_is_rated(opts, mod_code) and not custom_map) else 0
    conn = db()
    c = conn.cursor()
    row = c.execute("SELECT link FROM custom_game WHERE id = 1").fetchone()
    if row and row[0]:
        conn.close()
        return jsonify({"ok": True, "already": True, "message": "A lobby is already up."}), 200
    c.execute("INSERT INTO custom_game (id, wanted_at, options_json, mod_code, rated, join_gate, last_error, extracted_json, custom_map, stop_requested) "
              "VALUES (1, ?, ?, ?, ?, ?, '', '', ?, 0) ON CONFLICT(id) DO UPDATE SET "
              "wanted_at=excluded.wanted_at, options_json=excluded.options_json, "
              "mod_code=excluded.mod_code, rated=excluded.rated, join_gate=excluded.join_gate, "
              "last_error='', extracted_json='', custom_map=excluded.custom_map, stop_requested=0",
              (time.strftime('%Y-%m-%d %H:%M:%S'), json.dumps(opts), mod_code, rated, join_gate, custom_map))
    conn.commit()
    conn.close()
    kind = "rated standard" if rated else "unrated custom"
    return jsonify({"ok": True, "rated": bool(rated),
                    "message": "Opening a %s lobby - this takes a few seconds." % kind}), 200


@app.route('/api/customgame/pending')
def api_customgame_pending():
    """The droplet host polls this: is a lobby wanted and not yet up? Key-gated."""
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"error": "Unauthorized"}), 401
    conn = db()
    c = conn.cursor()
    row = c.execute("SELECT link, wanted_at, options_json, mod_code, rated, join_gate, custom_map "
                    "FROM custom_game WHERE id = 1").fetchone()
    conn.close()
    link = (row[0] if row else '') or ''
    wanted_at = (row[1] if row else '') or ''
    wanted = False
    if wanted_at and not link:
        try:
            wanted = (time.time() - time.mktime(
                time.strptime(wanted_at, '%Y-%m-%d %H:%M:%S'))) < 90
        except Exception:
            wanted = True
    resp = {"wanted": wanted}
    if wanted:                       # hand the host the config it should build
        try:
            opts = json.loads(row[2]) if (row and row[2]) else {}
        except Exception:
            opts = {}
        options = normalize_custom_options(opts)
        cmap = (row[6] if row else '') or ''
        if cmap:
            options["custom_map"] = cmap
        resp["options"] = options
        resp["mod_code"] = (row[3] if row else '') or ''
        resp["rated"] = bool(row[4]) if (row and row[4] is not None) else True
        resp["join_gate"] = (row[5] if row else '') or 'odyssey'
    return jsonify(resp), 200


@app.route('/api/customgame/status')
def api_customgame_status():
    """Live status for the /customgame page poll: the link if the signed-in user
    qualifies, plus whether an open request is in flight."""
    sub_id = current_user()
    allowed = _user_meets_custom_gate(sub_id)
    can_host = _can_host_custom(sub_id)
    conn = db()
    c = conn.cursor()
    row = c.execute("SELECT link, region, wanted_at, last_error FROM custom_game WHERE id = 1").fetchone()
    conn.close()
    link = (row[0] if row else '') or ''
    region = (row[1] if row else '') or ''
    wanted_at = (row[2] if row else '') or ''
    last_error = (row[3] if row else '') or ''
    return jsonify({"allowed": allowed, "can_host": can_host,
                    "link": (link if allowed else None),
                    "region": region, "opening": bool(wanted_at and not link),
                    # only the host needs to see why their open failed
                    "error": (last_error if (can_host and last_error and not link) else None)}), 200


