@app.route('/clan/revoke', methods=['POST'])
def clan_revoke():
    """Take clan admin away again. Site owner only.

    Admin does not expire on its own. The code that granted it is one-time,
    but the rights it hands over last until they are taken back here - so
    this is the way to deal with an admin who leaves or misbehaves. Removing
    a clan's last admin puts it back on automatic tag detection, and a fresh
    code can be issued to whoever takes over.
    """
    if not api_key_ok(request.headers.get('X-API-Key')):
        return jsonify({"message": "Unauthorized"}), 401
    known = canonical_clan_tag((request.json or {}).get('clan'))
    if not known:
        return jsonify({"message": "Unknown clan tag. Known tags: "
                                   + ", ".join(sorted(all_clan_tags()))}), 400

    conn = db()
    c = conn.cursor()
    c.execute("DELETE FROM clan_admins WHERE clan = ?", (known,))
    removed = c.rowcount
    # Unused codes for this clan would otherwise still be redeemable by
    # whoever is holding them.
    c.execute("DELETE FROM clan_codes WHERE clan = ? AND used_at IS NULL", (known,))
    conn.commit()
    conn.close()
    return jsonify({"message": f"Removed {removed} admin(s) from {known}. "
                               f"{known} is back on automatic tag detection."}), 200


# Clans are off while the change-over settles. The tags were matched
# against names read off the screen, and those were often wrong, so every
# membership derived from them is suspect. Saying so beats showing a
# directory that quietly lies.
CLANS_NOTICE = ("Clans are under construction. Names are now read from the game "
                "itself rather than off the screen, and the old clan tags were matched "
                "against names that were often misread - so they have been cleared and "
                "will be rebuilt from real data.")


# A clan is ranked from this many members up. One person's "average" is
# just their own rating, so a single strong player would sit above every
# real clan forever and the table would mean nothing. Smaller clans are
# still listed, just not placed.
CLAN_RANK_MIN = 2


@app.route('/myclan')
def my_clan_page():
    """Everything one clan's staff can do, in one place."""
    sub_id = current_user()
    conn = db()
    c = conn.cursor()
    tags = clan_admin_tags(c, sub_id) if sub_id else []
    if not tags and sub_id:
        # Not staff of any clan - but on a roster? Then this is THEIR clan,
        # in the member's view: the header, the roster, their row, Leave.
        # Until 9.31.0 the Your clan link brought a member here to be told
        # they run no clan.
        c.execute("SELECT clan FROM players WHERE google_sub = ? AND clan IS NOT NULL "
                  "AND clan != '' ORDER BY (COALESCE(wins, 0) + COALESCE(losses, 0)) DESC "
                  "LIMIT 1", (sub_id,))
        _mem = c.fetchone()
        if _mem and _mem[0]:
            tags = [_mem[0]]
    if not tags:
        conn.close()
        return render_template('myclan.html', clan=None, signed_in=bool(sub_id),
                               version=APP_VERSION, contact=CONTACT_HANDLE,
                               page='myclan', client_id=GOOGLE_CLIENT_ID,
                               palette=CLAN_PALETTE, themes=CLAN_THEMES,
                               role_help=CLAN_ROLE_HELP,
                               role_default_color=CLAN_ROLE_DEFAULT_COLOR)
    # More than one clan is rare, so a chooser rather than a whole page of
    # tabs: ?clan= picks, the first one is the default.
    asked = canonical_clan_tag(request.args.get('clan'))
    tag = asked if asked in tags else tags[0]
    role = clan_role(c, sub_id, tag)
    # Opening the clan page is a moment too: any instalment that has come
    # due for anyone on this roster is handed over before the page is drawn.
    if gems_visible() and escrow_tick(c, tag=tag):
        conn.commit()

    c.execute("SELECT name, elo, wins, losses, google_sub, clan_joined_at, "
              "COALESCE(strict_mode, 0), contract_clan, contract_until "
              "FROM players WHERE clan = ?", (tag,))
    rows = c.fetchall()
    c.execute("SELECT google_sub, COALESCE(role, 'leader') FROM clan_admins WHERE clan = ?",
              (tag,))
    roles = {r[0]: r[1] for r in c.fetchall() if r[0]}
    role_labels = clan_custom_labels(c, tag)
    role_colors = clan_role_colors(c, tag)
    role_color_keys = clan_role_color_keys(c, tag)
    _shown = clan_display(c, tag)
    rows.sort(key=leaderboard_sort_key)
    members = []
    for name, elo, wins, losses, owner_sub, joined, protected, _cclan, _cuntil in rows:
        wins = wins or 0
        losses = losses or 0
        played = wins + losses
        _role = roles.get(owner_sub, "")
        members.append({
            "name": name, "display": display_name(name, tag, _shown),
            "role": _role,
            "role_label": role_label_for(_role, role_labels),
            "role_color": role_colors.get(_role or "player", role_colors["player"]),
            "elo": f"{elo:.1f}", "wins": wins, "losses": losses,
            "winrate": f"{round(100 * wins / played)}%" if played else "-",
            "joined": join_date(joined),
            "is_you": bool(owner_sub) and owner_sub == sub_id,
            # only an account-holder can be given a rank or made leader
            "has_account": bool(owner_sub),
            "contract": contract_until(_cclan, _cuntil, tag),
            "rate": clan_member_rate(c, tag, normalize_name(name)),
        })

    c.execute("SELECT region, bio, theme FROM clans WHERE tag = ?", (tag,))
    _cr = c.fetchone() or (None, None, None)
    region = _cr[0] or ""
    clan_bio = _cr[1] or ""
    clan_theme = (_cr[2] or "") if (_cr[2] in CLAN_THEMES) else ""
    link_row = active_invite_link(c, tag)
    # The header band shows the same numbers the public page does.
    _tw = sum(m["wins"] for m in members)
    _tl = sum(m["losses"] for m in members)
    _elos = [float(r[1] or 0) for r in rows]
    _surv = 0
    if rows:
        _surv = c.execute("SELECT COALESCE(SUM(wins), 0) FROM survival_players "
                          "WHERE norm_name IN (%s)" % ",".join("?" for _ in rows),
                          [normalize_name(r[0]) for r in rows]).fetchone()[0]
    clan = {
        "tag": tag, "display": _shown, "members": members,
        "admins": [m["name"] for m in members if m["role"] == 'leader'],
        "avg_elo": f"{sum(_elos) / len(_elos):.1f}" if _elos else "0.0",
        "wins": _tw, "losses": _tl,
        "winrate": f"{round(100 * _tw / (_tw + _tl))}%" if (_tw + _tl) else "-",
        "surv_wins": int(_surv or 0),
        "size": len(members), "region": region,
        "region_label": REGION_LABELS.get(region, ""), "regions": REGIONS,
        "styles": [{"id": i, "shown": s, "default": n == 0}
                   for n, (i, s) in enumerate(clan_styles(c, tag))],
        "bio": clan_bio, "bio_max": CLAN_BIO_MAX,
        "theme": clan_theme, "theme_color": CLAN_THEMES.get(clan_theme, ""),
        "role_colors": role_colors, "role_color_keys": role_color_keys,
        "applications": clan_applications(c, tag),
        "treasury": gem_balance(c, "clan", tag),
        "member_rate": clan_pay_rates(c, tag)[0], "mod_rate": clan_pay_rates(c, tag)[1],
        "paid_week": clan_paid_week(c, tag),
        "payroll": clan_payroll(c, tag),
        "cv": clan_view(tag, True, c),
        "invited": [{"id": r[0], "name": r[1]} for r in c.execute(
            "SELECT id, name FROM clan_invites WHERE clan = ? "
            "AND status = 'pending' AND direction = 'invite' "
            "ORDER BY name", (tag,)).fetchall()],
        "role": role, "role_label": role_label_for(role, role_labels),
        "can_manage": clan_rank(role) >= clan_rank('coleader'),
        "is_leader": role == 'leader',
        # current role titles (custom or default) for the rename form
        "role_names": {r: role_labels.get(r) or CLAN_ROLE_LABELS.get(r, "")
                       for r in CUSTOMIZABLE_ROLES},
        "others": [t for t in tags if t != tag],
        "link": invite_link_json(link_row) if link_row else None,
        "link_days": INVITE_LINK_DAYS,
        # Running a clan and being on its roster are different things, so
        # staff with no leaderboard name are not a bug - but they are
        # invisible on their own roster and their clan says nobody runs it,
        # and nothing on the page told them why. Two of five leaders.
        "you_named": bool(account_name_for(c, sub_id)),
    }
    conn.close()
    return render_template('myclan.html', clan=clan, signed_in=True,
                           version=APP_VERSION, contact=CONTACT_HANDLE,
                           page='myclan', client_id=GOOGLE_CLIENT_ID,
                           palette=CLAN_PALETTE, themes=CLAN_THEMES,
                           role_help=CLAN_ROLE_HELP,
                           role_default_color=CLAN_ROLE_DEFAULT_COLOR,
                           rate_max=CLAN_RATE_MAX, coleader_cap=clan_coleader_cap(db().cursor(), tag),
                           pay_rates={"leader": GEM_LEADER_WIN, "coleader": GEM_COLEADER_WIN,
                                      "clan": GEM_CLAN_WIN, "sleader": GEM_SURVIVAL_LEADER_WIN,
                                      "scoleader": GEM_SURVIVAL_COLEADER_WIN, "sclan": GEM_SURVIVAL_CLAN_WIN})


@app.route('/clans')
def clans_page():
    """Public directory of every clan, ranked by average skill."""
    conn = db()
    c = conn.cursor()
    curated = curated_clans(c)
    c.execute("SELECT tag, region, theme FROM clans")
    _clanmeta = c.fetchall()
    regions = {r[0]: (r[1] or "") for r in _clanmeta}
    themes = {r[0]: (r[2] or "") for r in _clanmeta}
    shown = clan_display_map(c)
    rows = []
    for tag in sorted(all_clan_tags(c)):
        c.execute("SELECT elo, COALESCE(wins, 0), COALESCE(losses, 0) "
                  "FROM players WHERE clan = ? AND " + NOT_SANDBOX, (tag,))
        got = c.fetchall()
        elos = [r[0] for r in got]
        wins = sum(r[1] for r in got)
        losses = sum(r[2] for r in got)
        played = wins + losses
        avg = sum(elos) / len(elos) if elos else 0.0
        surv = c.execute("SELECT COALESCE(SUM(s.wins), 0) FROM survival_players s "
                         "JOIN players p ON p.norm_name = s.norm_name "
                         "WHERE p.clan = ? AND " + NOT_SANDBOX, (tag,)).fetchone()[0]
        rows.append({
            "tag": tag,
            "size": len(elos),
            "surv_wins": int(surv or 0),
            "avg": avg,
            "avg_elo": f"{avg:.1f}",
            "wins": wins,
            "losses": losses,
            "winrate": f"{round(100 * wins / played)}%" if played else "-",
            "display": shown.get(tag, tag),
            "region": regions.get(tag, ""),
            "region_label": REGION_LABELS.get(regions.get(tag, ""), ""),
            "theme": themes.get(tag, ""),
            "theme_color": CLAN_THEMES.get(themes.get(tag, ""), ""),
            "curated": tag in curated,
        })
    conn.close()
    ranked = [r for r in rows if r["size"] >= CLAN_RANK_MIN]
    small = [r for r in rows if r["size"] < CLAN_RANK_MIN]
    # Highest average first. Size breaks a tie: holding an average across
    # more people is the harder thing to have done.
    ranked.sort(key=lambda r: (-r["avg"], -r["size"], r["tag"]))
    for place, row in enumerate(ranked, 1):
        row["place"] = place
    small.sort(key=lambda r: (-r["size"], r["tag"]))
    # Bought perks, for those who may see the shop: a Spotlight clan sits at
    # the top of the table with its real place number; Recruiting is a pill.
    # Perks never touch the order. Recruiting is a label on the row; Spotlight
    # is a banner above the table, so a ranking stays a ranking.
    featured = []
    if gems_visible():
        live = {}
        try:
            _pc = db()
            _pcc = _pc.cursor()
            for _tag, _perk in _pcc.execute("SELECT clan, perk FROM clan_perks WHERE until > ?",
                                            (_stamp(),)).fetchall():
                live.setdefault(_tag, {})[_perk] = 1
            featured = featured_clans(_pcc)
            _pc.close()
        except sqlite3.Error:
            pass
        for row in ranked + small:
            row["perks"] = live.get(row["tag"], {})
    return render_template('clans.html', clans=ranked, small=small, featured=featured,
                           clan_cost=CLAN_START_COST,
                           total=len(rows), rank_min=CLAN_RANK_MIN,
                           version=APP_VERSION, contact=CONTACT_HANDLE,
                           # A clan directory is a ranking: it belongs to the
                           # Leaderboard tab, beside the players.
                           page='clans',
                           notice=CLANS_NOTICE)


