@app.route('/account')
def account_page():
    """Your stats and your settings, one place - the page a game opens
    when you tap your own name."""
    sub_id = current_user()
    conn = db()
    c = conn.cursor()
    account_name = account_name_for(c, sub_id)
    acct = None
    if account_name:
        c.execute("SELECT name, elo, COALESCE(wins,0), COALESCE(losses,0), clan, "
                  "COALESCE(wipe_available,0), bio, contract_clan, contract_until, "
                  "COALESCE(contract_rate, 0) "
                  "FROM players WHERE norm_name = ?", (normalize_name(account_name),))
        row = c.fetchone()
        if row:
            name, elo, wins, losses, clan, wipe_avail, bio, _cclan, _cuntil, _crate = row
            c.execute("SELECT COUNT(*) + 1 FROM players WHERE elo > ?", (elo,))
            rank = c.fetchone()[0]
            c.execute("SELECT COUNT(*) FROM players")
            total = c.fetchone()[0]
            played = wins + losses
            by_region = [r for r in region_split(c, name) if r["played"]]
            c.execute("SELECT mp.won, mp.delta, COALESCE(mp.half,0), m.played_at, "
                      "COALESCE(mp.seen, 0) "
                      "FROM match_players mp JOIN matches m ON m.id = mp.match_row "
                      "WHERE mp.norm_name = ? AND m.played_at > COALESCE((SELECT wiped_before FROM players WHERE norm_name = mp.norm_name), '') ORDER BY m.played_at DESC LIMIT 10",
                      (normalize_name(name),))
            recent = [{"won": r[0], "delta": r[1] or 0, "half": r[2],
                       "when": str(r[3])[:16], "unseen": not r[4]}
                      for r in c.fetchall()]
            # This render IS the notification. Clear every owned name,
            # not just the shown ten, so the counter matches what the
            # badge promised and can never get stuck on an old match.
            c.execute("UPDATE match_players SET seen = 1 "
                      "WHERE COALESCE(seen, 0) = 0 AND norm_name IN "
                      "(SELECT norm_name FROM players WHERE google_sub = ?)",
                      (sub_id,))
            conn.commit()
            gained = sum(r["gained"] for r in region_split(c, name))
            acct = {
                "name": name, "display": display_name(name, clan, player_tag(c, name, clan)) if clan else name,
                "elo": f"{elo:.2f}".rstrip('0').rstrip('.'),
                "rank": rank, "total": total, "wins": wins, "losses": losses,
                "winrate": f"{round(100 * wins / played)}%" if played else "-",
                "gained": ("%+.2f" % gained) if played else "-",
                "clan": clan, "clan_display": player_tag(c, name, clan) if clan else None,
                "tag_styles": account_tag_styles(c, name, clan),
                "by_region": by_region, "recent": recent,
                "wipe_available": int(wipe_avail or 0),
                "bio": bio or "",
                "cos": cosmetic_view(normalize_name(name), gems_visible()),
                "contract": contract_until(_cclan, _cuntil, clan) if clan else None,
                "contract_rate": int(_crate or 0),
                "cv": clan_view(clan, gems_visible()) if clan else {},
            }
    # Discord link status for the settings section. A Discord sign-in IS its
    # own Discord (nothing to link); a Google account may have one bound.
    is_discord_acct = bool(sub_id and str(sub_id).startswith('discord:'))
    if is_discord_acct:
        discord_link = {"handle": discord_handle(c, sub_id) or '', "own": True}
    else:
        ld = linked_discord_for(c, sub_id) if sub_id else None
        discord_link = ({"handle": ld.get('display') or ld.get('username') or '',
                         "own": False} if ld else None)
    conn.close()
    return render_template('account.html', version=APP_VERSION,
                           contact=CONTACT_HANDLE, client_id=GOOGLE_CLIENT_ID,
                           account_name=account_name, signed_in=bool(sub_id),
                           acct=acct, page='account',
                           discord_link=discord_link,
                           discord_can_link=bool(sub_id) and not is_discord_acct,
                           link_status=request.args.get('link'),
                           wins_required=CLAIM_WINS_REQUIRED, bio_max=BIO_MAX)


def perform_set_bio(c, sub_id, raw):
    """Set (or clear) the bio on the name this account owns. Screened for
    slurs/profanity like a typed name, and capped so it stays a blurb. Shared
    by the web /account/bio and the bot's /api/bot/bio. Does NOT commit;
    returns (status, payload)."""
    if raw is None:
        return 400, {"ok": False, "message": "No bio provided."}
    # Normalise line endings, drop control characters except newline/tab, and
    # trim trailing blank lines - but keep the author's own line breaks.
    text = str(raw).replace('\r\n', '\n').replace('\r', '\n')
    text = ''.join(ch for ch in text if ch == '\n' or ch == '\t' or ord(ch) >= 32)
    text = text.strip()
    if len(text) > BIO_MAX:
        return 400, {"ok": False, "message": f"A bio is at most {BIO_MAX} characters."}
    if bio_blocked(text):
        return 400, {"ok": False, "message": "That bio isn't allowed. Please remove "
                                             "any slurs or profanity."}
    account_name = account_name_for(c, sub_id)
    if not account_name:
        return 400, {"ok": False, "message": "Claim or register a name first, then "
                                             "you can add a bio to it."}
    c.execute("UPDATE players SET bio = ? WHERE norm_name = ?",
              (text or None, normalize_name(account_name)))
    return 200, {"ok": True, "bio": text,
                 "message": "Bio saved." if text else "Bio cleared."}


@app.route('/account/bio', methods=['POST'])
def account_bio():
    """Set (or clear) the bio shown on your public profile. Applies to the
    name your account owns; screened for slurs/profanity like a typed name,
    and capped so it stays a blurb, not an essay."""
    sub_id = current_user()
    if not sub_id:
        return jsonify({"message": "Sign in first."}), 401
    conn = db()
    c = conn.cursor()
    status, payload = perform_set_bio(c, sub_id, (request.json or {}).get('bio'))
    if status == 200:
        conn.commit()
    conn.close()
    return jsonify(payload), status


@app.route('/account/wipe', methods=['POST'])
def account_wipe():
    """The one-time claim wipe. A freshly claimed name may carry a record
    other people built before its real owner arrived; right after a claim
    completes - and only then - the owner may wipe it and start clean at
    the starting rating. 'Keep' dismisses the offer instead.

    A wipe is a TRUE reset to placement: the account's matches are archived
    into wiped_match_players and then DELETED from match_players, so nothing
    - the profile history, a stats recompute, or a future restore - can
    rebuild a record from them. Pending (held) results for the identity are
    dropped too, so an old match can't be applied after the reset. The
    archive keeps everything recoverable by an admin if a wipe is disputed."""
    sub_id = current_user()
    if not sub_id:
        return redirect('/account')
    choice = str(request.form.get('choice') or '')
    conn = db()
    c = conn.cursor()
    c.execute("SELECT name FROM players WHERE google_sub = ? "
              "AND COALESCE(wipe_available,0) = 1", (sub_id,))
    row = c.fetchone()
    if not row:
        conn.close()
        return redirect('/account')
    if choice == 'wipe':
        acct = row[0]
        nn = normalize_name(acct)
        now = time.strftime('%Y-%m-%d %H:%M:%S')
        # 1) copy this account's matches into cold storage
        c.execute(
            "INSERT INTO wiped_match_players "
            "(wiped_at, account, norm_name, match_row, match_id, played_at, "
            " region, won, delta, half, played_as, score, ship, deaths) "
            "SELECT ?, ?, mp.norm_name, mp.match_row, m.match_id, m.played_at, "
            " m.region, mp.won, mp.delta, mp.half, mp.played_as, mp.score, "
            " mp.ship, mp.deaths "
            "FROM match_players mp JOIN matches m ON m.id = mp.match_row "
            "WHERE mp.norm_name = ?", (now, acct, nn))
        # 2) remove them from the live tables so nothing counts them again
        c.execute("DELETE FROM match_players WHERE norm_name = ?", (nn,))
        c.execute("DELETE FROM held_results WHERE norm_name = ?", (nn,))
        # 3) reset the account to placement (fresh at the starting rating).
        #    wiped_before is still stamped as an audit marker of when it happened.
        c.execute("UPDATE players SET elo = ?, wins = 0, losses = 0, "
                  "wiped_before = ?, wipe_available = 0 WHERE name = ?",
                  (STARTING_ELO, now, acct))
    else:
        c.execute("UPDATE players SET wipe_available = 0 WHERE name = ?", (row[0],))
    conn.commit()
    conn.close()
    return redirect('/account?wiped=' + ('1' if choice == 'wipe' else '0'))


