@app.route('/play')
def play_page():
    """Live matches, checking in, and getting hold of your name.

    These were spread across the leaderboard and Settings, so the one thing
    a player actually does before a game - make sure it will count - took
    two pages and some guessing.
    """
    conn = db()
    c = conn.cursor()
    capacity, min_age, max_age, min_players = tracker_limits(c)
    c.execute("SELECT sys_id, name, players, age, COALESCE(watching, 0), "
              "COALESCE(region, 'america') FROM live_lobbies "
              "WHERE updated_at > datetime('now', '-5 minutes') "
              "AND COALESCE(mode, 'team') = 'team' ORDER BY watching DESC, age DESC")
    raw = c.fetchall()
    # Survival is described on its own terms: the team rules are about a match
    # that starts full and ends, and a survival round spends its first half
    # filling up, so "20 minutes in" means something completely different.
    surv_raw = c.execute(
        "SELECT sys_id, name, players, age, COALESCE(watching, 0), "
        "COALESCE(region, 'america') FROM live_lobbies "
        "WHERE updated_at > datetime('now', '-5 minutes') AND mode = 'survival' "
        "ORDER BY watching DESC, players DESC").fetchall()
    # Matches that just ended and are being scored - their lobby has dropped out
    # of the live push, so keep them visible as "Scoring" until the result lands
    # (game_end clears them) instead of vanishing into a blank gap.
    scoring_rows = c.execute(
        "SELECT sys_id, name, region, players, "
        "CAST((julianday('now') - julianday(since)) * 86400 AS INTEGER) "
        "FROM scoring_lobbies WHERE since > datetime('now', '-100 seconds') "
        "ORDER BY since DESC").fetchall()
    conn.close()
    lobbies, watched_now = describe_lobbies([(r[1], r[2], r[3], r[4]) for r in raw],
                                            capacity, min_age, max_age, min_players)
    for lobby, row in zip(lobbies, raw):
        lobby["id"] = row[0]
        lobby["region"] = row[5]
        lobby["mode"] = "team"
    for sid, sname, splayers, sage, swatch, sregion in surv_raw:
        lobbies.append({
            "id": sid, "region": sregion, "name": sname or ("Lobby %d" % sid),
            "players": splayers or 0, "mins": int((sage or 0) // 60),
            "watching": bool(swatch), "mode": "survival", "scoring": False,
            "status": ("Being watched" if swatch
                       else "Check in now - the watcher joins these in turn"),
            "tone": ("watching" if swatch else "waiting"),
            # Same rule as team: a check-in is worth making until a watcher is
            # on the lobby, which is the moment it becomes evidence.
            "can_checkin": not swatch})
    live_ids = {r[0] for r in raw} | {r[0] for r in surv_raw}
    for sid, sname, sregion, splayers, since_s in scoring_rows:
        if sid in live_ids:
            continue
        lobbies.append({"id": sid, "region": sregion or "america",
                        "name": sname or ("Lobby %d" % sid),
                        "players": splayers or 0, "mins": 0, "watching": False,
                        "status": "Scoring", "tone": "scoring",
                        "can_checkin": False, "scoring": True,
                        "since_s": max(0, since_s or 0)})

    # Grouped by region rather than one flat list. Three continents of
    # lobbies in one column is unreadable, and a player only ever cares
    # about the one they are about to play in.
    groups = []
    for key, label in REGIONS:
        here = [l for l in lobbies if l["region"] == key]
        if here:
            groups.append({"key": key, "label": label, "lobbies": here})
    # Every region gets a tab whether or not it has a match right now, so a
    # quiet hour does not look like the tracker has stopped covering it.
    all_regions = [{"key": k, "label": lbl} for k, lbl in REGIONS]
    group_keys = [g["key"] for g in groups]
    total_live = sum(1 for l in lobbies if not l.get("scoring"))

    conn = db()
    c = conn.cursor()
    account_name = account_name_for(c, current_user())
    conn.close()

    return render_template('play.html', version=APP_VERSION, page='play',
                           lobbies=lobbies, groups=groups, all_regions=all_regions,
                           group_keys=group_keys, watched=watched_now,
                           capacity=capacity, total=total_live, account_name=account_name,
                           min_age_mins=min_age // 60, contact=CONTACT_HANDLE,
                           wins_required=CLAIM_WINS_REQUIRED)


