# How many matches the watcher has behind it, team and survival. Whole-table
# counts on the busiest page, so they are cached: a few minutes stale is fine
# for a number that only ever goes up.
_WATCHED_CACHE = {"at": 0.0, "team": 0, "survival": 0}
_WATCHED_TTL = 300.0
_LAST_WATCHED = {"at": 0.0, "team": None, "survival": None}


def last_watched():
    """When the newest team match and the newest survival round ended, as
    the database stores them (UTC text), or None. Two indexed MAXes, kept
    for twenty seconds."""
    now = time.time()
    if now - _LAST_WATCHED["at"] < 20:
        return _LAST_WATCHED["team"], _LAST_WATCHED["survival"]
    team = surv = None
    try:
        conn = db(timeout=3)
        c = conn.cursor()
        try:
            team = c.execute("SELECT MAX(played_at) FROM matches").fetchone()[0]
        except sqlite3.Error:
            team = None
        try:
            surv = c.execute("SELECT MAX(ended_at) FROM survival_results").fetchone()[0]
        except sqlite3.Error:
            surv = None
        conn.close()
    except sqlite3.Error:
        return _LAST_WATCHED["team"], _LAST_WATCHED["survival"]
    _LAST_WATCHED.update({"at": now, "team": team, "survival": surv})
    return team, surv


def ago_text(stamp):
    """'4 min ago' for a UTC 'YYYY-MM-DD HH:MM:SS' stamp; '' if unknown."""
    if not stamp:
        return ''
    try:
        then = calendar.timegm(time.strptime(
            str(stamp).replace('T', ' ')[:19], '%Y-%m-%d %H:%M:%S'))
    except (ValueError, TypeError):
        return ''
    sec = max(0, int(time.time() - then))
    if sec < 90:
        return 'just now'
    if sec < 3600:
        return '%d min ago' % (sec // 60)
    if sec < 86400:
        h = sec // 3600
        return '%d hour%s ago' % (h, '' if h == 1 else 's')
    d = sec // 86400
    return '%d day%s ago' % (d, '' if d == 1 else 's')


def watched_totals():
    """(team matches, survival rounds) recorded so far."""
    now = time.time()
    if now - _WATCHED_CACHE["at"] < _WATCHED_TTL:
        return _WATCHED_CACHE["team"], _WATCHED_CACHE["survival"]
    team = surv = 0
    try:
        conn = db()
        c = conn.cursor()
        try:
            team = c.execute("SELECT COUNT(*) FROM matches "
                             "WHERE COALESCE(voided, 0) = 0").fetchone()[0] or 0
        except sqlite3.Error:
            team = 0
        try:
            surv = c.execute("SELECT COUNT(*) FROM survival_results").fetchone()[0] or 0
        except sqlite3.Error:
            surv = 0
        conn.close()
    except sqlite3.Error:
        return _WATCHED_CACHE["team"], _WATCHED_CACHE["survival"]
    _WATCHED_CACHE.update({"at": now, "team": team, "survival": surv})
    return team, surv


def home_page():
    """Your own front page: who you are, what you have, where to go.

    Deliberately not a stat sheet. The record is one line; what leads is the
    emblem, the name, the balance, the achievements in hand and the next one
    to reach. Returns None when there is nobody to show it to, and the caller
    falls through to the board.
    """
    conn = db()
    c = conn.cursor()
    me = my_player(c)
    if not me:
        conn.close()
        return None
    name, nn = me
    c.execute("SELECT elo, COALESCE(wins, 0), COALESCE(losses, 0), clan, bio, "
              "peak_rank, peak_div FROM players WHERE norm_name = ?", (nn,))
    row = c.fetchone()
    if not row:
        conn.close()
        return None
    elo, wins, losses, clan, bio, peak_rank, peak_div_key = row
    played = wins + losses
    c.execute("SELECT COUNT(*) + 1 FROM players WHERE elo > ?", (elo,))
    rank = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM players")
    rank_of = c.fetchone()[0]
    division = division_map().get(nn) if played >= PROVISIONAL_GAMES else None
    peak_division = ranks.RANK_BY_KEY.get(peak_div_key) if peak_div_key else None
    clan_shown = player_tag(c, name, clan) if clan else None

    # Anything a contract owes them by now lands before the balance is read.
    if escrow_tick(c, nn=nn):
        conn.commit()
    balance = gem_balance(c, "player", nn)
    emblem, emblem_color, mythic = worn_emblem(nn, display_ship_map(), True)
    today = time.strftime('%Y-%m-%d', time.gmtime())
    c.execute("SELECT COALESCE(SUM(amount), 0) FROM gem_ledger WHERE owner_kind = 'player' "
              "AND owner = ? AND amount > 0 AND at >= ?", (nn, today))
    today_gems = c.fetchone()[0]

    cat = ach_status(c, nn)
    have = [a for a in cat if a["claimed"]]
    ready = [a for a in cat if a["ready"]]
    objs = obj_status(c, nn)
    obj_ready = [o for o in objs if o["ready"]]
    # The next one to chase: whichever locked achievement you are furthest
    # along. Mythos is left out of it - there is no being most of the way to
    # having been number one, and offering it as "next" would be a lie.
    locked = [a for a in cat if not a["unlocked"]
              and not (a.get("rank") or {}).get("mythic")]
    next_up = (max(locked, key=lambda a: (a["have"] / float(a["need"] or 1), -a["gems"]))
               if locked else None)

    c.execute("SELECT m.played_at, mp.won, mp.delta, m.id FROM match_players mp "
              "JOIN matches m ON m.id = mp.match_row WHERE mp.norm_name = ? "
              "AND m.played_at > COALESCE((SELECT wiped_before FROM players "
              "WHERE norm_name = mp.norm_name), '') ORDER BY m.id DESC LIMIT 10", (nn,))
    recent = [{"at": (r[0] or "")[:16], "won": bool(r[1]),
               "delta": round(r[2] or 0, 1), "mid": r[3]} for r in c.fetchall()]
    conn.close()
    return render_template(
        'home.html', version=APP_VERSION, page='home', name=name,
        elo=elo, wins=wins, losses=losses, played=played,
        winrate=("%d%%" % round(100.0 * wins / played)) if played else None,
        rank=rank, rank_of=rank_of, division=division, peak_division=peak_division,
        peak_rank=peak_rank, clan=clan, clan_shown=clan_shown, bio=bio,
        placements_left=max(0, PROVISIONAL_GAMES - played) if played < PROVISIONAL_GAMES else 0,
        balance=balance, today_gems=today_gems, have=have, next_up=next_up,
        ready=ready, ready_gems=sum(a["gems"] for a in ready),
        objectives=objs, obj_ready=obj_ready,
        obj_gems=sum(o["gems"] for o in obj_ready),
        day_resets=obj_resets_in(),
        cos=cosmetic_view(nn, True), cv=(clan_view(clan, True) if clan else {}),
        total_ach=len(cat), recent=recent, preview=not GEMS_PUBLIC,
        emblem=emblem, emblem_color=emblem_color, mythic=mythic)


